window.EXPECTATIONS = window.EXPECTATIONS || {};
window.EXPECTATIONS.fr = {"subjects":{"k":{"k":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/kindergarten","sourceLang":"en","strands":[{"code":"A","title":"Foundations of Language and Mathematics ","why":"A strong foundation in reading, writing and math sets your child up for success. Language and math skills help your child to: process information for various reasons, including decision-making; understand ideas and information to make sense of the world; reason and think critically; communicate their ideas and thoughts; solve problems Your child will learn: listening and speaking skills and how to use facial expressions, gestures and body language; about the relationship between sounds and letters to read, understand and create simple texts by learning to use what they know about: words; sentence structure; grammar; punctuation; how to count, estimate, add, subtract and share equally using numbers; how to identify shapes, objects and patterns; how to answer questions by collecting data and organizing it into graphs; how to use a variety of tools and strategies to solve math problems","overall":[{"code":"A1","title":"Oral and Non-Verbal Communication","text":"communicate orally and non-verbally","specific":[{"code":"A1.1","title":"","text":"listen and respond"},{"code":"A1.2","title":"","text":"use language conventions and non-verbal communication"},{"code":"A1.3","title":"","text":"understand and use new words and develop morphological awareness"}]},{"code":"A2","title":"Foundations for Reading and Writing","text":"apply early reading and writing skills","specific":[{"code":"A2.1","title":"","text":"name upper- and lowercase letters (both in and out of order)"},{"code":"A2.2","title":"","text":"use proper formation patterns to write letters"},{"code":"A2.3","title":"","text":"isolate and blend phonemes, and segment simple words into phonemes"},{"code":"A2.4","title":"","text":"identify simple grapheme-phoneme correspondences"},{"code":"A2.5","title":"","text":"read and spell simple words using phonemic awareness and phonics knowledge"},{"code":"A2.6","title":"","text":"read short sentences fluently, including those with explicitly taught words, with increasing accuracy, to support comprehension"}]},{"code":"A3","title":"Understanding and Responding to Texts","text":"understand and respond to a variety of texts by diverse creators from Canada and by diverse First Nations, Métis, and Inuit creators","specific":[{"code":"A3.1","title":"","text":"identify purposes for choosing different texts"},{"code":"A3.2","title":"","text":"apply knowledge of words, sentence structure, and punctuation"},{"code":"A3.3","title":"","text":"read and understand simple texts, using background knowledge and beginning knowledge of words, grammar, and sentence structure"},{"code":"A3.4","title":"","text":"express personal thoughts and feelings about texts"},{"code":"A3.5","title":"","text":"make predictions about unfamiliar texts, using background knowledge"},{"code":"A3.6","title":"","text":"make connections to a variety of texts"}]},{"code":"A4","title":"Expressing Ideas and Creating Texts","text":"create texts using foundational language knowledge and skills","specific":[{"code":"A4.1","title":"","text":"use knowledge of letters, words, and sentences, with pictures and symbols, to create simple texts"},{"code":"A4.2","title":"","text":"use classroom writing resources to support creating simple texts"}]},{"code":"A5","title":"The Mathematical Processes","text":"apply the mathematical processes (i.e., problem solving; reasoning and proving; reflecting; connecting; communicating; representing; and selecting tools and strategies)","specific":[]},{"code":"A6","title":"Number Sense and Operations","text":"use numbers and operations","specific":[{"code":"A6.1","title":"","text":"explore what numbers are used for"},{"code":"A6.2","title":"","text":"understand when counting forward, the quantity gets bigger and when counting backward, the quantity gets smaller"},{"code":"A6.3","title":"","text":"identify and write numbers to 20"},{"code":"A6.4","title":"","text":"subitize quantities to 5"},{"code":"A6.5","title":"","text":"compose and decompose quantities to 10"},{"code":"A6.6","title":"","text":"understand the concept of more than, the same (equal), or less than"},{"code":"A6.7","title":"","text":"estimate the number of objects in small collections and check by counting"},{"code":"A6.8","title":"","text":"count to 20 by 1s, starting from any number"},{"code":"A6.9","title":"","text":"solve equal-share problems using concrete materials"},{"code":"A6.10","title":"","text":"describe relationships between any two numbers from 0 to 20"},{"code":"A6.11","title":"","text":"recall addition facts to 5 and related subtraction facts"},{"code":"A6.12","title":"","text":"solve situations involving addition and subtraction to 10 using concrete materials"},{"code":"A6.13","title":"","text":"identify and explore the value of Canadian coins to 25¢ and coins and bills to $10"}]},{"code":"A7","title":"Patterns and Relationships ","text":"investigate repeating patterns","specific":[{"code":"A7.1","title":"","text":"identify, describe, and create patterns"},{"code":"A7.2","title":"","text":"identify the core of a repeating pattern and describe why it is important"},{"code":"A7.3","title":"","text":"show that patterns can be represented in different ways because the core remains the same"},{"code":"A7.4","title":"","text":"extend patterns in both directions and identify any missing elements"}]},{"code":"A8","title":"Data Literacy and Probability ","text":"collect and display data to answer questions and communicate information, and explore probability in everyday contexts","specific":[{"code":"A8.1","title":"","text":"sort objects or data using one attribute"},{"code":"A8.2","title":"","text":"collect and record data to answer questions of interest, and display it in concrete graphs or picture graphs"},{"code":"A8.3","title":"","text":"respond to data in concrete graphs and picture graphs by interpreting it and drawing conclusions"},{"code":"A8.4","title":"","text":"describe how likely familiar events are to happen"}]},{"code":"A9","title":"Geometric and Spatial Reasoning","text":"describe two-dimensional shapes and three-dimensional objects, and the location and movement of people and objects","specific":[{"code":"A9.1","title":"","text":"identify, sort, and compare the most common two-dimensional shapes, including circle, hexagon, rhombus, and trapezoid"},{"code":"A9.2","title":"","text":"identify, sort, and compare the most common three-dimensional objects, including cube, sphere, prisms, cone, and pyramid"},{"code":"A9.3","title":"","text":"in structures they have made, identify three-dimensional objects and two-dimensional shapes"},{"code":"A9.4","title":"","text":"construct two-dimensional pictures and three-dimensional structures with matching halves"},{"code":"A9.5","title":"","text":"put two-dimensional shapes together to make other shapes, break them into smaller shapes, and put them together in different ways"},{"code":"A9.6","title":"","text":"describe basic spatial relationships and movements, and visualize objects from different perspectives"},{"code":"A9.7","title":"","text":"give and follow directions for moving from one location to another"}]},{"code":"A10","title":"Measurement","text":"describe and compare the length, area, mass, or capacity of a variety of objects","specific":[{"code":"A10.1","title":"","text":"describe different ways that objects can be measured"},{"code":"A10.2","title":"","text":"compare the length, area, mass, and capacity of objects using concrete materials"}]}]},{"code":"B","title":"Problem Solving and Innovating","why":"Learning to think creatively and critically is important in all aspects of life. Your child learns about the world around them and thinks in new ways to solve problems. Your child will learn to: explore the world through natural curiosity, in ways that engage their mind, senses and body; ask questions; try things out; design or make something new or different","overall":[{"code":"B11","title":"Coding Skills","text":"use foundational coding concepts and skills","specific":[{"code":"B11.1","title":"","text":"use directional and positional language to create and follow instructions involving movement"},{"code":"B11.2","title":"","text":"test and refine instructions"},{"code":"B11.3","title":"","text":"communicate and record step-by-step instructions using symbols, words, or pictures"}]},{"code":"B12","title":"Scientific Investigation and Engineering Design","text":"use an inquiry process to engage in scientific investigations and to design, build, and test models and structures","specific":[{"code":"B12.1","title":"","text":"state problems and pose questions"},{"code":"B12.2","title":"","text":"make predictions and observations while exploring, investigating, and designing"},{"code":"B12.3","title":"","text":"select materials and tools to carry out investigations and to construct models and structures"},{"code":"B12.4","title":"","text":"draw conclusions and communicate results"},{"code":"B12.5","title":"","text":"design, build, and test models and structures"},{"code":"B12.6","title":"","text":"follow safety rules to help prevent injuries, including concussion, and demonstrate an understanding of the importance of these practices"}]},{"code":"B13","title":"Exploring Environments","text":"investigate natural and built environments","specific":[{"code":"B13.1","title":"","text":"ask questions about and describe some natural occurrences"},{"code":"B13.2","title":"","text":"sort and classify groups of living and non-living things"},{"code":"B13.3","title":"","text":"compare patterns in natural and built environments"}]}]},{"code":"C","title":"Self-Regulation and Well-Being","why":"Your child will learn about emotions and feelings, and how to adapt to new situations. This gives them a strong foundation for life. The goal is for your child to: develop an understanding of how they focus and learn best; respect themselves and others; start to learn about physical and mental health and well-being in themselves and others Your child will develop the ability to: manage their own feelings and emotions; realize that others may have different thoughts and feelings, and to respect those differences; deal with distractions; advocate for themselves; understand consequences of actions; be aware of their physical and mental health and wellness; participate actively and regularly in physical activities and develop movement skills","overall":[{"code":"C14","title":"Social Skills","text":"identify and use social skills in play and other contexts","specific":[{"code":"C14.1","title":"","text":"act and talk with peers and adults by expressing and accepting positive messages"},{"code":"C14.2","title":"","text":"show the ability to take turns"},{"code":"C14.3","title":"","text":"demonstrate an awareness of ways of making and keeping friends"},{"code":"C14.4","title":"","text":"use problem-solving skills in social situations"}]},{"code":"C15","title":"Self-Regulation","text":"demonstrate independence, self-regulation, and a willingness to take on responsibility","specific":[{"code":"C15.1","title":"","text":"demonstrate self-reliance and a sense of responsibility"},{"code":"C15.2","title":"","text":"demonstrate a willingness to try new experiences and to adapt to new situations"},{"code":"C15.3","title":"","text":"demonstrate self-motivation, initiative, and confidence in their approach to learning"},{"code":"C15.4","title":"","text":"demonstrate self-control and adapt behaviour to different contexts"},{"code":"C15.5","title":"","text":"develop empathy for others, and acknowledge and respond to each other’s feelings"}]},{"code":"C16","title":"Understanding Health Concepts","text":"demonstrate an awareness of their own health and well-being","specific":[{"code":"C16.1","title":"","text":"demonstrate an understanding of the effects of healthy, active living on the mind and body"},{"code":"C16.2","title":"","text":"investigate the benefits of nutritious foods and explore ways of ensuring healthy eating"},{"code":"C16.3","title":"","text":"practise and discuss appropriate personal hygiene that promotes personal, family, and community health"},{"code":"C16.4","title":"","text":"discuss what action to take when they feel unsafe or uncomfortable, in person or online, and when and how to seek assistance"},{"code":"C16.5","title":"","text":"discuss and demonstrate in play what makes them happy and unhappy, and why"}]},{"code":"C17","title":"Active Participation","text":"participate actively and regularly in a variety of activities that require the application of movement concepts","specific":[{"code":"C17.1","title":"","text":"participate actively in creative movement and other daily physical activities"},{"code":"C17.2","title":"","text":"demonstrate persistence while engaged in activities that require the use of both large and small muscles"},{"code":"C17.3","title":"","text":"demonstrate strategies for engaging in cooperative play in a variety of games and activities"}]},{"code":"C18","title":"Movement Skills and Concepts","text":"develop movement skills and concepts as they use their growing bodies to move in a variety of ways and in a variety of contexts","specific":[{"code":"C18.1","title":"","text":"demonstrate spatial awareness in activities that require the use of large muscles"},{"code":"C18.2","title":"","text":"demonstrate control of large muscles with and without equipment"},{"code":"C18.3","title":"","text":"demonstrate balance, whole-body and hand-eye coordination, and flexibility in movement"},{"code":"C18.4","title":"","text":"demonstrate control of small muscles while working in a variety of learning areas and when using a variety of materials or equipment"},{"code":"C18.5","title":"","text":"demonstrate spatial awareness by doing activities that require the use of small muscles"}]}]},{"code":"D","title":"Belonging and Contributing","why":"Your child will develop a sense of self. Educators will encourage and support them to reach their full potential. They will develop social skills, self-confidence and a love for learning that they will take with them through school and life. Your child will develop: a positive understanding of themselves as a person and their unique strengths; a sense of connectedness to others, to their community and to the natural world; ways to consider different perspectives and life experiences as well as areas of connection; understanding of relationships and community and how people contribute to the world around them; problem-solving skills in social situations","overall":[{"code":"D19","title":"Identity and Self-Image ","text":"demonstrate a sense of identity and a positive self-image","specific":[{"code":"D19.1","title":"","text":"recognize personal interests, strengths, and accomplishments"},{"code":"D19.2","title":"","text":"identify and talk about their own interests and preferences"},{"code":"D19.3","title":"","text":"express their thoughts and share experiences"}]},{"code":"D20","title":"Understanding Perspectives and Canadian Identity","text":"show understanding of the multiple perspectives and diversity among individuals, groups, and communities in Canada, and identify areas of connection","specific":[{"code":"D20.1","title":"","text":"understand that everyone belongs to multiple groups and communities, and that these groups and communities together shape Canadian identity"},{"code":"D20.2","title":"","text":"describe, both verbally and non-verbally, ways in which they contribute to the various groups to which they belong"},{"code":"D20.3","title":"","text":"demonstrate respect for different perspectives and identify areas of connection"}]},{"code":"D21","title":"Self-Confidence","text":"recognize bias in ideas and develop the self-confidence to stand up for themselves and others against prejudice and discrimination","specific":[{"code":"D21.1","title":"","text":"stand up for themselves, and apply behaviours that enhance their own and others’ well-being"},{"code":"D21.2","title":"","text":"think critically about fair/unfair and biased behaviour towards both themselves and others, and act with compassion and kindness"},{"code":"D21.3","title":"","text":"recognize discriminatory and inequitable practices and behaviours and respond appropriately"}]},{"code":"D22","title":"People and Communities","text":"demonstrate an awareness of their surroundings","specific":[{"code":"D22.1","title":"","text":"recognize people in their community and talk about what they do"},{"code":"D22.2","title":"","text":"recognize places and buildings within their community, both natural and human-made, and talk about their functions"}]},{"code":"D23","title":"Respect and Care for Nature","text":"demonstrate an understanding of the natural world and the need to care for and respect the environment","specific":[{"code":"D23.1","title":"","text":"identify similarities and differences between local environments"},{"code":"D23.2","title":"","text":"describe what would happen if something in the local environment changed"},{"code":"D23.3","title":"","text":"describe ways in which they care for and respect the environment"}]},{"code":"D24","title":"Responding to Art","text":"respond to a variety of forms of dance, drama, music, and visual arts from various cultures and communities, including using their language and mathematics knowledge and skills","specific":[{"code":"D24.1","title":"","text":"express their responses to dance and drama"},{"code":"D24.2","title":"","text":"respond to texts and art forms from various cultures and communities through classroom drama activities and make connections to their own experiences"},{"code":"D24.3","title":"","text":"express their responses to music by moving, by making connections to their own experiences, or by talking about the musical form"}]},{"code":"D25","title":"Exploring and Creating Art","text":"explore and create a variety of art forms, including dance, drama, music, and visual arts","specific":[{"code":"D25.1","title":"","text":"explore the elements of dance, drama, music, and design"},{"code":"D25.2","title":"","text":"experiment with different materials, techniques, and processes used in a variety of art forms"},{"code":"D25.3","title":"","text":"use problem-solving skills and imagination to create forms of art"},{"code":"D25.4","title":"","text":"communicate ideas through dance, drama, music, and visual arts"}]}]}]}},"lang":{"g1":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-language","sourceLang":"en","strands":[{"code":"A","title":"Literacy Connections and Applications","why":"Students learn how transferable skills can support communication and engagement. Students also learn to navigate online environments safely, with appropriate permission, and manage their privacy. They demonstrate an understanding of the contributions and perspectives of a diversity of individuals and communities, including First Nations, Métis, and Inuit cultures. This learning is applied to learning related to the other three areas of the curriculum.","overall":[{"code":"A1","title":"Transferable Skills","text":"demonstrate an understanding of how the seven transferable skills (critical thinking and problem solving; innovation, creativity, and entrepreneurship; self-directed learning; collaboration; communication; global citizenship and sustainability; and digital literacy) are used in various language and literacy contexts","specific":[{"code":"A1.1","title":"Receptive and Expressive Communication","text":"identify how transferable skills can be used to support communication in various cultural, social, linguistic, and domain-specific contexts, and apply them when reading, listening to, viewing, and creating texts of various forms"},{"code":"A1.2","title":"Student Agency and Engagement","text":"demonstrate an understanding of how transferable skills help them to express their voice and be engaged in their learning"}]},{"code":"A2","title":"Digital Media Literacy","text":"demonstrate and apply the knowledge and skills needed to interact safely and responsibly in online environments, use digital and media tools to construct knowledge, and demonstrate learning as critical consumers and creators of media","specific":[{"code":"A2.1","title":"Digital Citizenship","text":"demonstrate an understanding of their rights and responsibilities when interacting online with appropriate permission, and make decisions that contribute positively to the development of their digital identity and those of their communities"},{"code":"A2.2","title":"Online Safety, Well-Being, and Etiquette","text":"demonstrate an understanding of how to navigate online environments safely, manage their privacy, and interact in a way that supports their well-being and that of others, including seeking appropriate permission"},{"code":"A2.3","title":"Research and Information Literacy","text":"gather, evaluate, and use information, considering various perspectives, to construct knowledge and demonstrate learning"},{"code":"A2.4","title":"Forms, Conventions, and Techniques","text":"demonstrate an understanding of the forms, conventions, and techniques of digital and media texts, and apply this understanding when analyzing texts"},{"code":"A2.5","title":"Media, Audience, and Production","text":"demonstrate an understanding of the interrelationships between the form, message, and context of a text, the audience, and the creator"},{"code":"A2.6","title":"Innovation and Design","text":"use digital and media tools to support stages of the design process and to develop creative solutions to authentic, real-world problems"},{"code":"A2.7","title":"Community and Cultural Awareness","text":"communicate and collaborate with various communities in a safe, respectful, responsible, and inclusive manner when using online platforms and environments, including digital and media tools, and demonstrate cultural awareness with members of the community"}]},{"code":"A3","title":"Applications, Connections, and Contributions","text":"apply language and literacy skills in cross-curricular and integrated learning, and demonstrate an understanding of, and make connections to, diverse voices, experiences, perspectives, histories, and contributions, including those of First Nations, Métis, and Inuit individuals, communities, groups, and nations","specific":[{"code":"A3.1","title":"Cross-Curricular and Integrated Learning","text":"apply the knowledge and skills developed in this grade to support learning in various subject areas and identify some ways this learning can be used in everyday life"},{"code":"A3.2","title":"Identity and Community","text":"demonstrate an understanding of the contributions, lived experiences, and perspectives of a diversity of individuals and communities, including those in Canada, by exploring the concepts of identity, self, and sense of belonging in culturally responsive and relevant texts"},{"code":"A3.3","title":"First Nations, Métis, and Inuit Perspectives and Ways of Knowing","text":"identify themes explored in First Nations, Métis, and Inuit cultures to demonstrate an understanding of the varied identities, perspectives, relationships, legacies, truths, and ways of knowing, being, and doing"}]}]},{"code":"B","title":"Foundations of Language","why":"Students identify and use listening skills and strategies before, during, and after listening, and identify the purpose and audience for speaking in various contexts. They identify and use oral and non-verbal communication strategies, and use word choice and grammar when speaking and communicating ideas. They use an understanding of the sound structure of spoken language to read and spell words. Students also identify and build simple and compound sentences.","overall":[{"code":"B1","title":"Oral and Non-Verbal Communication","text":"apply listening, speaking, and non-verbal communication skills and strategies to understand and communicate meaning in formal and informal contexts and for various purposes and audiences","specific":[{"code":"B1.1","title":"Effective Listening Skills","text":"use effective listening skills, including listening attentively and asking relevant questions, in formal and informal contexts, including conversations and classroom activities"},{"code":"B1.2","title":"Listening Strategies for Comprehension","text":"identify and use listening strategies before, during, and after listening to comprehend information communicated orally and non-verbally"},{"code":"B1.3","title":"Speaking Purposes and Strategies","text":"identify the purpose and audience for speaking in formal and informal contexts, and use appropriate speaking strategies, including taking turns, understanding when to speak, and knowing how much to say, to communicate clearly and coherently"},{"code":"B1.4","title":"Oral and Non-Verbal Communication Strategies","text":"identify and use oral and non-verbal communication strategies, including expression, gestures, and body language, to interpret or contribute to the meaning of messages"},{"code":"B1.5","title":"Word Choice, Syntax, and Grammar in Oral Communication","text":"use appropriate word choice, including new vocabulary, grammar, and cohesive phrases and sentences when speaking and communicating ideas"}]},{"code":"B2","title":"Language Foundations for Reading and Writing","text":"demonstrate an understanding of foundational language knowledge and skills, and apply this understanding when reading and writing","specific":[{"code":"B2.1","title":"Phonemic Awareness","text":"use understanding of the sound structure of spoken words to orally isolate, blend, and segment phonemes, from simple structures with two phonemes to structures with more phonemes"},{"code":"B2.2","title":"Alphabetic Knowledge","text":"name and form the upper- and lowercase letters both in and out of order and demonstrate knowledge of alphabetic order, with automaticity"},{"code":"B2.3","title":"Phonics: Grapheme-Phoneme Correspondence","text":"identify, read, and spell most common grapheme-phoneme correspondences of consonants and vowels, with automaticity"},{"code":"B2.4","title":"Word-Level Reading and Spelling: Using Phonics Knowledge ","text":"use phonics knowledge and phonemic blending to read words, and phonemic segmentation to spell phonetically regular words, in isolation and various text contexts"},{"code":"B2.5","title":"Word-Level Reading and Spelling: Using Orthographic Knowledge","text":"use developing orthographic knowledge, including position-based tendencies, to make a spelling choice or accurately pronounce a word when reading"},{"code":"B2.6","title":"Word-Level Reading and Spelling: Using Morphological Knowledge","text":"use developing knowledge of the meanings of words and common morphemes (i.e., bases, prefixes, and suffixes) to read and spell words"},{"code":"B2.7","title":"Vocabulary","text":"demonstrate an understanding of commonly used words, acquire and use explicitly taught vocabulary in various contexts, including other subject areas, and use their developing morphological knowledge to analyze and understand new words in context"},{"code":"B2.8","title":"Reading Fluency: Accuracy, Rate, and Prosody","text":"read simple words, short sentences, and paragraphs in a variety of texts fluently, with accuracy and appropriate pacing to support comprehension, and read aloud with expression"}]},{"code":"B3","title":"Language Conventions for Reading and Writing","text":"demonstrate an understanding of sentence structure, grammar, cohesive ties, and capitalization and punctuation, and apply this knowledge when reading and writing sentences, paragraphs, and a variety of texts","specific":[{"code":"B3.1","title":"Syntax and Sentence Structure","text":"identify and construct simple and compound sentences, including declarative, imperative, interrogative, and exclamatory sentences"},{"code":"B3.2","title":"Grammar","text":"demonstrate an understanding of the functions of parts of speech in sentences, including common singular and plural nouns, using the pronoun “I”, the past, present, and future verb tenses, common adjectives and adverbs, and common conjunctions, and use this knowledge to support comprehension and communicate meaning clearly"},{"code":"B3.3","title":"Capitalization and Punctuation","text":"use their understanding of the meaning and function of capitalization and punctuation to communicate meaning clearly, including the use of a capital letter at the beginning of a sentence and the appropriate punctuation mark at the end"}]}]},{"code":"C","title":"Comprehension: Understanding and Responding to Texts","why":"Students use their prior knowledge from reading and personal experiences to help them read and understand simple literary and informational texts, including cultural text forms. They learn and use strategies for understanding texts before, during, and after reading, and learn to understand simple elements of style used in texts and how they help communicate meaning. Students learn to recognize some cultural elements represented in texts and understand the narrator’s perspective.","overall":[{"code":"C1","title":"Knowledge about Texts","text":"apply foundational knowledge and skills to understand a variety of texts, including digital and media texts, by creators with diverse identities, perspectives, and experience, and demonstrate an understanding of the patterns, features, and elements of style associated with various text forms and genres","specific":[{"code":"C1.1","title":"Using Foundational Knowledge and Skills to Comprehend Texts","text":"read and comprehend short, simple texts, using knowledge of words, grammar, cohesive ties, sentence structures, and background knowledge"},{"code":"C1.2","title":"Text Forms and Genres","text":"identify simple literary and informational text forms and their associated genres"},{"code":"C1.3","title":"Text Patterns and Features","text":"identify some text patterns, such as sequencing and chronological order, and text features, including illustrations, symbols, and titles, associated with various text forms, and explain how they help readers, listeners, and viewers understand the meaning"},{"code":"C1.4","title":"Visual Elements of Texts","text":"demonstrate an understanding of the relationship between simple illustrations, images, and graphics and the text"},{"code":"C1.5","title":"Elements of Style","text":"identify some simple elements of style in texts, including voice, word choice, word patterns, and sentence structure, and describe how they help communicate meaning"},{"code":"C1.6","title":"Point of View","text":"identify the narrator’s point of view in a variety of texts, and suggest an alternative point of view to tell the story"},{"code":"C1.7","title":"Indigenous Context of Various Text Forms","text":"read, listen to, and view various forms of texts by diverse First Nations, Métis, and Inuit creators to demonstrate understanding of various aspects of First Nations, Métis, and Inuit histories, cultures, relationships, communities, groups, nations, and lived experiences"}]},{"code":"C2","title":"Comprehension Strategies","text":"apply comprehension strategies before, during, and after reading, listening to, and viewing a variety of texts, including digital and media texts, by creators with diverse identities, perspectives, and experience, in order to understand and clarify the meaning of texts","specific":[{"code":"C2.1","title":"Prereading: Activating Prior Knowledge","text":"activate prior knowledge, including knowledge gained from personal and text experiences, that they can use to understand the topics of new texts"},{"code":"C2.2","title":"Prereading: Identifying the Purpose for Reading, Listening, and Viewing","text":"identify purposes for engaging with texts, including enjoyment or finding information"},{"code":"C2.3","title":"Monitoring of Understanding: Making and Confirming Predictions","text":"make predictions using background knowledge, text features, and evidence from the text"},{"code":"C2.4","title":"Monitoring of Understanding: Ongoing Comprehension Check","text":"use strategies such as rereading, visualizing, and asking questions, to monitor their understanding of simple texts"},{"code":"C2.5","title":"Monitoring of Understanding: Making Connections","text":"identify connections between ideas expressed in simple texts and their knowledges and lived experiences, the ideas in other familiar texts, and the world around them"},{"code":"C2.6","title":"Summarizing: Identifying Relevant Information and Drawing Conclusions","text":"identify important information in a simple text, including the main idea"},{"code":"C2.7","title":"Reflecting on Learning","text":"identify strategies, such as activating prior knowledge and visualizing, that have helped them comprehend texts"}]},{"code":"C3","title":"Critical Thinking in Literacy","text":"apply critical thinking skills to deepen understanding of texts, and analyze how various perspectives and topics are communicated and addressed in a variety of texts, including digital, media, and cultural texts","specific":[{"code":"C3.1","title":"Literary Devices","text":"identify simple literary devices, including rhyme, alliteration, and onomatopoeia, and describe how they help communicate meaning"},{"code":"C3.2","title":"Making Inferences","text":"make simple inferences, using stated and implied information and ideas, to understand simple texts"},{"code":"C3.3","title":"Analyzing Texts","text":"analyze simple texts, including literary and informational texts, by identifying and sequencing important information and events"},{"code":"C3.4","title":"Analyzing Cultural Elements of Texts","text":"identify some cultural elements represented in various texts, including symbols and values, and explain how these elements contribute to the meaning"},{"code":"C3.5","title":"Perspectives within Texts","text":"identify explicit and implicit perspectives communicated in a text, and describe how these perspectives could influence an audience"},{"code":"C3.6","title":"Analysis and Response","text":"express personal thoughts and feelings about ideas presented in texts, such as ideas about diversity, inclusion, and accessibility"},{"code":"C3.7","title":"Indigenous Contexts","text":"identify some ways in which texts created by First Nations, Métis, and Inuit individuals, communities, groups, or nations communicate about historical periods, cultural experiences, and events, and how they relate to current lived experiences"},{"code":"C3.8","title":"Reflecting on Learning","text":"identify thinking skills that helped them understand simple texts"}]}]},{"code":"D","title":"Composition: Expressing Ideas and Creating Texts","why":"Students print letters and words. They generate, gather, and sequence ideas and create simple texts. They edit and proofread their work to prepare for publishing and presenting.","overall":[{"code":"D1","title":"Developing Ideas and Organizing Content","text":"plan, develop ideas, gather information, and organize content for creating texts of various forms, including digital and media texts, on a variety of topics","specific":[{"code":"D1.1","title":"Purpose and Audience ","text":"identify the topic, purpose, and audience for various simple texts they plan to create"},{"code":"D1.2","title":"Developing Ideas","text":"generate ideas about given and chosen topics, using simple strategies and drawing on various resources, including their own lived experiences, and learning from other subject areas"},{"code":"D1.3","title":"Research","text":"gather information and content relevant to a topic, using a single source"},{"code":"D1.4","title":"Organizing Content","text":"sort and sequence ideas and information, taking into account the text form and genre to be used"},{"code":"D1.5","title":"Reflecting on Learning","text":"identify the strategies that helped them to develop ideas for texts"}]},{"code":"D2","title":"Creating Texts ","text":"apply knowledge and understanding of various text forms and genres to create, revise, edit, and proofread their own texts, using a variety of media, tools, and/or strategies, and reflect critically on created texts","specific":[{"code":"D2.1","title":"Producing Drafts","text":"draft short, simple texts of various forms and genres, including personal narratives, persuasive texts, and procedural texts, using a variety of media, tools, and strategies"},{"code":"D2.2","title":"Printing","text":"print letters and words with appropriate formation patterns, size, placement, and spacing"},{"code":"D2.3","title":"Voice","text":"demonstrate a personal voice in their texts, with a focus on using words that express their thoughts, feelings, and opinions about the topic"},{"code":"D2.4","title":"Point of View","text":"identify the point of view, including first person, used in their texts"},{"code":"D2.5","title":"Editing and Proofreading","text":"make simple edits to draft texts, such as changes to capitalization, punctuation, and spelling"}]},{"code":"D3","title":"Publishing, Presenting, and Reflecting","text":"select suitable and effective media, techniques, and tools to publish and present final texts, and critically analyze how well the texts address various topics","specific":[{"code":"D3.1","title":"Producing Final Texts","text":"produce final texts, using simple techniques, to achieve the intended effect"},{"code":"D3.2","title":"Publishing and Presenting Texts","text":"present the texts they have created using appropriate strategies, including by reading aloud with expression"},{"code":"D3.3","title":"Reflecting on Learning","text":"identify a strategy they found helpful when presenting texts"}]}]}]},"g2":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-language","sourceLang":"en","strands":[{"code":"A","title":"Literacy Connections and Applications","why":"Students learn how transferable skills can support communication and engaging with others. They also learn to navigate online environments safely, with appropriate permission, and manage their privacy. They demonstrate an understanding of the contributions and perspectives of a diversity of individuals and communities, including First Nations, Métis, and Inuit cultures. This learning is applied to learning related to the other three areas of the curriculum.","overall":[{"code":"A1","title":"Transferable Skills","text":"demonstrate an understanding of how the seven transferable skills (critical thinking and problem solving; innovation, creativity, and entrepreneurship; self-directed learning; collaboration; communication; global citizenship and sustainability; and digital literacy) are used in various language and literacy contexts","specific":[{"code":"A1.1","title":"Receptive and Expressive Communication","text":"identify how transferable skills can be used to support communication in various cultural, social, linguistic, and domain-specific contexts, and apply them when reading, listening to, viewing, and creating texts of various forms"},{"code":"A1.2","title":"Student Agency and Engagement","text":"demonstrate an understanding of how transferable skills help them to express their voice and be engaged in their learning"}]},{"code":"A2","title":"Digital Media Literacy","text":"demonstrate and apply the knowledge and skills needed to interact safely and responsibly in online environments, use digital and media tools to construct knowledge, and demonstrate learning as critical consumers and creators of media","specific":[{"code":"A2.1","title":"Digital Citizenship","text":"demonstrate an understanding of their rights and responsibilities when interacting online with appropriate permission, and make decisions that contribute positively to the development of their digital identity and those of their communities"},{"code":"A2.2","title":"Online Safety, Well-Being, and Etiquette","text":"demonstrate an understanding of how to navigate online environments safely, manage their privacy, and interact in a way that supports their well-being and that of others, including seeking appropriate permission"},{"code":"A2.3","title":"Research and Information Literacy","text":"gather, evaluate, and use information, considering various perspectives, to construct knowledge and demonstrate learning"},{"code":"A2.4","title":"Forms, Conventions, and Techniques","text":"demonstrate an understanding of the forms, conventions, and techniques of digital and media texts, and apply this understanding when analyzing texts"},{"code":"A2.5","title":"Media, Audience, and Production","text":"demonstrate an understanding of the interrelationships between the form, message, and context of a text, the audience, and the creator"},{"code":"A2.6","title":"Innovation and Design","text":"use digital and media tools to support stages of the design process and to develop creative solutions to authentic, real-world problems"},{"code":"A2.7","title":"Community and Cultural Awareness","text":"communicate and collaborate with various communities in a safe, respectful, responsible, and inclusive manner when using online platforms and environments, including digital and media tools, and demonstrate cultural awareness with members of the community"}]},{"code":"A3","title":"Applications, Connections, and Contributions","text":"apply language and literacy skills in cross-curricular and integrated learning, and demonstrate an understanding of, and make connections to, diverse voices, experiences, perspectives, histories, and contributions, including those of First Nations, Métis, and Inuit individuals, communities, groups, and nations","specific":[{"code":"A3.1","title":"Cross-Curricular and Integrated Learning","text":"apply the knowledge and skills developed in this grade to support learning in various subject areas and identify some ways this learning can be used in everyday life"},{"code":"A3.2","title":"Identity and Community","text":"demonstrate an understanding of the contributions, lived experiences, and perspectives of a diversity of individuals and communities, including those in Canada, by exploring the concepts of identity, self, and sense of belonging in culturally responsive and relevant texts"},{"code":"A3.3","title":"First Nations, Métis, and Inuit Perspectives and Ways of Knowing","text":"identify themes explored in First Nations, Métis, and Inuit cultures to demonstrate an understanding of the varied identities, perspectives, relationships, legacies, truths, and ways of knowing, being, and doing"}]}]},{"code":"B","title":"Foundations of Language","why":"Students use listening skills and strategies, including asking questions, and identify the purpose and audience for speaking in formal and informal contexts. They identify and use oral and non-verbal communication strategies and use word choice and grammar when speaking and communicating ideas. They use phonics knowledge to read and spell words. They also identify and build declarative, imperative, interrogative, and exclamatory sentences.","overall":[{"code":"B1","title":"Oral and Non-Verbal Communication","text":"apply listening, speaking, and non-verbal communication skills and strategies to understand and communicate meaning in formal and informal contexts and for various purposes and audiences","specific":[{"code":"B1.1","title":"Effective Listening Skills","text":"use effective listening skills, including asking relevant questions, restating what they heard, and expressing interest, in formal and informal contexts and for various purposes, including in conversations and various classroom activities"},{"code":"B1.2","title":"Listening Strategies for Comprehension","text":"identify and use a variety of listening strategies before, during, and after listening to comprehend information communicated orally and non-verbally, and to recognize when a message is difficult to understand"},{"code":"B1.3","title":"Speaking Purposes and Strategies","text":"identify the purpose and audience for speaking in formal and informal contexts, and use appropriate speaking strategies, including taking turns and staying on topic, to communicate meaning clearly and coherently"},{"code":"B1.4","title":"Oral and Non-Verbal Communication Strategies","text":"identify and use oral and non-verbal communication strategies, including expression, gestures, and body language, and demonstrate an understanding of how these strategies can contribute to the meaning being conveyed"},{"code":"B1.5","title":"Word Choice, Syntax, and Grammar in Oral Communication","text":"use appropriate word choice, including new vocabulary, grammar, and cohesive sentences when speaking and communicating ideas, to support audience comprehension"}]},{"code":"B2","title":"Language Foundations for Reading and Writing","text":"demonstrate an understanding of foundational language knowledge and skills, and apply this understanding when reading and writing","specific":[{"code":"B2.1","title":"Word-Level Reading and Spelling: Using Phonics Knowledge","text":"use phonics knowledge, including phonemic blending to read words and set for variability to correct approximations, and phonemic segmentation to spell phonetically regular monosyllabic and multisyllabic words, in isolation and various text contexts"},{"code":"B2.2","title":"Word-Level Reading and Spelling: Using Orthographic Knowledge","text":"use orthographic knowledge, including position-based tendencies, to make a spelling choice or accurately pronounce a word when reading"},{"code":"B2.3","title":"Word-Level Reading and Spelling: Using Morphological Knowledge","text":"use developing knowledge of the meanings of words and common morphemes (i.e., bases, prefixes, and suffixes) to read and spell words"},{"code":"B2.4","title":"Vocabulary","text":"demonstrate an understanding of a variety of words, acquire and use explicitly taught vocabulary in various contexts, including other subject areas, and use their developing morphological knowledge to analyze and understand new words in context"},{"code":"B2.5","title":"Reading Fluency: Accuracy, Rate, and Prosody","text":"read words, sentences, and paragraphs in a variety of texts fluently, with accuracy and appropriate pacing to support comprehension, and read aloud with expression and intonation"}]},{"code":"B3","title":"Language Conventions for Reading and Writing","text":"demonstrate an understanding of sentence structure, grammar, cohesive ties, and capitalization and punctuation, and apply this knowledge when reading and writing sentences, paragraphs, and a variety of texts","specific":[{"code":"B3.1","title":"Syntax and Sentence Structure","text":"identify and construct declarative, imperative, interrogative, and exclamatory sentences, including compound sentences"},{"code":"B3.2","title":"Grammar","text":"demonstrate an understanding of the functions of parts of speech in sentences, including abstract and collective nouns, personal pronouns, forms of the verb “to be”, comparative and superlative adjectives, conjunctions, and recognition of the words that adverbs modify, and use this knowledge to support comprehension and communicate meaning clearly"},{"code":"B3.3","title":"Capitalization and Punctuation","text":"use their understanding of the meaning and function of capitalization and punctuation to communicate clearly, including capital letters for proper nouns, commas to separate items in lists, apostrophes for possessives, and quotation marks for direct speech"}]}]},{"code":"C","title":"Comprehension: Understanding and Responding to Texts","why":"Students use their prior knowledge from reading and personal experiences to help them read and understand simple literary and informational texts, including cultural text forms. They learn and use strategies for understanding texts before, during, and after reading, identify purposes for reading, and learn to understand simple elements of style used in texts and how they help communicate meaning. They begin to understand different perspectives and cultural elements represented in texts.","overall":[{"code":"C1","title":"Knowledge about Texts","text":"apply foundational knowledge and skills to understand a variety of texts, including digital and media texts, by creators with diverse identities, perspectives, and experience, and demonstrate an understanding of the patterns, features, and elements of style associated with various text forms and genres","specific":[{"code":"C1.1","title":"Using Foundational Knowledge and Skills to Comprehend Texts","text":"read and comprehend short texts, using knowledge of words, grammar, cohesive ties, sentence structures, and background knowledge"},{"code":"C1.2","title":"Text Forms and Genres ","text":"identify and describe some characteristics of literary and informational text forms and their associated genres"},{"code":"C1.3","title":"Text Patterns and Features","text":"identify some text patterns, such as chronological order and journal entry, and text features, including table of contents, charts, and icons, associated with various text forms, and explain how they help readers, listeners, and viewers understand the meaning"},{"code":"C1.4","title":"Visual Elements of Texts","text":"identify ways in which images, graphics, and visual design create, communicate, and contribute to meaning in a variety of texts"},{"code":"C1.5","title":"Elements of Style","text":"identify some simple elements of style in texts, including voice, word choice, word patterns, and sentence structure, and explain how they help communicate meaning"},{"code":"C1.6","title":"Point of View","text":"identify the narrator’s point of view, including first person or third person, in simple texts, and suggest an alternative point of view to tell the story"},{"code":"C1.7","title":"Indigenous Context of Various Text Forms","text":"read, listen to, and view various forms of texts by diverse First Nations, Métis, and Inuit creators to demonstrate understanding of various aspects of First Nations, Métis, and Inuit histories, cultures, relationships, communities, groups, nations, and lived experiences"}]},{"code":"C2","title":"Comprehension Strategies","text":"apply comprehension strategies before, during, and after reading, listening to, and viewing a variety of texts, including digital and media texts, by creators with diverse identities, perspectives, and experience, in order to understand and clarify the meaning of texts","specific":[{"code":"C2.1","title":"Prereading: Activating Prior Knowledge","text":"activate prior knowledge, including knowledge gained from personal and text experiences, that they can use to make connections and understand the topic and form of new texts"},{"code":"C2.2","title":"Prereading: Identifying the Purpose for Reading, Listening, and Viewing","text":"identify various purposes for engaging with texts, including enjoyment or finding information"},{"code":"C2.3","title":"Monitoring of Understanding: Making and Confirming Predictions","text":"make predictions using background knowledge, text features, and evidence from the text"},{"code":"C2.4","title":"Monitoring of Understanding: Ongoing Comprehension Check ","text":"use strategies such as rereading, visualizing, and asking questions, to monitor their understanding of simple texts"},{"code":"C2.5","title":"Monitoring of Understanding: Making Connections","text":"identify connections between ideas expressed in simple texts and their knowledges and lived experiences, the ideas in other familiar texts, and the world around them"},{"code":"C2.6","title":"Summarizing: Identifying Relevant Information and Drawing Conclusions","text":"identify the main idea in a simple text, and relate important details in sequence"},{"code":"C2.7","title":"Reflecting on Learning","text":"identify strategies, such as rereading, visualizing, and asking questions, that have helped them comprehend various texts"}]},{"code":"C3","title":"Critical Thinking in Literacy","text":"apply critical thinking skills to deepen understanding of texts, and analyze how various perspectives and topics are communicated and addressed in a variety of texts, including digital, media, and cultural texts","specific":[{"code":"C3.1","title":"Literary Devices","text":"identify simple literary devices, including consonance and simile, and describe how they help communicate meaning"},{"code":"C3.2","title":"Making Inferences","text":"make simple inferences using stated and implied information and ideas to understand simple texts"},{"code":"C3.3","title":"Analyzing Texts","text":"analyze simple texts, including literary and informational texts, by identifying and sequencing important information, and comparing and contrasting simple elements"},{"code":"C3.4","title":"Analyzing Cultural Elements of Texts","text":"identify some cultural elements represented in various texts, including symbols, language, and values, and pose questions and share ideas about how these elements contribute to the meaning"},{"code":"C3.5","title":"Perspectives within Texts","text":"identify explicit and implicit perspectives communicated in a text, providing evidence, and describe how these perspectives could influence an audience"},{"code":"C3.6","title":"Analysis and Response","text":"express personal thoughts and feelings about ideas presented in texts, such as ideas about diversity, inclusion, and accessibility"},{"code":"C3.7","title":"Indigenous Contexts","text":"identify some ways in which texts created by First Nations, Métis, and Inuit individuals, communities, groups, or nations communicate about historical periods, cultural experiences, and events, and how they relate to current lived experiences"},{"code":"C3.8","title":"Reflecting on Learning","text":"identify thinking skills that have helped them analyze and better understand simple texts"}]}]},{"code":"D","title":"Composition: Expressing Ideas and Creating Texts","why":"Students print legibly and fluently. They generate and develop ideas using simple strategies and create short texts of various forms and genres. They revise and edit their work to prepare for publishing and presenting.","overall":[{"code":"D1","title":"Developing Ideas and Organizing Content","text":"plan, develop ideas, gather information, and organize content for creating texts of various forms, including digital and media texts, on a variety of topics","specific":[{"code":"D1.1","title":"Purpose and Audience","text":"identify the topic, purpose, and audience for various texts they plan to create"},{"code":"D1.2","title":"Developing Ideas","text":"generate and develop ideas about given and chosen topics, using simple strategies, and drawing on various resources, including their own lived experiences, and learning from other subject areas"},{"code":"D1.3","title":"Research","text":"gather information and content relevant to a topic, using three or more sources"},{"code":"D1.4","title":"Organizing Content","text":"sort and sequence ideas and information, taking into account the text form and genre to be used"},{"code":"D1.5","title":"Reflecting on Learning","text":"identify the strategies that helped them develop ideas for texts"}]},{"code":"D2","title":"Creating Texts","text":"apply knowledge and understanding of various text forms and genres to create, revise, edit, and proofread their own texts, using a variety of media, tools, and strategies, and reflect critically on created texts","specific":[{"code":"D2.1","title":"Producing Drafts","text":"draft short texts of various forms and genres, including personal narratives, persuasive texts, and procedural texts, using a variety of media, tools, and strategies"},{"code":"D2.2","title":"Printing","text":"print legibly and fluently, with appropriate formation patterns, size, placement, and spacing"},{"code":"D2.3","title":"Voice","text":"demonstrate a personal voice in their texts, using descriptive words to express their thoughts, feelings, and opinions about the topic"},{"code":"D2.4","title":"Point of View","text":"identify the point of view, including first person, used in their texts"},{"code":"D2.5","title":"Revision","text":"make revisions to texts using feedback from others, such as adding or deleting sentences"},{"code":"D2.6","title":"Editing and Proofreading","text":"make simple edits to draft texts, such as checking for errors in capitalization, punctuation, and spelling"}]},{"code":"D3","title":"Publishing, Presenting, and Reflecting","text":"select suitable and effective media, techniques, and tools to publish and present final texts, and critically analyze how well the texts address various topics","specific":[{"code":"D3.1","title":"Producing Final Texts","text":"produce final texts using simple techniques, to achieve the intended effect"},{"code":"D3.2","title":"Publishing and Presenting Texts","text":"present the texts they have created using appropriate strategies, including by reading aloud with expression"},{"code":"D3.3","title":"Reflecting on Learning","text":"identify a few strategies they found helpful when presenting texts"}]}]}]},"g3":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-language","sourceLang":"en","strands":[{"code":"A","title":"Literacy Connections and Applications","why":"Students learn how transferable skills can support communication and engagement. They also learn to navigate online environments safely, with appropriate permission, and manage their privacy. They demonstrate an understanding of the contributions and perspectives of a diversity of individuals and communities, including First Nations, Métis, and Inuit cultures. This learning is applied to learning related to the other three areas of the curriculum.","overall":[{"code":"A1","title":"Transferable Skills","text":"demonstrate an understanding of how the seven transferable skills (critical thinking and problem solving; innovation, creativity, and entrepreneurship; self-directed learning; collaboration; communication; global citizenship and sustainability; and digital literacy) are used in various language and literacy contexts","specific":[{"code":"A1.1","title":"Receptive and Expressive Communication","text":"identify how transferable skills can be used to support communication in various cultural, social, linguistic, and domain-specific contexts, and apply them when reading, listening to, viewing, and creating texts of various forms"},{"code":"A1.2","title":"Student Agency and Engagement","text":"demonstrate an understanding of how transferable skills help them to express their voice and be engaged in their learning"}]},{"code":"A2","title":"Digital Media Literacy","text":"demonstrate and apply the knowledge and skills needed to interact safely and responsibly in online environments, use digital and media tools to construct knowledge, and demonstrate learning as critical consumers and creators of media","specific":[{"code":"A2.1","title":"Digital Citizenship","text":"demonstrate an understanding of their rights and responsibilities when interacting online with appropriate permission, and make decisions that contribute positively to the development of their digital identity and those of their communities"},{"code":"A2.2","title":"Online Safety, Well-Being, and Etiquette","text":"demonstrate an understanding of how to navigate online environments safely, manage their privacy, and interact in a way that supports their well-being and that of others, including seeking appropriate permission"},{"code":"A2.3","title":"Research and Information Literacy","text":"gather, evaluate, and use information, considering various perspectives, to construct knowledge and demonstrate learning"},{"code":"A2.4","title":"Forms, Conventions, and Techniques","text":"demonstrate an understanding of the forms, conventions, and techniques of digital and media texts, and apply this understanding when analyzing texts"},{"code":"A2.5","title":"Media, Audience, and Production","text":"demonstrate an understanding of the interrelationships between the form, message, and context of a text, the audience, and the creator"},{"code":"A2.6","title":"Innovation and Design","text":"use digital and media tools to support stages of the design process and to develop creative solutions to authentic, real-world problems"},{"code":"A2.7","title":"Community and Cultural Awareness","text":"communicate and collaborate with various communities in a safe, respectful, responsible, and inclusive manner when using online platforms and environments, including digital and media tools, and demonstrate cultural awareness with members of the community"}]},{"code":"A3","title":"Applications, Connections, and Contributions","text":"apply language and literacy skills in cross-curricular and integrated learning, and demonstrate an understanding of, and make connections to, diverse voices, experiences, perspectives, histories, and contributions, including those of First Nations, Métis, and Inuit individuals, communities, groups, and nations","specific":[{"code":"A3.1","title":"Cross-Curricular and Integrated Learning","text":"apply the knowledge and skills developed in this grade to support learning in various subject areas and identify some ways this learning can be used in everyday life"},{"code":"A3.2","title":"Identity and Community","text":"demonstrate an understanding of the contributions, lived experiences, and perspectives of a diversity of individuals and communities, including those in Canada, by exploring the concepts of identity, self, and sense of belonging in culturally responsive and relevant texts"},{"code":"A3.3","title":"First Nations, Métis, and Inuit Perspectives and Ways of Knowing","text":"identify themes explored in First Nations, Métis, and Inuit cultures to demonstrate an understanding of the varied identities, perspectives, relationships, legacies, truths, and ways of knowing, being, and doing"}]}]},{"code":"B","title":"Foundations of Language","why":"Students use a variety of listening skills and strategies, including asking relevant questions, and identify the purpose and audience for speaking in formal and informal contexts. They identify and use oral and non-verbal communication strategies, such as body language, and use word choice, sentence structure, and grammar when speaking and communicating ideas. They use knowledge of the meaning of words to read and spell. They also identify and build simple, compound, and complex sentences.","overall":[{"code":"B1","title":"Oral and Non-Verbal Communication","text":"apply listening, speaking, and non-verbal communication skills and strategies to understand and communicate meaning in formal and informal contexts and for various purposes and audiences","specific":[{"code":"B1.1","title":"Effective Listening Skills","text":"use effective listening skills, including asking questions to clarify information and ideas, in formal and informal contexts and for various purposes, including in small- and large-group conversations and various classroom activities"},{"code":"B1.2","title":"Listening Strategies for Comprehension ","text":"select and use a variety of listening strategies before, during, and after listening to comprehend information communicated orally and non-verbally, recognize when a message is difficult to understand, and develop an appropriate response"},{"code":"B1.3","title":"Speaking Purposes and Strategies","text":"identify the purpose and audience for speaking in formal and informal contexts, and use appropriate speaking strategies, including establishing a rapport with the audience, to communicate clearly and coherently"},{"code":"B1.4","title":"Oral and Non-Verbal Communication Strategies","text":"identify and use oral and non-verbal communication strategies, including expression, gestures, and body language, and demonstrate an understanding of how these strategies can contribute to the meaning being conveyed"},{"code":"B1.5","title":"Word Choice, Syntax, and Grammar in Oral Communication","text":"use appropriate word choice, including new vocabulary, grammar, and cohesive sentences when speaking and communicating ideas in various contexts, to support audience comprehension"}]},{"code":"B2","title":"Language Foundations for Reading and Writing","text":"demonstrate an understanding of foundational language knowledge and skills, and apply this understanding when reading and writing","specific":[{"code":"B2.1","title":"Word-Level Reading and Spelling: Using Phonics Knowledge ","text":"use consolidated phonics knowledge, including phonemic blending to read words and set for variability to correct approximations, and phonemic segmentation to spell phonetically regular monosyllabic and multisyllabic words, in isolation and various text contexts"},{"code":"B2.2","title":"Word-Level Reading and Spelling: Using Orthographic Knowledge","text":"use consolidated orthographic knowledge, including position-based tendencies, to make a spelling choice or accurately pronounce a word when reading"},{"code":"B2.3","title":"Word-Level Reading and Spelling: Using Morphological Knowledge","text":"use developing knowledge of the meanings of words and morphemes (i.e., bases, prefixes, and suffixes) to read and spell words"},{"code":"B2.4","title":"Vocabulary","text":"demonstrate an understanding of a variety of words, acquire and use explicitly taught vocabulary in various contexts, including other subject areas, and use morphological knowledge to analyze and understand new words in context"},{"code":"B2.5","title":"Reading Fluency: Accuracy, Rate, and Prosody","text":"read words, complex sentences, and paragraphs in a variety of texts fluently, with accuracy and appropriate pacing to support comprehension, and read aloud using varied expression and intonation according to the purpose of reading"}]},{"code":"B3","title":"Language Conventions for Reading and Writing\r","text":"demonstrate an understanding of sentence structure, grammar, cohesive ties, and capitalization and punctuation, and apply this knowledge when reading and writing sentences, paragraphs, and a variety of texts","specific":[{"code":"B3.1","title":"Syntax and Sentence Structure","text":"identify and construct various sentence types and forms, including simple sentences, compound sentences, and complex sentences containing adverbial clauses"},{"code":"B3.2","title":"Grammar","text":"demonstrate an understanding of the functions of parts of speech in sentences, including possessive nouns, linking verbs and the progressive tense, interrogative adjectives and adverbs, and prepositions and interjections, and use this knowledge to support comprehension and communicate meaning clearly"},{"code":"B3.3","title":"Capitalization and Punctuation","text":"use their understanding of the meaning and function of capitalization and punctuation to communicate meaning clearly, including the use of capital letters in dialogue and for words in titles, commas and quotation marks to mark direct speech and direct quotations from texts within sentences, and apostrophes to indicate contractions"}]}]},{"code":"C","title":"Comprehension: Understanding and Responding to Texts","why":"Students use their prior knowledge from reading and personal experiences to help them understand various literary and informational texts, including cultural text forms, and describe how their characteristics help communicate meaning. They explore how visuals such as images and graphics help to create, communicate, and contribute to meaning. They identify purposes for reading and learn about some elements of style used in texts and how they convey meaning. They begin to understand different perspectives and cultural elements represented in texts.","overall":[{"code":"C1","title":"Knowledge about Texts","text":"apply foundational knowledge and skills to understand a variety of texts, including digital and media texts, by creators with diverse identities, perspectives, and experience, and demonstrate an understanding of the patterns, features, and elements of style associated with various text forms and genres","specific":[{"code":"C1.1","title":"Using Foundational Knowledge and Skills to Comprehend Texts","text":"read and comprehend various texts, using knowledge of words, grammar, cohesive ties, sentence structures, and background knowledge"},{"code":"C1.2","title":"Text Forms and Genres","text":"identify and describe some characteristics of literary and informational text forms and their associated genres"},{"code":"C1.3","title":"Text Patterns and Features","text":"identify some text patterns, such as order of importance and cause and effect, and text features, such as headings and an index, associated with various text forms, and explain how they help readers, listeners, and viewers understand the meaning"},{"code":"C1.4","title":"Visual Elements of Texts","text":"describe ways in which images, graphics, and visual design are used in a given text, and demonstrate an understanding of their purpose and connection to the content of the text"},{"code":"C1.5","title":"Elements of Style","text":"identify some elements of style in texts, including voice, word choice, word patterns, and sentence structure, and explain how they help communicate meaning"},{"code":"C1.6","title":"Point of View","text":"identify the narrator’s point of view, including first person or third person, in a variety of texts, and suggest alternative points of view to tell each story"},{"code":"C1.7","title":"Indigenous Context of Various Text Forms","text":"read, listen to, and view various forms of texts by diverse First Nations, Métis, and Inuit creators and demonstrate understanding of various aspects of First Nations, Métis, and Inuit histories, cultures, relationships, communities, groups, nations, and lived experiences"}]},{"code":"C2","title":"Comprehension Strategies","text":"apply comprehension strategies before, during, and after reading, listening to, and viewing a variety of texts, including digital and media texts, by creators with diverse identities, perspectives, and experience, in order to understand and clarify the meaning of texts","specific":[{"code":"C2.1","title":"Prereading: Activating Prior Knowledge","text":"activate prior knowledge, including knowledge gained from personal and text experiences, that they can use to make connections and understand the topic and form of new texts"},{"code":"C2.2","title":"Prereading: Identifying the Purpose for Reading, Listening, and Viewing","text":"identify specific purposes for engaging with texts, including learning facts or information, or to gain insight or new perspectives"},{"code":"C2.3","title":"Monitoring of Understanding: Making and Confirming Predictions","text":"make predictions using background knowledge, text features, and evidence from the text, and adjust their understanding based on new information"},{"code":"C2.4","title":"Monitoring of Understanding: Ongoing Comprehension Check","text":"use strategies such as rereading, visualizing, and asking questions, to monitor and confirm their understanding of various texts"},{"code":"C2.5","title":"Monitoring of Understanding: Making Connections","text":"identify connections between ideas expressed in texts and their knowledges and lived experiences, the ideas in other texts, and the world around them"},{"code":"C2.6","title":"Summarizing: Identifying Relevant Information and Drawing Conclusions","text":"identify the main idea in a simple text, and relate important details in sequence"},{"code":"C2.7","title":"Reflecting on Learning","text":"describe how strategies, such as visualizing, making predictions, and connecting to their experiences, have helped them comprehend various texts"}]},{"code":"C3","title":"Critical Thinking in Literacy","text":"apply critical thinking skills to deepen understanding of texts, and analyze how various perspectives and topics are communicated and addressed in a variety of texts, including digital, media, and cultural texts","specific":[{"code":"C3.1","title":"Literary Devices","text":"identify literary devices, including metaphor and assonance, and describe how they help communicate meaning"},{"code":"C3.2","title":"Making Inferences","text":"make inferences using stated and implied information and ideas to understand texts"},{"code":"C3.3","title":"Analyzing Texts","text":"analyze various texts, including literary and informational texts, by identifying main and supporting ideas, sequencing information, and comparing and contrasting elements"},{"code":"C3.4","title":"Analyzing Cultural Elements of Texts","text":"identify some cultural elements represented in various texts, including symbols, language, and values, and pose questions and share ideas about how these elements contribute to the meaning"},{"code":"C3.5","title":"Perspectives within Texts","text":"identify explicit and implicit perspectives communicated in texts, providing evidence, and explain how these perspectives could influence an audience"},{"code":"C3.6","title":"Analysis and Response","text":"describe personal thoughts and feelings about ideas presented in texts, such as ideas about diversity, inclusion, and accessibility"},{"code":"C3.7","title":"Indigenous Contexts","text":"identify some ways in which texts created by First Nations, Métis, and Inuit individuals, communities, groups, or nations communicate about historical periods, cultural experiences, and events, and how they relate to current lived experiences"},{"code":"C3.8","title":"Reflecting on Learning","text":"identify thinking skills that have helped them analyze and better understand various texts"}]}]},{"code":"D","title":"Composition: Expressing Ideas and Creating Texts","why":"Students begin to write cursive. They generate and develop ideas using various strategies and create short texts of various forms and genres, demonstrating a personal voice in their texts. They revise and edit their work to improve accuracy and style and produce final texts and present them using appropriate strategies.","overall":[{"code":"D1","title":"Developing Ideas and Organizing Content","text":"plan, develop ideas, gather information, and organize content for creating texts of various forms, including digital and media texts, on a variety of topics","specific":[{"code":"D1.1","title":"Purpose and Audience","text":"identify the topic, purpose, and audience for various texts they plan to create, and describe how the chosen text form and genre will help communicate their intended meaning"},{"code":"D1.2","title":"Developing Ideas","text":"generate and develop ideas about given and chosen topics, using various strategies, and drawing on various resources, including their own lived experiences, and learning from other subject areas"},{"code":"D1.3","title":"Research","text":"gather information and content relevant to a topic, using three or more sources"},{"code":"D1.4","title":"Organizing Content","text":"sort and sequence ideas and information, using appropriate strategies and tools, taking into account the text form and genre to be used"},{"code":"D1.5","title":"Reflecting on Learning","text":"identify the strategies that helped them develop ideas for texts and organize content"}]},{"code":"D2","title":"Creating Texts","text":"apply knowledge and understanding of various text forms and genres to create, revise, edit, and proofread their own texts, using a variety of media, tools, and strategies, and reflect critically on created texts","specific":[{"code":"D2.1","title":"Producing Drafts","text":"draft short texts of various forms and genres, including narrative, persuasive, and informational texts, using a variety of media, tools, and strategies"},{"code":"D2.2","title":"Printing and Handwriting","text":"begin to write in cursive, forming letters with appropriate formation patterns, size, placement, and spacing"},{"code":"D2.3","title":"Voice","text":"demonstrate a personal voice in their texts, using descriptive words and sentence patterns to express their thoughts, feelings, and opinions about the topic"},{"code":"D2.4","title":"Point of View","text":"identify the point of view, including first person or third person, used in their texts"},{"code":"D2.5","title":"Revision","text":"make simple revisions to draft texts, including replacing words and adding sentences, to improve content and clarity, using feedback from others"},{"code":"D2.6","title":"Editing and Proofreading","text":"edit draft texts to improve accuracy and style, checking for errors in spelling, punctuation, grammar, and text conventions, and proofread edited texts to make corrections"}]},{"code":"D3","title":"Publishing, Presenting, and Reflecting","text":"select suitable and effective media, techniques, and tools to publish and present final texts, and critically analyze how well the texts address various topics","specific":[{"code":"D3.1","title":"Producing Final Texts","text":"produce final texts using simple techniques, to achieve the intended effect"},{"code":"D3.2","title":"Publishing and Presenting Texts","text":"present the texts they have created using appropriate strategies, including by reading aloud with expression"},{"code":"D3.3","title":"Reflecting on Learning","text":"identify the strategies that helped them present and communicate their message, and explain how they helped them improve as a text creator"}]}]}]},"g4":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-language","sourceLang":"en","strands":[{"code":"A","title":"Literacy Connections and Applications","why":"Students explain how transferable skills can help them express their unique voice. They gather, evaluate, and use information, considering its credibility and the perspectives found in different sources of information. They also explain themes explored in a diversity of First Nations, Métis and Inuit cultures. This learning is applied to learning related to the other three areas of the curriculum.","overall":[{"code":"A1","title":"Transferable Skills","text":"demonstrate an understanding of how the seven transferable skills (critical thinking and problem solving; innovation, creativity, and entrepreneurship; self-directed learning; collaboration; communication; global citizenship and sustainability; and digital literacy) are used in various language and literacy contexts","specific":[{"code":"A1.1","title":"Receptive and Expressive Communication","text":"explain how transferable skills can be used to support communication in various cultural, social, linguistic, and domain-specific contexts, and apply them when reading, listening to, viewing, and creating texts of various forms"},{"code":"A1.2","title":"Student Agency and Engagement","text":"explain how transferable skills help them to express their voice, be engaged in their learning, and plan the next steps to develop their capabilities and potential"}]},{"code":"A2","title":"Digital Media Literacy","text":"demonstrate and apply the knowledge and skills needed to interact safely and responsibly in online environments, use digital and media tools to construct knowledge, and demonstrate learning as critical consumers and creators of media","specific":[{"code":"A2.1","title":"Digital Citizenship","text":"explain their rights and responsibilities when interacting online with appropriate permission, and make decisions that contribute positively to the development of their digital identity and those of their communities"},{"code":"A2.2","title":"Online Safety, Well-Being, and Etiquette","text":"demonstrate an understanding of how to navigate online environments safely, manage their privacy and personal data, and interact in a way that supports their well-being and that of others, including seeking appropriate permission"},{"code":"A2.3","title":"Research and Information Literacy","text":"gather, evaluate, and use information, considering validity, credibility, accuracy, and perspectives, to construct knowledge, create texts, and demonstrate learning"},{"code":"A2.4","title":"Forms, Conventions, and Techniques","text":"demonstrate an understanding of the forms, conventions, and techniques of digital and media texts, consider the impact on the audience, and apply this understanding when analyzing and creating texts"},{"code":"A2.5","title":"Media, Audience, and Production","text":"demonstrate an understanding of the interrelationships between the form, message, and context of texts, the intended audience, and the purpose for production"},{"code":"A2.6","title":"Innovation and Design","text":"select and use appropriate digital and media tools to support the design process and address authentic, relevant, real-world problems by developing innovative solutions"},{"code":"A2.7","title":"Community and Cultural Awareness","text":"communicate and collaborate with various communities in a safe, respectful, responsible, and inclusive manner when using online platforms and environments, including digital and media tools, and demonstrate cultural awareness with members of the community"}]},{"code":"A3","title":"Applications, Connections, and Contributions","text":"apply language and literacy skills in cross-curricular and integrated learning, and demonstrate an understanding of, and make connections to, diverse voices, experiences, perspectives, histories, and contributions, including those of First Nations, Métis, and Inuit individuals, communities, groups, and nations","specific":[{"code":"A3.1","title":"Cross-Curricular and Integrated Learning","text":"explain how the knowledge and skills developed in this grade support learning in various subject areas and in everyday life, and describe how they enhance understanding and communication"},{"code":"A3.2","title":"Identity and Community","text":"demonstrate an understanding of the historical contexts, contributions, lived experiences, and perspectives of a diversity of individuals and communities, including those in Canada, by exploring the concepts of identity, self, and sense of belonging in a variety of culturally responsive and relevant texts"},{"code":"A3.3","title":"First Nations, Métis, and Inuit Perspectives and Ways of Knowing","text":"explain themes explored in First Nations, Métis, and Inuit cultures to demonstrate an understanding of the varied identities, perspectives, relationships, legacies, truths, and ways of knowing, being, and doing"}]}]},{"code":"B","title":"Foundations of Language","why":"Students use effective listening skills and strategies to respond to others and identify the purpose and audience for speaking in formal and informal contexts. They identify and use oral and non-verbal communication strategies, such as expression and gestures, and use a variety of sentence types to support audience comprehension. They demonstrate an understanding of a variety of words and read and spell fluently. Students also demonstrate an understanding of the functions of parts of speech in sentences.","overall":[{"code":"B1","title":"Oral and Non-Verbal Communication","text":"apply listening, speaking, and non-verbal communication skills and strategies to understand and communicate meaning in formal and informal contexts and for various purposes and audiences","specific":[{"code":"B1.1","title":"Effective Listening Skills","text":"use effective listening skills, including asking questions to encourage a speaker to elaborate, and responding to the contributions of others in group discussions, in formal and informal contexts and for various purposes"},{"code":"B1.2","title":"Listening Strategies for Comprehension","text":"select and use a variety of listening strategies before, during, and after listening to comprehend information and messages communicated orally and non-verbally, express interest in what is being said at appropriate times, seek clarification, and develop an appropriate response"},{"code":"B1.3","title":"Speaking Purposes and Strategies","text":"identify the purpose and audience for speaking in formal and informal contexts, and use appropriate speaking strategies, including paraphrasing and restating, to communicate clearly and coherently"},{"code":"B1.4","title":"Oral and Non-Verbal Communication Strategies","text":"identify and use oral and non-verbal communication strategies, including expression, gestures, and body language, and explain how these strategies help them understand or communicate ideas and meaning"},{"code":"B1.5","title":"Word Choice, Syntax, and Grammar in Oral Communication","text":"use appropriate word choice, including new vocabulary, varied adjectives and adverbs to elaborate, a variety of sentence types, and cohesive sentences during formal and informal communication, to support audience comprehension"}]},{"code":"B2","title":"Language Foundations for Reading and Writing","text":"demonstrate an understanding of foundational language knowledge and skills, and apply this understanding when reading and writing","specific":[{"code":"B2.1","title":"Word-Level Reading and Spelling: Using Morphological Knowledge","text":"use knowledge of the meanings of words and morphemes (i.e., bases, prefixes, and suffixes) to read and spell words"},{"code":"B2.2","title":"Vocabulary","text":"demonstrate an understanding of a variety of words, acquire and use explicitly taught vocabulary in various contexts, including other subject areas, and use morphological knowledge to analyze and understand new words in context"},{"code":"B2.3","title":"Reading Fluency: Accuracy, Rate, and Prosody","text":"read a variety of texts fluently, with accuracy and appropriate pacing to support comprehension, and when reading aloud, adjust expression and intonation according to the purpose of reading"}]},{"code":"B3","title":"Language Conventions for Reading and Writing ","text":"demonstrate an understanding of sentence structure, grammar, cohesive ties, and capitalization and punctuation, and apply this knowledge when reading and writing sentences, paragraphs, and a variety of texts","specific":[{"code":"B3.1","title":"Syntax and Sentence Structure","text":"identify and construct various sentence types and forms, including simple and compound sentences formed with prepositional phrases and/or independent and dependent clauses"},{"code":"B3.2","title":"Grammar","text":"demonstrate an understanding of the functions of parts of speech in sentences, including relative pronouns, the perfect verb tense and interrogative and imperative verbs, and the use of pronouns as adjectives, and use this knowledge to support comprehension and communicate meaning clearly"},{"code":"B3.3","title":"Capitalization and Punctuation","text":"use their understanding of the meaning and function of capitalization and punctuation to communicate meaning clearly and coherently, including the use of capital letters for proper adjectives, commas to set off nouns of direct address, and quotation marks to indicate the title of a short work"}]}]},{"code":"C","title":"Comprehension: Understanding and Responding to Texts","why":"Students analyze different literary and informational texts and explain how their characteristics help communicate meaning. They explore how visuals such as images and graphics help to create, communicate, and contribute to meaning. They begin to draw conclusions from texts and understand different perspectives and cultural elements represented in texts.","overall":[{"code":"C1","title":"Knowledge about Texts","text":"apply foundational knowledge and skills to understand a variety of texts, including digital and media texts, by creators with diverse identities, perspectives, and experience, and demonstrate an understanding of the patterns, features, and elements of style associated with various text forms and genres","specific":[{"code":"C1.1","title":"Using Foundational Knowledge and Skills to Comprehend Texts","text":"read and comprehend various texts, using knowledge of words, grammar, cohesive ties, sentence structures, and background knowledge"},{"code":"C1.2","title":"Text Forms and Genres","text":"describe some characteristics of various text forms and genres, including cultural text forms, and explain how they help communicate meaning"},{"code":"C1.3","title":"Text Patterns and Features","text":"identify text patterns, such as spatial order in a graphic text, and text features, such as type styles and hyperlinks, associated with various text forms, including cultural texts, and explain how they help readers, listeners, and viewers understand the meaning"},{"code":"C1.4","title":"Visual Elements of Texts","text":"explain how images, graphics, and visual design create, communicate, and contribute to meaning in a variety of texts"},{"code":"C1.5","title":"Elements of Style ","text":"identify various elements of style in texts, including voice, word choice, word patterns, and sentence structure, and analyze how each element helps create meaning and is appropriate for the text form and genre"},{"code":"C1.6","title":"Point of View","text":"identify the narrator’s point of view, including first, second, or third person, in a variety of texts, and describe the advantages and disadvantages of the approach used in each story"},{"code":"C1.7","title":"Indigenous Context of Various Text Forms","text":"read, listen to, and view various forms of texts by diverse First Nations, Métis, and Inuit creators to make meaning through Indigenous Storywork about First Nations, Métis, and Inuit histories, cultures, relationships, communities, groups, nations, and lived experiences"}]},{"code":"C2","title":"Comprehension Strategies","text":"apply comprehension strategies before, during, and after reading, listening to, and viewing a variety of texts, including digital and media texts, by creators with diverse identities, perspectives, and experience, in order to understand and clarify the meaning of texts","specific":[{"code":"C2.1","title":"Prereading: Activating Prior Knowledge","text":"identify and explain prior knowledge from various sources, including personal experiences, that they can use to make connections and understand new texts"},{"code":"C2.2","title":"Prereading: Identifying the Purpose for Reading, Listening, and Viewing","text":"identify a variety of purposes for engaging with texts, and select texts from diverse creators that are suitable for the purposes"},{"code":"C2.3","title":"Monitoring of Understanding: Making and Confirming Predictions","text":"make predictions using background knowledge, text features, and evidence from the text, and pose questions to check whether their predictions were correct"},{"code":"C2.4","title":"Monitoring of Understanding: Ongoing Comprehension Check","text":"use strategies such as adjusting reading rate, visualizing, reading ahead, asking questions, and consulting references and other texts or sources of information, to monitor and confirm their understanding of various texts"},{"code":"C2.5","title":"Monitoring of Understanding: Making Connections","text":"describe how the ideas expressed in texts connect to their knowledges and lived experiences, the ideas in other texts, and the world around them"},{"code":"C2.6","title":"Summarizing: Identifying Relevant information and Drawing Conclusions","text":"summarize the main idea of a text and the supporting details in sequence, and draw a simple conclusion"},{"code":"C2.7","title":"Reflecting on Learning","text":"explain how strategies, such as visualizing, making predictions, summarizing, and connecting to their experiences, have helped them comprehend various texts"}]},{"code":"C3","title":"Critical Thinking in Literacy","text":"apply critical thinking skills to deepen understanding of texts, and analyze how various perspectives and topics are communicated and addressed in a variety of texts, including digital, media, and cultural texts","specific":[{"code":"C3.1","title":"Literary Devices","text":"describe literary devices, including personification and anthropomorphism, in a variety of texts, and explain how they help create meaning and are appropriate for the intended purpose and audience"},{"code":"C3.2","title":"Making Inferences","text":"make local and global inferences, using explicit and implicit evidence, to extend their understanding of various texts"},{"code":"C3.3","title":"Analyzing Texts","text":"analyze various texts, including literary and informational texts, by identifying main and supporting ideas, sequencing the events of multiple plots, and explaining cause and effect"},{"code":"C3.4","title":"Analyzing Cultural Elements of Texts","text":"identify cultural elements that are represented in various texts, including norms, values, artifacts, sports, and music, investigate the meanings of these elements, and make connections to their lived experience and culture"},{"code":"C3.5","title":"Perspectives within Texts","text":"identify explicit and implicit perspectives communicated in various texts, explain how these perspectives are conveyed, give some evidence of any biases the texts may contain, and suggest how such biases could influence an audience"},{"code":"C3.6","title":"Analysis and Response","text":"explain how various topics, such as diversity, inclusion, and accessibility, are addressed in texts, and describe what insights or messages are conveyed"},{"code":"C3.7","title":"Indigenous Contexts","text":"explain how texts created by First Nations, Métis, and Inuit individuals, communities, groups, or nations are influenced by historical periods, cultural experiences, and events, and how they relate to current lived experiences"},{"code":"C3.8","title":"Reflecting on Learning","text":"identify the critical thinking skills they used to analyze and evaluate various texts, and explain how these skills have helped them better understand the texts"}]}]},{"code":"D","title":"Composition: Expressing Ideas and Creating Texts","why":"Students write in cursive. They generate and develop ideas about various topics and create texts of various forms and genres, establishing a personal voice and using varied language and elements of style. They revise and edit their work to improve accuracy and style and produce final texts and present them using appropriate strategies.","overall":[{"code":"D1","title":"Developing Ideas and Organizing Content","text":"plan, develop ideas, gather information, and organize content for creating texts of various forms, including digital and media texts, on a variety of topics","specific":[{"code":"D1.1","title":"Purpose and Audience","text":"identify the topic, purpose, and audience for various texts they plan to create, and explain why the chosen text form, genre, and medium suit the purpose and audience and how they will help communicate the intended meaning"},{"code":"D1.2","title":"Developing Ideas","text":"generate and develop ideas about various topics, such as topics related to diversity, equity, and inclusion and to other subject areas, using a variety of strategies, and drawing on various resources, including their own lived experiences"},{"code":"D1.3","title":"Research","text":"gather information and content relevant to a topic, using a variety of sources and strategies, and record the sources of information"},{"code":"D1.4","title":"Organizing Content","text":"select and classify ideas and collected information, using appropriate strategies and tools, and sequence content, taking into account the chosen text form, genre, and medium"},{"code":"D1.5","title":"Reflecting on Learning","text":"describe the strategies and tools that helped them develop ideas and organize content for texts of the chosen forms, genres, and media, and explain how they helped them improve as a text creator"}]},{"code":"D2","title":"Creating Texts","text":"apply knowledge and understanding of various text forms and genres to create, revise, edit, and proofread their own texts, using a variety of media, tools, and strategies, and reflect critically on created texts","specific":[{"code":"D2.1","title":"Producing Drafts","text":"draft texts of various forms and genres, including narrative, persuasive, and informational texts, using a variety of media, tools, and strategies"},{"code":"D2.2","title":"Printing, Handwriting, and Word Processing","text":"write in cursive, forming letters of appropriate shape, size, proportion, and slant to improve the legibility of texts, and begin to develop fluent keyboarding skills using touch-typing techniques"},{"code":"D2.3","title":"Voice","text":"establish a personal voice in their texts, using varied language and elements of style to express their thoughts, feelings, and opinions about a topic, and using a tone appropriate to the form and genre"},{"code":"D2.4","title":"Point of View and Perspective","text":"identify the point of view used in their texts, and the perspectives and bias conveyed in their texts"},{"code":"D2.5","title":"Revision","text":"make revisions to the content of draft texts and to elements of style, such as word choice and adding or deleting sentences, to improve clarity, focus, and coherence, seeking feedback"},{"code":"D2.6","title":"Editing and Proofreading","text":"edit draft texts to improve accuracy and style, checking for errors in spelling, punctuation, grammar, and format; use a word processor to edit texts"}]},{"code":"D3","title":"Publishing, Presenting, and Reflecting","text":"select suitable and effective media, techniques, and tools to publish and present final texts, and critically analyze how well the texts address various topics","specific":[{"code":"D3.1","title":"Producing Final Texts","text":"produce final texts using a variety of techniques and tools, including simple digital design and production tools, to achieve the intended effect"},{"code":"D3.2","title":"Publishing and Presenting Texts","text":"publish and present texts they have created, using selected media and tools, and explain how each helped them communicate their intended message"},{"code":"D3.3","title":"Reflecting on Learning","text":"describe various strategies that helped them present and communicate their message when publishing and presenting texts, and explain how they helped them improve as a text creator"}]}]}]},"g5":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-language","sourceLang":"en","strands":[{"code":"A","title":"Literacy Connections and Applications","why":"Students explain how transferable skills can help them express their unique voice. They gather, evaluate, and use information, considering its credibility and the perspectives found in different sources of information. They also explain themes explored in a diversity of First Nations, Métis and Inuit cultures. This learning is applied to learning related to the other three areas of the curriculum.","overall":[{"code":"A1","title":"Transferable Skills","text":"demonstrate an understanding of how the seven transferable skills (critical thinking and problem solving; innovation, creativity, and entrepreneurship; self-directed learning; collaboration; communication; global citizenship and sustainability; and digital literacy) are used in various language and literacy contexts","specific":[{"code":"A1.1","title":"Receptive and Expressive Communication","text":"explain how transferable skills can be used to support communication in various cultural, social, linguistic, and domain-specific contexts, and apply them when reading, listening to, viewing, and creating texts of various forms"},{"code":"A1.2","title":"Student Agency and Engagement","text":"explain how transferable skills help them to express their voice, be engaged in their learning, and plan the next steps to develop their capabilities and potential"}]},{"code":"A2","title":"Digital Media Literacy","text":"demonstrate and apply the knowledge and skills needed to interact safely and responsibly in online environments, use digital and media tools to construct knowledge, and demonstrate learning as critical consumers and creators of media","specific":[{"code":"A2.1","title":"Digital Citizenship","text":"explain their rights and responsibilities when interacting online with appropriate permission, and make decisions that contribute positively to the development of their digital identity and those of their communities"},{"code":"A2.2","title":"Online Safety, Well-Being, and Etiquette","text":"demonstrate an understanding of how to navigate online environments safely, manage their privacy and personal data, and interact in a way that supports their well-being and that of others, including seeking appropriate permission"},{"code":"A2.3","title":"Research and Information Literacy","text":"gather, evaluate, and use information, considering validity, credibility, accuracy, and perspectives, to construct knowledge, create texts, and demonstrate learning"},{"code":"A2.4","title":"Forms, Conventions, and Techniques","text":"demonstrate an understanding of the forms, conventions, and techniques of digital and media texts, consider the impact on the audience, and apply this understanding when analyzing and creating texts"},{"code":"A2.5","title":"Media, Audience, and Production","text":"demonstrate an understanding of the interrelationships between the form, message, and context of texts, the intended audience, and the purpose for production"},{"code":"A2.6","title":"Innovation and Design","text":"select and use appropriate digital and media tools to support the design process and address authentic, relevant, real-world problems by developing innovative solutions"},{"code":"A2.7","title":"Community and Cultural Awareness","text":"communicate and collaborate with various communities in a safe, respectful, responsible, and inclusive manner when using online platforms and environments, including digital and media tools, and demonstrate cultural awareness with members of the community"}]},{"code":"A3","title":"Applications, Connections, and Contributions","text":"apply language and literacy skills in cross-curricular and integrated learning, and demonstrate an understanding of, and make connections to, diverse voices, experiences, perspectives, histories, and contributions, including those of First Nations, Métis, and Inuit individuals, communities, groups, and nations","specific":[{"code":"A3.1","title":"Cross-Curricular and Integrated Learning","text":"explain how the knowledge and skills developed in this grade support learning in various subject areas and in everyday life, and describe how they enhance understanding and communication"},{"code":"A3.2","title":"Identity and Community","text":"demonstrate an understanding of the historical contexts, contributions, lived experiences, and perspectives of a diversity of individuals and communities, including those in Canada, by exploring the concepts of identity, self, and sense of belonging in a variety of culturally responsive and relevant texts"},{"code":"A3.3","title":"First Nations, Métis, and Inuit Perspectives and Ways of Knowing","text":"explain themes explored in First Nations, Métis, and Inuit cultures to demonstrate an understanding of the varied identities, perspectives, relationships, legacies, truths, and ways of knowing, being, and doing"}]}]},{"code":"B","title":"Foundations of Language","why":"Students use effective listening skills and strategies to determine the purpose of a text and identify the purpose and audience for speaking in formal and informal contexts. They identify and use oral and non-verbal communication strategies, such as expression, gestures, and body language, and use word choice and a variety of sentence types to support audience comprehension. They use knowledge of the meanings of words to read and spell. Students also use their understanding of capitalization and punctuation to communicate clearly.","overall":[{"code":"B1","title":"Oral and Non-Verbal Communication","text":"apply listening, speaking, and non-verbal communication skills and strategies to understand and communicate meaning in formal and informal contexts and for various purposes and audiences","specific":[{"code":"B1.1","title":"Effective Listening Skills","text":"use effective listening skills, including expressing interest in what is being said at appropriate times, asking questions to encourage a speaker to elaborate, and responding to the contributions of others in group discussions, in formal and informal contexts and for various purposes"},{"code":"B1.2","title":"Listening Strategies for Comprehension ","text":"select and use a variety of listening strategies before, during, and after listening to comprehend information and messages communicated orally and non-verbally, determine the purpose of a text, construct meaning, seek clarification, and develop an appropriate response"},{"code":"B1.3","title":"Speaking Purposes and Strategies","text":"identify the purpose and audience for speaking in formal and informal contexts, and use appropriate speaking strategies, including paraphrasing and restating, to communicate clearly and coherently"},{"code":"B1.4","title":"Oral and Non-Verbal Communication Strategies","text":"identify and use oral and non-verbal communication strategies, including expression, gestures, and body language, and explain how these strategies help them understand or communicate ideas and meaning"},{"code":"B1.5","title":"Word Choice, Syntax, and Grammar in Oral Communication","text":"use appropriate word choice, including new vocabulary, varied adjectives and adverbs to elaborate, a variety of sentence types, and cohesive sentences during formal and informal communication, to support audience comprehension"}]},{"code":"B2","title":"Language Foundations for Reading and Writing","text":"demonstrate an understanding of foundational language knowledge and skills, and apply this understanding when reading and writing","specific":[{"code":"B2.1","title":"Word-Level Reading and Spelling: Using Morphological Knowledge","text":"use generalized knowledge of the meanings of words and morphemes (i.e., bases, prefixes, and suffixes) to read and spell words with accuracy and automaticity"},{"code":"B2.2","title":"Vocabulary","text":"demonstrate an understanding of a variety of words, acquire and use explicitly taught vocabulary in various contexts, including other subject areas, and use generalized morphological knowledge to analyze and understand new words in context"},{"code":"B2.3","title":"Reading Fluency: Accuracy, Rate, and Prosody","text":"read a variety of texts fluently, with accuracy and appropriate pacing to support comprehension, and when reading aloud, adjust expression and intonation according to the purpose of reading"}]},{"code":"B3","title":"Language Conventions for Reading and Writing","text":"demonstrate an understanding of sentence structure, grammar, cohesive ties, and capitalization and punctuation, and apply this knowledge when reading and writing sentences, paragraphs, and a variety of texts","specific":[{"code":"B3.1","title":"Syntax and Sentence Structure","text":"identify and construct various sentence types and forms, including compound-complex sentences, and correct sentence fragments and run-on sentences"},{"code":"B3.2","title":"Grammar","text":"demonstrate an understanding of the functions of parts of speech in sentences, including direct objects for nouns, intensive and reflexive pronouns, proper adjectives, and correlative conjunctions, and use this knowledge to support comprehension and communicate meaning clearly"},{"code":"B3.3","title":"Capitalization and Punctuation","text":"use their understanding of the meaning and function of capitalization and punctuation to communicate meaning clearly and coherently, including the use of commas to set off advanced phrases or clauses, such as appositives and participles, and colons for introducing a list after a complete sentence"}]}]},{"code":"C","title":"Comprehension: Understanding and Responding to Texts","why":"Students analyze different literary and informational texts, including cultural text forms, and explain how their characteristics help communicate meaning. They explore how visuals such as images and graphics help to create, communicate, and contribute to meaning. They apply comprehension strategies and critical thinking skills to deepen their understanding of texts, including diverse perspectives and cultural elements represented in texts, and draw conclusions.","overall":[{"code":"C1","title":"Knowledge about Texts","text":"apply foundational knowledge and skills to understand a variety of texts, including digital and media texts, by creators with diverse identities, perspectives, and experience, and demonstrate an understanding of the patterns, features, and elements of style associated with various text forms and genres","specific":[{"code":"C1.1","title":"Using Foundational Knowledge and Skills to Comprehend Texts","text":"read and comprehend various texts, using knowledge of words, grammar, cohesive ties, sentence structures, and background knowledge"},{"code":"C1.2","title":"Text Forms and Genres","text":"describe some characteristics of various text forms and genres, including cultural text forms, and explain how they help communicate meaning"},{"code":"C1.3","title":"Text Patterns and Features","text":"identify text patterns, such as cause and effect in a persuasive text, and text features, such as a preface and glossary, associated with various text forms, including cultural texts, and explain how they help readers, listeners, and viewers understand the meaning"},{"code":"C1.4","title":"Visual Elements of Texts","text":"explain how images, graphics, and visual design create, communicate, and contribute to meaning in a variety of texts"},{"code":"C1.5","title":"Elements of Style","text":"describe various elements of style in texts, including voice, word choice, word patterns, and sentence structure, and analyze how each element helps create meaning and is appropriate for the text form and genre"},{"code":"C1.6","title":"Point of View","text":"identify the narrator’s point of view, including first, second, or third person, in a variety of texts, and describe the advantages and disadvantages of the approach used in each story"},{"code":"C1.7","title":"Indigenous Context of Various Text Forms","text":"read, listen to, and view various forms of texts by diverse First Nations, Métis, and Inuit creators to make meaning through Indigenous Storywork about First Nations, Métis, and Inuit histories, cultures, relationships, communities, groups, nations, and lived experiences"}]},{"code":"C2","title":"Comprehension Strategies ","text":"apply comprehension strategies before, during, and after reading, listening to, and viewing a variety of texts, including digital and media texts, by creators with diverse identities, perspectives, and experience, in order to understand and clarify the meaning of texts","specific":[{"code":"C2.1","title":"Prereading: Activating Prior Knowledge","text":"identify and explain prior knowledge from various sources, including personal experiences, that they can use to make connections and understand new texts"},{"code":"C2.2","title":"Prereading: Identifying the Purpose for Reading, Listening, and Viewing","text":"identify a variety of purposes for engaging with texts, and select texts from diverse creators that are suitable for the purposes"},{"code":"C2.3","title":"Monitoring of Understanding: Making and Confirming Predictions","text":"make predictions using background knowledge, text features, and evidence from the text, and pose questions to check whether their predictions were correct"},{"code":"C2.4","title":"Monitoring of Understanding: Ongoing Comprehension Check","text":"use strategies such as adjusting reading rate, visualizing, reading ahead, asking questions, and consulting references and other texts or sources of information, to monitor and confirm their understanding of various texts"},{"code":"C2.5","title":"Monitoring of Understanding: Making Connections","text":"describe how the ideas expressed in texts connect to their knowledges and lived experiences, the ideas in other texts, and the world around them"},{"code":"C2.6","title":"Summarizing: Identifying Relevant Information and Drawing Conclusions","text":"summarize the main idea of a text and the supporting details in sequence, and draw a well-supported conclusion"},{"code":"C2.7","title":"Reflecting on Learning","text":"explain how strategies such as visualizing, making predictions, summarizing, and connecting to their experiences have helped them comprehend various texts"}]},{"code":"C3","title":"Critical Thinking in Literacy","text":"apply critical thinking skills to deepen understanding of texts, and analyze how various perspectives and topics are communicated and addressed in a variety of texts, including digital, media, and cultural texts","specific":[{"code":"C3.1","title":"Literary Devices","text":"describe literary devices, including imagery and humour, in a variety of texts, and explain how they help create meaning and are appropriate for the intended purpose and audience"},{"code":"C3.2","title":"Making Inferences","text":"make local and global inferences, using explicit and implicit evidence, to extend their understanding of various texts"},{"code":"C3.3","title":"Analyzing Texts","text":"analyze various texts, including literary and informational texts, by identifying main and supporting ideas, sequencing the events of multiple plots, recording relevant information, and explaining cause and effect"},{"code":"C3.4","title":"Analyzing Cultural Elements of Texts","text":"identify cultural elements that are represented in various texts, including, norms, values, artifacts, sports, and music, investigate the meanings of these elements, and make connections to their lived experience and culture"},{"code":"C3.5","title":"Perspectives within Texts","text":"identify explicit and implicit perspectives communicated in various texts, explain how these perspectives are conveyed, give some evidence of any biases the texts may contain, and suggest how such biases could influence an audience"},{"code":"C3.6","title":"Analysis and Response","text":"explain how various topics, such as diversity, inclusion, and accessibility, are addressed in texts, and describe what insights or messages are conveyed"},{"code":"C3.7","title":"Indigenous Contexts","text":"explain how texts created by First Nations, Métis, and Inuit individuals, communities, groups, or nations are influenced by historical periods, cultural experiences, and events, and how they relate to current lived experiences"},{"code":"C3.8","title":"Reflecting on Learning","text":"identify the critical thinking skills they used to analyze and evaluate various texts, and explain how these skills have helped them better understand the texts"}]}]},{"code":"D","title":"Composition: Expressing Ideas and Creating Texts","why":"Students write in fluent cursive. They generate and develop ideas about various topics and create texts of various forms and genres, establishing a personal voice and using varied language and elements of style. They revise and edit their work to improve accuracy and style. They produce final texts using a variety of techniques and tools and publish and present them using selected media and tools.","overall":[{"code":"D1","title":"Developing Ideas and Organizing Content ","text":"plan, develop ideas, gather information, and organize content for creating texts of various forms, including digital and media texts, on a variety of topics","specific":[{"code":"D1.1","title":"Purpose and Audience","text":"identify the topic, purpose, and audience for various texts they plan to create, and explain why the chosen text form, genre, and medium suit the purpose and audience and how they will help communicate the intended meaning"},{"code":"D1.2","title":"Developing Ideas","text":"generate and develop ideas and details about various topics, such as topics related to diversity, equity, and inclusion and to other subject areas, using a variety of strategies, and drawing on various resources, including their own lived experiences"},{"code":"D1.3","title":"Research","text":"gather and record information and content relevant to a topic, using multiple textual sources; verify the reliability of sources, using simple criteria; and record the creator and source of all content created by others"},{"code":"D1.4","title":"Organizing Content","text":"select and classify ideas and collected information, using appropriate strategies and tools, and sequence content, taking into account the chosen text form, genre, and medium"},{"code":"D1.5","title":"Reflecting on Learning","text":"describe the strategies and tools that helped them develop ideas and organize content for texts of the chosen forms, genres, and media, and explain how they helped them improve as a text creator"}]},{"code":"D2","title":"Creating Texts","text":"apply knowledge and understanding of various text forms and genres to create, revise, edit, and proofread their own texts, using a variety of media, tools, and strategies, and reflect critically on created texts","specific":[{"code":"D2.1","title":"Producing Drafts","text":"draft texts of various forms and genres, including narrative, persuasive, and informational texts, using a variety of media, tools, and strategies"},{"code":"D2.2","title":"Printing, Handwriting, and Word Processing","text":"write in fluent cursive, begin to keyboard with automaticity, and apply word-processing skills, including selecting appropriate fonts, to produce and enhance texts of various lengths"},{"code":"D2.3","title":"Voice","text":"establish a personal voice in their texts, using varied language and elements of style to express their thoughts, feelings, and opinions about a topic, and using a tone appropriate to the form and genre"},{"code":"D2.4","title":"Point of View and Perspective","text":"identify the point of view, implicit and explicit perspectives, and bias conveyed in their texts, and explain how their messages might be interpreted by audiences with different perspectives"},{"code":"D2.5","title":"Revision","text":"make revisions to the content of draft texts and to elements of style, such as word choice, and add or delete sentences, to improve clarity, focus, and coherence, seeking feedback"},{"code":"D2.6","title":"Editing and Proofreading","text":"edit draft texts to improve accuracy and style, checking for errors in spelling, punctuation, grammar, and format; use a word processor to edit texts"}]},{"code":"D3","title":"Publishing, Presenting, and Reflecting","text":"select suitable and effective media, techniques, and tools to publish and present final texts, and critically analyze how well the texts address various topics","specific":[{"code":"D3.1","title":"Producing Final Texts","text":"produce final texts using a variety of techniques and tools, including digital design and production tools, to achieve the intended effect"},{"code":"D3.2","title":"Publishing and Presenting Texts","text":"publish and present texts they have created, using selected media and tools, and explain how each helped them communicate their intended message"},{"code":"D3.3","title":"Reflecting on Learning","text":"describe various strategies and tools that helped them communicate their intended message when publishing and presenting texts, and suggest steps for future improvement as a text creator"}]}]}]},"g6":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-language","sourceLang":"en","strands":[{"code":"A","title":"Literacy Connections and Applications","why":"Students explain how transferable skills can help them express their unique voice. They gather, evaluate, and use information, considering its credibility and the perspectives found in different sources of information. They also explain themes explored in a diversity of First Nations, Métis, and Inuit cultures. This learning is applied to learning related to the other three areas of the curriculum.","overall":[{"code":"A1","title":"Transferable Skills","text":"demonstrate an understanding of how the seven transferable skills (critical thinking and problem solving; innovation, creativity, and entrepreneurship; self-directed learning; collaboration; communication; global citizenship and sustainability; and digital literacy) are used in various language and literacy contexts","specific":[{"code":"A1.1","title":"Receptive and Expressive Communication","text":"explain how transferable skills can be used to support communication in various cultural, social, linguistic, and domain-specific contexts, and apply them when reading, listening to, viewing, and creating texts of various forms"},{"code":"A1.2","title":"Student Agency and Engagement","text":"explain how transferable skills help them to express their voice, be engaged in their learning, and plan the next steps to develop their capabilities and potential"}]},{"code":"A2","title":"Digital Media Literacy","text":"demonstrate and apply the knowledge and skills needed to interact safely and responsibly in online environments, use digital and media tools to construct knowledge, and demonstrate learning as critical consumers and creators of media","specific":[{"code":"A2.1","title":"Digital Citizenship","text":"explain their rights and responsibilities when interacting online with appropriate permission, and make decisions that contribute positively to the development of their digital identity and those of their communities"},{"code":"A2.2","title":"Online Safety, Well-Being, and Etiquette","text":"demonstrate an understanding of how to navigate online environments safely, manage their privacy and personal data, and interact in a way that supports their well-being and that of others, including seeking appropriate permission"},{"code":"A2.3","title":"Research and Information Literacy","text":"gather, evaluate, and use information, considering validity, credibility, accuracy, and perspectives, to construct knowledge, create texts, and demonstrate learning"},{"code":"A2.4","title":"Forms, Conventions, and Techniques","text":"demonstrate an understanding of the forms, conventions, and techniques of digital and media texts, consider the impact on the audience, and apply this understanding when analyzing and creating texts"},{"code":"A2.5","title":"Media, Audience, and Production","text":"demonstrate an understanding of the interrelationships between the form, message, and context of texts, the intended audience, and the purpose for production"},{"code":"A2.6","title":"Innovation and Design","text":"select and use appropriate digital and media tools to support the design process and address authentic, relevant, real-world problems by developing innovative solutions"},{"code":"A2.7","title":"Community and Cultural Awareness","text":"communicate and collaborate with various communities in a safe, respectful, responsible, and inclusive manner when using online platforms and environments, including digital and media tools, and demonstrate cultural awareness with members of the community"}]},{"code":"A3","title":"Applications, Connections, and Contributions","text":"apply language and literacy skills in cross-curricular and integrated learning, and demonstrate an understanding of, and make connections to, diverse voices, experiences, perspectives, histories, and contributions, including those of First Nations, Métis, and Inuit individuals, communities, groups, and nations","specific":[{"code":"A3.1","title":"Cross-Curricular and Integrated Learning","text":"explain how the knowledge and skills developed in this grade support learning in various subject areas and in everyday life, and describe how they enhance understanding and communication"},{"code":"A3.2","title":"Identity and Community","text":"demonstrate an understanding of the historical contexts, contributions, lived experiences, and perspectives of a diversity of individuals and communities, including those in Canada, by exploring the concepts of identity, self, and sense of belonging in a variety of culturally responsive and relevant texts"},{"code":"A3.3","title":"First Nations, Métis, and Inuit Perspectives and Ways of Knowing","text":"explain themes explored in First Nations, Métis, and Inuit cultures to demonstrate an understanding of the varied identities, perspectives, relationships, legacies, truths, and ways of knowing, being, and doing"}]}]},{"code":"B","title":"Foundations of Language","why":"Students use effective listening skills and strategies to determine the purpose of a text. They also seek clarification and identify the purpose and audience for speaking in formal and informal contexts. They identify and use oral and non-verbal communication strategies, analyze how these strategies support communication, and use word choice, sentence structure, and grammar in oral communication. They demonstrate an understanding of a variety of words, including words learned in other subject areas, and use this knowledge to read and spell. They also use their knowledge of sentence types and forms to communicate effectively.","overall":[{"code":"B1","title":"Oral and Non-Verbal Communication","text":"apply listening, speaking, and non-verbal communication skills and strategies to understand and communicate meaning in formal and informal contexts and for various purposes and audiences","specific":[{"code":"B1.1","title":"Effective Listening Skills","text":"analyze various effective listening skills, including understanding when to ask relevant questions and how to respond to the contributions of others in group discussions, and use these skills in formal and informal contexts and for various purposes"},{"code":"B1.2","title":"Listening Strategies for Comprehension ","text":"select and use a variety of listening strategies before, during, and after listening to comprehend information communicated orally and non-verbally, seek clarification, and develop a relevant response appropriate to the context"},{"code":"B1.3","title":"Speaking Purposes and Strategies","text":"identify the purpose and audience for speaking in formal and informal contexts, and choose appropriate speaking strategies to communicate clearly and coherently"},{"code":"B1.4","title":"Oral and Non-Verbal Communication Strategies","text":"identify and use oral and non-verbal communication strategies, including expression, gestures, and body language, and analyze the ways in which these strategies support understanding or communication, including how their use may vary across cultures"},{"code":"B1.5","title":"Word Choice, Syntax, and Grammar in Oral Communication","text":"use precise and descriptive word choice, including varied adjectives and adverbs to elaborate, a variety of sentence types, cohesive sentences, and the active or passive voice as appropriate during formal and informal communication, to support audience comprehension"}]},{"code":"B2","title":"Language Foundations for Reading and Writing","text":"demonstrate an understanding of foundational language knowledge and skills, and apply this understanding when reading and writing","specific":[{"code":"B2.1","title":"Word-Level Reading and Spelling: Using Morphological Knowledge","text":"use generalized knowledge of the meanings of words and morphemes (i.e., bases, prefixes, and suffixes) to read and spell complex words with accuracy and automaticity"},{"code":"B2.2","title":"Vocabulary","text":"demonstrate an understanding of a variety of words, acquire and use explicitly taught vocabulary in various contexts, including other subject areas, and use generalized morphological knowledge to analyze and understand new words in context"},{"code":"B2.3","title":"Reading Fluency: Accuracy, Rate, and Prosody","text":"read a variety of texts fluently, with accuracy and appropriate pacing to support comprehension, and when reading aloud, adjust expression and intonation according to the purpose of reading"}]},{"code":"B3","title":"Language Conventions for Reading and Writing","text":"demonstrate an understanding of sentence structure, grammar, cohesive ties, and capitalization and punctuation, and apply this knowledge when reading and writing sentences, paragraphs, and a variety of texts","specific":[{"code":"B3.1","title":"Syntax and Sentence Structure","text":"use their knowledge of sentence types and forms to construct sentences that communicate ideas effectively, including using and creating complex sentences with adjective or relative clauses to express relationships among ideas"},{"code":"B3.2","title":"Grammar","text":"demonstrate an understanding of the functions of parts of speech in sentences, including nouns that are gerunds, distinguishing and converting between active and passive voice, and use this knowledge to support comprehension and communicate meaning clearly"},{"code":"B3.3","title":"Capitalization and Punctuation","text":"use their understanding of the meaning and function of capitalization and punctuation to communicate meaning clearly and coherently, including the use of colons in formal letters and memo salutations and to indicate a new speaker in script dialogue, and commas after transitional words or phrases"}]}]},{"code":"C","title":"Comprehension: Understanding and Responding to Texts","why":"Students analyze various literary and informational texts, including cultural text forms, and explain how their characteristics help communicate meaning. They explore how visuals such as images and graphics help to create, communicate, and contribute to meaning. They apply comprehension strategies and critical thinking skills to deepen their understanding of texts, including diverse perspectives and cultural elements represented in texts, and draw conclusions.","overall":[{"code":"C1","title":"Knowledge about Texts","text":"apply foundational knowledge and skills to understand a variety of texts, including digital and media texts, by creators with diverse identities, perspectives, and experience, and demonstrate an understanding of the patterns, features, and elements of style associated with various text forms and genres","specific":[{"code":"C1.1","title":"Using Foundational Knowledge and Skills to Comprehend Texts","text":"read and comprehend various texts, using knowledge of words, grammar, cohesive ties, sentence structures, and background knowledge"},{"code":"C1.2","title":"Text Forms and Genres","text":"analyze a variety of text forms and genres, including cultural text forms, and explain how their characteristics help communicate meaning"},{"code":"C1.3","title":"Text Patterns and Features","text":"analyze text patterns, such as problem-solution in a report, and text features, such as subheadings and pull-down menus, associated with various text forms, including cultural texts, and explain how they help readers, listeners, and viewers understand the meaning"},{"code":"C1.4","title":"Visual Elements of Texts","text":"analyze and compare how images, graphics, and visual design create, communicate, and contribute to meaning in a variety of texts"},{"code":"C1.5","title":"Elements of Style","text":"identify various elements of style in texts, including voice, word choice, word patterns, and sentence structure, and analyze how each element helps create meaning and is appropriate for the text form and genre"},{"code":"C1.6","title":"Point of View","text":"identify the narrator’s point of view, including first, second, or third person, in a variety of texts, providing evidence, and explain how using an alternative point of view would change each story"},{"code":"C1.7","title":"Indigenous Context of Various Text Forms","text":"read, listen to, and view various forms of texts by diverse First Nations, Métis, and Inuit creators to make meaning through Indigenous Storywork about First Nations, Métis, and Inuit histories, cultures, relationships, communities, groups, nations, and lived experiences"}]},{"code":"C2","title":"Comprehension Strategies","text":"apply comprehension strategies before, during, and after reading, listening to, and viewing a variety of texts, including digital and media texts, by creators with diverse identities, perspectives, and experience, in order to understand and clarify the meaning of texts","specific":[{"code":"C2.1","title":"Prereading: Activating Prior Knowledge","text":"identify and explain prior knowledge from various sources, including personal experiences and learning in other subject areas, that they can use to make connections and understand new texts"},{"code":"C2.2","title":"Prereading: Identifying the Purpose for Reading, Listening, and Viewing","text":"identify a variety of purposes for engaging with texts, select texts from diverse creators that are suitable for the purposes, and explain why the selections are appropriate"},{"code":"C2.3","title":"Monitoring of Understanding: Making and Confirming Predictions","text":"make predictions using background knowledge and textual information, pose questions to check whether their predictions were correct, and, if not, adjust their understanding"},{"code":"C2.4","title":"Monitoring of Understanding: Ongoing Comprehension Check","text":"use strategies such as visualizing, reading ahead, asking questions, and consulting references and other texts or sources of information, to monitor and confirm their understanding of various texts"},{"code":"C2.5","title":"Monitoring of Understanding: Making Connections","text":"explain how the ideas expressed in texts connect to their knowledges and lived experiences, the ideas in other texts, and the world around them"},{"code":"C2.6","title":"Summarizing: Identifying Relevant Information and Drawing Conclusions","text":"summarize and record the main idea and supporting details in various texts, and draw well-supported conclusions"},{"code":"C2.7","title":"Reflecting on Learning","text":"explain and compare how various strategies, such as visualizing, making predictions, summarizing, and connecting to their experiences, have helped them comprehend various texts, and set goals to improve their comprehension"}]},{"code":"C3","title":"Critical Thinking in Literacy","text":"apply critical thinking skills to deepen understanding of texts, and analyze how various perspectives and topics are communicated and addressed in a variety of texts, including digital, media, and cultural texts","specific":[{"code":"C3.1","title":"Literary Devices","text":"describe literary devices, including hyperbole and idioms, in a variety of texts, and explain how they help create meaning and are appropriate for the intended purpose and audience"},{"code":"C3.2","title":"Making Inferences","text":"make local and global inferences, using explicit and implicit evidence, to develop interpretations about various texts and to extend their understanding"},{"code":"C3.3","title":"Analyzing Texts","text":"analyze various texts, including literary and informational texts, by identifying main and supporting ideas, evaluating the quality of information and its relevance for a specific purpose, and formulating conclusions"},{"code":"C3.4","title":"Analyzing Cultural Elements of Texts","text":"analyze cultural elements that are represented in various texts, including values, rituals and ceremonies, architecture, art, and dance, by investigating the meanings of these elements, making connections to their lived experience and culture, and sharing their interpretations with others"},{"code":"C3.5","title":"Perspectives within Texts","text":"explain explicit and implicit perspectives communicated in various texts, including narrative texts, provide any evidence that could suggest bias in these perspectives, and suggest ways to avoid any such bias"},{"code":"C3.6","title":"Analysis and Response","text":"explain how various topics, such as diversity, inclusion, and accessibility, are addressed in texts, analyze the insights or messages conveyed, and identify different positions presented"},{"code":"C3.7","title":"Indigenous Contexts","text":"assess the influence of historical periods, cultural experiences, and/or socio-political conditions and events on texts created by First Nations, Métis, and Inuit individuals, communities, groups, or nations, and how they relate to current lived experiences"},{"code":"C3.8","title":"Reflecting on Learning","text":"compare the critical thinking skills they used when analyzing and evaluating various texts, identify the skills that best supported their understanding, and explain why they were effective"}]}]},{"code":"D","title":"Composition: Expressing Ideas and Creating Texts","why":"Students write in fluent cursive and use keyboarding skills to create texts. They generate and develop ideas and details about various topics and create texts of various forms and genres, establishing a personal voice and using varied language and elements of style. They revise the content and edit their work to improve accuracy and style and produce final texts using a variety of techniques and tools. They then publish and present their texts using selected media and tools.","overall":[{"code":"D1","title":"Developing Ideas and Organizing Content","text":"plan, develop ideas, gather information, and organize content for creating texts of various forms, including digital and media texts, on a variety of topics","specific":[{"code":"D1.1","title":"Purpose and Audience","text":"identify the topic, purpose, and audience for various texts they plan to create, and explain why the chosen text form, genre, and medium suit the purpose and audience, and how they will help communicate the intended meaning"},{"code":"D1.2","title":"Developing Ideas","text":"generate and develop ideas and details about various topics, such as topics related to diversity, equity, and inclusion and to other subject areas, using a variety of strategies, and drawing on various resources, including their own lived experiences"},{"code":"D1.3","title":"Research","text":"gather information and content relevant to a topic, using multiple textual sources; summarize the information; verify the reliability of sources; and record the creator and source of all content created by others"},{"code":"D1.4","title":"Organizing Content","text":"classify and sequence ideas and collected information, using appropriate strategies and tools, and identify and organize relevant content, taking into account the chosen text form, genre, and medium"},{"code":"D1.5","title":"Reflecting on Learning","text":"explain and compare how the strategies and tools used helped them develop ideas and organize content for texts of the chosen forms, genres, and media, and how they helped them improve as a text creator"}]},{"code":"D2","title":"Creating Texts ","text":"apply knowledge and understanding of various text forms and genres to create, revise, edit, and proofread their own texts, using a variety of media, tools, and strategies, and reflect critically on created texts","specific":[{"code":"D2.1","title":"Producing Drafts","text":"draft complex texts of various forms and genres, including narrative, expository, and informational texts, using a variety of media, tools, and strategies"},{"code":"D2.2","title":"Printing, Handwriting, and Word Processing","text":"write in fluent cursive, and apply keyboarding skills with increasing fluency, automaticity, and proficiency to improve the accuracy and effect of texts"},{"code":"D2.3","title":"Voice","text":"establish a personal voice in their texts, using varied language and elements of style to express their thoughts, feelings, and opinions about a topic, and using a tone appropriate to the form and genre"},{"code":"D2.4","title":"Point of View and Perspective","text":"identify the point of view, perspectives, and bias conveyed in their texts, and explain how their messages might be interpreted by audiences with different perspectives"},{"code":"D2.5","title":"Revision","text":"make revisions to the content, elements of style, patterns, and features of draft texts, and add and delete sentences to improve clarity, focus, and coherence, using various strategies and seeking and selectively using feedback"},{"code":"D2.6","title":"Editing and Proofreading","text":"edit draft texts to improve accuracy and style, checking for errors in spelling, punctuation, grammar, and format; edit digital texts using word-processing software, including spell- and grammar-checkers"}]},{"code":"D3","title":"Publishing, Presenting, and Reflecting","text":"select suitable and effective media, techniques, and tools to publish and present final texts, and critically analyze how well the texts address various topics","specific":[{"code":"D3.1","title":"Producing Final Texts","text":"produce final texts, selecting a variety of suitable techniques and tools, including digital design and production tools, to achieve the intended effect"},{"code":"D3.2","title":"Publishing and Presenting Texts","text":"publish and present texts they have created, using selected media and tools, and analyze how their choices helped them communicate their intended message"},{"code":"D3.3","title":"Reflecting on Learning","text":"compare how various strategies and tools helped them communicate their intended message when publishing and presenting texts, and suggest future steps for improvement as a text creator"}]}]}]}},"math":{"g1":{"url":"https://www.dcp.edu.gov.on.ca/fr/curriculum/elementaire-mathematiques","sourceLang":"fr","strands":[{"code":"A","title":"Apprentissage socioémotionnel en mathématiques et processus mathématiques ","why":"Les élèves apprennent ce qu’est la motivation positive et comment employer des stratégies telles que se dire à soi-même par exemple: « J’ai déjà fait ça, donc je saurai le refaire », pour s’encourager ou pour encourager un camarade lorsque la classe fait une activité où il faut compter.","overall":[{"code":"A1","title":"Habiletés socioémotionnelles en mathématiques et processus mathématiques ","text":"mettre en application, au mieux de ses capacités, diverses habiletés socioémotionnelles pour appuyer son utilisation des processus mathématiques et son apprentissage lié aux attentes et aux contenus d’apprentissage des cinq autres domaines d’étude du programme-cadre de mathématiques.","specific":[]}]},{"code":"B","title":"Nombres","why":"Les élèves explorent les nombres jusqu’à 50 dans divers contextes et commencent à comprendre les différentes façons de les utiliser. On leur présente l’idée des fractions au moyen d’un partage équitable d’objets.","overall":[{"code":"B1","title":"Sens du nombre","text":"démontrer sa compréhension des nombres et établir des liens avec leur utilisation dans la vie quotidienne.","specific":[{"code":"B1.1","title":"Nombres naturels","text":"lire et représenter les nombres naturels de 0 jusqu’à 50 et décrire de quelles façons ils sont utilisés dans la vie quotidienne."},{"code":"B1.2","title":"Nombres naturels","text":"composer et décomposer les nombres naturels de 0 jusqu’à 50, à l’aide d’une variété d’outils et de stratégies, dans divers contextes."},{"code":"B1.3","title":"Nombres naturels","text":"comparer et ordonner les nombres naturels jusqu’à 50, dans divers contextes."},{"code":"B1.4","title":"Nombres naturels","text":"estimer le nombre d’objets dans des ensembles qui comprennent jusqu’à 50 objets et vérifier son estimation en utilisant des stratégies de dénombrement."},{"code":"B1.5","title":"Nombres naturels","text":"compter jusqu’à 50 par intervalles de 1, 2, 5 et 10, à l’aide d’une variété d’outils et de stratégies."},{"code":"B1.6","title":"Fractions","text":"utiliser des schémas pour représenter et résoudre des problèmes de partage équitable d’une quantité entre 2 et 4 personnes, avec un reste de 1 ou 2."},{"code":"B1.7","title":"Fractions","text":"reconnaître l’équivalence entre un demi et deux quarts d’un même tout, dans des contextes de partage équitable d’une quantité."},{"code":"B1.8","title":"Fractions","text":"utiliser des schémas pour comparer et ordonner des fractions unitaires désignant les portions individuelles obtenues lorsqu’un tout est divisé par des nombres différents de personnes, jusqu’à un maximum de 10."}]},{"code":"B2","title":"Sens des opérations ","text":"utiliser ses connaissances des nombres et des opérations pour résoudre des problèmes mathématiques de la vie quotidienne.","specific":[{"code":"B2.1","title":"Propriétés et relations","text":"utiliser les propriétés de l’addition et de la soustraction ainsi que la relation entre l’addition et la soustraction pour résoudre des problèmes et vérifier la vraisemblance des calculs."},{"code":"B2.2","title":"Faits numériques","text":"se rappeler les faits d’addition de nombres jusqu’à 10 et les faits de soustraction associés, et démontrer sa compréhension de ces faits."},{"code":"B2.3","title":"Calcul mental","text":"utiliser des stratégies de calcul mental, y compris l’estimation, pour additionner des nombres naturels dont la somme est égale ou inférieure à 20 et pour soustraire des nombres égaux ou inférieurs à 20, et expliquer les stratégies utilisées."},{"code":"B2.4","title":"Addition et soustraction","text":"utiliser des objets, des schémas et des équations pour représenter, décrire et résoudre des situations relatives à l’addition de nombres naturels dont la somme est égale ou inférieure à 50 et à la soustraction de nombres égaux ou inférieurs à 50."},{"code":"B2.5","title":"Multiplication et division","text":"représenter et résoudre des problèmes de groupes égaux dont le nombre d’éléments est égal ou inférieur à 10, y compris des problèmes dans lesquels chaque groupe est la moitié d’un tout, à l’aide d’outils et de schémas."}]}]},{"code":"C","title":"Algèbre","why":"Les élèves commencent à découvrir les façons dont les régularités peuvent être utilisées pour faire des prédictions. Ils commencent aussi à comprendre que dans une phrase mathématique (comme 2 + 2 = 4), les deux côtés du symbole « = » doivent être égaux. Ces idées sont le fondement des apprentissages que les élèves feront en algèbre dans les années d’études supérieures. Les élèves commencent à écrire des codes pour ordonner des séquences d’étapes. De plus, on leur présente la modélisation mathématique pour qu’ils analysent et créent des solutions correspondant à des situations réelles, telles que la disposition des places pour une activité en classe.","overall":[{"code":"C1","title":"Suites et relations","text":"reconnaître, décrire, prolonger et créer une variété de suites, y compris des suites trouvées dans la vie quotidienne, et faire des prédictions à leur sujet.","specific":[{"code":"C1.1","title":"Suites","text":"reconnaître et décrire les règles dans une variété de suites, y compris des suites trouvées dans la vie quotidienne."},{"code":"C1.2","title":"Suites","text":"créer des suites à l’aide de mouvements, de sons, d’objets, de formes géométriques, de lettres et de nombres, et représenter les suites de différentes façons."},{"code":"C1.3","title":"Suites","text":"déterminer et utiliser les règles pour prolonger des suites, faire et justifier des prédictions, et trouver les termes manquants dans des suites."},{"code":"C1.4","title":"Suites","text":"créer et décrire des suites numériques comprenant des nombres naturels jusqu’à 50, et représenter des relations entre ces nombres."}]},{"code":"C2","title":"Équations et inégalités","text":"démontrer sa compréhension des variables, des expressions, des égalités et des inégalités et mettre en application cette compréhension dans divers contextes.","specific":[{"code":"C2.1","title":"Variables","text":"déterminer les quantités qui peuvent changer et celles qui restent toujours les mêmes, dans des situations de la vie quotidienne."},{"code":"C2.2","title":"Relations d’égalité et inégalité","text":"déterminer si des paires d’expressions numériques comportant des additions et des soustractions sont équivalentes ou non."},{"code":"C2.3","title":"Relations d’égalité et inégalité","text":"déterminer et utiliser des relations d’équivalence comprenant des nombres naturels jusqu’à 50, dans divers contextes."}]},{"code":"C3","title":"Codage","text":"résoudre des problèmes et créer des représentations de situations mathématiques de façons computationnelles à l’aide de concepts et d’habiletés en codage.","specific":[{"code":"C3.1","title":"Habiletés en codage","text":"résoudre des problèmes et créer des représentations de situations mathématiques de façons computationnelles en écrivant et exécutant des codes, y compris des codes comprenant des événements séquentiels."},{"code":"C3.2","title":"Habiletés en codage","text":"lire et modifier des codes donnés, y compris des codes comprenant des événements séquentiels, et décrire l’incidence des changements sur les résultats."}]},{"code":"C4","title":"Modélisation mathématique","text":"mettre en application le processus de modélisation mathématique pour représenter et analyser des situations de la vie quotidienne, ainsi que pour faire des prédictions et fournir des renseignements à leur sujet. Il n’y a pas de contenus d’apprentissage rattachés à cette attente. La modélisation mathématique est un processus itératif et interconnecté qui, lorsque mis en application dans divers contextes, permet aux élèves de transférer des apprentissages effectués dans d’autres domaines d’étude. L’évaluation porte sur la manifestation par l’élève de son apprentissage du processus de modélisation mathématique dans le contexte des concepts et des connaissances acquis dans les autres domaines. En savoir plus sur le processus de la modélisation mathématique","specific":[]}]},{"code":"D","title":"Données","why":"Les élèves commencent à mieux comprendre les données en répondant à diverses questions (par exemple: quels sont les animaux préférés de mes camarades?). Ils organisent les données recueillies en catégories puis présentent l’information de sorte à tirer des conclusions.","overall":[{"code":"D1","title":"Littératie statistique","text":"traiter, analyser et utiliser des données pour formuler des arguments persuasifs et prendre des décisions éclairées dans divers contextes de la vie quotidienne.","specific":[{"code":"D1.1","title":"Collecte et organisation des données","text":"trier et classer des ensembles de données portant sur des personnes ou des objets en fonction d’un attribut et décrire les critères de classement utilisés."},{"code":"D1.2","title":"Collecte et organisation des données","text":"collecter des données au moyen d’observations, d’expériences et d’entrevues pour répondre à des questions d’intérêt concernant un seul élément d’information, enregistrer les données en utilisant des méthodes d’enregistrement de son choix, et organiser les données dans des tableaux de dénombrement."},{"code":"D1.3","title":"Visualisation des données","text":"représenter des ensembles de données, en utilisant la correspondance un à un, à l’aide de diagrammes concrets et de diagrammes à pictogrammes comprenant des sources, des titres et des étiquettes appropriés."},{"code":"D1.4","title":"Analyse des données","text":"ordonner, en fonction de leur fréquence, de la plus élevée à la plus faible, des catégories de données appartenant à divers ensembles de données présentées dans des tableaux de dénombrement, des diagrammes concrets ou des diagrammes à pictogrammes."},{"code":"D1.5","title":"Analyse des données","text":"analyser divers ensembles de données présentées de différentes façons, y compris dans des tableaux de dénombrement, des diagrammes concrets et des diagrammes à pictogrammes, en se posant des questions au sujet des données, en y répondant et en tirant des conclusions, et ensuite formuler des arguments persuasifs et prendre des décisions éclairées."}]},{"code":"D2","title":"Probabilité","text":"décrire la probabilité que des événements se produisent et utiliser cette information pour faire des prédictions.","specific":[{"code":"D2.1","title":"Probabilité","text":"utiliser le vocabulaire mathématique, y compris des termes comme « impossible », « possible » et « certain » pour exprimer la probabilité que des événements se produisent, et s’appuyer sur cette probabilité pour faire des prédictions et prendre des décisions éclairées."},{"code":"D2.2","title":"Probabilité","text":"formuler et vérifier des prédictions sur la probabilité que les catégories d’un ensemble de données d’une population aient les mêmes fréquences si les données sont collectées auprès d’une population différente mais de la même taille."}]}]},{"code":"E","title":"Sens de l’espace","why":"Les élèves développent leur sens de l’espace en comparant la longueur, la masse et la capacité de divers objets et ils apprennent comment les calendriers sont organisés pour représenter le temps. Ils apprennent des termes précis pour décrire diverses formes géométriques.","overall":[{"code":"E1","title":"Raisonnement géométrique et spatial","text":"décrire et représenter la forme, la position et le déplacement en se servant de propriétés géométriques et de relations spatiales pour s’orienter dans le monde qui l’entoure.","specific":[{"code":"E1.1","title":"Raisonnement géométrique","text":"classer des solides et des figures planes selon un attribut à la fois et déterminer le critère de classement utilisé."},{"code":"E1.2","title":"Raisonnement géométrique","text":"construire des solides et décrire les figures planes qui les composent."},{"code":"E1.3","title":"Raisonnement géométrique","text":"construire et décrire des figures planes et des solides qui sont symétriques."},{"code":"E1.4","title":"Position et déplacement","text":"décrire l’emplacement relatif d’objets ou de personnes, en utilisant le vocabulaire associé à la position."},{"code":"E1.5","title":"Position et déplacement","text":"donner et suivre des directives pour se déplacer d’un endroit à un autre."}]},{"code":"E2","title":"Sens de la mesure","text":"comparer, estimer et déterminer des mesures dans divers contextes.","specific":[{"code":"E2.1","title":"Attribut","text":"reconnaître les attributs mesurables de figures planes et de solides, y compris la longueur, l’aire, la masse, la capacité et les angles."},{"code":"E2.2","title":"Attribut","text":"comparer plusieurs objets du quotidien et les mettre en ordre selon leur longueur, leur aire, leur masse et leur capacité."},{"code":"E2.3","title":"Temps","text":"lire la date à partir d’un calendrier et savoir y reconnaître les jours, les semaines, les mois, les fêtes et les saisons."}]}]},{"code":"F","title":"Littératie financière","why":"Les élèves apprennent à reconnaître les pièces et les billets canadiens et comparent leur valeur.","overall":[{"code":"F1","title":"Argent et finances","text":"démontrer sa compréhension de la valeur de la monnaie canadienne.","specific":[{"code":"F1.1","title":"Concepts monétaires","text":"nommer les pièces de monnaie canadienne jusqu’à 50 ¢ et des pièces de monnaie et des billets jusqu’à 50 $, et comparer leur valeur."}]}]}]},"g2":{"url":"https://www.dcp.edu.gov.on.ca/fr/curriculum/elementaire-mathematiques","sourceLang":"fr","strands":[{"code":"A","title":"Apprentissage socioémotionnel en mathématiques et processus mathématiques ","why":"Les élèves exercent leur pensée critique et créative. Par exemple, en littératie financière, ils apprennent à diviser les catégories de pièces de monnaie et à choisir différents outils et stratégies, tels que faire une liste des différentes combinaisons de monnaie, dessiner les différents regroupements et utiliser du matériel de manipulation pour diviser les montants de plusieurs façons différentes.","overall":[{"code":"A1","title":"Habiletés socioémotionnelles en mathématiques et processus mathématiques ","text":"mettre en application, au mieux de ses capacités, diverses habiletés socioémotionnelles pour appuyer son utilisation des processus mathématiques et son apprentissage lié aux attentes et aux contenus d’apprentissage des cinq autres domaines d’étude du programme-cadre de mathématiques.","specific":[]}]},{"code":"B","title":"Nombres","why":"Les élèves utilisent les nombres jusqu’à 200 dans divers contextes. Ils développent et appliquent leur compréhension croissante des nombres de diverses façons, notamment dans la résolution de problèmes où il faut faire des additions et des soustractions. Ils continuent d’explorer les fractions, par exemple pour faire un partage équitable.","overall":[{"code":"B1","title":"Sens du nombre","text":"démontrer sa compréhension des nombres et établir des liens avec leur utilisation dans la vie quotidienne.","specific":[{"code":"B1.1","title":"Nombres naturels","text":"lire, représenter, composer et décomposer les nombres naturels de 0 jusqu’à 200, à l’aide d’une variété d’outils et de stratégies, dans divers contextes, et décrire de quelles façons ils sont utilisés dans la vie quotidienne."},{"code":"B1.2","title":"Nombres naturels","text":"comparer et ordonner les nombres naturels jusqu’à 200, dans divers contextes."},{"code":"B1.3","title":"Nombres naturels","text":"estimer le nombre d’objets dans des ensembles comprenant jusqu’à 200 objets et vérifier son estimation en utilisant des stratégies de dénombrement."},{"code":"B1.4","title":"Nombres naturels","text":"compter jusqu’à 200, y compris par intervalles de 20, 25 et 50, à l’aide d’une variété d’outils et de stratégies."},{"code":"B1.5","title":"Nombres naturels","text":"décrire les caractéristiques des nombres pairs et impairs."},{"code":"B1.6","title":"Fractions","text":"utiliser des schémas pour représenter et résoudre des problèmes de partage équitable d’un tout pouvant comprendre jusqu’à 10 éléments entre 2, 3, 4 et 6 personnes, y compris des problèmes dont le résultat est un nombre naturel, un nombre fractionnaire ou une fraction, et comparer les résultats."},{"code":"B1.7","title":"Fractions","text":"reconnaître l’équivalence entre un tiers et deux sixièmes d’un même tout, dans des contextes de partage équitable d’une quantité."}]},{"code":"B2","title":"Sens des opérations ","text":"utiliser ses connaissances des nombres et des opérations pour résoudre des problèmes mathématiques de la vie quotidienne.","specific":[{"code":"B2.1","title":"Propriétés et relations","text":"utiliser les propriétés de l’addition et de la soustraction, et les relations entre l’addition et la multiplication ainsi qu’entre la soustraction et la division pour résoudre des problèmes et vérifier la vraisemblance des calculs."},{"code":"B2.2","title":"Faits numériques","text":"se rappeler les faits d’addition et de soustraction de nombres jusqu’à 20 et les faits de la soustraction associés, et démontrer sa compréhension de ces faits."},{"code":"B2.3","title":"Calcul mental","text":"utiliser des stratégies de calcul mental, y compris l’estimation, pour additionner des nombres naturels dont la somme est égale ou inférieure à 50 et pour soustraire des nombres égaux ou inférieurs à 50, et expliquer les stratégies utilisées."},{"code":"B2.4","title":"Addition et soustraction","text":"utiliser des objets, des schémas et des équations pour représenter, décrire et résoudre des situations relatives à l’addition de nombres naturels dont la somme est égale ou inférieure à 100 et à la soustraction de nombres égaux ou inférieurs à 100."},{"code":"B2.5","title":"Multiplication et division","text":"représenter et résoudre des problèmes relatifs à la multiplication en tant qu’addition répétée de groupes égaux, y compris des groupes de un demi et de un quart, à l’aide d’une variété d’outils et de schémas."},{"code":"B2.6","title":"Multiplication et division","text":"représenter et résoudre des problèmes relatifs à la division de 12 éléments ou moins en tant que partage égal d’une quantité, à l’aide d’une variété d’outils et de schémas."}]}]},{"code":"C","title":"Algèbre","why":"Les élèves continuent d’étudier les suites en utilisant des formes géométriques et des nombres et en développant des stratégies pour les prolonger. Ils découvrent aussi le concept d’égalité en ajustant des paires d’énoncés d’addition et de soustraction pour les rendre égaux. Les élèves écrivent des codes pour déplacer plusieurs objets sur une grille en même temps. Ils utilisent également la modélisation mathématique pour analyser et créer des solutions dans des situations réelles, par exemple pour déterminer le coût d’un programme de repas à l’école.","overall":[{"code":"C1","title":"Suites et relations","text":"reconnaître, décrire, prolonger et créer une variété de suites, y compris des suites trouvées dans la vie quotidienne, et faire des prédictions à leur sujet.","specific":[{"code":"C1.1","title":"Suites","text":"reconnaître et décrire une variété de suites non numériques, y compris des suites trouvées dans la vie quotidienne."},{"code":"C1.2","title":"Suites","text":"créer des suites à l’aide d’une variété de représentations, y compris des nombres et des formes géométriques, et établir des liens entre les différentes représentations."},{"code":"C1.3","title":"Suites","text":"déterminer et utiliser les règles pour prolonger des suites, faire et justifier des prédictions, et trouver des termes manquants dans des suites représentées à l’aide de formes géométriques et de nombres (suites numériques et non numériques)."},{"code":"C1.4","title":"Suites","text":"créer et décrire des suites comprenant des nombres naturels jusqu’à 100, et représenter des relations entre ces nombres."}]},{"code":"C2","title":"Équations et inégalités","text":"démontrer sa compréhension des variables, des expressions, des égalités et des inégalités et mettre en application cette compréhension dans divers contextes.","specific":[{"code":"C2.1","title":"Variables","text":"décrire des façons et des situations où des symboles sont utilisés comme variables."},{"code":"C2.2","title":"Relations d’égalité et d’inégalité","text":"déterminer ce qui doit être ajouté ou soustrait pour que des expressions comportant des additions et des soustractions deviennent équivalentes."},{"code":"C2.3","title":"Relations d’égalité et d’inégalité","text":"déterminer et utiliser des relations d’équivalence comprenant des nombres naturels jusqu’à 100, dans divers contextes."}]},{"code":"C3","title":"Codage","text":"résoudre des problèmes et créer des représentations de situations mathématiques de façons computationnelles à l’aide de concepts et d’habiletés en codage.","specific":[{"code":"C3.1","title":"Habiletés en codage","text":"résoudre des problèmes et créer des représentations de situations mathématiques de façons computationnelles en écrivant et exécutant des codes, y compris des codes comprenant des événements séquentiels et des événements simultanés."},{"code":"C3.2","title":"Habiletés en codage","text":"lire et modifier des codes donnés, y compris des codes comprenant des événements séquentiels et des événements simultanés, et décrire l’incidence de ces changements sur les résultats dans divers contextes."}]},{"code":"C4","title":"Modélisation mathématique","text":"mettre en application le processus de modélisation mathématique pour représenter et analyser des situations de la vie quotidienne, ainsi que pour faire des prédictions et fournir des renseignements à leur sujet. Il n’y a pas de contenus d’apprentissage rattachés à cette attente. La modélisation mathématique est un processus itératif et interconnecté qui, lorsque mis en application dans divers contextes, permet aux élèves de transférer des apprentissages effectués dans d’autres domaines d’étude. L’évaluation porte sur la manifestation par l’élève de son apprentissage du processus de modélisation mathématique dans le contexte des concepts et des connaissances acquis dans les autres domaines. En savoir plus sur le processus de la modélisation mathématique","specific":[]}]},{"code":"D","title":"Données","why":"Les élèves continuent d’accroître leur compréhension des données en apprenant des moyens de collecter, d’organiser, de représenter et d’interpréter des données plus complexes. Ils apprennent que la probabilité que certains événements puissent arriver peut être utilisée pour prendre des décisions éclairées. Par exemple, « s’il est très probable qu’il pleuve demain, je devrais porter des bottes de pluie ».","overall":[{"code":"D1","title":"Littératie statistique","text":"traiter, analyser et utiliser des données pour formuler des arguments persuasifs et prendre des décisions éclairées dans divers contextes de la vie quotidienne.","specific":[{"code":"D1.1","title":"Collecte et organisation des données","text":"trier et classer des ensembles de données portant sur des personnes ou des objets en fonction de deux attributs, en utilisant des tableaux et des logigrammes, y compris des diagrammes de Venn et de Carroll."},{"code":"D1.2","title":"Collecte et organisation des données","text":"collecter des données au moyen d’observations, d’expériences et d’entrevues pour répondre à des questions d’intérêt concernant deux éléments d’information, et organiser ces données à l’aide de tableaux de dénombrement à double entrée."},{"code":"D1.3","title":"Visualisation des données","text":"représenter des ensembles de données, en utilisant la correspondance un à un, à l’aide de diagrammes concrets, de diagrammes à pictogrammes, de lignes de dénombrement et de diagrammes à bandes, comprenant des sources, des titres et des étiquettes appropriés."},{"code":"D1.4","title":"Analyse des données","text":"déterminer le ou les modes de divers ensembles de données présentées dans des diagrammes concrets, des diagrammes à pictogrammes, des lignes de dénombrement, des diagrammes à bandes et des tableaux, et expliquer ce que ces valeurs indiquent au sujet des données."},{"code":"D1.5","title":"Analyse des données","text":"analyser divers ensembles de données présentées de différentes façons, y compris dans des logigrammes, des lignes de dénombrement et des diagrammes à bandes, en se posant des questions au sujet des données, en y répondant et en tirant des conclusions, et ensuite formuler des arguments persuasifs et prendre des décisions éclairées."}]},{"code":"D2","title":"Probabilité","text":"décrire la probabilité que des événements se produisent et utiliser cette information pour faire des prédictions.","specific":[{"code":"D2.1","title":"Probabilité","text":"utiliser le vocabulaire mathématique, y compris des termes comme « impossible », « possible » et « certain » pour exprimer la probabilité que des événements complémentaires se produisent et s’appuyer sur cette probabilité pour faire des prédictions et prendre des décisions éclairées."},{"code":"D2.2","title":"Probabilité","text":"formuler et vérifier des prédictions sur la probabilité que le ou les modes d’un ensemble de données reste le même si les données sont collectées auprès d’une population différente."}]}]},{"code":"E","title":"Sens de l’espace","why":"Les élèves continuent de développer leur sens de l’espace en apprenant à visualiser à quoi ressemblent diverses formes si on les retourne sur elles-mêmes ou les décompose. Ils apprennent à reconnaître et à décrire des formes géométriques plus complexes et à créer des cartes simples d’endroits familiers. Ils utilisent des outils comme une règle pour mesurer avec exactitude la longueur des objets, et une minuterie ou une horloge pour mesurer le temps.","overall":[{"code":"E1","title":"Raisonnement géométrique et spatial","text":"décrire et représenter la forme, la position et le déplacement en se servant de propriétés géométriques et de relations spatiales pour s’orienter dans le monde qui l’entoure.","specific":[{"code":"E1.1","title":"Raisonnement géométrique","text":"classer et identifier des figures planes en comparant le nombre de côtés, la longueur des côtés, les angles et le nombre d’axes de symétrie."},{"code":"E1.2","title":"Raisonnement géométrique","text":"composer et décomposer des figures planes, et montrer que l’aire d’une figure reste constante, quelle que soit la façon dont ses parties sont organisées."},{"code":"E1.3","title":"Raisonnement géométrique","text":"identifier des longueurs et des angles congrus dans des figures planes en les superposant mentalement et concrètement, et déterminer si les figures planes sont congruentes."},{"code":"E1.4","title":"Position et déplacement","text":"créer et interpréter des cartes simples représentant des lieux familiers."},{"code":"E1.5","title":"Position et déplacement","text":"décrire la position relative d’objets divers et les déplacements nécessaires pour passer d’un objet à l’autre."}]},{"code":"E2","title":"Sens de la mesure","text":"comparer, estimer et déterminer des mesures dans divers contextes.","specific":[{"code":"E2.1","title":"Longueur","text":"utiliser des unités de mesure non conventionnelles de façon appropriée pour mesurer des longueurs, et décrire la relation inverse entre la taille de l’unité et le nombre d’unités nécessaire."},{"code":"E2.2","title":"Longueur","text":"expliquer la relation entre les centimètres et les mètres comme unités de mesure de longueur, et utiliser des repères représentant ces unités pour estimer des longueurs."},{"code":"E2.3","title":"Longueur","text":"mesurer et tracer des longueurs en centimètres et en mètres en utilisant un instrument de mesure, et reconnaître les conséquences du choix d’un point de départ autre que zéro."},{"code":"E2.4","title":"Temps","text":"utiliser des unités de mesure de temps, y compris des secondes, des minutes, des heures ainsi que des unités de mesure non conventionnelles, pour décrire la durée d’une gamme d’activités."}]}]},{"code":"F","title":"Littératie financière","why":"Les élèves améliorent leur compréhension de la valeur de l’argent et déterminent diverses manières de représenter un montant d’argent, par exemple combien de combinaisons différentes de pièces il y a pour obtenir 1 $, et combien de combinaisons différentes de pièces de 1 $, de 2 $ et de billets il y a pour obtenir 100 $.","overall":[{"code":"F1","title":"Argent et finances","text":"démontrer sa compréhension de la valeur de la monnaie canadienne.","specific":[{"code":"F1.1","title":"Concepts monétaires","text":"déterminer différentes façons d’arriver au même montant d’argent en monnaie canadienne jusqu’à 200 ¢ avec diverses combinaisons de pièces de monnaie, et jusqu’à 200 $ avec différentes combinaisons de pièces de 1 $ et de 2 $ et de billets de 5 $, 10 $, 20 $, 50 $ et 100 $."}]}]}]},"g3":{"url":"https://www.dcp.edu.gov.on.ca/fr/curriculum/elementaire-mathematiques","sourceLang":"fr","strands":[{"code":"A","title":"Apprentissage socioémotionnel en mathématiques et processus mathématiques ","why":"Les élèves reconnaissent leurs émotions, comme la fierté, la confusion, la peur et l’excitation, et apprennent à les maîtriser; par exemple, en algèbre, lorsqu’ils créent et appliquent des codes qui représentent des situations mathématiques.","overall":[{"code":"A1","title":"Habiletés socioémotionnelles en mathématiques et processus mathématiques ","text":"mettre en application, au mieux de ses capacités, diverses habiletés socioémotionnelles pour appuyer son utilisation des processus mathématiques et son apprentissage lié aux attentes et aux contenus d’apprentissage des cinq autres domaines d’étude du programme-cadre de mathématiques.","specific":[]}]},{"code":"B","title":"Nombres","why":"Les élèves explorent les nombres jusqu’à 1 000 et apprennent à décomposer des nombres de diverses façons. Par exemple, le nombre 225 peut être décomposé ainsi: 200 + 20 + 5, ou deux centaines, deux dizaines et cinq unités. Les élèves apprennent que les fractions peuvent être représentées de plusieurs façons, par exemple, on peut penser à une demie comme étant deux quarts. On introduit les multiplications au moyen d’un modèle composé de rangées et de colonnes (disposition rectangulaire), et l’on s’attend à ce que les élèves sachent les tables de multiplication de 2, 5 et 10, par exemple 1 × 2, 2 × 2, 1 × 5, 2 × 5, 1 × 10, 2 × 10.","overall":[{"code":"B1","title":"Sens du nombre","text":"démontrer sa compréhension des nombres et établir des liens avec leur utilisation dans la vie quotidienne.","specific":[{"code":"B1.1","title":"Nombres naturels","text":"lire, représenter, composer et décomposer les nombres naturels de 0 jusqu’à 1 000, à l’aide d’une variété d’outils et de stratégies, et décrire de quelles façons ils sont utilisés dans la vie quotidienne."},{"code":"B1.2","title":"Nombres naturels","text":"comparer et ordonner les nombres naturels jusqu’à 1 000, dans divers contextes."},{"code":"B1.3","title":"Nombres naturels","text":"arrondir les nombres naturels à la dizaine et à la centaine près, dans divers contextes."},{"code":"B1.4","title":"Nombres naturels","text":"compter jusqu’à 1 000, y compris par intervalles de 50, 100 et 200, à l’aide d’une variété d’outils et de stratégies."},{"code":"B1.5","title":"Nombres naturels","text":"utiliser la valeur de position pour décrire et représenter des nombres de différentes façons, y compris à l’aide de matériel de base dix."},{"code":"B1.6","title":"Fractions","text":"utiliser des schémas pour représenter et résoudre des problèmes de partage équitable d’un tout pouvant comprendre jusqu’à 20 éléments entre 2, 3, 4, 5, 6, 8 et 10 personnes, incluant des problèmes dont le résultat est un nombre naturel, un nombre fractionnaire ou une fraction, et comparer les résultats."},{"code":"B1.7","title":"Fractions","text":"représenter et résoudre des problèmes de partage équitable ciblant la recherche et l’utilisation des fractions équivalentes, y compris des problèmes comportant des demis, des quarts et des huitièmes; des tiers et des sixièmes; ou des cinquièmes et des dixièmes."}]},{"code":"B2","title":"Sens des opérations ","text":"utiliser ses connaissances des nombres et des opérations pour résoudre des problèmes mathématiques de la vie quotidienne.","specific":[{"code":"B2.1","title":"Propriétés et relations","text":"utiliser les propriétés des opérations, et démontrer les relations entre la multiplication et la division pour résoudre des problèmes et vérifier la vraisemblance des calculs."},{"code":"B2.2","title":"Faits numériques","text":"se rappeler les faits de multiplication de 2, 5 et 10, et les faits de division associés, et démontrer sa compréhension de ces faits."},{"code":"B2.3","title":"Calcul mental","text":"utiliser des stratégies de calcul mental, y compris l’estimation, pour additionner des nombres dont la somme est égale ou inférieure à 1 000 et pour soustraire des nombres naturels égaux ou inférieurs à 1 000, et expliquer les stratégies utilisées."},{"code":"B2.4","title":"Addition et soustraction","text":"démontrer sa compréhension des algorithmes de l’addition et de la soustraction de nombres naturels en établissant des liens avec les outils et les stratégies utilisés pour additionner et soustraire, et décrire ces liens."},{"code":"B2.5","title":"Addition et soustraction","text":"représenter et résoudre des problèmes relatifs à l’addition de nombres naturels dont la somme est égale ou inférieure à 1 000 et à la soustraction de nombres naturels égaux ou inférieurs à 1 000, à l’aide d’une variété d’outils et d’algorithmes."},{"code":"B2.6","title":"Multiplication et division","text":"représenter la multiplication de nombres jusqu’à 10 × 10 et la division de nombres jusqu’à 100 ÷ 10, à l’aide d’une variété d’outils et de schémas, y compris des dispositions rectangulaires."},{"code":"B2.7","title":"Multiplication et division","text":"représenter et résoudre des problèmes relatifs à la multiplication et à la division, y compris des problèmes comprenant des groupes de un demi, un tiers et un quart, à l’aide d’outils et de schémas."},{"code":"B2.8","title":"Multiplication et division","text":"démontrer la relation entre le numérateur d’une fraction et l’addition répétée de la fraction unitaire ayant le même dénominateur, à l’aide d’une variété d’outils et de schémas ainsi que de la notation fractionnaire usuelle."},{"code":"B2.9","title":"Multiplication et division","text":"utiliser les rapports de 1 à 2, de 1 à 5 et de 1 à 10 pour résoudre des problèmes, y compris des problèmes faisant appel au raisonnement proportionnel."}]}]},{"code":"C","title":"Algèbre","why":"Les élèves apprennent à repérer et à décrire ce qui se répète dans une régularité, par exemple une activité donnée qui se produit tous les lundis, ou une séquence numérique qui croît de deux à chaque fois. On commence à présenter aux élèves des multiplications et des divisions qui sont équivalentes, par exemple 3 × 4 et 6 × 2. Les élèves écrivent des codes pour exécuter une opération répétitive, telle que la production d’une suite numérique à motif répété. Ils apprennent à utiliser la modélisation mathématique pour analyser et créer des solutions possibles s’appliquant à des situations réelles, comme la collecte de fonds pour un organisme de bienfaisance.","overall":[{"code":"C1","title":"Suites et relations","text":"reconnaître, décrire, prolonger et créer une variété de suites, y compris des suites trouvées dans la vie quotidienne, et faire des prédictions à leur sujet.","specific":[{"code":"C1.1","title":"Suites","text":"reconnaître et décrire les éléments et les opérations qui se répètent dans diverses suites (numériques et non numériques), y compris des suites trouvées dans la vie quotidienne."},{"code":"C1.2","title":"Suites","text":"créer des suites qui comprennent des éléments, des mouvements ou des opérations qui se répètent, à l’aide d’une variété de représentations, y compris des formes géométriques, des nombres et des tables de valeurs, et établir des liens entre les différentes représentations."},{"code":"C1.3","title":"Suites","text":"déterminer et utiliser les règles pour prolonger des suites, faire et justifier des prédictions, et trouver des termes manquants dans des suites qui ont des éléments, des mouvements ou des opérations qui se répètent."},{"code":"C1.4","title":"Suites","text":"créer et décrire des suites numériques comprenant des nombres naturels jusqu’à 1 000, et représenter des relations entre ces nombres."}]},{"code":"C2","title":"Équations et inégalités","text":"démontrer sa compréhension des variables, des expressions, des égalités et des inégalités et mettre en application cette compréhension dans divers contextes.","specific":[{"code":"C2.1","title":"Variables","text":"décrire de quelles façons les variables sont utilisées et les utiliser de manière appropriée dans une variété de contextes."},{"code":"C2.2","title":"Relations d’égalité et d’inégalité","text":"déterminer si des ensembles d’expressions qui comportent des additions, des soustractions, des multiplications et des divisions sont équivalents ou non."},{"code":"C2.3","title":"Relations d’égalité et d’inégalité","text":"déterminer et utiliser les relations d’équivalence comprenant des nombres naturels jusqu’à 1 000, dans divers contextes."}]},{"code":"C3","title":"Codage","text":"résoudre des problèmes et créer des représentations de situations mathématiques de façons computationnelles à l’aide de concepts et d’habiletés en codage.","specific":[{"code":"C3.1","title":"Habiletés en codage","text":"résoudre des problèmes et créer des représentations de situations mathématiques de façons computationnelles en écrivant et exécutant des codes, y compris des codes comprenant des événements séquentiels, simultanés et répétitifs."},{"code":"C3.2","title":"Habiletés en codage","text":"lire et modifier des codes donnés, y compris des codes comprenant des événements séquentiels, simultanés et répétitifs, et décrire l’incidence de ces changements sur les résultats."}]},{"code":"C4","title":"Modélisation mathématique","text":"mettre en application le processus de modélisation mathématique pour représenter et analyser des situations de la vie quotidienne, ainsi que pour faire des prédictions et fournir des renseignements à leur sujet. Il n’y a pas de contenus d’apprentissage rattachés à cette attente. La modélisation mathématique est un processus itératif et interconnecté qui, lorsque mis en application dans divers contextes, permet aux élèves de transférer des apprentissages effectués dans d’autres domaines d’étude. L’évaluation porte sur la manifestation par l’élève de son apprentissage du processus de modélisation mathématique dans le contexte des concepts et des connaissances acquis dans les autres domaines. En savoir plus sur le processus de la modélisation mathématique","specific":[]}]},{"code":"D","title":"Données","why":"Les élèves approfondissent leur compréhension des données. Ils apprennent d’autres façons de collecter, d’organiser, de représenter et d’interpréter des données comportant de grands nombres. Ils commencent à inclure des échelles dans leurs diagrammes, de sorte à pouvoir représenter de plus grands ensembles de données et à se servir de la moyenne pour comparer les données.","overall":[{"code":"D1","title":"Littératie statistique","text":"traiter, analyser et utiliser des données pour formuler des arguments persuasifs et prendre des décisions éclairées dans divers contextes de la vie quotidienne.","specific":[{"code":"D1.1","title":"Collecte et organisation des données","text":"trier et classer des ensembles de données portant sur des personnes ou des objets en fonction de deux ou trois attributs, en utilisant des tableaux et des logigrammes, y compris des diagrammes de Venn et de Carroll, et des diagrammes en arbre."},{"code":"D1.2","title":"Collecte et organisation des données","text":"collecter des données au moyen d’observations, d’expériences et d’entrevues pour répondre à des questions d’intérêt concernant les données qualitatives et quantitatives, et organiser les données à l’aide de tableaux de fréquences."},{"code":"D1.3","title":"Visualisation des données","text":"représenter des ensembles de données, en utilisant la correspondance un à plusieurs, à l’aide de diagrammes à pictogrammes et de diagrammes à bandes comprenant des sources, des titres, des étiquettes et des échelles appropriés."},{"code":"D1.4","title":"Analyse des données","text":"déterminer la moyenne et le ou les modes de divers ensembles de données représentées à l’aide de nombres naturels, et expliquer ce que chacune de ces valeurs indique au sujet des données."},{"code":"D1.5","title":"Analyse des données","text":"analyser divers ensembles de données présentées de différentes façons, y compris dans des tableaux de fréquences et des diagrammes à différentes échelles, en se posant des questions au sujet des données, en y répondant et en tirant des conclusions, et ensuite formuler des arguments persuasifs et prendre des décisions éclairées."}]},{"code":"D2","title":"Probabilité","text":"décrire la probabilité que des événements se produisent et utiliser cette information pour faire des prédictions.","specific":[{"code":"D2.1","title":"Probabilité","text":"utiliser le vocabulaire mathématique, y compris des termes comme « impossible », « peu probable », « équiprobable », « très probable » et « certain » pour exprimer la probabilité que des événements se produisent et s’appuyer sur cette probabilité pour faire des prédictions et prendre des décisions éclairées."},{"code":"D2.2","title":"Probabilité","text":"formuler et vérifier des prédictions sur la probabilité que la moyenne et le ou les modes d’un ensemble de données restent les mêmes si les données sont collectées auprès d’une population différente."}]}]},{"code":"E","title":"Sens de l’espace","why":"Les élèves continuent de développer leur sens de l’espace en reconnaissant et en décrivant des objets tridimensionnels et en imaginant à quoi pourraient ressembler ces objets s’ils étaient décomposés ou retournés sur eux-mêmes. Les élèves continuent de mesurer des longueurs et apprennent à mesurer ce qu’un objet peut peser et ce qu’il peut contenir. Ils mesurent l’aire et la comparent à la longueur, et apprennent à lire l’heure sur les horloges numériques et analogiques.","overall":[{"code":"E1","title":"Raisonnement géométrique et spatial","text":"décrire et représenter la forme, la position et le déplacement en se servant de propriétés géométriques et de relations spatiales pour s’orienter dans le monde qui l’entoure.","specific":[{"code":"E1.1","title":"Raisonnement géométrique","text":"classer, construire et identifier des cubes, des prismes, des pyramides, des cylindres et des cônes en comparant les faces, les sommets, les arêtes et les angles."},{"code":"E1.2","title":"Raisonnement géométrique","text":"composer et décomposer des structures variées, et reconnaître les figures planes et les solides qu’elles contiennent."},{"code":"E1.3","title":"Raisonnement géométrique","text":"reconnaître des longueurs et des angles congrus ainsi que des faces congruentes dans des solides en les superposant, et déterminer si les solides sont congruents."},{"code":"E1.4","title":"Position et déplacement","text":"donner et suivre des directives à étapes multiples, incluant des distances ainsi que des demi-tours et des quarts de tour, pour effectuer un déplacement d’un endroit à un autre."}]},{"code":"E2","title":"Sens de la mesure","text":"comparer, estimer et déterminer des mesures dans divers contextes.","specific":[{"code":"E2.1","title":"Longueur, masse et capacité","text":"utiliser des unités de mesure de longueur appropriées pour estimer, mesurer et comparer les périmètres de polygones et de lignes courbes fermées, et construire des polygones ayant un périmètre donné."},{"code":"E2.2","title":"Longueur, masse et capacité","text":"expliquer la relation entre les millimètres, les centimètres, les mètres et les kilomètres comme unités de mesure de longueur du système métrique, et utiliser des repères représentant ces unités pour estimer des longueurs."},{"code":"E2.3","title":"Longueur, masse et capacité","text":"utiliser correctement des unités de mesure non conventionnelles pour estimer, mesurer et comparer des capacités, et expliquer l’effet du remplissage excessif ou insuffisant et des espaces entre les unités sur l’exactitude de la mesure."},{"code":"E2.4","title":"Longueur, masse et capacité","text":"comparer, estimer et mesurer la masse de divers objets, à l’aide d’une balance à plateaux et des unités de mesure non conventionnelles."},{"code":"E2.5","title":"Longueur, masse et capacité","text":"utiliser des unités de mesure de tailles différentes pour mesurer le même attribut d’un objet donné et démontrer que même si l’utilisation de différentes unités de mesure donne des résultats différents, la taille de l’attribut reste inchangée."},{"code":"E2.6","title":"Temps","text":"utiliser des horloges et des minuteries analogiques et numériques pour dire l’heure, en heures, en minutes et en secondes."},{"code":"E2.7","title":"Aire","text":"comparer les aires de figures planes en les faisant correspondre, en les superposant ou en les décomposant et les recomposant, et démontrer que différentes figures planes peuvent avoir la même aire."},{"code":"E2.8","title":"Aire","text":"utiliser des unités de mesure non conventionnelles appropriées pour mesurer l’aire et expliquer l’incidence du chevauchement et des espaces entre les unités sur l’exactitude de la mesure."},{"code":"E2.9","title":"Aire","text":"utiliser des centimètres carrés (cm2) et des mètres carrés (m2) pour estimer, mesurer et comparer l’aire de diverses figures planes, y compris celles avec des lignes courbes."}]}]},{"code":"F","title":"Littératie financière","why":"Les élèves continuent d’élargir leur compréhension des montants d’argent en calculant la monnaie à rendre dans le cas de transactions simples comprenant des montants en dollars entiers.","overall":[{"code":"F1","title":"Argent et finances","text":"démontrer sa compréhension de la valeur et du rôle de la monnaie canadienne.","specific":[{"code":"F1.1","title":"Concepts monétaires","text":"estimer et calculer la monnaie à rendre pour diverses transactions monétaires simples en argent comptant, comportant des montants en dollars et des montants de moins de un dollar."}]}]}]},"g4":{"url":"https://www.dcp.edu.gov.on.ca/fr/curriculum/elementaire-mathematiques","sourceLang":"fr","strands":[{"code":"A","title":"Apprentissage socioémotionnel en mathématiques et processus mathématiques","why":"Pour éveiller leur motivation positive, les élèves emploieront divers outils et stratégies liés au sens de l’espace en utilisant la structure de rangées et colonnes de la disposition rectangulaire pour mesurer l’aire d’une table et en faisant des adaptations à mesure qu’ils avancent afin de trouver une solution.","overall":[{"code":"A1","title":"Habiletés socioémotionnelles en mathématiques et processus mathématiques ","text":"mettre en application, au mieux de ses capacités, diverses habiletés socioémotionnelles pour appuyer son utilisation des processus mathématiques et son apprentissage lié aux attentes et aux contenus d’apprentissage des cinq autres domaines d’étude du programme-cadre de mathématiques.","specific":[]}]},{"code":"B","title":"Nombres","why":"Les élèves utilisent les nombres jusqu’à 10 000 dans divers contextes et explorent les nombres décimaux. Ils apprennent comment les nombres décimaux sont utilisés dans la vie, par exemple pour prendre la température d’une personne avec un thermomètre ou pour calculer et enregistrer des mesures précises. Les élèves commencent à diviser des nombres naturels à deux et trois chiffres par un nombre naturel d’un chiffre. On s’attend à ce qu’ils connaissent leurs multiplications de 0 × 0 à 10 × 10. Ils commencent aussi à résoudre des problèmes nécessitant plus d’une opération avec des nombres naturels.","overall":[{"code":"B1","title":"Sens du nombre","text":"démontrer sa compréhension des nombres et établir des liens avec leur utilisation dans la vie quotidienne.","specific":[{"code":"B1.1","title":"Nombres naturels","text":"lire, représenter, composer et décomposer les nombres naturels de 0 jusqu’à 10 000, à l’aide d’outils et de stratégies appropriés, et décrire de quelles façons ils sont utilisés dans la vie quotidienne."},{"code":"B1.2","title":"Nombres naturels","text":"comparer et ordonner les nombres naturels jusqu’à 10 000, dans divers contextes."},{"code":"B1.3","title":"Nombres naturels","text":"arrondir les nombres naturels à la dizaine, à la centaine ou au millier près, dans divers contextes."},{"code":"B1.4","title":"Fractions et nombres décimaux","text":"représenter des fractions à partir des demis jusqu’aux dixièmes à l’aide de schémas, d’outils et de la notation fractionnaire usuelle, et expliquer la signification du numérateur et du dénominateur."},{"code":"B1.5","title":"Fractions et nombres décimaux","text":"utiliser des schémas et des modèles pour représenter, comparer et ordonner des fractions représentant les portions individuelles provenant de deux scénarios de partage équitable d’une quantité entre n’importe quel regroupement de 2, 3, 4, 5, 6, 8 et 10 personnes."},{"code":"B1.6","title":"Fractions et nombres décimaux","text":"compter jusqu’à 10 par intervalle de un demi, de un tiers, de un quart, de un cinquième, de un sixième, de un huitième et de un dixième avec ou sans l’aide d’outils."},{"code":"B1.7","title":"Fractions et nombres décimaux","text":"lire, représenter, comparer et ordonner des nombres décimaux jusqu’aux dixièmes, dans divers contextes."},{"code":"B1.8","title":"Fractions et nombres décimaux","text":"arrondir des nombres décimaux au nombre naturel le plus près, dans divers contextes."},{"code":"B1.9","title":"Fractions et nombres décimaux","text":"décrire les relations et représenter les équivalences entre des fractions et des nombres décimaux jusqu’aux dixièmes, dans divers contextes."}]},{"code":"B2","title":"Sens des opérations ","text":"utiliser ses connaissances des nombres et des opérations pour résoudre des problèmes mathématiques de la vie quotidienne.","specific":[{"code":"B2.1","title":"Propriétés et relations","text":"utiliser les propriétés des opérations et les relations entre l’addition, la soustraction, la multiplication et la division pour résoudre des problèmes comprenant des nombres naturels, y compris des problèmes nécessitant plus d’une opération, et vérifier la vraisemblance des calculs."},{"code":"B2.2","title":"Faits numériques","text":"se rappeler les faits de multiplication de 1 × 1 à 10 × 10 et les faits de division associés, et démontrer sa compréhension de ces faits."},{"code":"B2.3","title":"Calcul mental","text":"utiliser des stratégies de calcul mental pour multiplier un nombre naturel par 10, 100 et 1 000 et pour diviser un nombre naturel par 10, et additionner et soustraire des nombres décimaux jusqu’aux dixièmes, et expliquer les stratégies utilisées."},{"code":"B2.4","title":"Addition et soustraction","text":"représenter et résoudre des problèmes relatifs à l’addition de nombres naturels dont la somme est égale ou inférieure à 10 000 et à la soustraction de nombres naturels égaux ou inférieurs à 10 000 ainsi qu’à l’addition et à la soustraction de nombres décimaux jusqu’aux dixièmes, à l’aide d’outils et de stratégies appropriés, et d’algorithmes."},{"code":"B2.5","title":"Multiplication et division","text":"représenter et résoudre des problèmes relatifs à la multiplication d’un nombre naturel à deux ou à trois chiffres par un nombre naturel à un chiffre, et par 10, 100, et 1 000, à l’aide d’outils appropriés, y compris des dispositions rectangulaires."},{"code":"B2.6","title":"Multiplication et division","text":"représenter et résoudre des problèmes relatifs à la division d’un nombre naturel à deux ou à trois chiffres par un nombre naturel à un chiffre, en exprimant le reste sous forme de fraction, si nécessaire, à l’aide d’outils appropriés, y compris de dispositions rectangulaires."},{"code":"B2.7","title":"Multiplication et division","text":"démontrer la relation entre l’addition répétée d’une fraction unitaire et la multiplication de cette fraction unitaire par un nombre naturel, à l’aide d’outils, de schémas et de la notation fractionnaire usuelle."},{"code":"B2.8","title":"Multiplication et division","text":"représenter des relations multiplicatives simples comprenant des taux avec des nombres naturels, à l’aide d’une variété d’outils et de schémas."}]}]},{"code":"C","title":"Algèbre","why":"Les élèves poursuivent l’étude des suites en commençant à classifier des régularités selon qu’elles sont à motif répété ou croissantes. Ils commencent aussi à déterminer les valeurs qui font qu’un énoncé algébrique est vrai, par exemple, si n + 3 = 10, alors la valeur de n doit être 7. Les élèves apprennent aussi à écrire et à lire des codes pour créer des modèles géométriques. Ils utilisent le processus de modélisation pour analyser et créer des solutions dans le cas de situations réelles, telles un marche-o-thon pour collecter des fonds.","overall":[{"code":"C1","title":"Suites et relations","text":"reconnaître, décrire, prolonger et créer une variété de suites, y compris des suites trouvées dans la vie quotidienne, et faire des prédictions à leur sujet.","specific":[{"code":"C1.1","title":"Suites","text":"reconnaître et décrire des suites à motif répété et des suites croissantes, y compris des suites trouvées dans la vie quotidienne."},{"code":"C1.2","title":"Suites","text":"créer des suites à motif répété et des suites croissantes, à l’aide d’une variété de représentations, y compris des tables de valeurs et des représentations graphiques, et établir des liens entre les différentes représentations."},{"code":"C1.3","title":"Suites","text":"déterminer et utiliser les règles pour prolonger des suites, faire et justifier des prédictions, et trouver des termes manquants dans des suites à motif répété et des suites croissantes."},{"code":"C1.4","title":"Suites","text":"créer et décrire des suites numériques comprenant des nombres naturels et des nombres décimaux jusqu’aux dixièmes, et représenter des relations entre les nombres."}]},{"code":"C2","title":"Équations et inégalités","text":"démontrer sa compréhension des variables, des expressions, des égalités et des inégalités et mettre en application cette compréhension dans divers contextes.","specific":[{"code":"C2.1","title":"Variables","text":"déterminer et utiliser des symboles comme variables dans des expressions et des équations."},{"code":"C2.2","title":"Relations d’égalité et inégalité","text":"résoudre des équations qui comprennent des nombres naturels jusqu’à 50, dans divers contextes, et vérifier les solutions."},{"code":"C2.3","title":"Relations d’égalité et inégalité","text":"résoudre des inégalités qui comprennent des additions et des soustractions de nombres naturels jusqu’à 20, et vérifier et présenter les solutions à l’aide de modèles et de représentations graphiques."}]},{"code":"C3","title":"Codage","text":"résoudre des problèmes et créer des représentations de situations mathématiques de façons computationnelles, à l’aide de concepts et d’habiletés en codage.","specific":[{"code":"C3.1","title":"Habiletés en codage","text":"résoudre des problèmes et créer des représentations de situations mathématiques de façons computationnelles en écrivant et exécutant des codes, y compris des codes comprenant des événements séquentiels, simultanés, répétitifs et imbriqués."},{"code":"C3.2","title":"Habiletés en codage","text":"lire et modifier des codes donnés, y compris des codes comprenant des événements séquentiels, simultanés, répétitifs et imbriqués, et décrire l’incidence de ces changements sur les résultats."}]},{"code":"C4","title":"Modélisation mathématique","text":"mettre en application le processus de modélisation mathématique pour représenter et analyser des situations de la vie quotidienne, ainsi que pour faire des prédictions et fournir des renseignements à leur sujet. Il n’y a pas de contenus d’apprentissage rattachés à cette attente. La modélisation mathématique est un processus itératif et interconnecté qui, lorsque mis en application dans divers contextes, permet aux élèves de transférer des apprentissages effectués dans d’autres domaines d’étude. L’évaluation porte sur la manifestation par l’élève de son apprentissage du processus de modélisation mathématique dans le contexte des concepts et des connaissances acquis dans les autres domaines. En savoir plus sur le processus de la modélisation mathématique","specific":[]}]},{"code":"D","title":"Données","why":"Les élèves continuent d’élargir leur compréhension des données en collectant, organisant et présentant deux ou plusieurs ensembles de données à l’aide de tableaux de fréquences et de diagrammes à bandes multiples. Les élèves commencent à apprendre comment créer une infographie, ce qui leur permet d’interpréter les données.","overall":[{"code":"D1","title":"Littératie statistique","text":"traiter, analyser et utiliser des données pour formuler des arguments persuasifs et prendre des décisions éclairées dans divers contextes de la vie quotidienne.","specific":[{"code":"D1.1","title":"Collecte et organisation des données","text":"décrire la différence entre les données qualitatives et les données quantitatives, et fournir des exemples de leur utilisation dans divers contextes."},{"code":"D1.2","title":"Collecte et organisation des données","text":"collecter des données provenant de sources primaires et secondaires pour répondre à des questions d’intérêt concernant la comparaison entre deux ou plusieurs ensembles de données et organiser ces données à l’aide de tableaux de fréquences et de diagrammes à tiges et à feuilles."},{"code":"D1.3","title":"Visualisation des données","text":"choisir le diagramme le plus approprié pour représenter divers ensembles de données à partir d’une variété de diagrammes, y compris des diagrammes à bandes multiples; représenter ces données à l’aide de diagrammes comprenant des sources, des titres, des étiquettes et des échelles appropriés; et justifier son choix."},{"code":"D1.4","title":"Visualisation des données","text":"créer une infographie pour représenter un ensemble de données de façon appropriée, y compris à l’aide de tableaux de fréquences, de diagrammes à tiges et à feuilles et de diagrammes à bandes multiples, ainsi qu’en incorporant d’autres renseignements pertinents qui permettent de raconter une histoire au sujet des données."},{"code":"D1.5","title":"Analyse des données","text":"déterminer la moyenne, la médiane et le ou les modes de divers ensembles de données représentées à l’aide de nombres naturels, et expliquer ce que chacune de ces valeurs indique au sujet des données."},{"code":"D1.6","title":"Analyse des données","text":"examiner divers ensembles de données présentées de différentes façons, y compris dans des diagrammes à tiges et à feuilles et des diagrammes à bandes multiples, en se posant des questions au sujet des données, en y répondant et en tirant des conclusions, et ensuite formuler des arguments persuasifs et prendre des décisions éclairées."}]},{"code":"D2","title":"Probabilité","text":"décrire la probabilité que des événements se produisent et utiliser cette information pour faire des prédictions.","specific":[{"code":"D2.1","title":"Probabilité","text":"utiliser le vocabulaire mathématique, y compris des termes comme « impossible », « peu probable », « équiprobable », « très probable » et « certain » pour exprimer la probabilité que des événements se produisent, la représenter sur une ligne de probabilité et s’appuyer sur cette probabilité pour faire des prédictions et prendre des décisions éclairées."},{"code":"D2.2","title":"Probabilité","text":"formuler et vérifier des prédictions sur la probabilité que la moyenne, la médiane et le ou les modes d’un ensemble de données restent les mêmes si les données sont collectées auprès d’une population différente."}]}]},{"code":"E","title":"Sens de l’espace","why":"Les élèves apprennent les caractéristiques et les propriétés du rectangle, qui est une des formes les plus courantes dans notre vie quotidienne, et à trouver son aire. Ils apprennent la relation entre les diverses unités du système métrique, le système de mesure utilisé dans tout le Canada et dans la plus grande partie du monde.","overall":[{"code":"E1","title":"Raisonnement géométrique et spatial","text":"décrire et représenter la forme, la position et le déplacement en se servant de propriétés géométriques et de relations spatiales pour s’orienter dans le monde qui l’entoure.","specific":[{"code":"E1.1","title":"Raisonnement géométrique","text":"identifier les propriétés géométriques des rectangles, y compris le nombre d’angles droits, de côtés parallèles et perpendiculaires et d’axes de symétrie."},{"code":"E1.2","title":"Position et déplacement","text":"situer et lire des coordonnées dans le premier quadrant d’un plan cartésien, et décrire les déplacements d’une coordonnée à l’autre à l’aide de translations."},{"code":"E1.3","title":"Position et déplacement","text":"décrire et effectuer des translations et des réflexions dans une grille, et prédire les résultats de ces transformations."}]},{"code":"E2","title":"Sens de la mesure","text":"comparer, estimer et déterminer des mesures dans divers contextes.","specific":[{"code":"E2.1","title":"Système métrique","text":"expliquer les relations entre des grammes et des kilogrammes comme unités de mesure métriques de la masse ainsi que des millilitres et des litres comme unités de mesure métriques de la capacité, et utiliser des repères représentant ces unités pour estimer la masse et la capacité."},{"code":"E2.2","title":"Système métrique","text":"utiliser des préfixes métriques pour décrire la taille relative de différentes unités de mesure métriques et choisir l’unité et l’instrument de mesure appropriés pour mesurer la longueur, la masse et la capacité."},{"code":"E2.3","title":"Temps","text":"résoudre des problèmes associés à la durée en se servant des relations entre différentes unités de mesure de temps."},{"code":"E2.4","title":"Angles","text":"reconnaître des angles et les classer en tant qu’angle droit, plat, aigu ou obtus."},{"code":"E2.5","title":"Aire","text":"utiliser la structure en rangées et en colonnes d’une disposition rectangulaire pour mesurer l’aire d’un rectangle et pour démontrer que l’aire d’un rectangle peut être calculée en multipliant sa base par sa hauteur."},{"code":"E2.6","title":"Aire","text":"se servir de la formule de calcul de l’aire d’un rectangle pour trouver la mesure inconnue lorsque deux des trois mesures sont connues."}]}]},{"code":"F","title":"Littératie financière","why":"Les élèves apprennent qu’il existe différents moyens de payer des produits et des services. Ils apprennent aussi comment les consommateurs déterminent si un article donné a un bon rapport qualité-prix.","overall":[{"code":"F1","title":"Argent et finances","text":"démontrer les connaissances et les habiletés nécessaires pour prendre des décisions financières éclairées.","specific":[{"code":"F1.1","title":"Concepts monétaires","text":"déterminer divers modes de paiement qui peuvent être utilisés pour acheter des biens et des services."},{"code":"F1.2","title":"Concepts monétaires","text":"estimer et calculer le coût de transactions comprenant plusieurs articles dont les valeurs sont en dollars, en excluant les taxes de vente, ainsi que le montant de monnaie nécessaire lorsque le paiement est effectué en argent comptant, en utilisant le calcul mental."},{"code":"F1.3","title":"Gestion financière","text":"expliquer les concepts de dépense, d’épargne, de revenu, d’investissement et de don, et déterminer les principaux éléments à considérer dans la prise de décisions simples."},{"code":"F1.4","title":"Gestion financière","text":"expliquer la relation entre les dépenses et l’épargne, et décrire comment les comportements en matière de dépenses et d’épargne peuvent varier d’une personne à l’autre."},{"code":"F1.5","title":"Sensibilisation à la consommation et au civisme","text":"décrire des façons de déterminer si le prix d’une chose est raisonnable et par conséquent constitue un bon achat."}]}]}]},"g5":{"url":"https://www.dcp.edu.gov.on.ca/fr/curriculum/elementaire-mathematiques","sourceLang":"fr","strands":[{"code":"A","title":"Apprentissage socioémotionnel en mathématiques et processus mathématiques","why":"Les élèves continueront de développer des aptitudes relationnelles saines tout en travaillant avec les nombres. En jouant avec leurs camarades de classe à un jeu comprenant des fractions, des nombres décimaux et des nombres naturels, ils apprendront à établir des interactions positives et à faire preuve de patience lorsque c’est le tour des autres joueurs et que chaque personne avance à sa cadence pour trouver la réponse.","overall":[{"code":"A1","title":"Habiletés socioémotionnelles en mathématiques et processus mathématiques ","text":"mettre en application, au mieux de ses capacités, diverses habiletés socioémotionnelles pour appuyer son utilisation des processus mathématiques et son apprentissage lié aux attentes et aux contenus d’apprentissage des cinq autres domaines d’étude du programme-cadre de mathématiques.","specific":[]}]},{"code":"B","title":"Nombres","why":"Les élèves continuent d’explorer des nombres jusqu’à 100 000. Ils abordent les pourcentages et continuent d’accroître leur compréhension des nombres décimaux et des fractions. Ils abordent également l’addition et la soustraction de fractions ayant le même dénominateur. On s’attend à ce que les élèves connaissent les tables de multiplication de 0 × 0 à 12 × 12. Les élèves résolvent aussi des problèmes comprenant plus d’une opération avec des nombres naturels et décimaux.","overall":[{"code":"B1","title":"Sens du nombre","text":"démontrer sa compréhension des nombres et établir des liens avec leur utilisation dans la vie quotidienne.","specific":[{"code":"B1.1","title":"Nombres naturels","text":"lire, représenter, composer et décomposer les nombres naturels de 0 jusqu’à 100 000, à l’aide d’outils et de stratégies appropriés, et décrire de quelles façons ils sont utilisés dans la vie quotidienne."},{"code":"B1.2","title":"Nombres naturels","text":"comparer et ordonner les nombres naturels jusqu’à 100 000, dans divers contextes."},{"code":"B1.3","title":"Fractions, nombres décimaux et pourcentages","text":"représenter des fractions équivalentes à partir des demis jusqu’aux douzièmes, y compris des fractions impropres et des nombres fractionnaires, à l’aide d’outils appropriés, dans divers contextes."},{"code":"B1.4","title":"Fractions, nombres décimaux et pourcentages","text":"comparer et ordonner des fractions à partir des demis jusqu’aux douzièmes, y compris des fractions impropres et des nombres fractionnaires, dans divers contextes."},{"code":"B1.5","title":"Fractions, nombres décimaux et pourcentages","text":"lire, représenter, comparer et ordonner des nombres décimaux jusqu’aux centièmes, dans divers contextes."},{"code":"B1.6","title":"Fractions, nombres décimaux et pourcentages","text":"arrondir les nombres décimaux au dixième près, dans divers contextes."},{"code":"B1.7","title":"Fractions, nombres décimaux et pourcentages","text":"décrire les relations et représenter les équivalences entre des fractions, des nombres décimaux jusqu’aux centièmes et des pourcentages, à l’aide d’outils et de schémas appropriés, dans divers contextes."}]},{"code":"B2","title":"Sens des opérations ","text":"utiliser ses connaissances des nombres et des opérations pour résoudre des problèmes mathématiques de la vie quotidienne.","specific":[{"code":"B2.1","title":"Propriétés et relations","text":"utiliser les propriétés des opérations et les relations entre les opérations pour résoudre des problèmes comprenant des nombres naturels et des nombres décimaux, y compris des problèmes nécessitant plus d’une opération, et vérifier la vraisemblance des calculs."},{"code":"B2.2","title":"Faits numériques","text":"se rappeler les faits de multiplication de 0 × 0 à 12 × 12 et les faits de division associés, et démontrer sa compréhension de ces faits."},{"code":"B2.3","title":"Calcul mental","text":"utiliser des stratégies de calcul mental pour multiplier des nombres naturels par 0,1 et 0,01 et estimer des sommes et des différences de nombres décimaux jusqu’aux centièmes, et expliquer les stratégies utilisées."},{"code":"B2.4","title":"Addition et soustraction","text":"représenter et résoudre des problèmes relatifs à l’addition de nombres naturels dont la somme est égale ou inférieure à 100 000 et à la soustraction de nombres naturels égaux ou inférieurs à 100 000, et l’addition et la soustraction de nombres décimaux jusqu’aux centièmes, à l’aide d’outils et de stratégies appropriés, et d’algorithmes."},{"code":"B2.5","title":"Addition et soustraction","text":"additionner et soustraire des fractions ayant des dénominateurs communs, dans divers contextes."},{"code":"B2.6","title":"Multiplication et division","text":"représenter et résoudre des problèmes relatifs à la multiplication d’un nombre naturel à deux chiffres par un nombre naturel à deux chiffres, et établir des liens entre la disposition rectangulaire et les algorithmes."},{"code":"B2.7","title":"Multiplication et division","text":"représenter et résoudre des problèmes relatifs à la division d’un nombre naturel à trois chiffres par un nombre naturel à deux chiffres, et établir des liens entre la disposition rectangulaire et les algorithmes, et exprimer le reste de façon appropriée."},{"code":"B2.8","title":"Multiplication et division","text":"multiplier et diviser un nombre naturel à un chiffre par une fraction unitaire, à l’aide d’outils et de schémas."},{"code":"B2.9","title":"Multiplication et division","text":"représenter et créer des rapports et des taux équivalents, à l’aide d’une variété d’outils et de modèles, dans divers contextes."}]}]},{"code":"C","title":"Algèbre","why":"Les élèves continuent de classer les suites selon qu’elles sont à motif répété, croissantes ou décroissantes. Ils commencent à écrire et à résoudre des équations algébriques utilisant des nombres naturels, comme 3 + x = 24 - 5. Les élèves se servent de leur compréhension de la multiplication et des rapports pour créer et exécuter des codes s’appliquant à des régularités croissantes. Ils utilisent le processus de la modélisation mathématique pour résoudre des problèmes tirés de la vie quotidienne, par exemple en créant la maquette du terrain de jeu d’une école et en calculant le coût des structures de jeux choisies.","overall":[{"code":"C1","title":"Suites et relations","text":"reconnaître, décrire, prolonger et créer une variété de suites, y compris des suites trouvées dans la vie quotidienne, et faire des prédictions à leur sujet.","specific":[{"code":"C1.1","title":"Suites","text":"reconnaître et décrire des suites à motif répété ainsi que des suites croissantes et des suites décroissantes, y compris des suites trouvées dans la vie quotidienne."},{"code":"C1.2","title":"Suites","text":"créer des suites croissantes et des suites décroissantes, à l’aide d’une variété de représentations, y compris des tables de valeurs et des représentations graphiques, et établir des liens entre les différentes représentations."},{"code":"C1.3","title":"Suites","text":"déterminer et utiliser des règles pour prolonger des suites, faire et justifier des prédictions, et trouver des termes manquants dans des suites à motif répété et des suites croissantes et décroissantes."},{"code":"C1.4","title":"Suites","text":"créer et décrire des suites numériques comprenant des nombres naturels, des nombres décimaux jusqu’aux dixièmes et des nombres décimaux jusqu’aux centièmes, et représenter des relations entre les nombres."}]},{"code":"C2","title":"Équations et inégalités","text":"démontrer sa compréhension des variables, des expressions, des égalités et des inégalités et mettre en application cette compréhension dans divers contextes.","specific":[{"code":"C2.1","title":"Variables et expressions","text":"décrire des relations d’équivalence à l’aide de mots, d’expressions algébriques et de représentations visuelles, et établir les liens entre les représentations."},{"code":"C2.2","title":"Variables et expressions","text":"évaluer des expressions algébriques comprenant des nombres naturels."},{"code":"C2.3","title":"Relations d’égalité et d’inégalité","text":"résoudre des équations qui comprennent des nombres naturels jusqu’à 100, dans divers contextes, et vérifier les solutions."},{"code":"C2.4","title":"Relations d’égalité et d’inégalité","text":"résoudre des inégalités qui comprennent une opération et des nombres naturels jusqu’à 50, et vérifier et présenter les solutions à l’aide de modèles et de représentations graphiques."}]},{"code":"C3","title":"Codage","text":"résoudre des problèmes et créer des représentations de situations mathématiques de façons computationnelles, à l’aide de concepts et d’habiletés en codage.","specific":[{"code":"C3.1","title":"Habiletés en codage","text":"résoudre des problèmes et créer des représentations de situations mathématiques de façons computationnelles en écrivant et exécutant des codes, y compris des codes comprenant des instructions conditionnelles et d’autres structures de contrôle."},{"code":"C3.2","title":"Habiletés en codage","text":"lire et modifier des codes donnés, y compris des codes comprenant des instructions conditionnelles et d’autres structures de contrôle, et décrire l’incidence de ces changements sur les résultats."}]},{"code":"C4","title":"Modélisation mathématique","text":"mettre en application le processus de modélisation mathématique pour représenter et analyser des situations de la vie quotidienne, ainsi que pour faire des prédictions et fournir des renseignements à leur sujet. Il n’y a pas de contenus d’apprentissage rattachés à cette attente. La modélisation mathématique est un processus itératif et interconnecté qui, lorsque mis en application dans divers contextes, permet aux élèves de transférer des apprentissages effectués dans d’autres domaines d’étude. L’évaluation porte sur la manifestation par l’élève de son apprentissage du processus de modélisation mathématique dans le contexte des concepts et des connaissances acquis dans les autres domaines. En savoir plus sur le processus de la modélisation mathématique","specific":[]}]},{"code":"D","title":"Données","why":"Les élèves apprennent l’importance de l’utilisation de diverses techniques d’échantillonnage pour obtenir de « bonnes » données. Ils créent des infographies et apprennent comment déterminer si un diagramme est trompeur. Les élèves commencent à faire des expériences pour comprendre le concept de la probabilité.","overall":[{"code":"D1","title":"Littératie statistique","text":"traiter, analyser et utiliser des données pour formuler des arguments persuasifs et prendre des décisions éclairées dans divers contextes de la vie quotidienne.","specific":[{"code":"D1.1","title":"Collecte et organisation des données","text":"expliquer l’importance de diverses techniques d’échantillonnage pour collecter des données à partir d’un échantillon représentatif d’une population."},{"code":"D1.2","title":"Collecte et organisation des données","text":"collecter des données, en utilisant des techniques d’échantillonnage appropriées, pour répondre à des questions d’intérêt portant sur une population, et organiser les données dans des tableaux de fréquences relatives."},{"code":"D1.3","title":"Visualisation des données","text":"choisir le diagramme le plus approprié pour représenter divers ensembles de données à partir d’une variété de diagrammes, y compris des diagrammes à bandes empilées; représenter ces données à l’aide de diagrammes comprenant des sources, des titres, des étiquettes et des échelles appropriés; et justifier son choix."},{"code":"D1.4","title":"Visualisation des données","text":"créer une infographie pour représenter un ensemble de données de façon appropriée, y compris à l’aide de tableaux de fréquences relatives et de diagrammes à bandes empilées, ainsi qu’en incorporant d’autres renseignements pertinents qui permettent de raconter une histoire au sujet des données."},{"code":"D1.5","title":"Analyse des données","text":"déterminer la moyenne, la médiane et le ou les modes de divers ensembles de données représentées à l’aide de nombres naturels et de nombres décimaux, et expliquer ce que chacune de ces valeurs indique concernant les données."},{"code":"D1.6","title":"Analyse des données","text":"examiner divers ensembles de données présentées de différentes façons, y compris à l’aide de diagrammes à bandes empilées et de diagrammes trompeurs, en se posant des questions au sujet des données et en y répondant, en remettant en question des idées reçues et en tirant des conclusions, et ensuite formuler des arguments persuasifs et prendre des décisions éclairées."}]},{"code":"D2","title":"Probabilité","text":"décrire la probabilité que des événements se produisent et utiliser cette information pour faire des prédictions.","specific":[{"code":"D2.1","title":"Probabilité","text":"utiliser des fractions pour exprimer la probabilité que des événements se produisent, la représenter sur une ligne de probabilité et s’appuyer sur cette probabilité pour faire des prédictions et prendre des décisions éclairées."},{"code":"D2.2","title":"Probabilité","text":"déterminer et comparer les probabilités théoriques et expérimentales qu’un événement se produise."}]}]},{"code":"E","title":"Sens de l’espace","why":"Les élèves continuent de développer leurs connaissances du sens de l’espace avec l’étude du triangle. Ils apprennent les caractéristiques et les propriétés de divers types de triangles, notamment leurs angles et mesures. Ils continuent de mieux comprendre et d’utiliser le système métrique pour mesurer la longueur, l’aire, la masse et la capacité et pour faire des conversions de grandes unités en petites unités.","overall":[{"code":"E1","title":"Raisonnement géométrique et spatial","text":"décrire et représenter la forme, la position et le déplacement en se servant de propriétés géométriques et de relations spatiales pour s’orienter dans le monde qui l’entoure.","specific":[{"code":"E1.1","title":"Raisonnement géométrique","text":"reconnaître les propriétés géométriques des triangles et construire divers types de triangles en utilisant des mesures d’angles ou de côtés données."},{"code":"E1.2","title":"Raisonnement géométrique","text":"reconnaître et construire des triangles, des rectangles et des parallélogrammes congruents."},{"code":"E1.3","title":"Raisonnement géométrique","text":"tracer les vues de côté, de face et de dessus de divers objets et faire correspondre le dessin à l’objet."},{"code":"E1.4","title":"Position et déplacement","text":"situer et lire des coordonnées dans le premier quadrant d’un plan cartésien en utilisant diverses échelles, et décrire les déplacements d’une coordonnée à l’autre à l’aide de translations."},{"code":"E1.5","title":"Position et déplacement","text":"décrire et effectuer des translations, des réflexions et des rotations jusqu’à 180° dans une grille, et prédire les résultats de ces transformations."}]},{"code":"E2","title":"Sens de la mesure","text":"comparer, estimer et déterminer des mesures dans divers contextes.","specific":[{"code":"E2.1","title":"Système métrique","text":"utiliser des unités de mesure métriques appropriées pour estimer et mesurer la longueur, l’aire, la masse et la capacité."},{"code":"E2.2","title":"Système métrique","text":"résoudre des problèmes associés à la conversion de grandes unités de mesure métriques en des unités plus petites et décrire les relations en base dix entre les unités de mesure métriques."},{"code":"E2.3","title":"Angles","text":"comparer des angles et déterminer leurs tailles respectives en les superposant et en les mesurant au moyen d’unités de mesure non conventionnelles appropriées."},{"code":"E2.4","title":"Angles","text":"expliquer le fonctionnement d’un rapporteur d’angles et l’utiliser pour mesurer et construire des angles jusqu’à 180°, et se servir d’angles repères pour estimer la taille d’autres angles."},{"code":"E2.5","title":"Aire","text":"utiliser les relations entre l’aire des rectangles, des parallélogrammes et des triangles afin de développer des formules pour l’aire d’un parallélogramme et d’un triangle, et résoudre des problèmes connexes."},{"code":"E2.6","title":"Aire","text":"démontrer que des figures planes ayant la même aire peuvent avoir des périmètres différents et résoudre des problèmes connexes."}]}]},{"code":"F","title":"Littératie financière","why":"Les élèves apprennent différentes façons de transférer de l’argent entre des personnes et des organisations, notamment à l’aide de transferts électroniques et de chèques. Ils calculent le coût total et la monnaie à rendre dans le cas d’achats en espèces où le prix des articles est donné en dollars et en cents, en utilisant le calcul mental et d’autres stratégies. Ils apprennent également à déterminer la valeur la plus avantageuse d’un article: par exemple, cinq pommes pour 1 $ ou trois pommes pour 75 ¢. Les élèves établissent des budgets de base et apprennent le concept de crédit et de dette.","overall":[{"code":"F1","title":"Argent et finances","text":"démontrer les connaissances et les habiletés nécessaires pour prendre des décisions financières éclairées.","specific":[{"code":"F1.1","title":"Concepts monétaires","text":"décrire différentes façons de transférer de l’argent entre des personnes, des organismes ou des entreprises."},{"code":"F1.2","title":"Concepts monétaires","text":"estimer et calculer le coût de transactions comprenant plusieurs articles dont le prix est exprimé en dollars et en cents, en incluant les taxes de vente, à l’aide de diverses stratégies."},{"code":"F1.3","title":"Gestion financière","text":"établir des exemples de budgets simples afin de gérer des finances dans diverses situations de revenu et de dépenses."},{"code":"F1.4","title":"Gestion financière","text":"expliquer les concepts de crédit et de dette, et décrire l’impact potentiel du crédit et de la dette sur les décisions financières."},{"code":"F1.5","title":"Sensibilisation à la consommation et au civisme","text":"calculer des prix unitaires pour divers biens et services, et déterminer quels prix représentent l’achat le plus avantageux."},{"code":"F1.6","title":"Sensibilisation à la consommation et au civisme","text":"décrire les types de taxes qui sont perçues par les divers ordres de gouvernement au Canada, et expliquer comment les recettes fiscales sont utilisées pour fournir des services à la communauté."}]}]}]},"g6":{"url":"https://www.dcp.edu.gov.on.ca/fr/curriculum/elementaire-mathematiques","sourceLang":"fr","strands":[{"code":"A","title":"Apprentissage socioémotionnel en mathématiques et processus mathématiques","why":"Les élèves continuent de développer la notion de soi. Ils font un suivi des différents aspects qui ont une incidence sur leur santé mentale et physique, par exemple le nombre de pas qu’ils font chaque jour ou les minutes passées devant l’écran ou comment ils se sentent après avoir fait de l’activité physique. Ils se servent de diagrammes et d’outils de visualisation des données afin de réfléchir et d’apprendre en se fondant sur l’information ainsi produite.","overall":[{"code":"A1","title":"Habiletés socioémotionnelles en mathématiques et processus mathématiques ","text":"mettre en application, au mieux de ses capacités, diverses habiletés socioémotionnelles pour appuyer son utilisation des processus mathématiques et son apprentissage lié aux attentes et aux contenus d’apprentissage des cinq autres domaines d’étude du programme-cadre de mathématiques.","specific":[]}]},{"code":"B","title":"Nombres","why":"Les élèves utilisent des nombres jusqu’à 1 million dans divers contextes, et on leur présente des nombres entiers tels que -2, -1, 0, 1, 2. Ils apprennent les règles de divisibilité par 2, 3, 4, 5, 6, 8, 9 et 10, par exemple, un nombre est divisible par 5 s’il se termine par 5 ou 0. Les élèves élargissent l’étendue de leurs compétences en opérations mathématiques en apprenant entre autres à diviser un nombre naturel par une fraction ou un nombre mixte, comme 2 ½. Les élèves résolvent aussi des problèmes comprenant plus d’une opération comprenant des nombres naturels, des nombres décimaux et des fractions.","overall":[{"code":"B1","title":"Sens du nombre","text":"démontrer sa compréhension des nombres et établir des liens avec leur utilisation dans la vie quotidienne.","specific":[{"code":"B1.1","title":"Nombres rationnels","text":"lire et représenter les nombres naturels de 0 jusqu’à un million, à l’aide d’outils et de stratégies appropriés, et décrire de quelles façons ils sont utilisés dans la vie quotidienne."},{"code":"B1.2","title":"Nombres rationnels","text":"lire et représenter des nombres entiers, à l’aide d’outils et de stratégies, y compris des droites numériques horizontales et verticales."},{"code":"B1.3","title":"Nombres rationnels","text":"comparer et ordonner des nombres entiers, des nombres décimaux et des fractions, séparément et en les combinant, dans divers contextes."},{"code":"B1.4","title":"Fractions, nombres décimaux et pourcentages","text":"lire, représenter, comparer et ordonner les nombres décimaux jusqu’aux millièmes, dans divers contextes."},{"code":"B1.5","title":"Fractions, nombres décimaux et pourcentages","text":"arrondir des nombres à virgule, dont la partie décimale est finie ou périodique, au dixième et au centième près, ainsi qu’au nombre naturel près, selon le cas, dans divers contextes."},{"code":"B1.6","title":"Fractions, nombres décimaux et pourcentages","text":"décrire les relations et représenter l’équivalence entre des fractions et des nombres décimaux jusqu’aux millièmes, à l’aide d’outils et de schémas appropriés, dans divers contextes."}]},{"code":"B2","title":"Sens des opérations ","text":"utiliser ses connaissances des nombres et des opérations pour résoudre des problèmes mathématiques de la vie quotidienne.","specific":[{"code":"B2.1","title":"Propriétés et relations","text":"utiliser les propriétés des opérations et les relations entre les opérations pour résoudre des problèmes comportant des nombres naturels, des nombres décimaux, des fractions, des rapports, des taux, et des pourcentages, y compris des problèmes à plusieurs étapes ou plusieurs opérations."},{"code":"B2.2","title":"Faits numériques","text":"comprendre les critères de divisibilité et les utiliser pour vérifier si les nombres sont divisibles par 2, 3, 4, 5, 6, 8, 9, et 10."},{"code":"B2.3","title":"Calcul mental","text":"utiliser des stratégies de calcul mental pour calculer des pourcentages de 1 %, 5 %, 10 %, 15 %, 25 % et 50 % de nombres naturels, et expliquer les stratégies utilisées."},{"code":"B2.4","title":"Addition et soustraction","text":"représenter et résoudre des problèmes relatifs à l’addition et à la soustraction de nombres naturels et de nombres décimaux, à l’aide d’estimations et d’algorithmes."},{"code":"B2.5","title":"Addition et soustraction","text":"additionner et soustraire des fractions avec et sans dénominateurs communs, à l’aide d’outils et de stratégies appropriés, dans divers contextes."},{"code":"B2.6","title":"Multiplication et division","text":"représenter des nombres composés sous la forme d’une multiplication de ses facteurs premiers, y compris à l’aide de l’arbre de facteurs."},{"code":"B2.7","title":"Multiplication et division","text":"représenter et résoudre des problèmes relatifs à la multiplication d’un nombre naturel à trois chiffres par un nombre décimal jusqu’aux dixièmes, à l’aide d’algorithmes."},{"code":"B2.8","title":"Multiplication et division","text":"représenter et résoudre des problèmes relatifs à la division d’un nombre naturel à trois chiffres par un nombre décimal jusqu’aux dixièmes, à l’aide d’outils et de stratégies appropriés, et d’algorithmes, et exprimer le reste de façon appropriée."},{"code":"B2.9","title":"Multiplication et division","text":"multiplier des nombres naturels par des fractions propres, à l’aide d’outils et de stratégies appropriés."},{"code":"B2.10","title":"Multiplication et division","text":"diviser des nombres naturels par des fractions propres, à l’aide d’une variété d’outils et de stratégies."},{"code":"B2.11","title":"Multiplication et division","text":"représenter et résoudre des problèmes relatifs à la division de nombres décimaux jusqu’aux millièmes par un nombre naturel égal ou inférieur à 10, à l’aide d’outils et de stratégies appropriés."},{"code":"B2.12","title":"Multiplication et division","text":"résoudre des problèmes comprenant des rapports, y compris des pourcentages et des taux, à l’aide d’outils et de stratégies appropriés."}]}]},{"code":"C","title":"Algèbre","why":"Les élèves continuent de faire des exercices portant sur les suites et commencent à identifier celles qui ont un taux constant (par exemple, la distance parcourue en un temps donné augmente de 100 kilomètres par heure). Ils résolvent des équations algébriques ayant des nombres naturels et des dixièmes, ainsi que des équations comprenant des termes multiples tels que 2x + 3x = 5. Les élèves utilisent le codage pour résoudre des problèmes d’optimisation, par exemple pour trouver l’aire maximale d’un périmètre donné. Ils utilisent aussi le processus de modélisation mathématique pour résoudre des problèmes tirés de la vie quotidienne, par exemple déterminer diverses manières de maximiser l’aire des jeux d’un terrain de jeu et de calculer le coût de chaque possibilité.","overall":[{"code":"C1","title":"Suites et relations","text":"reconnaître, décrire, prolonger et créer une variété de suites, y compris des suites trouvées dans la vie quotidienne, et faire des prédictions à leur sujet.","specific":[{"code":"C1.1","title":"Suites","text":"reconnaître et décrire des suites à motif répété ainsi que des suites croissantes et des suites décroissantes, y compris celles trouvées dans la vie quotidienne, et déterminer lesquelles sont des suites croissantes linéaires."},{"code":"C1.2","title":"Suites","text":"créer des suites à motif répété, des suites croissantes et des suites décroissantes à l’aide d’une variété de représentations y compris des tables de valeurs, des représentations graphiques, ainsi que des expressions algébriques et des équations pour des suites croissantes linéaires, et établir des liens entre les différentes représentations."},{"code":"C1.3","title":"Suites","text":"déterminer et utiliser les règles pour prolonger des suites, faire et justifier des prédictions, et trouver les termes manquants dans des suites à motif répété, des suites croissantes et des suites décroissantes, et utiliser les représentations symboliques des règles pour trouver des valeurs inconnues dans des suites croissantes linéaires."},{"code":"C1.4","title":"Suites","text":"créer et décrire des suites numériques comprenant des nombres naturels et des nombres décimaux, et représenter des relations entre ces nombres."}]},{"code":"C2","title":"Équations et inégalités","text":"démontrer sa compréhension des variables, des expressions, des égalités et des inégalités et mettre en application cette compréhension dans divers contextes.","specific":[{"code":"C2.1","title":"Variables et expressions","text":"additionner des monômes du premier degré comprenant des nombres naturels, à l’aide d’outils."},{"code":"C2.2","title":"Variables et expressions","text":"évaluer des expressions algébriques comprenant des nombres naturels et des nombres décimaux jusqu’aux dixièmes."},{"code":"C2.3","title":"Relations d’égalité et inégalité","text":"résoudre des équations qui comprennent des termes multiples et des nombres naturels, dans divers contextes, et vérifier les solutions."},{"code":"C2.4","title":"Relations d’égalité et inégalité","text":"résoudre des inégalités qui comprennent deux opérations et des nombres naturels jusqu’à 100, et vérifier et présenter les solutions à l’aide de modèles et de représentations graphiques."}]},{"code":"C3","title":"Codage","text":"mettre en application ses habiletés en codage pour résoudre des problèmes et créer des représentations de situations mathématiques de façons computationnelles, à l’aide de concepts et d’habiletés en codage.","specific":[{"code":"C3.1","title":"Habiletés en codage","text":"résoudre des problèmes et créer des représentations de situations mathématiques de façons computationnelles en écrivant et exécutant des codes efficaces, y compris des codes comprenant des instructions conditionnelles et d’autres structures de contrôle."},{"code":"C3.2","title":"Habiletés en codage","text":"lire et modifier des codes donnés, y compris des codes comprenant des instructions conditionnelles et d’autres structures de contrôle, et décrire l’incidence de ces changements sur les résultats et l’efficacité."}]},{"code":"C4","title":"Modélisation mathématique","text":"mettre en application le processus de modélisation mathématique pour représenter et analyser des situations de la vie quotidienne, ainsi que pour faire des prédictions et fournir des renseignements à leur sujet. Il n’y a pas de contenus d’apprentissage rattachés à cette attente. La modélisation mathématique est un processus itératif et interconnecté qui, lorsque mis en application dans divers contextes, permet aux élèves de transférer des apprentissages effectués dans d’autres domaines d’étude. L’évaluation porte sur la manifestation par l’élève de son apprentissage du processus de modélisation mathématique dans le contexte des concepts et des connaissances acquis dans les autres domaines. En savoir plus sur le processus de la modélisation mathématique","specific":[]}]},{"code":"D","title":"Données","why":"Les élèves apprennent à distinguer les données discrètes (p. ex., le nombre d’élèves) des données continues (p. ex., la quantité de précipitation en centimètres). Ils choisissent la façon de présenter ces différents types de données, par exemple en utilisant des diagrammes à ligne brisée pour représenter le changement au cours du temps. Les élèves apprennent également diverses façons de décrire des probabilités. Par exemple, il y a une chance sur quatre de gagner un prix à la fête de l’école, ou il y a 40 % de chance qu’il pleuve demain.","overall":[{"code":"D1","title":"Littératie statistique","text":"traiter, analyser et utiliser des données pour formuler des arguments persuasifs et prendre des décisions éclairées dans divers contextes de la vie quotidienne.","specific":[{"code":"D1.1","title":"Collecte et organisation des données","text":"décrire la différence entre les données discrètes et les données continues, et en fournir des exemples."},{"code":"D1.2","title":"Collecte et organisation des données","text":"collecter des données qualitatives et des données quantitatives discrètes et continues pour répondre à des questions d’intérêt portant sur une population, et organiser les ensembles de données de façon appropriée, y compris à l’aide d’intervalles."},{"code":"D1.3","title":"Visualisation des données","text":"choisir le diagramme le plus approprié pour représenter divers ensembles de données à partir d’une variété de diagrammes, y compris des histogrammes et des diagrammes à ligne brisée; représenter des données à l’aide de diagrammes comprenant des sources, des titres, des étiquettes et des échelles appropriés; et justifier son choix."},{"code":"D1.4","title":"Visualisation des données","text":"créer une infographie pour représenter un ensemble de données de façon appropriée, y compris à l’aide de tableaux, d’histogrammes et de diagrammes à ligne brisée, ainsi qu’en incorporant d’autres renseignements pertinents qui permettent de raconter une histoire au sujet des données."},{"code":"D1.5","title":"Analyse des données","text":"déterminer l’étendue comme mesure de dispersion et les mesures de tendances centrales de divers ensembles de données, et utiliser ces renseignements pour comparer deux ensembles de données ou plus."},{"code":"D1.6","title":"Analyse des données","text":"examiner divers ensembles de données présentées de différentes façons, y compris à l’aide d’histogrammes, de diagrammes à ligne brisée et de diagrammes trompeurs, en se posant des questions au sujet des données et en y répondant, en remettant en question des idées reçues, et en tirant des conclusions, et ensuite formuler des arguments persuasifs et prendre des décisions éclairées."}]},{"code":"D2","title":"Probabilité","text":"décrire la probabilité que des événements se produisent et utiliser cette information pour faire des prédictions.","specific":[{"code":"D2.1","title":"Probabilité","text":"utiliser des fractions, des nombres décimaux et des pourcentages pour exprimer la probabilité que des événements se produisent, la représenter sur une ligne de probabilité et s’appuyer sur cette probabilité pour faire des prédictions et prendre des décisions éclairées."},{"code":"D2.2","title":"Probabilité","text":"déterminer et comparer les probabilités théoriques et expérimentales que deux événements indépendants se produisent."}]}]},{"code":"E","title":"Sens de l’espace","why":"Les élèves continuent d’étudier le sens de l’espace, notamment les formes à quatre côtés: ils apprennent les caractéristiques et les propriétés de diverses formes à quatre côtés et en déterminent l’aire. Ils construisent des objets tridimensionnels et apprennent à calculer la superficie. De plus, ils apprennent à faire une conversion d’unités en utilisant le système métrique et améliorent leur aptitude à mesurer les angles.","overall":[{"code":"E1","title":"Raisonnement géométrique et spatial","text":"décrire et représenter la forme, la position et le déplacement en se servant de propriétés géométriques et de relations spatiales pour s’orienter dans le monde qui l’entoure.","specific":[{"code":"E1.1","title":"Raisonnement géométrique","text":"créer des listes des propriétés géométriques de divers types de quadrilatères, y compris les propriétés des diagonales, la symétrie rotationnelle et les axes de symétrie."},{"code":"E1.2","title":"Raisonnement géométrique","text":"construire des objets à trois dimensions à partir de vues de face, de côté et de dessus."},{"code":"E1.3","title":"Position et déplacement","text":"situer et lire des coordonnées dans les quatre quadrants d’un plan cartésien, et décrire les déplacements d’une coordonnée à l’autre à l’aide de translations."},{"code":"E1.4","title":"Position et déplacement","text":"décrire et effectuer des combinaisons de translations, de réflexions et de rotations jusqu’à 360° dans une grille, et prédire les résultats de ces transformations."}]},{"code":"E2","title":"Sens de la mesure","text":"comparer, estimer et déterminer des mesures dans divers contextes.","specific":[{"code":"E2.1","title":"Système métrique","text":"mesurer la longueur, l’aire, la masse et la capacité à l’aide d’unités métriques appropriées et résoudre des problèmes qui requièrent la conversion de petites unités en des unités plus grandes, et vice versa."},{"code":"E2.2","title":"Angles","text":"utiliser un rapporteur pour mesurer et construire des angles jusqu’à 360° et indiquer la relation entre les angles mesurés dans le sens des aiguilles d’une montre et ceux mesurés dans le sens contraire des aiguilles d’une montre."},{"code":"E2.3","title":"Angles","text":"utiliser les propriétés des angles supplémentaires, complémentaires, opposés ainsi que des angles intérieurs et extérieurs pour déterminer les mesures d’angles manquantes."},{"code":"E2.4","title":"Aire et aire totale","text":"déterminer l’aire de trapèzes, de losanges, de cerfs-volants ainsi que de polygones complexes en les décomposant en figures planes avec des aires connues."},{"code":"E2.5","title":"Aire et aire totale","text":"créer et utiliser les développements de solides pour déterminer les relations entre les faces de prismes et de pyramides et leur aire totale."},{"code":"E2.6","title":"Aire et aire totale","text":"déterminer l’aire totale de prismes et de pyramides en calculant les aires de chaque face à deux dimensions et en les additionnant."}]}]},{"code":"F","title":"Littératie financière","why":"Les élèves explorent les avantages et les inconvénients de l’utilisation de diverses modes de paiement de produits et services. Ils examinent divers types d’objectifs financiers, déterminent et décrivent des facteurs qui pourraient avoir une incidence sur ces objectifs et définissent les étapes pour les atteindre. Les élèves expliquent le concept des taux d’intérêt et présentent les taux d’intérêt et les frais utilisés par les banques et d’autres institutions financières. Ils apprennent que le commerce, les prêts, les emprunts et les dons constituent diverses façons de distribuer des ressources.","overall":[{"code":"F1","title":"Argent et finances","text":"démontrer les connaissances et les habiletés nécessaires pour prendre des décisions financières éclairées.","specific":[{"code":"F1.1","title":"Concepts monétaires","text":"décrire les avantages et les désavantages de divers modes de paiement qui peuvent être utilisés pour acheter des biens et des services."},{"code":"F1.2","title":"Gestion financière","text":"déterminer divers types d’objectifs financiers, y compris des objectifs d’épargne et de revenu, et présenter quelques étapes importantes nécessaires à leur atteinte."},{"code":"F1.3","title":"Gestion financière","text":"déterminer et décrire divers facteurs qui peuvent aider ou entraver l’atteinte d’objectifs financiers."},{"code":"F1.4","title":"Sensibilisation à la consommation et au civisme","text":"expliquer le concept des taux d’intérêt et déterminer les types de taux d’intérêt et de frais associés à différents comptes et prêts offerts par diverses banques et autres institutions financières."},{"code":"F1.5","title":"Sensibilisation à la consommation et au civisme","text":"décrire le commerce, le prêt, l’emprunt et le don comme différents moyens de répartir des ressources financières et autres entre les individus et les organismes."}]}]}]}},"sci":{"g1":{"url":"https://www.dcp.edu.gov.on.ca/fr/curriculum/sciences-technologie","sourceLang":"fr","strands":[{"code":"A","title":"Habiletés liées aux STIM et liens connexes","why":"Au cours de chaque année d’études, le programme-cadre de sciences et technologie intègre l’apprentissage des lié aux habiletés liées aux STIM et aux liens connexes aux quatre autres domaines d’étude du programme qui en font partie.","overall":[{"code":"A1","title":"Recherches et expériences liées aux STIM et habiletés de communication","text":"utiliser une démarche de recherche, une démarche expérimentale et un processus de design en ingénierie pour effectuer des recherches et des expériences ainsi que pour résoudre des problèmes, tout en respectant les consignes de santé et de sécurité.","specific":[{"code":"A1.1","title":"","text":"utiliser une démarche de recherche et les habiletés connexes pour effectuer des recherches."},{"code":"A1.2","title":"","text":"utiliser une démarche expérimentale et les habiletés connexes pour effectuer des expériences."},{"code":"A1.3","title":"","text":"utiliser un processus de design en ingénierie et les habiletés connexes pour concevoir, construire et tester des dispositifs, des modèles, des structures et/ou des systèmes."},{"code":"A1.4","title":"","text":"respecter les consignes de santé et de sécurité à suivre durant les expériences scientifiques et technologiques, y compris le port de l’équipement et des vêtements de protection individuelle appropriés, et utiliser adéquatement les outils, les instruments et le matériel mis à sa disposition."},{"code":"A1.5","title":"","text":"communiquer les résultats de ses recherches et de ses expériences en utilisant la terminologie propre aux sciences et à la technologie et les moyens de communication appropriés selon les objectifs établis et l’auditoire cible."}]},{"code":"A2","title":"Codage et technologies émergentes","text":"utiliser le codage pour examiner et modéliser des concepts, et analyser l’incidence du codage et des technologies émergentes sur la vie quotidienne.","specific":[{"code":"A2.1","title":"","text":"écrire et exécuter des codes lors de l’exploration et de la modélisation de concepts, notamment pour créer des instructions claires et précises dans des algorithmes simples."},{"code":"A2.2","title":"","text":"déterminer et décrire l’incidence du codage et des technologies émergentes sur des situations de la vie quotidienne."}]},{"code":"A3","title":"Applications, liens et contributions ","text":"démontrer sa compréhension des applications pratiques des sciences et de la technologie, ainsi que des contributions aux sciences et à la technologie d’individus ayant vécu diverses expériences.","specific":[{"code":"A3.1","title":"","text":"décrire des applications pratiques de concepts de sciences et technologie à la maison et dans sa communauté, ainsi que des façons dont ces applications traitent de problèmes tirés de situations de la vie quotidienne."},{"code":"A3.2","title":"","text":"examiner des façons dont les sciences et la technologie peuvent être utilisées avec d’autres disciplines pour traiter de problèmes tirés de situations de la vie quotidienne."},{"code":"A3.3","title":"","text":"analyser des contributions apportées aux sciences et à la technologie par diverses communautés."}]}]},{"code":"B","title":"Systèmes vivants","why":"Les élèves explorent les milieux naturels, comme un sentier, un cours d’eau ou un boisé, où des êtres vivants et inanimés cohabitent. Elles et ils comprennent l’importance et les moyens contribuant au maintien d’un environnement sain, par exemple, laisser le milieu naturel intact (ne cueillir aucune fleur sauvage). Dans le cadre de ce domaine d’étude, les élèves découvrent les besoins essentiels des êtres vivants, comme l’air, l’eau et les éléments nutritifs.","overall":[{"code":"B1","title":"Rapprochement entre les sciences, la technologie et notre monde en évolution","text":"évaluer l’importance d’un environnement sain pour les êtres vivants et les éléments non vivants, ainsi que les responsabilités des humains envers un tel environnement.","specific":[{"code":"B1.1","title":"Les êtres vivants : caractéristiques et besoins","text":"décrire des changements ou des problèmes qui pourraient résulter de la perte d’êtres vivants (plantes et animaux) et d’éléments non vivants faisant partie de la vie quotidienne, en tenant compte de diverses perspectives."},{"code":"B1.2","title":"Les êtres vivants : caractéristiques et besoins","text":"suggérer des actions qui peuvent contribuer à un environnement sain."}]},{"code":"B2","title":"Exploration et compréhension des concepts","text":"démontrer sa compréhension des besoins essentiels et des caractéristiques des êtres vivants, y compris les humains.","specific":[{"code":"B2.1","title":"Les êtres vivants : caractéristiques et besoins","text":"décrire l’environnement comme étant un lieu dans lequel les êtres vivants et les éléments non vivants sont interreliés."},{"code":"B2.2","title":"Les êtres vivants : caractéristiques et besoins","text":"déterminer les besoins essentiels d’êtres vivants, y compris les besoins en air, en eau, en nourriture, en chaleur, en abri et en espace."},{"code":"B2.3","title":"Les êtres vivants : caractéristiques et besoins","text":"déterminer les caractéristiques physiques d’une variété de plantes et d’animaux, y compris les humains, et expliquer les façons dont ces caractéristiques permettent aux plantes et aux animaux de répondre à leurs besoins essentiels."},{"code":"B2.4","title":"Les êtres vivants : caractéristiques et besoins","text":"localiser les parties principales du corps humain, y compris les organes sensoriels, et décrire leurs fonctions."},{"code":"B2.5","title":"Les êtres vivants : caractéristiques et besoins","text":"décrire les caractéristiques d’un environnement sain, y compris l’air et l’eau purs et les aliments nutritifs, et les façons dont un tel environnement permet aux êtres vivants de satisfaire leurs besoins."},{"code":"B2.6","title":"Les êtres vivants : caractéristiques et besoins","text":"décrire des façons dont des êtres vivants répondent aux besoins d’autres êtres vivants."}]}]},{"code":"C","title":"Matière et énergie ","why":"Les élèves prennent conscience de l’importance et de l’utilisation de l’énergie dans leur vie et en découvrent différents aspects, par exemple ses formes et ses changements, son rôle dans la croissance des arbres et des plantes ainsi que le chauffage des maisons. Elles et ils apprennent que le Soleil est la principale source d’énergie sur la Terre, et qu’il réchauffe l’air, le sol et l’eau. Elles et ils approfondissent leur compréhension des moyens contribuant à une consommation d’énergie responsable.","overall":[{"code":"C1","title":"Rapprochement entre les sciences, la technologie et notre monde en évolution","text":"examiner différentes utilisations de l’énergie à la maison, à l’école et dans la communauté, et proposer des façons d’utiliser l’énergie de manière responsable.","specific":[{"code":"C1.1","title":"L’énergie dans nos vies","text":"décrire l’usage quotidien de l’énergie à l’école et à la maison, et proposer des façons d’utiliser l’énergie de manière responsable."},{"code":"C1.2","title":"L’énergie dans nos vies","text":"décrire les façons dont la vie des humains et des autres êtres vivants changerait si l’énergie électrique n’était plus disponible."}]},{"code":"C2","title":"Exploration et compréhension des concepts ","text":"démontrer sa compréhension de l’incidence de l’énergie dans sa vie, et du fait que le Soleil est la principale source d’énergie sur la Terre.","specific":[{"code":"C2.1","title":"L’énergie dans nos vies","text":"reconnaître que l’énergie est nécessaire pour effectuer un mouvement ou entraîner un changement."},{"code":"C2.2","title":"L’énergie dans nos vies","text":"expliquer que le Soleil est la source principale d’énergie sur la Terre en reconnaissant qu’il réchauffe l’air, l’eau et le sol, qu’il procure de la lumière à la Terre, et qu’il permet de faire pousser les plantes."},{"code":"C2.3","title":"L’énergie dans nos vies","text":"reconnaître que la nourriture est une source d’énergie pour les êtres vivants."},{"code":"C2.4","title":"L’énergie dans nos vies","text":"dresser une liste d’utilisations quotidiennes de diverses sources d’énergie."},{"code":"C2.5","title":"L’énergie dans nos vies","text":"expliquer que les humains obtiennent les ressources énergétiques nécessaires du monde qui les entoure et que plusieurs de ces ressources sont en quantités limitées."},{"code":"C2.6","title":"L’énergie dans nos vies","text":"décrire différentes façons d’utiliser l’énergie et diverses formes d’énergie utilisées selon les saisons."}]}]},{"code":"D","title":"Structures et mécanismes","why":"Les élèves commencent à analyser les caractéristiques des structures, comme la texture, la grandeur, la forme et les types de matériaux utilisés dans leur fabrication. Elles et ils se familiarisent avec la composition d’objets couramment employés, par exemple les vêtements, les jouets, les crayons, le papier, les stylos ainsi que celle de structures, comme les ponts, les étables, les habitations et les lampadaires et examinent leur incidence sur les gens et l’environnement.","overall":[{"code":"D1","title":"Rapprochement entre les sciences, la technologie et notre monde en évolution","text":"évaluer l’incidence d’objets de la vie quotidienne, y compris des structures et des matériaux utilisés dans leur fabrication, sur les humains et l’environnement.","specific":[{"code":"D1.1","title":"Les matériaux, les objets et les structures au quotidien","text":"identifier les types de déchets produits par les humains, et établir et mettre en action un plan afin de minimiser le gaspillage dans la salle de classe ou à la maison, en expliquant l’importance de chaque action."},{"code":"D1.2","title":"Les matériaux, les objets et les structures au quotidien","text":"examiner des objets de la vie quotidienne, y compris des structures, qui ont la même fonction, selon les types et les origines de matériaux qui les composent et le sort de ces objets une fois usés ou devenus inutiles."}]},{"code":"D2","title":"Exploration et compréhension des concepts","text":"démontrer sa compréhension du fait que les objets, y compris les structures, ont des caractéristiques observables et que les matériaux utilisés dans leur fabrication ont des propriétés précises qui déterminent leur utilisation.","specific":[{"code":"D2.1","title":"Les matériaux, les objets et les structures au quotidien","text":"décrire les objets comme étant des choses composées d’un ou de plusieurs matériaux."},{"code":"D2.2","title":"Les matériaux, les objets et les structures au quotidien","text":"déterminer des structures pouvant supporter une charge, y compris des structures à ossature servant de support à d’autres objets."},{"code":"D2.3","title":"Les matériaux, les objets et les structures au quotidien","text":"déterminer les matériaux utilisés dans la fabrication de divers objets de la vie quotidienne, y compris des structures."},{"code":"D2.4","title":"Les matériaux, les objets et les structures au quotidien","text":"décrire des caractéristiques observables de divers objets de la vie quotidienne, y compris des structures, en se servant de l’information qualitative perçue par ses sens."},{"code":"D2.5","title":"Les matériaux, les objets et les structures au quotidien","text":"décrire l’utilité de divers objets de la vie quotidienne, y compris des structures."},{"code":"D2.6","title":"Les matériaux, les objets et les structures au quotidien","text":"décrire les propriétés de matériaux qui sont essentielles au fonctionnement et à l’utilisation d’objets."},{"code":"D2.7","title":"Les matériaux, les objets et les structures au quotidien","text":"donner des exemples de différentes formes d’attaches et de leur utilisation."},{"code":"D2.8","title":"Les matériaux, les objets et les structures au quotidien","text":"reconnaître les substances d’origine naturelle dans les matériaux couramment utilisés pour fabriquer divers objets, y compris des structures."}]}]},{"code":"E","title":"Systèmes de la Terre et de l’espace ","why":"Les élèves abordent leur apprentissage des cycles du jour, de la nuit et des quatre saisons et apprennent que ceux-ci sont attribuables à la rotation de la Terre sur son axe et à son orbite autour du Soleil. Elles et ils examinent les répercussions des saisons sur les êtres vivants, comme l’hibernation de certaines espèces animales, le changement de la couleur des feuilles en automne, le bourgeonnement des arbres ou la production de sève des arbres au printemps.","overall":[{"code":"E1","title":"Rapprochement entre les sciences, la technologie et notre monde en évolution","text":"évaluer les effets des changements quotidiens et saisonniers sur les êtres vivants, y compris les humains.","specific":[{"code":"E1.1","title":"Le cycle des jours et des saisons","text":"examiner l’incidence des changements quotidiens et saisonniers sur les activités humaines en plein air, et indiquer des innovations qui permettent de s’adonner à une variété d’activités tout au long de l’année."},{"code":"E1.2","title":"Le cycle des jours et des saisons","text":"évaluer les répercussions des changements quotidiens et saisonniers sur la société, sur l’environnement, et sur les êtres vivants, autres que les humains."}]},{"code":"E2","title":"Exploration et compréhension des concepts ","text":"démontrer sa compréhension des changements quotidiens et saisonniers.","specific":[{"code":"E2.1","title":"Le cycle des jours et des saisons","text":"reconnaître que des changements quotidiens et saisonniers sur la Terre sont le résultat de la relation entre la Terre et le Soleil."},{"code":"E2.2","title":"Le cycle des jours et des saisons","text":"reconnaître qu’un cycle est une série d’événements répétitifs et que des changements cycliques s’observent dans le contexte des jours et des saisons."},{"code":"E2.3","title":"Le cycle des jours et des saisons","text":"décrire les variations dans l’intensité de la lumière et de la chaleur provenant du Soleil au cours de la journée et selon les saisons."},{"code":"E2.4","title":"Le cycle des jours et des saisons","text":"décrire et comparer les quatre saisons, dans sa communauté, en se référant aux conditions météorologiques, y compris aux précipitations et à la température."},{"code":"E2.5","title":"Le cycle des jours et des saisons","text":"décrire des changements d’apparence ou de comportements d’êtres vivants en réponse aux changements saisonniers."},{"code":"E2.6","title":"Le cycle des jours et des saisons","text":"décrire les façons dont les humains se préparent ou s’adaptent aux changements quotidiens et saisonniers."}]}]}]},"g2":{"url":"https://www.dcp.edu.gov.on.ca/fr/curriculum/sciences-technologie","sourceLang":"fr","strands":[{"code":"A","title":"Habiletés liées aux STIM et liens connexes","why":"Au cours de chaque année d’études, le programme-cadre de sciences et technologie intègre l’apprentissage des lié aux habiletés liées aux STIM et aux liens connexes aux quatre autres domaines d’étude du programme qui en font partie.","overall":[{"code":"A1","title":"Recherches et expériences liées aux STIM et habiletés de communication","text":"utiliser une démarche de recherche, une démarche expérimentale et un processus de design en ingénierie pour effectuer des recherches et des expériences ainsi que pour résoudre des problèmes, tout en respectant les consignes de santé et de sécurité.","specific":[{"code":"A1.1","title":"","text":"utiliser une démarche de recherche et les habiletés connexes pour effectuer des recherches."},{"code":"A1.2","title":"","text":"utiliser une démarche expérimentale et les habiletés connexes pour effectuer des expériences."},{"code":"A1.3","title":"","text":"utiliser un processus de design en ingénierie et les habiletés connexes pour concevoir, construire et tester des dispositifs, des modèles, des structures et/ou des systèmes."},{"code":"A1.4","title":"","text":"respecter les consignes de santé et de sécurité à suivre durant les expériences scientifiques et technologiques, y compris le port de l’équipement et des vêtements de protection individuelle appropriés, et utiliser adéquatement les outils, les instruments et le matériel mis à sa disposition."},{"code":"A1.5","title":"","text":"communiquer les résultats de ses recherches et de ses expériences en utilisant la terminologie propre aux sciences et à la technologie et les moyens de communication appropriés selon les objectifs établis et l’auditoire cible."}]},{"code":"A2","title":"Codage et technologies émergentes","text":"utiliser le codage pour examiner et modéliser des concepts, et analyser l’incidence du codage et des technologies émergentes sur la vie quotidienne.","specific":[{"code":"A2.1","title":"","text":"écrire et exécuter des codes lors de l’exploration et de la modélisation de concepts, notamment pour décomposer des problèmes en petites étapes."},{"code":"A2.2","title":"","text":"déterminer et décrire l’incidence du codage et des technologies émergentes sur des situations de la vie quotidienne."}]},{"code":"A3","title":"Applications, liens et contributions","text":"démontrer sa compréhension des applications pratiques des sciences et de la technologie, ainsi que des contributions aux sciences et à la technologie d’individus ayant vécu diverses expériences.","specific":[{"code":"A3.1","title":"","text":"décrire des applications pratiques de concepts de sciences et technologie à la maison et dans sa communauté, ainsi que des façons dont ces applications traitent de problèmes tirés de situations de la vie quotidienne."},{"code":"A3.2","title":"","text":"examiner des façons dont les sciences et la technologie peuvent être utilisées avec d’autres disciplines pour traiter de problèmes tirés de situations de la vie quotidienne."},{"code":"A3.3","title":"","text":"analyser des contributions apportées aux sciences et à la technologie par diverses communautés."}]}]},{"code":"B","title":"Systèmes vivants","why":"Les élèves réfléchissent aux animaux, qui grandissent et changent au cours de leur cycle de vie, et qui possèdent des caractéristiques distinctes: les poissons sont recouverts d’écailles, les chats ont une fourrure, les oiseaux sont couverts de plumes et les tortues sont munies d’une carapace. Au fur et à mesure que les élèves poursuivent leurs recherches sur les animaux et leurs habitats naturels, elles et ils commencent à comprendre l’interdépendance entre les espèces animales et leur environnement. Elles et ils élargissent leur compréhension des effets de l’activité humaine sur les animaux et voient qu’elles et ils peuvent prendre des mesures en vue de protéger et de respecter les animaux ainsi que leur habitat naturel.","overall":[{"code":"B1","title":"Rapprochement entre les sciences, la technologie et notre monde en évolution","text":"évaluer l’incidence des animaux sur la société et l’environnement, ainsi que l’incidence de l’activité humaine sur les animaux et leurs habitats.","specific":[{"code":"B1.1","title":"Les animaux : croissance et changements","text":"examiner l’incidence que les animaux peuvent avoir sur la société et l’environnement, et décrire des façons d’en minimiser les effets négatifs."},{"code":"B1.2","title":"Les animaux : croissance et changements","text":"examiner l’incidence de diverses activités humaines sur les animaux et leurs habitats, et décrire des pratiques qui minimisent les effets négatifs."}]},{"code":"B2","title":"Exploration et compréhension des concepts ","text":"démontrer sa compréhension du fait que les animaux croissent, changent et ont des caractéristiques distinctes.","specific":[{"code":"B2.1","title":"Les animaux : croissance et changements","text":"comparer les caractéristiques physiques de divers animaux, y compris celles qui restent constantes et celles qui changent."},{"code":"B2.2","title":"Les animaux : croissance et changements","text":"décrire les modes de locomotion d’une variété d’animaux."},{"code":"B2.3","title":"Les animaux : croissance et changements","text":"décrire le cycle de vie d’une variété d’animaux, y compris des insectes, des amphibiens, des oiseaux et des mammifères."},{"code":"B2.4","title":"Les animaux : croissance et changements","text":"comparer des changements physiques et comportementaux de divers animaux au cours de leur cycle de vie."},{"code":"B2.5","title":"Les animaux : croissance et changements","text":"décrire des adaptations, telles que des changements physiques ou comportementaux, qui permettent aux animaux de survivre dans leur habitat."}]}]},{"code":"C","title":"Matière et énergie ","why":"Les élèves étudient les propriétés et les transformations des liquides et des solides. Elles et ils approfondissent leur apprentissage en mettant à l’essai différentes structures et observant l’interaction ou les transformations qui s’opèrent entre les solides et les liquides. Elles et ils analysent les diverses utilisations des liquides et des solides ainsi que les conséquences de ces usages sur la société et l’environnement.","overall":[{"code":"C1","title":"Rapprochement entre les sciences, la technologie et notre monde en évolution","text":"évaluer l’incidence sur la société et l’environnement de divers liquides et solides et de leurs utilisations.","specific":[{"code":"C1.1","title":"Les propriétés des liquides et des solides","text":"décrire diverses utilisations de liquides et de solides à la maison, y compris leur entreposage et leur mise au rebut, en tenant compte de divers aspects dont la santé et sécurité personnelle et l’intendance environnementale, et proposer des façons d’améliorer ces pratiques."},{"code":"C1.2","title":"Les propriétés des liquides et des solides","text":"évaluer les conséquences de différents changements d’état des liquides et des solides sur les humains, l’environnement naturel et l’environnement bâti."}]},{"code":"C2","title":"Exploration et compréhension des concepts ","text":"démontrer sa compréhension des propriétés et des changements physiques de liquides et de solides.","specific":[{"code":"C2.1","title":"Les propriétés des liquides et des solides","text":"reconnaître diverses substances dans l’environnement naturel et l’environnement bâti en tant que liquides ou solides."},{"code":"C2.2","title":"Les propriétés des liquides et des solides","text":"décrire les propriétés des liquides et des solides."},{"code":"C2.3","title":"Les propriétés des liquides et des solides","text":"décrire les propriétés de l’eau à l’état liquide et à l’état solide, et déterminer les conditions qui provoquent le passage d’un état à un autre."},{"code":"C2.4","title":"Les propriétés des liquides et des solides","text":"déterminer des situations dans lesquelles les états des liquides et des solides demeurent constants, et les conditions propices à leur changement."},{"code":"C2.5","title":"Les propriétés des liquides et des solides","text":"décrire certaines façons de combiner des liquides et des solides afin d’obtenir des mélanges utiles."},{"code":"C2.6","title":"Les propriétés des liquides et des solides","text":"classifier des objets et des matériaux solides selon leur flottabilité et leur capacité à absorber l’eau ou à la repousser."},{"code":"C2.7","title":"Les propriétés des liquides et des solides","text":"décrire les symboles internationaux qui renseignent sur les dangers des substances."}]}]},{"code":"D","title":"Structures et mécanismes","why":"Les élèves étudient les machines simples et leur utilisation en concevant et en fabriquant une machine simple, comme un jouet mobile muni de roues et d’un essieu. Les élèves analysent aussi l’incidence des machines simples sur la société, y compris les communautés autochtones, et l’environnement à l’aide d’exemples de moyens de transport et de constructions.","overall":[{"code":"D1","title":"Rapprochement entre les sciences, la technologie et notre monde en évolution","text":"évaluer l’incidence des machines simples sur la société et sur l’environnement.","specific":[{"code":"D1.1","title":"Les machines simples et le mouvement","text":"examiner l’incidence de l’utilisation de machines simples sur la vie quotidienne de diverses communautés."},{"code":"D1.2","title":"Les machines simples et le mouvement","text":"examiner l’incidence sur l’environnement des appareils technologiques qui utilisent des machines simples pour faciliter le mouvement."}]},{"code":"D2","title":"Exploration et compréhension des concepts","text":"démontrer sa compréhension du mouvement et des façons de déplacer des objets à l’aide de machines simples.","specific":[{"code":"D2.1","title":"Les machines simples et le mouvement","text":"décrire différentes sortes de mouvements d’objets."},{"code":"D2.2","title":"Les machines simples et le mouvement","text":"déterminer des façons de changer la position d’un objet."},{"code":"D2.3","title":"Les machines simples et le mouvement","text":"reconnaître les six principaux types de machines simples: levier, plan incliné, poulie, roue et essieu, vis, et coin."},{"code":"D2.4","title":"Les machines simples et le mouvement","text":"décrire des façons dont chaque type de machine simple est utilisé pour faciliter le travail au quotidien."},{"code":"D2.5","title":"Les machines simples et le mouvement","text":"comparer, qualitativement ou quantitativement, la force requise pour déplacer un objet à l’aide de diverses machines simples à la force requise pour déplacer l’objet sans utiliser de machine simple."}]}]},{"code":"E","title":"Systèmes de la Terre et de l’espace","why":"Les élèves commencent à se familiariser avec les propriétés de l’air et de l’eau, y compris les états de l’eau (solide, liquide et gazeux) dans l’environnement. Elles et ils poursuivent leur apprentissage de l’importance de l’air et de l’eau en examinant les différentes manières dont la survie des êtres humains et d’autres êtres vivants est tributaire de ces éléments (par exemple: les poissons ne peuvent vivre que dans une eau saine). Les élèves sont conscientisés au fait que l’eau potable se raréfie au sein de plusieurs collectivités et qu’il s’agit donc d’une ressource que les êtres humains doivent utiliser de manière responsable.","overall":[{"code":"E1","title":"Rapprochement entre les sciences, la technologie et notre monde en évolution","text":"évaluer les effets de l’activité humaine sur la qualité de l’air et de l’eau, et élaborer des plans d’action pour protéger ces ressources.","specific":[{"code":"E1.1","title":"L’air et l’eau dans l’environnement","text":"évaluer les répercussions de l’activité humaine sur l’air et l’eau, en tenant compte de diverses perspectives, incluant celles des Premières Nations, des Métis et des Inuit, et élaborer un plan d’action pour contribuer à la protection de l’air et de l’eau dans sa communauté."},{"code":"E1.2","title":"L’air et l’eau dans l’environnement","text":"évaluer son utilisation personnelle de l’eau et celle de son foyer, et élaborer un plan pour utiliser l’eau de manière responsable."},{"code":"E1.3","title":"L’air et l’eau dans l’environnement","text":"examiner la disponibilité de l’eau douce et potable à travers le monde et décrire l’incidence sur des communautés locales quand les ressources en eau sont insuffisantes ou rares."}]},{"code":"E2","title":"Exploration et compréhension des concepts ","text":"démontrer sa compréhension des propriétés de l’air et de l’eau, y compris l’eau sous divers états, et des façons dont les êtres vivants dépendent de l’air et de l’eau pour leur survie.","specific":[{"code":"E2.1","title":"L’air et l’eau dans l’environnement","text":"examiner les principales propriétés de l’air et de l’eau."},{"code":"E2.2","title":"L’air et l’eau dans l’environnement","text":"identifier des sources d’eau dans l’environnement naturel et l’environnement bâti."},{"code":"E2.3","title":"L’air et l’eau dans l’environnement","text":"décrire les phases du cycle de l’eau, dont l’évaporation, la condensation, la précipitation et la collecte."},{"code":"E2.4","title":"L’air et l’eau dans l’environnement","text":"décrire les trois états de l’eau dans l’environnement et expliquer les façons dont des changements de température influencent l’état de l’eau dans le cycle de l’eau."},{"code":"E2.5","title":"L’air et l’eau dans l’environnement","text":"décrire la dépendance des êtres vivants, y compris les humains, à l’égard de l’air et de l’eau."}]}]}]},"g3":{"url":"https://www.dcp.edu.gov.on.ca/fr/curriculum/sciences-technologie","sourceLang":"fr","strands":[{"code":"A","title":"Habiletés liées aux STIM et liens connexes","why":"Au cours de chaque année d’études, le programme-cadre de sciences et technologie intègre l’apprentissage des lié aux habiletés liées aux STIM et aux liens connexes aux quatre autres domaines d’étude du programme qui en font partie.","overall":[{"code":"A1","title":"Recherches et expériences liées aux STIM et habiletés de communication ","text":"utiliser une démarche de recherche, une démarche expérimentale et un processus de design en ingénierie pour effectuer des recherches et des expériences ainsi que pour résoudre des problèmes, tout en respectant les consignes de santé et de sécurité.","specific":[{"code":"A1.1","title":"","text":"utiliser une démarche de recherche et les habiletés connexes pour effectuer des recherches."},{"code":"A1.2","title":"","text":"utiliser une démarche expérimentale et les habiletés connexes pour effectuer des expériences."},{"code":"A1.3","title":"","text":"utiliser un processus de design en ingénierie et les habiletés connexes pour concevoir, construire et tester des dispositifs, des modèles, des structures et/ou des systèmes."},{"code":"A1.4","title":"","text":"respecter les consignes de santé et de sécurité à suivre durant les expériences scientifiques et technologiques, y compris le port de l’équipement et des vêtements de protection individuelle appropriés, et utiliser adéquatement les outils, les instruments et le matériel mis à sa disposition."},{"code":"A1.5","title":"","text":"communiquer les résultats de ses recherches et de ses expériences en utilisant la terminologie propre aux sciences et à la technologie et les moyens de communication appropriés selon les objectifs établis et l’auditoire cible."}]},{"code":"A2","title":"Codage et technologies émergentes ","text":"utiliser le codage pour examiner et modéliser des concepts, et analyser l’incidence du codage et des technologies émergentes sur la vie quotidienne.","specific":[{"code":"A2.1","title":"","text":"écrire et exécuter des codes lors de l’exploration et de la modélisation de concepts, notamment pour tester, déboguer et améliorer des programmes."},{"code":"A2.2","title":"","text":"déterminer et décrire l’incidence du codage et des technologies émergentes sur des situations de la vie quotidienne."}]},{"code":"A3","title":"Applications, liens et contributions","text":"démontrer sa compréhension des applications pratiques des sciences et de la technologie, ainsi que des contributions aux sciences et à la technologie d’individus ayant vécu diverses expériences.","specific":[{"code":"A3.1","title":"","text":"décrire des applications pratiques de concepts de sciences et technologie à la maison et dans sa communauté, ainsi que des façons dont ces applications traitent de problèmes tirés de situations de la vie quotidienne."},{"code":"A3.2","title":"","text":"examiner des façons dont les sciences et la technologie peuvent être utilisées avec d’autres disciplines pour traiter de problèmes tirés de situations de la vie quotidienne."},{"code":"A3.3","title":"","text":"analyser des contributions apportées aux sciences et à la technologie par diverses communautés."}]}]},{"code":"B","title":"Systèmes vivants","why":"Les élèves étudient les principales parties de la plante et leurs fonctions. Par exemple: les racines d’une plante absorbent l’eau et les minéraux présents dans le sol, et la tige sert à soutenir la plante ainsi qu’à transporter l’eau et les éléments nutritifs du sol à toutes les autres parties. Les élèves approfondissent leur apprentissage en réfléchissant à l’importance des plantes à la vie humaine et à d’autres êtres vivants pour ce qui est de l’alimentation, de la production d’oxygène, des médicaments et d’autres produits qu’elles fournissent. Elles et ils examinent également les conséquences de l’activité humaine sur les plantes et leur habitat naturel.","overall":[{"code":"B1","title":"Rapprochement entre les sciences, la technologie et notre monde en évolution","text":"évaluer l’incidence de l’activité humaine sur les plantes et leurs habitats ainsi que les bienfaits des plantes pour la société et l’environnement.","specific":[{"code":"B1.1","title":"Les plantes : croissance et changements","text":"souligner l’importance des plantes pour les humains et les autres êtres vivants, en tenant compte de diverses perspectives, et suggérer des moyens par lesquels les humains peuvent assurer la survie de plantes indigènes et de leurs habitats."},{"code":"B1.2","title":"Les plantes : croissance et changements","text":"examiner l’incidence de l’activité humaine sur les plantes et leurs habitats, et suggérer des actions personnelles pour minimiser les effets négatifs et accentuer les effets positifs."},{"code":"B1.3","title":"Les plantes : croissance et changements","text":"examiner les bienfaits et les limites des aliments cultivés localement."}]},{"code":"B2","title":"Exploration et compréhension des concepts","text":"démontrer sa compréhension des caractéristiques et des utilisations de plantes ainsi que des réactions de plantes à leur environnement.","specific":[{"code":"B2.1","title":"Les plantes : croissance et changements","text":"décrire les besoins essentiels des plantes, y compris leurs besoins en air, en eau, en lumière, en chaleur, en éléments nutritifs et en espace, et déterminer des conditions environnementales qui peuvent menacer la survie des plantes."},{"code":"B2.2","title":"Les plantes : croissance et changements","text":"nommer les différentes parties d’une plante, dont la racine, la tige, la feuille, la fleur, la graine, le pistil, l’étamine, le fruit et le cône, et décrire la contribution de chaque partie à la survie de la plante dans son environnement."},{"code":"B2.3","title":"Les plantes : croissance et changements","text":"décrire les changements qui s’opèrent dans les plantes au cours de leur cycle de vie."},{"code":"B2.4","title":"Les plantes : croissance et changements","text":"décrire des adaptations ou des réactions de diverses plantes à leur environnement, y compris à des changements à l’environnement."},{"code":"B2.5","title":"Les plantes : croissance et changements","text":"reconnaître que la plupart des plantes obtiennent l’énergie directement du Soleil à la suite du processus de la photosynthèse, qui se produit par l’absorption du dioxyde de carbone et la libération de l’oxygène."},{"code":"B2.6","title":"Les plantes : croissance et changements","text":"décrire diverses utilisations de plantes comme sources de nourriture, d’abri, de médicaments et de vêtements par des individus provenant de différentes cultures du monde, y compris les peuples autochtones."},{"code":"B2.7","title":"Les plantes : croissance et changements","text":"décrire diverses plantes qui servent de nourriture, y compris celles cultivées par les Premières Nations, les Métis et les Inuit, et indiquer des endroits locaux où elles peuvent être trouvées ou cultivées."},{"code":"B2.8","title":"Les plantes : croissance et changements","text":"décrire l’interdépendance entre les plantes et les animaux, y compris les humains."}]}]},{"code":"C","title":"Matière et énergie","why":"Les élèves comprennent que les forces sont des actions qui peuvent causer du mouvement ou un changement dans le mouvement et qu’elles sont utilisées au quotidien. Elles et ils élargissent leur compréhension en concevant, en construisant et en mettant à l’essai des dispositifs qui permettent d’appliquer des forces de manière à faire bouger un objet de façon contrôlée. Elles et ils examinent également les effets de différentes forces sur la société et sur l’environnement et cernent des moyens dont l’activité humaine peut contribuer à réduire ou à améliorer les effets de ces forces.","overall":[{"code":"C1","title":"Rapprochement entre les sciences, la technologie et notre monde en évolution","text":"examiner les effets de diverses forces sur la société et l’environnement.","specific":[{"code":"C1.1","title":"Les forces et le mouvement","text":"examiner les effets des forces résultant de phénomènes naturels sur l’environnement naturel et l’environnement bâti, et indiquer des façons dont les humains peuvent réduire ou accentuer ces effets."},{"code":"C1.2","title":"Les forces et le mouvement","text":"examiner les effets négatifs de forces pouvant résulter de diverses activités humaines, et décrire des façons dont des dispositifs favorisant la santé et la sécurité peuvent minimiser ces effets."}]},{"code":"C2","title":"Exploration et compréhension des concepts ","text":"démontrer sa compréhension des façons dont les forces produisent un mouvement ou un changement dans les mouvements.","specific":[{"code":"C2.1","title":"Les forces et le mouvement","text":"décrire différents types de forces de contact et de forces à distance."},{"code":"C2.2","title":"Les forces et le mouvement","text":"décrire différentes façons dont une force peut être appliquée sur un objet."},{"code":"C2.3","title":"Les forces et le mouvement","text":"décrire comment différentes forces agissant sur un objet, y compris des forces de diverses intensités, peuvent le mettre en mouvement, l’arrêter, le faire changer de direction ou de vitesse, ou changer sa forme."},{"code":"C2.4","title":"Les forces et le mouvement","text":"énumérer des applications de diverses forces dans des situations de la vie quotidienne."}]}]},{"code":"D","title":"Structures et mécanismes","why":"Les élèves démontrent une compréhension des relations entre différentes formes et fonctions des structures, du concept de solidité et de stabilité des structures ainsi que des facteurs qui influent sur la solidité et la stabilité des structures. Elles et ils conçoivent, construisent et mettent à l’essai une structure solide et stable ayant une utilité particulière. Cet exercice renforce leur compréhension de l’importance des concepts des formes, des fonctions, de la solidité et de la stabilité des structures destinées aux êtres humains et aux animaux.","overall":[{"code":"D1","title":"Rapprochement entre les sciences, la technologie et notre monde en évolution","text":"évaluer l’importance de la forme, de la fonction, de la solidité et de la stabilité des structures dans la société et l’environnement.","specific":[{"code":"D1.1","title":"Les structures solides et stables","text":"examiner l’incidence sur la société et l’environnement des structures solides et stables."},{"code":"D1.2","title":"Les structures solides et stables","text":"examiner l’incidence environnementale de structures construites par divers animaux, y compris de structures construites par les humains."}]},{"code":"D2","title":"Exploration et compréhension des concepts","text":"démontrer sa compréhension des concepts de solidité et de stabilité pour des structures de diverses formes et fonctions, ainsi que des facteurs qui influent sur la solidité et la stabilité de ces structures.","specific":[{"code":"D2.1","title":"Les structures solides et stables","text":"décrire une structure comme un objet supportant une charge et ayant une taille, une forme et une fonction précises, et reconnaître des structures dans l’environnement naturel et dans l’environnement bâti."},{"code":"D2.2","title":"Les structures solides et stables","text":"expliquer la relation entre la forme et la fonction de diverses structures."},{"code":"D2.3","title":"Les structures solides et stables","text":"décrire la solidité d’une structure comme étant sa capacité à supporter une charge et décrire des façons d’augmenter la solidité des structures, y compris des façons d’augmenter la solidité des différents matériaux utilisés dans leur construction."},{"code":"D2.4","title":"Les structures solides et stables","text":"décrire la stabilité d’une structure comme étant sa capacité à conserver sa forme, à maintenir son équilibre, à flotter ou à rester fixe à son emplacement quand elle est soumise à une force, et décrire des façons d’améliorer sa stabilité."},{"code":"D2.5","title":"Les structures solides et stables","text":"indiquer des propriétés de matériaux à considérer lors de la construction des structures."},{"code":"D2.6","title":"Les structures solides et stables","text":"décrire les façons dont différentes forces peuvent modifier la forme, l’équilibre ou la position d’une structure."},{"code":"D2.7","title":"Les structures solides et stables","text":"expliquer la fonction des entretoises et des attaches dans les structures soumises à une charge."}]}]},{"code":"E","title":"Systèmes de la Terre et de l’espace","why":"Dans leur milieu local, les élèves explorent activement les différents types de sols, leur composition et les changements qui s’y opèrent constamment. Elles et ils développent leur compréhension des sols en étudiant leur importance du point de vue de l’agriculture, de la culture de différents aliments, et elles et ils déterminent différents moyens d’entretenir des sols sains en vue d’assurer un bon rendement des cultures.","overall":[{"code":"E1","title":"Rapprochement entre les sciences, la technologie et notre monde en évolution","text":"évaluer l’importance des sols pour la société et l’environnement ainsi que l’incidence de l’activité humaine sur les sols.","specific":[{"code":"E1.1","title":"Le sol dans l’environnement","text":"examiner l’importance des sols pour la société et l’environnement."},{"code":"E1.2","title":"Le sol dans l’environnement","text":"examiner l’incidence de l’activité humaine sur les sols et suggérer des façons dont les humains peuvent améliorer la santé des sols et, le cas échéant, minimiser ou prévenir la dégradation des sols."}]},{"code":"E2","title":"Exploration et compréhension des concepts","text":"démontrer sa compréhension de la composition des sols, de différents types de sols ainsi que de processus et pratiques qui influent sur la santé des sols.","specific":[{"code":"E2.1","title":"Le sol dans l’environnement","text":"nommer les principales composantes vivantes et non vivantes du sol et décrire les caractéristiques d’un sol sain."},{"code":"E2.2","title":"Le sol dans l’environnement","text":"déterminer des substances qui sont communément ajoutées aux sols ou absorbées par ceux-ci, et décrire leurs effets sur la santé des sols."},{"code":"E2.3","title":"Le sol dans l’environnement","text":"examiner divers types de sols en Ontario et décrire les façons dont différents sols sont adaptés à la culture d’aliments, y compris des produits agricoles."},{"code":"E2.4","title":"Le sol dans l’environnement","text":"expliquer le processus d’érosion, y compris ses causes et ses effets sur les sols."},{"code":"E2.5","title":"Le sol dans l’environnement","text":"décrire différentes pratiques en Ontario pour préserver et améliorer la santé des sols."},{"code":"E2.6","title":"Le sol dans l’environnement","text":"décrire le processus de compostage et expliquer certains de ses bienfaits."}]}]}]},"g4":{"url":"https://www.dcp.edu.gov.on.ca/fr/curriculum/sciences-technologie","sourceLang":"fr","strands":[{"code":"A","title":"Habiletés liées aux STIM et liens connexes","why":"Au cours de chaque année d’études, le programme-cadre de sciences et technologie intègre l’apprentissage des lié aux habiletés liées aux STIM et aux liens connexes aux quatre autres domaines d’étude du programme qui en font partie.","overall":[{"code":"A1","title":"Recherches et expériences liées aux STIM et habiletés de communication ","text":"utiliser une démarche de recherche, une démarche expérimentale et un processus de design en ingénierie pour effectuer des recherches et des expériences ainsi que pour résoudre des problèmes, tout en respectant les consignes de santé et de sécurité.","specific":[{"code":"A1.1","title":"","text":"utiliser une démarche de recherche et les habiletés connexes pour effectuer des recherches."},{"code":"A1.2","title":"","text":"utiliser une démarche expérimentale et les habiletés connexes pour effectuer des expériences."},{"code":"A1.3","title":"","text":"utiliser un processus de design en ingénierie et les habiletés connexes pour concevoir, construire et tester des dispositifs, des modèles, des structures et/ou des systèmes."},{"code":"A1.4","title":"","text":"respecter les consignes de santé et de sécurité à suivre durant les expériences scientifiques et technologiques, y compris le port de l’équipement et des vêtements de protection individuelle appropriés, et utiliser adéquatement les outils, les instruments et le matériel mis à sa disposition."},{"code":"A1.5","title":"","text":"communiquer les résultats de ses recherches et de ses expériences en utilisant la terminologie propre aux sciences et à la technologie et les moyens de communication appropriés selon les objectifs établis et l’auditoire cible."}]},{"code":"A2","title":"Codage et technologies émergentes ","text":"utiliser le codage pour examiner et modéliser des concepts, et analyser l’incidence du codage et des technologies émergentes sur la vie quotidienne et les secteurs liés aux STIM.","specific":[{"code":"A2.1","title":"","text":"écrire et exécuter des codes lors de l’exploration et de la modélisation de concepts, notamment pour produire différents types de données de sortie à des fins diverses."},{"code":"A2.2","title":"","text":"déterminer et décrire l’incidence du codage et des technologies émergentes sur des situations de la vie quotidienne et sur des métiers spécialisés."}]},{"code":"A3","title":"Applications, liens et contributions","text":"démontrer sa compréhension des applications pratiques des sciences et de la technologie, ainsi que des contributions aux sciences et à la technologie d’individus ayant vécu diverses expériences.","specific":[{"code":"A3.1","title":"","text":"décrire des applications pratiques de concepts de sciences et technologie dans le cadre de diverses professions, y compris des métiers spécialisés, ainsi que des façons dont ces applications traitent de problèmes tirés de situations de la vie quotidienne."},{"code":"A3.2","title":"","text":"examiner des façons dont les sciences et la technologie peuvent être utilisées avec d’autres disciplines pour traiter de problèmes tirés de situations de la vie quotidienne."},{"code":"A3.3","title":"","text":"analyser des contributions apportées aux sciences et à la technologie par diverses communautés."}]}]},{"code":"B","title":"Systèmes vivants","why":"Les élèves poursuivent leur apprentissage de l’environnement en explorant les différents habitats naturels, en examinant l’interaction entre différents organismes et en décrivant la formation de communautés. Elles et ils approfondissent leur compréhension et leurs connaissances en s’initiant au concept des chaînes alimentaires et en apprenant à classer les organismes présents dans l’environnement en fonction de leur régime alimentaire. Les élèves continuent d’analyser les effets de l’activité humaine sur les habitats et les communautés et étudient les solutions visant à contrer ces effets.","overall":[{"code":"B1","title":"Rapprochement entre les sciences, la technologie et notre monde en évolution","text":"analyser l’incidence de l’activité humaine sur les habitats et les communautés et déterminer des façons d’en minimiser les effets négatifs et d’en accentuer les effets positifs.","specific":[{"code":"B1.1","title":"Les habitats et les communautés ","text":"examiner les effets positifs et négatifs de l’activité humaine sur les habitats et les communautés, en tenant compte de diverses perspectives."},{"code":"B1.2","title":"Les habitats et les communautés ","text":"examiner les répercussions de la décroissance ou de la disparition d’une espèce sur son habitat et dans la communauté, et décrire des actions pour prévenir cette décroissance ou disparition."}]},{"code":"B2","title":"Exploration et compréhension des concepts","text":"démontrer sa compréhension des habitats et des communautés ainsi que de l’interrelation des organismes qui s’y trouvent.","specific":[{"code":"B2.1","title":"Les habitats et les communautés","text":"décrire un habitat comme un milieu naturel qui comble les besoins essentiels des organismes, incluant les plantes et les animaux, ainsi que des façons dont un habitat local répond à ces besoins."},{"code":"B2.2","title":"Les habitats et les communautés","text":"décrire une communauté comme un ensemble d’organismes interagissant dans un habitat commun, et déterminer des facteurs qui ont une incidence sur la capacité d’une communauté de plantes et d’animaux à survivre dans un habitat local."},{"code":"B2.3","title":"Les habitats et les communautés","text":"décrire la relation entre des organismes dans une chaîne alimentaire, et classifier les organismes en tant que producteurs, consommateurs ou décomposeurs."},{"code":"B2.4","title":"Les habitats et les communautés","text":"décrire un réseau alimentaire comme l’interrelation de plusieurs chaînes alimentaires dans une communauté naturelle."},{"code":"B2.5","title":"Les habitats et les communautés","text":"expliquer que les animaux peuvent être classifiés selon leur régime alimentaire et classifier divers animaux en tant que carnivores, herbivores ou omnivores."},{"code":"B2.6","title":"Les habitats et les communautés","text":"décrire des adaptations structurelles de divers plantes et animaux et les façons dont elles aident à la survie de ces êtres vivants dans un habitat donné."},{"code":"B2.7","title":"Les habitats et les communautés","text":"expliquer que tous les habitats ont un nombre maximal d’animaux et de plantes qu’ils peuvent soutenir."}]}]},{"code":"C","title":"Matière et énergie ","why":"Les élèves démontrent leur compréhension de la lumière et du son en tant que formes d’énergie possédant des caractéristiques et des propriétés particulières. Elles et ils analysent aussi l’incidence des innovations technologiques liées au son et à la lumière sur la société et l’environnement. En outre, elles et ils étudient les vibrations qui causent des ondes sonores et explorent les interactions des matériaux avec la lumière et l’énergie sonore.","overall":[{"code":"C1","title":"Rapprochement entre les sciences, la technologie et notre monde en évolution","text":"analyser l’incidence sur la société et l’environnement des innovations technologiques associées à la lumière et au son.","specific":[{"code":"C1.1","title":"La lumière et le son","text":"analyser l’incidence sur la société de dispositifs faisant appel aux propriétés du son, de la lumière ou des deux."},{"code":"C1.2","title":"La lumière et le son","text":"analyser l’incidence sur l’environnement de l’énergie lumineuse et de l’énergie sonore produites par différentes technologies, en tenant compte de diverses perspectives."}]},{"code":"C2","title":"Exploration et compréhension des concepts","text":"démontrer sa compréhension de la lumière et du son en tant que formes d’énergie qui ont des caractéristiques et des propriétés particulières.","specific":[{"code":"C2.1","title":"La lumière et le son","text":"déterminer diverses sources de lumière naturelle et artificielle."},{"code":"C2.2","title":"La lumière et le son","text":"distinguer les objets et les êtres vivants qui émettent la lumière de ceux qui réfléchissent la lumière provenant d’autres sources."},{"code":"C2.3","title":"La lumière et le son","text":"décrire des propriétés de la lumière, y compris la propagation rectiligne, ainsi que le fait que la lumière peut être absorbée, réfléchie ou réfractée."},{"code":"C2.4","title":"La lumière et le son","text":"décrire des propriétés du son, y compris la propagation d’ondes sonores dans un milieu, ainsi que le fait que le son peut être absorbé, réfléchi ou modifié."},{"code":"C2.5","title":"La lumière et le son","text":"expliquer que les ondes sonores sont causées par des vibrations."},{"code":"C2.6","title":"La lumière et le son","text":"décrire les interactions de l’énergie lumineuse et de l’énergie sonore avec différents objets et matériaux."},{"code":"C2.7","title":"La lumière et le son","text":"distinguer les sources de lumière qui émettent la lumière et la chaleur des sources qui émettent la lumière et très peu de chaleur."},{"code":"C2.8","title":"La lumière et le son","text":"nommer des organes sensoriels et des dispositifs qui utilisent les propriétés de la lumière et du son."}]}]},{"code":"D","title":"Structures et mécanismes","why":"Les élèves explorent les principes et les fonctions de base des machines et de leurs mécanismes et analysent leur incidence sur la société et l’environnement. Elles et ils apprennent la façon dont les mécanismes transmettent et transforment les divers types de mouvement et les modifications des forces, par exemple la levée d’un drapeau à l’aide d’un système de poulies ou le fait d’appuyer sur une touche de piano.","overall":[{"code":"D1","title":"Rapprochement entre les sciences, la technologie et notre monde en évolution","text":"analyser l’incidence de diverses machines et de leurs mécanismes sur la société et l’environnement.","specific":[{"code":"D1.1","title":"Les machines et leurs mécanismes","text":"analyser l’incidence de l’utilisation de machines et de leurs mécanismes sur la vie quotidienne de diverses communautés."},{"code":"D1.2","title":"Les machines et leurs mécanismes","text":"évaluer les répercussions environnementales de l’utilisation de diverses machines ayant la même fonction."}]},{"code":"D2","title":"Exploration et compréhension des concepts","text":"démontrer sa compréhension des principes de base et des fonctions de diverses machines et de leurs mécanismes.","specific":[{"code":"D2.1","title":"Les machines et leurs mécanismes","text":"nommer des machines couramment utilisées et décrire leurs fonctions."},{"code":"D2.2","title":"Les machines et leurs mécanismes","text":"nommer les pièces de divers mécanismes et décrire le rôle de chacune."},{"code":"D2.3","title":"Les machines et leurs mécanismes","text":"décrire les mécanismes permettant de transmettre divers types de mouvement, y compris le mouvement de rotation, d’une pièce mécanique à une autre."},{"code":"D2.4","title":"Les machines et leurs mécanismes","text":"décrire les mécanismes permettant de transformer divers types de mouvement, y compris les façons dont ils peuvent changer le plan géométrique dans lequel le mouvement se produit, ainsi que la vitesse et la direction du mouvement."},{"code":"D2.5","title":"Les machines et leurs mécanismes","text":"expliquer les façons de modifier la force dans une variété de machines."}]}]},{"code":"E","title":"Systèmes de la Terre et de l’espace","why":"Les élèves poursuivent leur apprentissage de l’environnement naturel en s’initiant aux processus terrestres ayant entraîné la formation de différents types de roches. Elles et ils approfondissent leur savoir sur les roches et les minéraux en apprenant à les classer selon des tests et des critères. Elles et ils découvrent le rôle important des roches et des minéraux dans la vie quotidienne, de même que leurs liens avec l’environnement.","overall":[{"code":"E1","title":"Rapprochement entre les sciences, la technologie et notre monde en évolution","text":"analyser l’incidence des processus géologiques et de l’utilisation des roches et des minéraux par les humains sur la société et l’environnement.","specific":[{"code":"E1.1","title":"Les roches, les minéraux et les processus géologiques","text":"analyser l’incidence des processus géologiques sur la société et l’environnement."},{"code":"E1.2","title":"Les roches, les minéraux et les processus géologiques","text":"évaluer les effets sur la société et sur l’environnement de l’extraction et du raffinage des roches et des minéraux, ainsi que de la fabrication, du recyclage et de l’élimination des produits dérivés de roches et de minéraux, en tenant compte de diverses perspectives."}]},{"code":"E2","title":"Exploration et compréhension des concepts","text":"démontrer sa compréhension des roches, des minéraux et des processus géologiques de la Terre.","specific":[{"code":"E2.1","title":"Les roches, les minéraux et les processus géologiques","text":"expliquer les processus géologiques à l’origine de la formation des roches ignées, sédimentaires et métamorphiques, en utilisant le cycle des roches."},{"code":"E2.2","title":"Les roches, les minéraux et les processus géologiques","text":"décrire les propriétés physiques des roches ignées, sédimentaires et métamorphiques."},{"code":"E2.3","title":"Les roches, les minéraux et les processus géologiques","text":"classifier différents roches et minéraux selon leur composition et leurs propriétés physiques, à l’aide de divers tests et critères."},{"code":"E2.4","title":"Les roches, les minéraux et les processus géologiques","text":"décrire diverses utilisations quotidiennes de roches et de minéraux."},{"code":"E2.5","title":"Les roches, les minéraux et les processus géologiques","text":"décrire la formation de fossiles et l’information qu’ils fournissent au sujet de l’histoire de la Terre."},{"code":"E2.6","title":"Les roches, les minéraux et les processus géologiques","text":"expliquer les façons dont les Premières Nations, les Métis et les Inuit mettent en application leurs connaissances géologiques pour choisir des roches et des minéraux à des fins précises."}]}]}]},"g5":{"url":"https://www.dcp.edu.gov.on.ca/fr/curriculum/sciences-technologie","sourceLang":"fr","strands":[{"code":"A","title":"Habiletés liées aux STIM et liens connexes","why":"Au cours de chaque année d’études, le programme-cadre de sciences et technologie intègre l’apprentissage des lié aux habiletés liées aux STIM et aux liens connexes aux quatre autres domaines d’étude du programme qui en font partie.","overall":[{"code":"A1","title":"Recherches et expériences liées aux STIM et habiletés de communication ","text":"utiliser une démarche de recherche, une démarche expérimentale et un processus de design en ingénierie pour effectuer des recherches et des expériences ainsi que pour résoudre des problèmes, tout en respectant les consignes de santé et de sécurité.","specific":[{"code":"A1.1","title":"","text":"utiliser une démarche de recherche et les habiletés connexes pour effectuer des recherches."},{"code":"A1.2","title":"","text":"utiliser une démarche expérimentale et les habiletés connexes pour effectuer des expériences."},{"code":"A1.3","title":"","text":"utiliser un processus de design en ingénierie et les habiletés connexes pour concevoir, construire et tester des dispositifs, des modèles, des structures et/ou des systèmes."},{"code":"A1.4","title":"","text":"respecter les consignes de santé et de sécurité à suivre durant les expériences scientifiques et technologiques, y compris le port de l’équipement et des vêtements de protection individuelle appropriés, et utiliser adéquatement les outils, les instruments et le matériel mis à sa disposition."},{"code":"A1.5","title":"","text":"communiquer les résultats de ses recherches et de ses expériences en utilisant la terminologie propre aux sciences et à la technologie et les moyens de communication appropriés selon les objectifs établis et l’auditoire cible."}]},{"code":"A2","title":"Codage et technologies émergentes ","text":"utiliser le codage pour examiner et modéliser des concepts, et analyser l’incidence du codage et des technologies émergentes sur la vie quotidienne et les secteurs liés aux STIM.","specific":[{"code":"A2.1","title":"","text":"écrire et exécuter des codes lors de l’exploration et de la modélisation de concepts, notamment pour utiliser différentes méthodes de stockage et de traitement de données à des fins diverses."},{"code":"A2.2","title":"","text":"déterminer et décrire l’incidence du codage et des technologies émergentes sur des situations de la vie quotidienne et sur des métiers spécialisés."}]},{"code":"A3","title":"Applications, liens et contributions","text":"démontrer sa compréhension des applications pratiques des sciences et de la technologie, ainsi que des contributions aux sciences et à la technologie d’individus ayant vécu diverses expériences.","specific":[{"code":"A3.1","title":"","text":"décrire des applications pratiques de concepts de sciences et technologie dans le cadre de diverses professions, y compris des métiers spécialisés, ainsi que des façons dont ces applications traitent de problèmes tirés de situations de la vie quotidienne."},{"code":"A3.2","title":"","text":"examiner des façons dont les sciences et la technologie peuvent être utilisées avec d’autres disciplines pour traiter de problèmes tirés de situations de la vie quotidienne."},{"code":"A3.3","title":"","text":"analyser des contributions apportées aux sciences et à la technologie par diverses communautés."}]}]},{"code":"B","title":"Systèmes vivants","why":"Les élèves approfondissent leur compréhension des systèmes du corps humain en étudiant leur structure et leur fonction ainsi que les relations entre différents organes. Par exemple, elles et ils explorent le fonctionnement du système circulatoire en harmonie avec le système respiratoire afin d’acheminer suffisamment d’oxygène à tous les organes. Les élèves examinent différents facteurs sociaux et environnementaux ainsi que l’incidence des technologies émergentes sur la santé humaine.","overall":[{"code":"B1","title":"Rapprochement entre les sciences, la technologie et notre monde en évolution","text":"analyser l’incidence de divers facteurs sociaux et environnementaux, de l’activité humaine et d’innovations technologiques sur la santé.","specific":[{"code":"B1.1","title":"La santé et les systèmes du corps humain","text":"examiner les effets de facteurs sociaux et environnementaux sur la santé, et décrire des moyens d’en réduire les conséquences nocives et d’en exploiter les bienfaits."},{"code":"B1.2","title":"La santé et les systèmes du corps humain","text":"examiner les effets de diverses technologies sur la santé et les systèmes du corps humain, en tenant compte de diverses perspectives."},{"code":"B1.3","title":"La santé et les systèmes du corps humain","text":"expliquer les façons dont la littératie alimentaire peut appuyer les décisions quant à la santé physique et mentale."}]},{"code":"B2","title":"Exploration et compréhension des concepts","text":"démontrer sa compréhension de la structure et de la fonction des systèmes du corps humain ainsi que de leurs interactions.","specific":[{"code":"B2.1","title":"La santé et les systèmes du corps humain","text":"nommer des systèmes du corps humain et décrire leurs fonctions principales."},{"code":"B2.2","title":"La santé et les systèmes du corps humain","text":"décrire la structure et la fonction de base des organes vitaux de divers systèmes du corps humain."},{"code":"B2.3","title":"La santé et les systèmes du corps humain","text":"décrire des interrelations entre des systèmes du corps humain."},{"code":"B2.4","title":"La santé et les systèmes du corps humain","text":"nommer des maladies ou des troubles de santé qui affectent les organes ou les systèmes du corps humain."}]}]},{"code":"C","title":"Matière et énergie","why":"Les élèves étudient les propriétés de la matière, les transformations des états, les changements physiques et chimiques, et les raisons pour lesquelles les propriétés physiques particulières de certains solides, liquides et gaz les rendent utiles pour certaines applications. Elles et ils analysent les conséquences des matières et des processus utilisés pour fabriquer des produits courants ainsi que les moyens pour lutter contre leurs effets négatifs.","overall":[{"code":"C1","title":"Rapprochement entre les sciences, la technologie et notre monde en évolution","text":"analyser l’incidence sur la société et l’environnement de divers procédés et matériaux utilisés dans la fabrication de produits courants ainsi que des moyens d’en atténuer les effets négatifs.","specific":[{"code":"C1.1","title":"Les propriétés et les changements de la matière","text":"analyser l’incidence sur la société et l’environnement de divers procédés de fabrication de produits courants."},{"code":"C1.2","title":"Les propriétés et les changements de la matière","text":"analyser l’incidence sur l’environnement de l’utilisation de certains matériaux dans la fabrication de produits courants, et proposer des actions que les individus et la société peuvent entreprendre pour en atténuer les effets négatifs."}]},{"code":"C2","title":"Exploration et compréhension des concepts","text":"démontrer sa compréhension des propriétés de la matière, des changements d’état ainsi que des changements physiques et chimiques.","specific":[{"code":"C2.1","title":"Les propriétés et les changements de la matière","text":"décrire la matière comme tout ce qui a une masse et qui occupe un volume."},{"code":"C2.2","title":"Les propriétés et les changements de la matière","text":"reconnaître les états de la matière, et décrire les caractéristiques et les propriétés des solides, des liquides et des gaz."},{"code":"C2.3","title":"Les propriétés et les changements de la matière","text":"décrire des changements d’état de la matière observés à la maison, dans la communauté ou dans la nature."},{"code":"C2.4","title":"Les propriétés et les changements de la matière","text":"décrire des changements physiques de la matière comme étant des changements d’état, de volume ou de forme n’entraînant pas la formation d’une autre substance."},{"code":"C2.5","title":"Les propriétés et les changements de la matière","text":"décrire des changements chimiques de la matière comme étant des changements entraînant la formation d’autres substances, et déterminer des indicateurs d’un changement chimique."},{"code":"C2.6","title":"Les propriétés et les changements de la matière","text":"expliquer des changements d’état qui peuvent se produire lorsque la matière absorbe ou libère de l’énergie thermique."},{"code":"C2.7","title":"Les propriétés et les changements de la matière","text":"expliquer pourquoi les propriétés physiques spécifiques de divers solides, liquides et gaz les rendent utiles pour des applications précises."}]}]},{"code":"D","title":"Structures et mécanismes","why":"Les élèves élargissent leur compréhension des forces agissant sur les structures et la façon dont différentes structures peuvent supporter les charges. Elles et ils explorent les caractéristiques physiques de différentes espèces animales et espèces de plantes qui protègent ces structures contre les effets négatifs des forces. Elles et ils analysent et évaluent aussi des moyens d’atténuer les conséquences sociales et environnementales des forces agissant sur les structures. Elles et ils décrivent également en quoi l’équipement de protection assure la sécurité des gens.","overall":[{"code":"D1","title":"Rapprochement entre les sciences, la technologie et notre monde en évolution","text":"évaluer les effets sur la société et l’environnement des forces agissant sur les structures, et les moyens d’atténuer les effets négatifs de ces forces.","specific":[{"code":"D1.1","title":"Les forces agissant sur les structures","text":"analyser les effets des forces résultant de phénomènes naturels sur des structures dans un environnement naturel et un environnement bâti."},{"code":"D1.2","title":"Les forces agissant sur les structures","text":"examiner des moyens mis en place par les humains visant à atténuer les effets des forces résultant de phénomènes naturels sur des structures dans les communautés urbaines, rurales et éloignées."}]},{"code":"D2","title":"Exploration et compréhension des concepts","text":"démontrer sa compréhension des forces agissant sur les structures ainsi que de la résistance de diverses structures à ces forces.","specific":[{"code":"D2.1","title":"Les forces agissant sur les structures","text":"indiquer des forces internes agissant sur une structure et décrire leurs effets sur celle-ci."},{"code":"D2.2","title":"Les forces agissant sur les structures","text":"indiquer des forces externes agissant sur une structure et décrire leurs effets sur celle-ci."},{"code":"D2.3","title":"Les forces agissant sur les structures","text":"décrire des forces résultant de phénomènes naturels, qui peuvent avoir de graves conséquences sur des structures bâties par les humains, et déterminer des caractéristiques structurelles ainsi que des choix de matériaux qui peuvent permettre à de telles structures de résister à ces forces."},{"code":"D2.4","title":"Les forces agissant sur les structures","text":"décrire les façons dont des caractéristiques physiques de diverses espèces animales et végétales contribuent à les protéger contre les effets potentiellement négatifs des forces."},{"code":"D2.5","title":"Les forces agissant sur les structures","text":"décrire les façons dont des équipements de protection contribuent à protéger les humains contre les effets potentiellement négatifs des forces."}]}]},{"code":"E","title":"Systèmes de la Terre et de l’espace","why":"Les élèves font l’apprentissage de la conservation de l’énergie, de même que les diverses formes, sources et utilisations de l’énergie. Elles et ils enrichissent leur compréhension des effets de l’utilisation de l’énergie et des ressources naturelles sur la société et l’environnement.","overall":[{"code":"E1","title":"Rapprochement entre les sciences, la technologie et notre monde en évolution","text":"évaluer les effets de l’utilisation de l’énergie et des ressources sur la société et l’environnement, et proposer des options pour conserver l’énergie et les ressources.","specific":[{"code":"E1.1","title":"Conservation de l’énergie et des ressources","text":"analyser l’incidence à long terme de l’utilisation de l’énergie et des ressources naturelles par les humains sur la société et l’environnement, y compris les changements climatiques, et proposer des moyens d’en réduire les effets négatifs."},{"code":"E1.2","title":"Conservation de l’énergie et des ressources","text":"analyser l’incidence de diverses technologies sur la consommation d’énergie et décrire des moyens de faire appel à la technologie afin de réduire la consommation d’énergie."},{"code":"E1.3","title":"Conservation de l’énergie et des ressources","text":"décrire des façons dont des communautés des Premières Nations, des Métis et des Inuit utilisent leurs connaissances et formes du savoir pour conserver l’énergie et les ressources naturelles."}]},{"code":"E2","title":"Exploration et compréhension des concepts","text":"démontrer sa compréhension de la conservation de l’énergie ainsi que des diverses formes, sources et utilisations de l’énergie et des ressources.","specific":[{"code":"E2.1","title":"Conservation de l’énergie et des ressources","text":"nommer diverses formes d’énergie et en donner des exemples d’utilisations quotidiennes."},{"code":"E2.2","title":"Conservation de l’énergie et des ressources","text":"reconnaître que, d’après la loi de la conservation de l’énergie, l’énergie ne peut être ni créée ni détruite, mais qu’elle peut seulement être transformée d’une forme à une autre."},{"code":"E2.3","title":"Conservation de l’énergie et des ressources","text":"décrire des façons dont l’énergie est emmagasinée sous forme d’énergie potentielle et transformée par un dispositif ou un système donné."},{"code":"E2.4","title":"Conservation de l’énergie et des ressources","text":"reconnaître que lors du processus de transformation d’énergie d’une forme à une autre, une certaine quantité d’énergie peut se dissiper dans l’environnement sous forme de chaleur, de lumière ou d’énergie sonore."},{"code":"E2.5","title":"Conservation de l’énergie et des ressources","text":"distinguer des sources d’énergie renouvelables et non renouvelables."},{"code":"E2.6","title":"Conservation de l’énergie et des ressources","text":"expliquer comment l’utilisation de l’énergie dérivée de combustibles fossiles change la composition de l’atmosphère et comment ces changements contribuent aux changements climatiques."}]}]}]},"g6":{"url":"https://www.dcp.edu.gov.on.ca/fr/curriculum/sciences-technologie","sourceLang":"fr","strands":[{"code":"A","title":"Habiletés liées aux STIM et liens connexes","why":"Au cours de chaque année d’études, le programme-cadre de sciences et technologie intègre l’apprentissage des lié aux habiletés liées aux STIM et aux liens connexes aux quatre autres domaines d’étude du programme qui en font partie.","overall":[{"code":"A1","title":"Recherches et expériences liées aux STIM et habiletés de communication","text":"utiliser une démarche de recherche, une démarche expérimentale et un processus de design en ingénierie pour effectuer des recherches et des expériences ainsi que pour résoudre des problèmes, tout en respectant les consignes de santé et de sécurité.","specific":[{"code":"A1.1","title":"","text":"utiliser une démarche de recherche et les habiletés connexes pour effectuer des recherches."},{"code":"A1.2","title":"","text":"utiliser une démarche expérimentale et les habiletés connexes pour effectuer des expériences."},{"code":"A1.3","title":"","text":"utiliser un processus de design en ingénierie et les habiletés connexes pour concevoir, construire et tester des dispositifs, des modèles, des structures et/ou des systèmes."},{"code":"A1.4","title":"","text":"respecter les consignes de santé et de sécurité à suivre durant les expériences scientifiques et technologiques, y compris le port de l’équipement et des vêtements de protection individuelle appropriés, et utiliser adéquatement les outils, les instruments et le matériel mis à sa disposition."},{"code":"A1.5","title":"","text":"communiquer les résultats de ses recherches et de ses expériences en utilisant la terminologie propre aux sciences et à la technologie et les moyens de communication appropriés selon les objectifs établis et l’auditoire cible."}]},{"code":"A2","title":"Codage et technologies émergentes","text":"utiliser le codage pour examiner et modéliser des concepts, et analyser l’incidence du codage et des technologies émergentes sur la vie quotidienne et les secteurs liés aux STIM.","specific":[{"code":"A2.1","title":"","text":"écrire et exécuter des codes lors de l’exploration et de la modélisation de concepts, notamment pour obtenir des données d’entrée de différentes façons à des fins diverses."},{"code":"A2.2","title":"","text":"déterminer et décrire l’incidence du codage et des technologies émergentes sur des situations de la vie quotidienne et sur des métiers spécialisés."}]},{"code":"A3","title":"Applications, liens et contributions","text":"démontrer sa compréhension des applications pratiques des sciences et de la technologie, ainsi que des contributions aux sciences et à la technologie d’individus ayant vécu diverses expériences.","specific":[{"code":"A3.1","title":"","text":"décrire des applications pratiques de concepts de sciences et technologie dans le cadre de diverses professions, y compris des métiers spécialisés, ainsi que des façons dont ces applications traitent de problèmes tirés de situations de la vie quotidienne."},{"code":"A3.2","title":"","text":"examiner des façons dont les sciences et la technologie peuvent être utilisées avec d’autres disciplines pour traiter de problèmes tirés de situations de la vie quotidienne."},{"code":"A3.3","title":"","text":"analyser des contributions apportées aux sciences et à la technologie par diverses communautés."}]}]},{"code":"B","title":"Systèmes vivants","why":"Les élèves étudient le concept de biodiversité: les différentes formes de vie sur la Terre, c’est-à-dire les animaux, les plantes et les micro-organismes, et leur importance des points de vue de la race humaine, de la société et de l’environnement. Dans le cadre de ce domaine d’étude, les élèves classent des organismes selon des critères précis. Elles et ils commencent également à établir des liens entre les effets des changements climatiques sur la biodiversité et l’incidence positive des efforts de préservation de la biodiversité.","overall":[{"code":"B1","title":"Rapprochement entre les sciences, la technologie et notre monde en évolution","text":"évaluer l’importance de la biodiversité et décrire des façons de la préserver.","specific":[{"code":"B1.1","title":"La biodiversité","text":"évaluer les bienfaits de la biodiversité et les conséquences de la réduction de la biodiversité."},{"code":"B1.2","title":"La biodiversité","text":"examiner un enjeu d’ordre local qui porte sur la biodiversité, en tenant compte de diverses perspectives, élaborer un plan d’action en vue de remédier à l’enjeu, et agir en fonction de ce plan."}]},{"code":"B2","title":"Exploration et compréhension des concepts","text":"démontrer sa compréhension de la biodiversité, ainsi que de la contribution de la biodiversité à la stabilité de l’environnement et des avantages de la biodiversité pour les humains.","specific":[{"code":"B2.1","title":"La biodiversité","text":"décrire différents groupes d’organismes selon des caractéristiques distinctes, et utiliser ces caractéristiques pour classifier ces organismes à l’aide d’un système de classification."},{"code":"B2.2","title":"La biodiversité","text":"décrire la biodiversité comme la diversité de la vie sur la Terre, incluant la diversité d’organismes au sein de chaque espèce, la diversité parmi les espèces dans une communauté, ainsi qu’au sein des communautés et des habitats les soutenant."},{"code":"B2.3","title":"La biodiversité","text":"décrire l’importance de la biodiversité au sein d’une espèce pour sa survie."},{"code":"B2.4","title":"La biodiversité","text":"décrire des façons dont la biodiversité au sein des communautés, et entre elles, est essentielle à leur survie."},{"code":"B2.5","title":"La biodiversité","text":"décrire les interrelations existant au sein des espèces, entre diverses espèces et entre des espèces et leur environnement, et expliquer comment ces relations soutiennent la biodiversité."},{"code":"B2.6","title":"La biodiversité","text":"expliquer les façons dont les espèces envahissantes réduisent la biodiversité dans les environnements locaux."},{"code":"B2.7","title":"La biodiversité","text":"expliquer le rôle des changements climatiques dans la perte de biodiversité et décrire l’incidence de ces pertes."},{"code":"B2.8","title":"La biodiversité","text":"décrire l’importance de la biodiversité pour soutenir l’agriculture, y compris l’agriculture autochtone dans le monde."}]}]},{"code":"C","title":"Matière et énergie","why":"Les élèves abordent le concept de l’électricité, les principes de l’énergie électrique et sa transformation en d’autres formes d’énergie. Elles et ils conçoivent, construisent et mettent à l’essai des dispositifs électriques et approfondissent leur apprentissage au sujet des circuits électriques en parallèle et en série. Elles et ils enrichissent leur compréhension de la production et l’utilisation d’énergie électrique et de ses effets sur la société et l’environnement.","overall":[{"code":"C1","title":"Rapprochement entre les sciences, la technologie et notre monde en évolution","text":"analyser l’incidence sur la société et l’environnement de la production et l’utilisation de l'énergie électrique, et proposer des façons d’utiliser l’énergie électrique de manière responsable.","specific":[{"code":"C1.1","title":"Les phénomènes, l’énergie et les dispositifs électriques","text":"examiner l’incidence à court terme et à long terme sur la société et l’environnement de la production d’énergie électrique au Canada, y compris l’incidence sur les communautés des Premières Nations, des Métis et des Inuit, et sur les changements climatiques."},{"code":"C1.2","title":"Les phénomènes, l’énergie et les dispositifs électriques","text":"examiner différentes façons de réduire sa consommation personnelle d’énergie électrique, en tenant compte de diverses sources renouvelables et non renouvelables, et proposer des pratiques responsables d’utiliser l’énergie électrique dans la communauté scolaire."}]},{"code":"C2","title":"Exploration et compréhension des concepts","text":"démontrer sa compréhension des principes de l’énergie électrique et de la transformation de l’énergie électrique en diverses formes d’énergie et vice-versa.","specific":[{"code":"C2.1","title":"Les phénomènes, l’énergie et les dispositifs électriques","text":"expliquer des phénomènes électrostatiques couramment observés à partir des principes de l’électricité statique."},{"code":"C2.2","title":"Les phénomènes, l’énergie et les dispositifs électriques","text":"décrire l’électricité dynamique et la comparer à l’électricité statique en faisant ressortir les différences."},{"code":"C2.3","title":"Les phénomènes, l’énergie et les dispositifs électriques","text":"nommer des matériaux qui sont de bons conducteurs d’électricité et d’autres qui sont de bons isolants."},{"code":"C2.4","title":"Les phénomènes, l’énergie et les dispositifs électriques","text":"décrire des façons dont les technologies transforment diverses formes d’énergie en énergie électrique."},{"code":"C2.5","title":"Les phénomènes, l’énergie et les dispositifs électriques","text":"décrire diverses façons de transformer l’énergie électrique en d’autres formes d’énergie."},{"code":"C2.6","title":"Les phénomènes, l’énergie et les dispositifs électriques","text":"expliquer les fonctions des composantes d’un circuit électrique simple."},{"code":"C2.7","title":"Les phénomènes, l’énergie et les dispositifs électriques","text":"distinguer les circuits en série des circuits en parallèle, et déterminer des utilisations courantes de chaque type de circuit."}]}]},{"code":"D","title":"Structures et mécanismes","why":"Les élèves apprennent la manière dont les propriétés de l’air sont appliquées à la mécanique du vol et la manière de rendre possibles les quatre forces du vol. Elles et ils étudient les dispositifs volants et les divers êtres vivants qui recourent à l’équilibre et au déséquilibre des forces pour maîtriser leur vol. Les élèves approfondissent leur compréhension des incidences sociales et environnementales de différents dispositifs volants.","overall":[{"code":"D1","title":"Rapprochement entre les sciences, la technologie et notre monde en évolution","text":"analyser l’incidence des machines volantes sur l’environnement.","specific":[{"code":"D1.1","title":"Le vol","text":"analyser l’incidence des technologies aéronautiques sur la société, en tenant compte des perspectives locales et mondiales."}]},{"code":"D2","title":"Exploration et compréhension des concepts","text":"démontrer sa compréhension des diverses applications des propriétés de l’air à la mécanique du vol et aux machines volantes.","specific":[{"code":"D2.1","title":"Le vol","text":"déterminer des applications des propriétés de l’air dans le domaine de la mécanique du vol."},{"code":"D2.2","title":"Le vol","text":"décrire les relations qui existent entre les quatre forces du vol: la portance, le poids, la traînée et la poussée, et qui rendent le vol possible."},{"code":"D2.3","title":"Le vol","text":"décrire l’utilisation par des machines volantes et divers êtres vivants de l’équilibre et du déséquilibre des forces pour contrôler leur vol."},{"code":"D2.4","title":"Le vol","text":"décrire diverses méthodes utilisées pour modifier les quatre forces du vol."},{"code":"D2.5","title":"Le vol","text":"décrire les caractéristiques et les adaptations qui permettent aux organismes de voler."}]}]},{"code":"E","title":"Systèmes de la Terre et de l’espace","why":"Les élèves abordent leur apprentissage de notre système solaire, qui se compose du Soleil, ainsi que de planètes, de comètes et d’astéroïdes en orbite autour de celui-ci. Elles et ils étudient les technologies utilisées dans l’exploration spatiale et leurs contributions dans la vie quotidienne, qu’il s’agisse des satellites, des systèmes de localisation GPS ou des appareils photo sur les téléphones portables. Les élèves analysent également la portée tout aussi importante des contributions de ces innovations technologiques à notre compréhension de l’espace et de l’Univers.","overall":[{"code":"E1","title":"Rapprochement entre les sciences, la technologie et notre monde en évolution","text":"analyser l’incidence de l’exploration spatiale sur les humains, la société et l’environnement.","specific":[{"code":"E1.1","title":"L’espace","text":"examiner les effets de l’espace sur les astronautes en mission spatiale et les adaptations nécessaires à leurs besoins sociaux, émotionnels et physiologiques dans l’espace."},{"code":"E1.2","title":"L’espace","text":"évaluer le rôle des technologies liées à l’exploration spatiale dans l’observation et la compréhension des changements environnementaux sur la Terre, y compris les changements climatiques."},{"code":"E1.3","title":"L’espace","text":"analyser l’incidence de l’exploration spatiale sur la société et l’environnement, en tenant compte de diverses perspectives."}]},{"code":"E2","title":"Exploration et compréhension des concepts","text":"démontrer sa compréhension du système solaire, des phénomènes attribuables aux mouvements de divers corps au sein de celui-ci et des technologies liées à l’exploration spatiale.","specific":[{"code":"E2.1","title":"L’espace","text":"identifier des composantes du système solaire, incluant le Soleil, la Terre, les autres planètes, les satellites naturels, les comètes, les astéroïdes et les météoroïdes, et décrire leurs principales caractéristiques physiques."},{"code":"E2.2","title":"L’espace","text":"distinguer entre les concepts de masse et de poids."},{"code":"E2.3","title":"L’espace","text":"décrire la relation entre la force gravitationnelle et le poids d’un corps."},{"code":"E2.4","title":"L’espace","text":"distinguer, dans l’espace, les corps qui émettent de la lumière de ceux qui réfléchissent la lumière."},{"code":"E2.5","title":"L’espace","text":"décrire divers effets des mouvements et des positions relatives de la Terre, de la Lune et du Soleil."},{"code":"E2.6","title":"L’espace","text":"nommer diverses technologies liées à l’exploration spatiale et décrire la contribution des innovations technologiques à notre compréhension de l’espace."}]}]}]}},"ss":{"g1":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-sshg","sourceLang":"en","strands":[{"code":"A","title":"Heritage and Identity: Our Changing Roles and Responsibilities","why":"Students learn about the various roles, relationships and responsibilities that people have and how they change over time and in different situations. They also explore how their own roles, relationships and responsibilities are connected to their own identity, culture and sense of self. Students will develop their appreciation of the need to treat all people, as well as built features, such as buildings, transportation routes or structures, and the natural environment, responsibly and with respect.","overall":[{"code":"A1","title":"Application: Why Roles and Responsibilities Change","text":"describe some of the ways in which people’s roles, relationships with, and responsibilities to others and the world around them relate to who they are and what their situation is, and how and why changes in circumstances might affect people’s roles, relationships, and responsibilities as well as their sense of self (FOCUS ON: Continuity and Change)","specific":[{"code":"A1.1","title":"","text":"describe how and why a person’s roles, relationships, and responsibilities, in relation to others and to the environment, may change in different places or situations and at different times (e.g., how and why a student’s relationship with a teacher is different from that with a peer; how and why a student’s relationship with the natural environment, such as taking part in harvesting or fishing, could support learning that deepens family and/or community cultural connections; how their parents’/caregivers’ roles differ at home and at work; how a child’s responsibilities at home may change as the child gets older)"},{"code":"A1.2","title":"","text":"describe how some significant events in their lives (e.g., the birth of a sibling, starting school, moving to a new home, getting a pet; participating in various cultural ceremonies and traditions specific to their family, community, or nation such as taking part in a naming ceremony, joining in seasonal ceremonies, building a personal sacred bundle, making noodles for Lunar New Year, lighting a menorah or Kwanzaa candle, collecting maple sap to make maple syrup, building a family canoe, participating in a Khalsa Day parade, setting up an ofrenda for the Day of the Dead) led to changes in their roles, relationships, and/or responsibilities"},{"code":"A1.3","title":"","text":"compare some of the significant events in their own lives and/or the lives of their family members with those in the lives of their peers"},{"code":"A1.4","title":"","text":"describe the impact that people can have on each other in some different situations (e.g., when a person helps a child who is lost, when a child upsets another child, when a teacher helps a student find the answer to a problem, when schoolmates share toys or art supplies) and some of the ways in which interactions between people can affect a person’s sense of self"},{"code":"A1.5","title":"","text":"identify some of the ways in which First Nations, Métis, and Inuit individuals and communities are reclaiming and revitalizing aspects of their identity that were lost or taken away due to colonization, including the residential school system (e.g., traditional practices and rituals being taught and celebrated in community; strengthening of family, clan, and/or extended family relationships; language learning and revitalization; acts of resilience and healing; reclaiming of identity), and the role that these aspects play in their sense of self (e.g., personal pride in self and community; sense of belonging – who they are, where they come from, and how they relate to one another)"}]},{"code":"A2","title":"Inquiry: Roles, Responsibilities, and Identity","text":"use the social studies inquiry process to investigate some aspects of the interrelationship between their identity/sense of self, their different roles, relationships, and responsibilities, and various situations in their daily lives (FOCUS ON: Interrelationships)","specific":[{"code":"A2.1","title":"","text":"formulate questions to guide investigations into some aspects of the interrelationship between events, people, and/or places in their lives and their own roles, relationships, responsibilities, and identity/sense of self (e.g., brainstorm with their peers to formulate simple questions related to an event that has affected their self-concept, to changes in their responsibilities since they started school, or to how they behave in different places)"},{"code":"A2.2","title":"","text":"gather and organize information on significant events, people, and/or places in their lives that contribute or have contributed to the development of their roles, relationships, responsibilities, and identity/sense of self (e.g., a birth or death in the family, their first day at school, a friend getting hurt at the park, getting lost in a shopping mall, their family’s place of worship, moving to a new home, joining a recreation, language, or cultural program for children and youth), using primary and/or secondary sources that they have located themselves or that have been provided to them (e.g., photographs, family and other stories, interviews, artefacts, newspapers and magazines, educational websites for children, books written by diverse voices – including First Nations, Métis, and Inuit authors/storytellers – on identity, family, and community relationships)"},{"code":"A2.3","title":"","text":"analyse and construct simple maps as part of their investigations into places that are significant to them or to their family (e.g., construct a map that includes a title, legend, and directions to show the route from their home to their best friend’s home or to school; construct a map to show key places they visit in their community; find the school entrance, playground, and their classroom on a map of their school)"},{"code":"A2.4","title":"","text":"interpret and analyse information relevant to their investigations, using a variety of tools (e.g., use a timeline of significant events in their life to help them make connections between those events and changes in their sense of self; list the activities they like to help with at home and at school on a Venn diagram to help them determine the similarities and differences between their roles in different locations; use a graphic organizer to help them determine the relationship between the responsibilities of adults in their life and their own responsibilities; create a cyclical calendar that acknowledges the changes in responsibilities for each of the seasons)"},{"code":"A2.5","title":"","text":"evaluate evidence and draw conclusions about some aspects of the interrelationship between events, people, and/or places in their lives and their own roles, relationships, responsibilities, and identity/sense of self"},{"code":"A2.6","title":"","text":"communicate the results of their inquiries, using appropriate vocabulary (e.g., role, relationship, responsibility, sense of self, community, identity) and formats (e.g., an oral presentation on the biggest change or significant event in their life and how it affected them; a map showing places that are important to them; captioned photographs of significant people in their lives)"}]},{"code":"A3","title":"Understanding Context: Roles, Relationships, and Respect","text":"demonstrate an understanding that they and other people experience a range of different roles, relationships, and responsibilities, and that all people and the environment should be treated with respect (FOCUS ON: Significance)","specific":[{"code":"A3.1","title":"","text":"describe some of their own roles, relationships, and responsibilities (e.g., as a student, member of a family, friend, member of the community, as someone who cares for the environment, pet owner)"},{"code":"A3.2","title":"","text":"identify some of the significant people, places, and things in their life, including their life in the community (e.g., people: parent, teacher, Elder, Knowledge Keeper, Knowledge Holder, Métis Senator, doctor, cultural or youth worker; places: school, friends’ homes, the library, parks or playgrounds, their place of worship, after-school community program, sacred sites; living and non-living things: pets, culturally significant items in their home, toys and comfort items), and describe their purpose or the role they have"},{"code":"A3.3","title":"","text":"demonstrate an understanding of simple chronology by identifying and organizing chronologically some significant events related to their personal experience (e.g., their progress from daycare to Kindergarten and then to Grade 1; learning to walk, to ride a tricycle, and then to ride a bicycle)"},{"code":"A3.4","title":"","text":"identify some elements of positive and inclusive behaviour and actions that they can practise in their everyday life (e.g., sharing, cooperating, being courteous, not damaging the natural or built environment, acknowledging and extending gratitude to the Earth, caring for Elders, Knowledge Holders, Knowledge Keepers, and Traditional Teachers; understanding and considering a variety of cultures and the diversity of traditions, including the diversity that exists among First Nations, Métis, and Inuit individuals) and/or that other people practise (e.g., bowing to each other as a sign of respect)"},{"code":"A3.5","title":"","text":"demonstrate an understanding that it is important to treat other people and the environment with respect (e.g., practise taking turns listening, make a list of ways to care for plants in the school community, make and illustrate a poster of ways to save water at home)"}]}]},{"code":"B","title":"People and Environments: The Local Community","why":"Students learn about how their local community provides services and has natural and built features that help meet the needs of the people who live and work there. They investigate how the actions of people have an impact on the natural and built features of the community. Students also learn to understand and read the basic elements of maps, so they can create one.","overall":[{"code":"B1","title":"Application: Interrelationships within the Community","text":"describe some aspects of the interrelationship between people and the natural and built features of their community (FOCUS ON: Interrelationships)","specific":[{"code":"B1.1","title":"","text":"describe some of the ways in which people interact with the natural environment and the built features of, and human services in, the local community to meet their needs, and what might happen if these features/services did not exist"},{"code":"B1.2","title":"","text":"identify some services and service-related occupations in their community (e.g., occupations such as sanitation worker, store clerk, restaurant server, repair person; services provided by the post office, the First Nation administration office, the Métis community council office, Inuit community centres, the community health clinic, the Indigenous Friendship Centre, cultural education centres, the water treatment plant, grocery stores, gas stations), and describe how they meet people’s needs, including their own needs"},{"code":"B1.3","title":"","text":"create a plan that outlines some specific ways in which they can responsibly interact with the built and/or natural environment in the local community (e.g., map out the location of garbage and recycling cans in parks so they can properly dispose of their waste; help plan and grow a sustainable garden at home, composting in the school, or other ways of reducing their environmental footprint; plan ways to participate in clean-up days), and describe how their actions might enhance the features of the local environment"}]},{"code":"B2","title":"Inquiry: Interrelationships and Their Impact","text":"use the social studies inquiry process to investigate some aspects of the interrelationship between people and different natural and built features of their local community, with a focus on significant short- and long-term effects of this interrelationship (FOCUS ON: Cause and Consequence)","specific":[{"code":"B2.1","title":"","text":"formulate questions to guide investigations into some aspects of the interrelationship between people and the natural and built features of their community, with a focus on some of the short- and long-term effects of this interrelationship (e.g., brainstorm with their peers to formulate simple questions related to the effects of not using garbage cans or not cleaning up after their dogs on the playground, of a community tree-planting event, of the building of a new road or big-box store on what was once green space, or of shutting down a local store)"},{"code":"B2.2","title":"","text":"gather and organize information on the interrelationship between people and the natural and built features of their community, and on the effects of this interrelationship, using sources that they have located themselves or that have been provided to them (e.g., use a tally sheet to monitor the use of garbage cans and recycling containers around the school; use a digital camera to record the amount of garbage on the ground in the park; organize satellite images that show changes in natural or built features in their community; interview a person who works in the park; listen to people speak and teach about various Fall Harvest festivals and activities)"},{"code":"B2.3","title":"","text":"analyse maps, and construct simple maps using appropriate elements, as part of their investigations into the interrelationship between people and significant natural and built features in their community (e.g., show the location of parks, bodies of water, or shopping districts, using symbols or photographs, a legend, directions, and colour; label a map with Indigenous place names)"},{"code":"B2.4","title":"","text":"interpret and analyse information and data relevant to their investigations, using a variety of tools (e.g., plot their data on a pictograph or chart to determine ways in which an area in their community has changed; compare their own photographs or drawings of the way an area looks now to old photographs to determine changes)"},{"code":"B2.5","title":"","text":"evaluate evidence and draw conclusions about some aspects of the interrelationship between people and natural and built features of their local community, and some of the effects of this interrelationship"},{"code":"B2.6","title":"","text":"communicate the results of their inquiries using appropriate vocabulary (e.g., location, map, symbol, distance, legend, direction, scale, community) and formats (e.g., a cooperatively produced book of photos from a field study; song lyrics, a rap, a dance, or a poem about the benefits of a community garden; a poster illustrating the benefits of planting trees; a map showing the natural and built features of their neighbourhood; role play illustrating responsible and respectful treatment of the environment)"}]},{"code":"B3","title":"Understanding Context: The Elements of the Local Community","text":"describe significant aspects of their community, with reference to different areas, services, and natural and built features, demonstrating an understanding of some basic ways of describing location and measuring distance (FOCUS ON: Significance; Patterns and Trends)","specific":[{"code":"B3.1","title":"","text":"identify the traditional Indigenous and treaty territory or territories on which their school is located"},{"code":"B3.2","title":"","text":"identify some of the natural and built features of their community (e.g., rivers, lakes, forests, parks, roads, stores, houses, apartment or condominium buildings, libraries, schools, arenas, recreation centres, places of worship, Indigenous sacred fire arbour, community and cultural centres)"},{"code":"B3.3","title":"","text":"identify some distinct areas in the local community (e.g., residential areas, commercial areas, high-traffic areas, different areas within the school, natural areas), and describe some of the characteristics of these areas (e.g., high-traffic areas have wide roads and stoplights; commercial areas have lots of stores; residential areas have rows of houses or apartments and are separate from business areas; mixed-use areas may include buildings that have both businesses and housing; the school has wings of classrooms that are connected by hallways; the natural areas have trees, plants, water, and lots of animals that live there)"},{"code":"B3.4","title":"","text":"describe the location of some significant places in their community, using relative location (e.g., near, far, up, down), relative distance (e.g., close, far, farther), and relative direction (e.g., right, left, in front, behind)"},{"code":"B3.5","title":"","text":"demonstrate an understanding of the basic elements of a map (e.g., title, symbols in the legend, direction, scale, and colour) when reading and constructing simple maps showing places that are significant to them (e.g., their classroom, the school, their immediate neighbourhood, their library, their cultural or community centre)"},{"code":"B3.6","title":"","text":"demonstrate an understanding of some common non-standard units of measurement (e.g., footsteps, tiles, blocks, houses)"},{"code":"B3.7","title":"","text":"demonstrate the ability to construct simple maps of places they have visited, using symbols and non-standard units (e.g., use different symbols to show the location of the play, picnic, and walking areas in a local park; use houses or blocks as units of measurement; include a scale and legend on a map showing the route and distance from their classroom to the washroom; use symbols on a sketch map of their route to school to show the built and natural features they pass by)"},{"code":"B3.8","title":"","text":"identify some of the services in the community for which the government and/or community is responsible (e.g., postal service, police services, fire services, hospitals, garbage collection, ploughing snow, maintenance of public areas, water treatment, daycare centres, First Nation administration office, local Métis community council offices, Inuit community centres, community health services, Indigenous Friendship Centre, language schools), and describe key responsibilities of people in the community in relation to those services (e.g., to properly sort garbage and recycling and place the bins on the street for pick up; to shovel snow off their sidewalks; to dispose of hazardous waste at collection sites; to install and maintain smoke detectors; to keep noise down after hours; to provide support and care to community members; to teach language and culture)"}]}]}]},"g2":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-sshg","sourceLang":"en","strands":[{"code":"A","title":"Heritage and Identity: Changing Family and Community Traditions","why":"Students explore a variety of traditions within their families and their local communities, as well as First Nations, Métis and/or Inuit and other diverse communities. They investigate how traditions and celebrations may have changed over time. They develop an understanding of how these traditions contribute to and enrich their own community and Canadian society.","overall":[{"code":"A1","title":"Application: Why Traditions Change","text":"compare some significant traditions and celebrations among diverse groups and at different times, including those of First Nations, Métis, and/or Inuit, and identify some of the reasons for changes in these traditions/celebrations (FOCUS ON: Perspective; Cause and Consequence)","specific":[{"code":"A1.1","title":"","text":"compare ways in which some traditions have been celebrated over multiple generations in their family (e.g., First Nations, Métis, or Inuit traditions and customs, such as sharing of knowledge, ceremonies, environmental experiences, songs and dances, hunting, harvesting, and/or gathering activities; holiday and/or special meals; decorations and items of significance used in celebrations) and identify some of the main reasons for changes in these traditions (e.g., immigration to Canada, changes in technology, acts of colonization)"},{"code":"A1.2","title":"","text":"compare their family structure and some of their traditions and celebrations with those of their peers’ families (e.g., traditions/celebrations related to rites of passage, holidays, foods, ceremonies, language preservation [both written and spoken])"},{"code":"A1.3","title":"","text":"compare some of the past and present traditions and celebrations of various ethnocultural groups in their local community, and identify some of the main reasons for the change (e.g., when some of their spiritual or cultural traditions were outlawed or people were forced to give them up, First Nations, Métis, and Inuit individuals developed different practices, but now some traditional practices are being reclaimed)"},{"code":"A1.4","title":"","text":"identify some ways in which First Nations, Métis, and/or Inuit individuals, communities, and nations are reclaiming traditions, customs, teachings, and celebrations (e.g., sharing songs, dances, foods, and clothing styles; holding traditional ceremonies and community gatherings) that were banned, lost, or practised in secret due to settlement and/or colonization, including the residential school system (e.g., forcing First Nations peoples to live on reserves; removing Indigenous children from their families and placing them in residential schools; forcing Inuit to relocate; prohibiting ceremonies, dancing, and traditional clothing)"}]},{"code":"A2","title":"Inquiry: Past and Present Traditions","text":"use the social studies inquiry process to investigate some of the past and present traditions and celebrations within their own family and the communities to which they belong (FOCUS ON: Continuity and Change)","specific":[{"code":"A2.1","title":"","text":"formulate questions to guide investigations into some of the past and present traditions and celebrations in their own family and the communities to which they belong (e.g., simple questions related to past and present practices associated with Christmas, Yom Kippur, Eid al-Fitr, Diwali, Kwanzaa, the Midwinter ceremony)"},{"code":"A2.2","title":"","text":"gather and organize information on some of the past and present traditions and celebrations within their family and the community to which they belong, using primary and/or secondary sources that they have gathered themselves or that have been provided to them (e.g., photo albums, family stories, interviews, artefacts, newspaper clippings, paintings, Elders’ and other community members’ stories)"},{"code":"A2.3","title":"","text":"analyse and construct simple maps as part of their investigations into past and present traditions and celebrations in their local community (e.g., locate on a map the regions of origin of different settlers in their area; construct a map that includes an appropriate legend to show peoples who are newcomers in the area; locate on a map places where some First Nations, Métis, and/or Inuit host their annual events and celebrations)"},{"code":"A2.4","title":"","text":"interpret and analyse information relevant to their investigations, using a variety of tools (e.g., list the holiday decorations that their family uses today and that were used by their grandparents and great-grandparents, and use a Venn diagram to help them determine the similarities and differences; create a list of holiday traditions or special days/observances of their parents, grandparents, and great-grandparents, or of their community, and use a bar graph to help them determine which have changed; list traditional food items shared at First Nations, Métis, and/or Inuit community gatherings and celebrations, and use a Venn diagram to help them determine similarities and differences)"},{"code":"A2.5","title":"","text":"evaluate evidence and draw conclusions about past and present traditions and celebrations in their own families and the communities to which they belong"},{"code":"A2.6","title":"","text":"communicate the results of their inquiries, using appropriate vocabulary (e.g., holiday, tradition, culture, language, celebrations, generations) and formats (e.g., a big book cooperatively produced by the class using photographs uploaded from digital cameras; a recording of stories [with permission from the storytellers] about how celebrations have changed and stayed the same in their family and community; interpretive movements representing a variety of celebrations)"}]},{"code":"A3","title":"Understanding Context: Tradition and Heritage","text":"describe some of the major groups in their community, including First Nations, Métis, and/or Inuit, other diverse communities, and different types of families, and some of the ways in which traditions and heritage are passed on by such groups (FOCUS ON: Interrelationships; Significance)","specific":[{"code":"A3.1","title":"","text":"identify and describe different types of families (e.g., families with one parent, two parents, no children; same-sex families; blended and multigenerational families; families where the parents come from different religious or ethnocultural groups; foster families)"},{"code":"A3.2","title":"","text":"identify various groups in their community (e.g., various religious and ethnocultural groups; First Nations, Métis, and/or Inuit individuals; Black and racialized groups; immigrants and refugees), and describe some of the ways in which their community reflects this diversity (e.g., the presence of a variety of languages, foods, music, clothing, holidays; distinct cultural neighbourhoods with specialized shops and restaurants)"},{"code":"A3.3","title":"","text":"identify places and/or countries of personal or familial significance, and locate them on a globe and/or print, digital, or interactive map"},{"code":"A3.4","title":"","text":"describe some significant traditions and celebrations of their families, their peers, and their own communities, as well as of some other communities in Canada, including First Nations, Métis, and/or Inuit communities (e.g., fall fairs; faith/cultural holidays such as Easter, Passover, Eid al-Fitr, Diwali; Kwanzaa; commemorative days such as Remembrance Day, Canada Day, National Indigenous Peoples Day, National Day for Truth and Reconciliation, Louis Riel Day, Powley Day, Earth Day; religious ceremonies; cultural festivals such as Toronto Caribbean Carnival, Desifest, Mississauga Latin Festival)"},{"code":"A3.5","title":"","text":"demonstrate an understanding of simple chronology by identifying and organizing chronologically some important events and/or people from multiple generations in their family and/or community (e.g., construct a three-generation family tree; construct a timeline showing marriages and births within their family; prepare a chronological list showing when family members moved, including, if applicable, when they immigrated to Canada; construct a timeline of seasonal ceremonies)"},{"code":"A3.6","title":"","text":"identify some ways in which heritage is passed on through various community celebrations, traditions, teachings, ceremonies, and events (e.g., recipes are passed down to new generations when traditional food is prepared for a community celebration; ethnocultural or community-based cultural festivals and events often showcase traditional clothing, music, dance, stories, and/or games)"},{"code":"A3.7","title":"","text":"identify some ways in which heritage is passed on through various family celebrations and practices, including at least one First Nation, Métis, and/or Inuit family celebration or practice (e.g., celebrations around Christmas, Ramadan, Hanukkah, Diwali, Kwanzaa; traditions related to rites of passage)"}]}]},{"code":"B","title":"People and Environments: Global Communities","why":"Students learn about communities around the world, including contemporary First Nations, Métis and Inuit communities. They explore the relationship between location, climate, physical features and how people live in various communities. They continue to develop their ability to read and construct maps for specific purposes.","overall":[{"code":"B1","title":"Application: Variations in Global Communities","text":"describe some similarities and differences in the ways in which people in two or more communities in different parts of the world meet their needs and have adapted to the location, climate, and physical features of their regions (FOCUS ON: Cause and Consequence)","specific":[{"code":"B1.1","title":"","text":"compare selected communities from around the world, including their own community, in terms of the lifestyles of people in those communities and some ways in which the people meet their needs (e.g., in northern Europe, people have homes that are heated and insulated, while in the Caribbean, houses do not need to be insulated and may have rooms that are open to the outdoors; in cities, most people buy their groceries from a local shop or a grocery store, but in rural South America people either grow their own food or trade with other farmers)"},{"code":"B1.2","title":"","text":"describe some of the ways in which two or more distinct communities have adapted to their location, climate, and physical features (e.g., in Arctic Canada, where it is cold, people wear warm clothes made with fur and hide or insulated with down or fleece; in Hawaii some schools start early in the morning and end before it gets really hot in the afternoon)"},{"code":"B1.3","title":"","text":"demonstrate an understanding of the importance of sustainability in people’s interrelationship with their natural environment and of some of the consequences of sustainable and/or non-sustainable actions (e.g., if people in dry regions do not use their water carefully, they may run out; if people do not use sustainable farming techniques, they may exhaust the fertility of the soil; responsible use of resources helps ensure that they will be available for future generations; overhunting or overfishing can cause a decline in certain species of wildlife important to the survival of groups of people)"}]},{"code":"B2","title":"Inquiry: Natural Environments and Ways of Life","text":"use the social studies inquiry process to investigate aspects of the interrelationship between the natural environment, including the climate, of selected communities, including at least one contemporary First Nation, Métis, or Inuit community, and the ways in which people in those communities live (FOCUS ON: Interrelationships; Patterns and Trends)","specific":[{"code":"B2.1","title":"","text":"formulate questions to guide investigations into some aspects of the interrelationship between the natural environment of selected communities, including at least one contemporary First Nation, Métis, or Inuit community, and the ways in which people live (e.g., questions about how climate relates to clothing, agriculture, housing, recreation)"},{"code":"B2.2","title":"","text":"gather and organize information and data about some communities’ locations, climate, and physical features, and the ways of life of people in these communities, including at least one contemporary First Nation, Métis, or Inuit community (e.g., use atlases, globes, print, digital or interactive maps, and/or satellite images to determine location; find photographs in magazines or on the Internet that provide information on people’s food, shelter, and/or clothing; invite an individual with community connections and expertise, such as an Elder, Knowledge Keeper, Métis Captain of the Hunt, or Traditional Teacher, to discuss relationships between the location of their community and what is harvested/hunted in the region)"},{"code":"B2.3","title":"","text":"analyse and construct simple maps to determine and illustrate patterns in the interrelationship between the location of some communities and human activities in those communities (e.g., use a print, digital, or interactive map to determine the proximity of communities to the equator and then infer whether their climates are likely to be hot, temperate, or cold; use different colours on a map to illustrate climatic changes as one moves north and south from the equator; include photographs of shelter, clothing, or recreational activities on a map to show how people’s adaptations are related to the general location of their community on the globe)"},{"code":"B2.4","title":"","text":"interpret and analyse information relevant to their investigations, using a variety of tools (e.g., plot data on a chart, bar graph, or pictograph to help them determine which countries have similar climates; determine the climatic region in which people live by examining photos of their clothing, natural resources, foods, or homes)"},{"code":"B2.5","title":"","text":"evaluate evidence and draw conclusions about some aspects of the interrelationship between communities’ natural environment and the ways of life of people in those communities, including at least one contemporary First Nation, Métis, or Inuit community"},{"code":"B2.6","title":"","text":"communicate the results of their inquiries, using appropriate vocabulary (e.g., globe, sphere, hemisphere, continent, country, equator, North Pole, South Pole, model, distance, culture) and formats (e.g., a book of captioned photos from a field study; song lyrics, a rap, or poem on the way of life in various communities around the world; a poster showing clothing of people who live in cold climates and in hot climates; a role play to illustrate variations in recreational activities)"}]},{"code":"B3","title":"Understanding Context: Physical Features and Communities","text":"identify and locate various physical features and selected communities around the world, including at least one contemporary First Nation, Métis, or Inuit community, and describe some aspects of people’s ways of life in those communities (FOCUS ON: Significance)","specific":[{"code":"B3.1","title":"","text":"demonstrate an understanding that there are a variety of countries, continents, physical features, and bodies of water around the world and that their locations can be represented in different ways (e.g., using globes; print, digital, and/or interactive maps; mapping programs; electronic images)"},{"code":"B3.2","title":"","text":"identify continents, significant bodies of water, the equator, poles, and hemispheres, using a globe, print, digital, or interactive maps, and/or a mapping program"},{"code":"B3.3","title":"","text":"identify cardinal directions on a map (i.e., N, S, E, W), and use these directions when locating selected communities, countries, and/or continents"},{"code":"B3.4","title":"","text":"identify the location of selected countries, cities, and/or towns around the world, including at least one contemporary First Nation, Métis, or Inuit community, and describe how their location and climate are related (e.g., Mexico is warm year-round because it is close to the equator; Canada has four seasons because it is far from the equator; Winnipeg is usually colder than Toronto in the winter because it is farther north)"},{"code":"B3.5","title":"","text":"demonstrate the ability to extract information on the location and climate of a region from photographs and print, digital, and/or interactive maps"},{"code":"B3.6","title":"","text":"identify basic human needs (e.g., for food, water, clothing, transportation, shelter), and describe some ways in which people in communities around the world meet these needs (e.g., food: hunting, fishing, farming, shopping at grocery stores; water: taps, water treatment facilities, wells, rivers, freshwater lakes; transportation: on foot, using animals, using motorized vehicles, using bicycles, by water)"},{"code":"B3.7","title":"","text":"describe selected communities around the world, including at least one contemporary First Nation, Métis, or Inuit community, with reference to their major physical features, wildlife, and some aspects of their culture (e.g., physical features such as mountains, lakes, rivers; native animals; cultural practices related to food, clothing, recreation, the arts; structures such as houses)"},{"code":"B3.8","title":"","text":"describe similarities and differences between their community and a community in a different region in the world (e.g., with respect to food, clothing, housing, beliefs, climate, flora and fauna, recreation, agricultural practices)"}]}]}]},"g3":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-sshg","sourceLang":"en","strands":[{"code":"A","title":"Heritage and Identity: Communities in Canada, 1780–1850","why":"Students learn about some of the diverse communities, including a few First Nations, Métis and Inuit communities, that existed in Canada during this time. They explore what life was like for different groups during this time period and compare the lives of these peoples to present-day Canada. Students will also use primary sources such as journals, letters, maps and paintings to investigate how people in early Canada responded to challenges in their lives.","overall":[{"code":"A1","title":"Application: Life in Canada – Then and Now","text":"compare ways of life among some specific groups in Canada, including a few First Nations, Métis, and Inuit communities, from around 1780 to 1850, and describe some of the changes between that era and the present day (FOCUS ON: Continuity and Change; Perspective)","specific":[{"code":"A1.1","title":"","text":"describe some of the similarities and differences in various aspects of everyday life (e.g., housing, clothing, food, religious/spiritual practices, work, recreation, the role of children) of selected groups and communities living in Canada between 1780 and 1850 (e.g., First Nations, Métis, Inuit, French, British, Black people; adults, children; people of different genders; enslaved people, indentured servants, habitants, seigneurs, farmers; people from different social classes)"},{"code":"A1.2","title":"","text":"compare what life was like between 1780 and 1850 in a few First Nations, Métis, and Inuit communities (e.g., they learned off the land; produced agriculture and fished, hunted, and/or harvested; practised their own languages, cultures, and ways of life; participated in economic trading with settler communities when possible; shared knowledge with settlers) with the ways in which later colonial policies, including the residential school system, changed life in these communities (e.g., removal of children: loss of culture and language, impacts of assimilation on identity, challenges to developing family relationships, the breakdown of community; communities: loss of land and freedom to make decisions about the use of Indigenous lands and territories; loss of sovereignty)"},{"code":"A1.3","title":"","text":"compare some of the roles of and challenges facing people living in Canada between 1780 and 1850 with those in the present day, including people in a few First Nations, Métis, and/or Inuit communities (e.g., the roles of women, men, and children; challenges related to the environment, life on the land, work, community life, the law; treaty-making between First Nations and the Crown)"},{"code":"A1.4","title":"","text":"identify some key components of identity in Canada today, including First Nations, Métis, and Inuit identity (e.g., bilingualism, multiculturalism, founding nations, religious freedom, nation-to-nation agreements), and describe some of the ways in which communities that were in Canada between 1780 and 1850 have had an impact on this identity (e.g., with reference to treaty rights and other agreements; Canada’s official languages; cultural symbols and contributions such as the birchbark canoe, lacrosse, kayak, inukshuk, or maple syrup; place names in Ontario and the rest of Canada; observances such as National Indigenous Peoples Day or Black History Month)"}]},{"code":"A2","title":"Inquiry: Community Challenges and Adaptations","text":"use the social studies inquiry process to investigate some of the major challenges that various groups and communities, including a few First Nations, Métis, and Inuit communities, faced in Canada from around 1780 to 1850, and key measures taken to address these challenges (FOCUS ON: Significance; Cause and Consequence)","specific":[{"code":"A2.1","title":"","text":"formulate questions to guide investigations into some of the major challenges facing various groups and communities in Canada from around 1780 to 1850 (e.g., isolation; climate; lack of access to medical care and medicine; law enforcement, or manufactured goods in isolated communities; encroachment of European settlers on First Nations territory; racism facing First Nations, Métis, and Black Loyalists; spread of diseases such as tuberculosis and smallpox among First Nations and Inuit communities; settler economics encouraging the overhunting of wildlife; unfair treaty-making processes) and measures taken to address these challenges"},{"code":"A2.2","title":"","text":"gather and organize information on major challenges facing various groups and communities, including at least one First Nation, Métis, or Inuit community, and on measures taken to address these challenges, using a variety of primary and/or secondary sources (e.g., settler journals, artefacts, newspapers, period paintings and drawings, historical fiction, oral histories)"},{"code":"A2.3","title":"","text":"analyse and construct print and digital maps, including thematic maps, as part of their investigations into challenges facing various groups and communities, including at least one First Nation, Métis, or Inuit community, in Canada during this period, and measures taken to address these challenges (e.g., find main roads and canals on a digital thematic map showing transportation routes; plot settlements on a map in order to determine their proximity to water; compare a map showing precontact territories of First Nations to a map showing reserves in 1850; use Indigenous sources to construct a map of the seasonal encampments of a First Nation, Métis, or Inuit community that moved according to the availability of food sources)"},{"code":"A2.4","title":"","text":"interpret and analyse information relevant to their investigations, using a variety of tools (e.g., use timelines and maps to help them determine how European settlement affected the location and size of First Nations and/or Métis communities; create a matrix to help them analyse the different challenges communities faced and how they adapted to them)"},{"code":"A2.5","title":"","text":"evaluate evidence and draw conclusions about some of the major challenges facing various groups and communities in Canada, including at least one First Nation, Métis, or Inuit community, during this period, and measures taken to overcome these challenges"},{"code":"A2.6","title":"","text":"communicate the results of their inquiries using appropriate vocabulary (e.g., First Nations, Métis, Inuit, Upper Canada, Lower Canada, treaty, displacement, settler, refugee, Loyalist, allies, land grant, seigneurie, habitant, enslaved person, hardship, isolation) and formats (e.g., a comic book that shows settler life before and after the construction of roads; a poster that shows how First Nations learned from their long-standing relationship with their territories, focusing on plants or technologies; a drawing that shows how people adapted to the climate; a map showing how European settlement affected First Nations territories)"}]},{"code":"A3","title":"Understanding Context: Life in Colonial Canadian Communities","text":"identify some of the communities in Canada, including a few First Nations, Métis, and Inuit communities, from around 1780 to 1850, and describe their relationships to the land and to each other (FOCUS ON: Interrelationships)","specific":[{"code":"A3.1","title":"","text":"identify various First Nations and some Métis communities in Upper and Lower Canada from 1780 to 1850, including those living in traditional territory and those who moved or were forced to relocate to new areas in response to European settlement, and locate the areas where they lived, using print, digital, and/or interactive maps or a mapping program (e.g., the traditional territories of the Anishinaabe around Thunder Bay; Chippewa land in southern Ontario; Drummond Island – focusing on the history of Métis settlement in the region; new Mohawk settlements in the Bay of Quinte area; the tract of land that the Six Nations gave the Mississauga; Métis communities around Lake Huron)"},{"code":"A3.2","title":"","text":"identify various settler communities in Canada during this period (e.g., French along the St. Lawrence River; English and Irish in Kingston, Bytown, and York/Toronto, Upper Canada; Black settlers in the Elgin Settlement in Buxton, Upper Canada; Scots in Nova Scotia and the Red River Valley; Mennonites in Waterloo County, Upper Canada; United Empire Loyalists in Upper and Lower Canada; Black Loyalists in Nova Scotia), and locate the areas where they lived, using print, digital, and/or interactive maps or a mapping program"},{"code":"A3.3","title":"","text":"identify some of the main factors that helped shape the development of settlements in Canada, including First Nations, Métis, and Inuit communities, during this period (e.g., the fur trade, the establishment of trading posts based on trade routes and the knowledge of First Nations and Métis peoples; navigable lakes and rivers for trade and transportation; climate; proximity to natural resources; the origins of settlers), and describe how the physical features of the land (e.g., topography, proximity to water, fertility of the soil) and the availability of goods and services (e.g., mills, churches, roads, proximity to sacred sites) can facilitate settlement and enhance community life"},{"code":"A3.4","title":"","text":"describe some of the major challenges facing communities in Canada during this period, including at least one First Nation, Métis, or Inuit community (e.g., challenges relating to the climate; isolation in rural settlements; competition for resources; European diseases among First Nations; colonial wars and other conflicts; racism; displacement; overfishing of whales)"},{"code":"A3.5","title":"","text":"describe the impact of some different kinds of settlements (e.g., seasonal settlements of some seminomadic First Nations, Métis, and Inuit communities; trading posts; resource towns; large-scale farms; large towns or developing cities) on the natural environment and on any existing settlements"},{"code":"A3.6","title":"","text":"describe some key aspects of life in selected First Nations, Métis, and settler communities in Canada during this period, including the roles of men, women, and children (e.g., with reference to diet; how food was obtained; clothing; housing; recreation; education; the division of labour between men, women, and children)"},{"code":"A3.7","title":"","text":"identify a few key treaties relevant to Indigenous people in their region during this period, including wampum belts exchanged (e.g., Two Row Wampum), and explain how some of these agreements affected various peoples and communities in that region and beyond (e.g., with reference to the Treaty of Fort Stanwix, 1784; the Haldimand Proclamation, 1784; the Jay Treaty, 1794; the Treaty of Greenville, 1795; the Selkirk Treaty, 1817; the Huron Tract Treaty, 1827; the Saugeen Treaty, 1836; the Mississaugas of New Credit Land Cession Agreements; the Manitoulin Island Treaties, 1836; the Robinson-Superior and Robinson-Huron Treaties, 1850)"},{"code":"A3.8","title":"","text":"describe how some different communities in Canada related to each other during this period, with a focus on whether the relationships were characterized by conflict or cooperation (e.g., cooperation between First Nations and settler communities with respect to the sharing of medicines and technologies; intermarriage between First Nations women and European men; cooperative efforts to establish farms and villages; conflicts as settlers impinged on First Nations lands and Métis communities; conflicts between various religious or cultural groups)"}]}]},{"code":"B","title":"People and Environments: Living and Working in Ontario","why":"Students learn about the about the physical regions, municipal regions, First Nations communities, and/or Métis regions of Ontario. They will also explore the relationship between the natural environment, land use, and employment opportunities, and how different uses of land and resources affect the environment. Students continue to develop their spatial skills, as they learn to intrepret the data and information found in graphs, globes, and maps. They use mapping programs to create print and digital maps to help them determine the relationship between the environment and land use.","overall":[{"code":"B1","title":"Application: Land Use and the Environment","text":"demonstrate an understanding of some key aspects of the interrelationship between the natural environment, land use, employment opportunities, and the development of municipal regions, First Nations communities, and/or Métis regions in Ontario (FOCUS ON: Interrelationships; Patterns and Trends)","specific":[{"code":"B1.1","title":"","text":"describe some major connections between features of the natural environment of a region and the type of land use and/or the type of community that is established in that region (e.g., ports on lakes or major rivers; farming on flat land with fertile soil; resource towns in areas with ore, trees, or other natural resources)"},{"code":"B1.2","title":"","text":"describe some major connections between features of the natural environment and the type of employment that is available in a region, with reference to two or more municipal regions, including First Nations communities and/or Métis regions, in Ontario (e.g., in the District Municipality of Muskoka, which is known for its lakes, beaches, and many islands, some of the employment opportunities are seasonal jobs in the recreation industry; Dryden and its surrounding area is heavily forested, so there are a number of employment opportunities in the pulp and paper industry; the natural attraction of Niagara Falls led to the development of the area around it as a tourist centre, so the region offers many jobs in tourist and service industries; Bkejwanong Territory, also known as Walpole Island First Nation, is known for its biodiversity and some residents support their families through activities such as hunting, fishing, and trapping)"},{"code":"B1.3","title":"","text":"identify and describe some of the main patterns in population distribution and land use in two or more municipal regions in Ontario, including First Nations communities and/or Métis regions, using mapping and globe skills (e.g., read city maps to extract information on how much land is used for residential, transportation, and recreational purposes; read digital provincial land-use and/or agricultural maps to identify population patterns in agricultural areas; create a thematic map to show how land used for commercial purposes often exists in specific pockets within areas with large populations)"}]},{"code":"B2","title":"Inquiry: The Impact of Land and Resource Use","text":"use the social studies inquiry process to investigate some of the environmental effects of different types of land and/or resource use in two or more Ontario municipal regions, First Nations communities, and/or Métis regions, as well as some of the measures taken to reduce the negative impact of that use (FOCUS ON: Cause and Consequence; Perspective)","specific":[{"code":"B2.1","title":"","text":"formulate questions to guide investigations into some of the short- and/or long-term effects on the environment of different types of land and/or resource use in two or more municipal regions of Ontario, including First Nations communities and/or Métis regions (e.g., the impact of mining, forestry, agriculture, suburban land development, First Nation[s] and Métis involvement in land-use planning) and measures taken to reduce the negative impact of that use"},{"code":"B2.2","title":"","text":"gather and organize a variety of data and information on the environmental effects of different land and/or resource use and measures taken to reduce the negative impact of that use (e.g., photographs, oral histories, resource books, magazines, online articles; information from regional conservation authorities or provincial and national park websites; information from municipalities on recycling; an interview with a First Nation, Métis, or Inuit individual or group with Indigenous ecological knowledge about a region and their observations on changes in that region; information from a website sharing Indigenous knowledges and ways of knowing)"},{"code":"B2.3","title":"","text":"analyse and construct print and digital maps, including thematic maps, as part of their investigations into the environmental impact of land and/or resource use in different municipal regions, including First Nations communities and/or Métis regions (e.g., use maps and atlases to locate information about the spatial boundaries of municipal areas / First Nation communities / Métis regions and the different land uses within them; use an interactive atlas to identify natural resources in your local area)"},{"code":"B2.4","title":"","text":"interpret and analyse information and data relevant to their investigations, using a variety of tools (e.g., use a graphic organizer to help them determine the environmental impact of an aggregate mine; plot trends in forest cover of a municipal region on a line or bar graph and compare it to a graph showing land-use trends for the same municipal region)"},{"code":"B2.5","title":"","text":"evaluate evidence and draw conclusions about some of the short- and long-term effects on the environment of different types of land use in municipal regions of Ontario, including First Nations communities and/or Métis regions, and about key measures to reduce the negative impact of that use"},{"code":"B2.6","title":"","text":"communicate the results of their inquiries, using appropriate vocabulary (e.g., municipality, county, reserve, traditional territory, stewardship, restoration, population, pollution, deforestation, rehabilitation, public transportation, ecological footprint, natural resources, Indigenous ecological knowledge [IEK]) and formats (e.g., a plan of action to address a local land-use issue; a cooperatively produced book of photos showing the environmental impact of a mine; with proper permission, a sketchnote of a story told by an individual with community connections and expertise, such as a local Elder, Métis Senator, Knowledge Keeper, Knowledge Holder, or Traditional Teacher, about their community’s or nation’s relationship with the land; a report on the benefits of forestry in provincial parks; song lyrics, a rap, or a poem about the effects of industrial pollution on a local waterway; an informational poster on what individuals can do to reduce their ecological footprint)"}]},{"code":"B3","title":"Understanding Context: Regions and Land Use in Ontario","text":"describe major landform regions and types of land use in Ontario and some of the ways in which land use in various Ontario municipalities, including First Nations communities and/or Métis regions, addresses human needs and wants, including the need for jobs (FOCUS ON: Significance)","specific":[{"code":"B3.1","title":"","text":"demonstrate an understanding that Ontario is divided into different municipal or regional entities (i.e., cities, towns, townships, villages, counties, First Nations communities, Métis regions), and that local governments within these entities provide specific services and regulate development according to local needs (e.g., elected municipal governments deal with local issues and needs; First Nations have an elected chief and council and/or hereditary chiefs; the Métis Nation of Ontario has elected councillors from the Provisional Council [PCMNO], which represents the community and regional interests of Métis citizens; different municipalities have different laws or policies relating to land development)"},{"code":"B3.2","title":"","text":"demonstrate an understanding that political maps, both print and digital, use different typographical styles to indicate different types of entities (e.g., boldface capitals for a country [CANADA], capitals for a province [ONTARIO], and lowercase for a city [Sudbury])"},{"code":"B3.3","title":"","text":"identify the major landform regions in Ontario (e.g., the Canadian Shield, the Great Lakes–St. Lawrence Lowlands, the Hudson Bay Lowlands), and describe the major characteristics that make each distinct"},{"code":"B3.4","title":"","text":"identify and describe the main types of employment that are available in two or more municipal regions in Ontario, including First Nations communities and/or Métis regions (e.g., jobs dependent on natural resources; jobs in manufacturing, tourism and recreation, the service sector, education, the arts, traditional and/or political government; jobs in conservation, stewardship, and/or land restoration)"},{"code":"B3.5","title":"","text":"describe major types of land use (e.g., for agriculture, industry, commerce, housing, recreation, transportation, conservation) and how they address human needs and wants (e.g., agricultural lands provide us with a variety of foods for local consumption and export; lakes provide traditional foods like fish and wild rice; the forest offers plant medicines; land use for recreation enables people to enjoy the outdoors and to participate in or watch sports and other activities; residential areas have different types of buildings to meet people’s housing needs; conservation lands protect ecosystems and habitat for organisms so that biodiversity is preserved for future generations; untouched wetlands help ensure clean water and a healthy habitat)"},{"code":"B3.6","title":"","text":"compare some aspects of land use in two or more municipalities, including First Nations communities and/or Métis regions (e.g., the number and size of roads; the size and location of commercial areas; the location and types of housing; the proximity of residential and commercial/industrial areas; the size and number of parks and other recreational spaces; space for waste disposal; the amount of agricultural land in the area; the amount of open space)"},{"code":"B3.7","title":"","text":"construct print and/or digital maps that show some different land uses, landform regions, and/or municipalities in Ontario, including First Nations communities and/or Métis regions, using appropriate elements of a map, including standard units of measurement (e.g., use an online atlas or mapping program to create a map showing the major cities in Ontario, with a scale in kilometres; create a map showing the location of major landform regions in the province; create a map showing traditional territory and existing First Nations communities; create a map showing the Métis regions in Ontario)"}]}]}]},"g4":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-sshg","sourceLang":"en","strands":[{"code":"A","title":"Heritage and Identity: Early Societies to 1500 CE ","why":"Students develop the skills to study the past as they learn about different societies that existed prior to the year 1500, including First Nations and Inuit societies. They investigate the role that the environment had on daily life in a variety of early societies and make comparisons to present-day Canada, building on what was learned in earlier grades.","overall":[{"code":"A1","title":"Application: Past and Present Societies","text":"compare key aspects of life in a few early societies (to 1500), including at least one First Nation and one Inuit society, each from a different region and era and representing a different culture, and describe some key similarities and differences between these early societies and present-day Canadian society (FOCUS ON: Continuity and Change; Perspective)","specific":[{"code":"A1.1","title":"","text":"compare social organization (e.g., social classes, general political structure, inherited privilege, the status of women) in a few early societies, including at least one First Nation and one Inuit society (e.g., a slave-owning and a feudal society; a matrilineal First Nation and a society in medieval Asia)"},{"code":"A1.2","title":"","text":"compare aspects of the daily lives of different groups within a few early societies, including at least one First Nation and one Inuit society (e.g., the work, family life, education, food, dress, and/or housing of a slave and a senator in ancient Rome; women of different castes in medieval India; a serf and lord in feudal England; a man and a woman in medieval China or in early Mohawk society; a merchant and noble in Renaissance Italy), and explain how differences were related to the social organization of that society (e.g., the caste system in India; the matrilineal organization of Haudenosaunee society; classes in imperial Rome or in feudal societies in Europe or Asia; the emergence of a wealthy merchant class in Renaissance Italy)"},{"code":"A1.3","title":"","text":"describe some of the ways in which their daily life differs from the lives of young people from different backgrounds (e.g., wealthy, poor, slave, urban, rural) in a few early societies, including at least one First Nation and one Inuit society (e.g., with reference to family life, education, leisure time and recreation, responsibilities, work)"},{"code":"A1.4","title":"","text":"compare a few early societies, including at least one First Nation and one Inuit society, in terms of their relationship with the environment (e.g., with reference to seasonal rhythms, use of land and resources, differences between urban and rural communities, religious and spiritual practices/beliefs with respect to the environment), and describe some key similarities and differences in environmental practices between these societies and present-day Canada"}]},{"code":"A2","title":"Inquiry: Ways of Life and Relationships with the Environment","text":"use the social studies inquiry process to investigate ways of life and relationships with the environment in a few early societies (to 1500), including at least one First Nation and one Inuit society, with an emphasis on aspects of the interrelationship between the environment and life in those societies (FOCUS ON: Interrelationships)","specific":[{"code":"A2.1","title":"","text":"formulate questions to guide investigations into ways of life and relationships with the environment in a few early societies, including at least one First Nation and one Inuit society, with an emphasis on aspects of the interrelationship between the environment and life in those societies (e.g., connections between the local environment and settlement, art, medicine, religion, spirituality, types of work; the impact on the environment of agriculture or the development of towns, cities, settlements, communities, and/or villages)"},{"code":"A2.2","title":"","text":"gather and organize information on ways of life and relationships with the environment in a few early societies, including at least one First Nation and one Inuit society, using a variety of primary and secondary sources in both print and electronic formats (e.g., images depicting the daily life of different social classes; religious or spiritual stories that provide evidence of a society’s view of the environment; agricultural artefacts; traditional stories, creation stories, legends, and/or oral history shared by Elders, community members, and/or knowledge keepers; virtual field trips to museums and to First Nations cultural centres to view artefacts and images)"},{"code":"A2.3","title":"","text":"analyse and construct print and/or digital maps, including thematic maps, as part of their investigations into interrelationships between the environment and life in a few early societies, including at least one First Nation and one Inuit society (e.g., analyse thematic and/or physical maps showing rivers, vegetation, volcanoes, soil types; create a thematic map showing traditional trade routes of the Cree, Algonquin, or Haudenosaunee; analyse a climate map to determine the climatic challenges facing early settlements; construct soil and vegetation maps to determine the connection between soil type and agricultural activity; analyse maps to determine the proximity of early settlements to water; construct a map showing the location of some traditional First Nations and/or Inuit territories; use a decolonial map or atlas to determine the Indigenous names of the places they are investigating)"},{"code":"A2.4","title":"","text":"interpret and analyse information relevant to their investigations, using a variety of tools (e.g., use a graphic organizer to help them determine the relationship between soil type, availability of water, and agricultural activity; analyse the content of paintings on the Internet or at a local gallery for information on a society’s religious practices; analyse artefacts found in a museum or on a website for information on a society’s daily life and relationship with the environment; use a Venn diagram or a T-chart to help them compare historic hunting customs, including giving thanks to animals, between an early First Nation and an early Inuit society; analyse petroglyphs and rock formations for information on sacred sites and their location)"},{"code":"A2.5","title":"","text":"evaluate evidence and draw conclusions about ways of life and relationships with the environment in a few early societies, including at least one First Nation and one Inuit society, with an emphasis on aspects of the interrelationship between the environment and life in those societies"},{"code":"A2.6","title":"","text":"communicate the results of their inquiries, using appropriate vocabulary (e.g., peasant, serf, merchant, noble, Elder, clan mother, faith keeper, knowledge keeper, Inuk shaman, medicine man, healer, healer’s helper, feudalism, god/goddess, privilege, hierarchy, culture, civilization, rural, urban, resources/gifts) and formats (e.g., an annotated map showing how a society situated on a flood plain was affected by and responded to its environment; an interactive map that highlights traditional territories of some early Indigenous societies in what would become North America, along with key natural features of the environment; an oral presentation on the impact of medieval cities on the environment; a stop-animation video on the lives of children in a society that followed seasonal migration routes or lived in different locations during different seasons; a chart and presentation comparing farming techniques of different societies)"}]},{"code":"A3","title":"Understanding Context: Characteristics of Early Societies","text":"demonstrate an understanding of key aspects of a few early societies (to 1500), including at least one First Nation and one Inuit society, each from a different region and era and representing a different culture, with reference to their political and social organization, daily life, and relationships with the environment and with each other (FOCUS ON: Significance)","specific":[{"code":"A3.1","title":"","text":"identify the location of some early societies, including at least one First Nation and one Inuit society, on a globe or on print, digital, and/or interactive maps, and demonstrate the ability to extract information on early societies’ relationship with the environment from thematic maps (e.g., climate, physical, topographical, vegetation maps)"},{"code":"A3.2","title":"","text":"demonstrate the ability to extract information on daily life in a few early societies, including at least one First Nation and one Inuit society, from visual evidence (e.g., art works such as paintings, sculptures, carvings, masks, mosaics, hide paintings, beadwork, quillwork, soapstone carvings; clothing; ceremonial dress; regalia; petroglyphs; monuments; rock/earth mounds; artefacts such as tools, household utensils, pottery, religious articles, weapons)"},{"code":"A3.3","title":"","text":"describe significant aspects of daily life in a few early societies, including at least one First Nation and one Inuit society (e.g., with reference to food, housing, clothing, education, recreation, spiritual/religious life, family life, transportation, ceremonies, ways of giving thanks and acknowledgement)"},{"code":"A3.4","title":"","text":"describe significant physical features and natural processes and events in a few early societies, including at least one First Nation and one Inuit society (e.g., physical features: rivers, flood plains, mountains, volcanoes, barren lands, tundra, ocean shore, fertile soil; natural processes: seasonal changes in climate, animal migration, erosion; natural events: earthquakes, floods, volcanic eruptions) and how they affected these societies, with a focus on the societies’ sustainability and food production (e.g., how flooding of rivers in ancient Egypt, India, and China enriched agricultural land, making it possible to sustain large populations; how the thin topsoil of Central America, Mesopotamia, and Easter Island limited population growth; how volcanoes threatened the survival of communities in ancient Greece and parts of the Roman Empire; how fluctuations in temperature led early Inuit societies to develop techniques like igunaq [meat fermentation] to prevent food spoilage, Cree societies to develop sphagnum moss bags to prolong meat freshness, or Anishinaabe societies to develop techniques to smoke fish)"},{"code":"A3.5","title":"","text":"describe the importance of the environment for a few early societies, including at least one First Nation and one Inuit society, with a particular focus on how the local environment affected the ways in which people met their physical needs (e.g., food, housing, clothing)"},{"code":"A3.6","title":"","text":"identify and describe some of the major scientific and technological developments in the ancient and medieval world, including some from at least one First Nation and one Inuit society (e.g., calendars; the printing press; developments in agriculture, architecture, medicine, transportation, weaponry, navigation)"},{"code":"A3.7","title":"","text":"describe how a few early societies, including at least one First Nation and one Inuit society, were governed (e.g., early democracy in Greece or Haudenosaunee society; city states on the Swahili Coast; emperors in China; the roles of nobles, priests, and the military in Aztec society, of kings, nobles, and knights in medieval France, or of chiefs in the Haida nation)"},{"code":"A3.8","title":"","text":"describe the social organization of a few different types of early societies, including at least one First Nation and one Inuit society (e.g., a slave-owning society, a feudal society, an agrarian society), and the role and status of some significant social and work-related groups in these societies (e.g., women, men, children, slaves, peasants, nobles, monarchs, warriors, knights, priests/priestesses, druids, shamans, imams, monks, nuns, merchants, artisans, apprentices, scribes, midwives, healers)"},{"code":"A3.9","title":"","text":"describe some key reasons why different groups in a few early societies, including at least one First Nation and one Inuit society, cooperated or came into conflict at different times (e.g., to explore; to expand territory; to make decisions, govern, and administer; to promote trade; to wage war or make peace; to acquire wealth, power, and control; to rebel; to spread religious beliefs and/or enforce the power of particular religious institutions; to protect spiritual beliefs, ceremonies and other cultural practices, and traditional lands)"},{"code":"A3.10","title":"","text":"describe some attempts within a few early societies, including at least one First Nation and one Inuit society, to deal with conflict and to establish greater cooperation (e.g., democratic developments in ancient Greece; establishment of religious rights in medieval Islam; matrilineal structures among some First Nations; the Magna Carta; guilds; intermarriage between royal houses; treaties and alliances; the Great Law of Peace; the resolution of conflict with drumming, dancing, poetry, and/or humour among Inuit; the role of lacrosse games; the use of marriage and the ceremonial sharing of food and skins to symbolize alliances and the building of relationships in Inuit societies)"}]}]},{"code":"B","title":"People and Environments: Political and Physical Regions of Canada","why":"Students learn about the provinces and territories that make up Canada as well as the various physical regions, such as landform, vegetation and climate regions. They also conduct an inquiry into balancing human needs/wants and activities with environmental stewardship. They begin to acknowledge and understand the interrelationship between human activity and the environment in Canada. Students also continue to develop their mapping skills and use spatial technologies as they investigate human interactions with the environment.","overall":[{"code":"B1","title":"Application: Industrial Development and the Environment","text":"assess some key ways in which industrial development and the natural environment affect each other in two or more political and/or physical regions of Canada (FOCUS ON: Cause and Consequence; Interrelationships)","specific":[{"code":"B1.1","title":"","text":"analyse some of the general ways in which the natural environment of regions in Canada has affected the development of industry (e.g., how the characteristics of the Canadian Shield made possible the development of mining and smelting, forestry, fresh water fisheries, pulp and paper; how the characteristics of the Maritime provinces made possible the development of fisheries, coal mining, agriculture, off-shore oil drilling; how the topography and climate of the Prairies make the region suitable for large-scale farming and ranching)"},{"code":"B1.2","title":"","text":"assess aspects of the environmental impact of different industries in two or more physical and/or political regions of Canada (e.g., hydroelectric development in Quebec, the development of the oil sands in northern Alberta, fishing in Atlantic Canada, steel production in Nova Scotia, forestry and fishing in British Columbia, coal-powered electrical plants in Ontario, smelting in northern Ontario, shipping in the Great Lakes–St. Lawrence region)"},{"code":"B1.3","title":"","text":"describe some key actions taken by both industries and citizens to address the need for more sustainable use of land and resources (e.g., controlling industrial tailings; putting solar panels on houses or other buildings; ensuring responsible hunting and fishing practices; consulting with First Nations, Métis, and/or Inuit communities about resource development in their territories), and assess their effectiveness"}]},{"code":"B2","title":"Inquiry: Balancing Human Needs and Environmental Stewardship","text":"use the social studies inquiry process to investigate some issues and challenges associated with balancing human needs/wants and activities with environmental stewardship in one or more of the political and/or physical regions of Canada (FOCUS ON: Perspective)","specific":[{"code":"B2.1","title":"","text":"formulate questions to guide investigations into some of the issues and challenges associated with balancing human needs/wants and activities with environmental stewardship in one or more of the political and/or physical regions of Canada"},{"code":"B2.2","title":"","text":"gather and organize information and data from various sources to investigate issues and challenges associated with balancing human needs/wants and activities with environmental stewardship in one or more of the political and/or physical regions of Canada (e.g., spatial technologies and satellite images showing physical features; print and digital thematic maps showing land use or population; climate graphs for various regions; writer views with peers from different regions using electronic communications; an interview with a First Nation or Inuk Elder or a Métis Senator)"},{"code":"B2.3","title":"","text":"analyse and construct print and/or digital maps, including thematic maps, as part of their investigations into balancing human needs/wants and activities with environmental stewardship in Canada (e.g., analyse population settlement maps; construct natural resource maps, using symbols to represent different resources; construct physical region maps, using shading to represent elevation change)"},{"code":"B2.4","title":"","text":"interpret and analyse information and data related to their investigations, using a variety of tools (e.g., use a graphic organizer to help them determine the interrelationship between a region’s physical features and tourism or recreation; plot population trends in a specific region and compare them to a graph showing industrial development in the same region; use a decision-making chart to determine the best location for a new hydroelectric dam; use a double bar graph to help them determine the effect of an increase in tourism on waste production in a region)"},{"code":"B2.5","title":"","text":"evaluate evidence and draw conclusions about issues and challenges associated with balancing human needs/wants and activities with environmental stewardship in Canada"},{"code":"B2.6","title":"","text":"communicate the results of their inquiries using appropriate vocabulary (e.g., mountains, foothills, prairies, tundra, wetlands, forestry, mining, agriculture, fish farming, tourism, commerce, hydroelectricity, wind farms) and formats (e.g., a poster explaining the chosen location for a hydroelectric project; a cooperatively produced big book of photos from a field study or from the Internet about how companies are responding to their role as environmental stewards; a brochure outlining the steps an industry is taking to help protect the local area; a song, rap, or poem from the perspective of an animal that is losing its habitat because of a new housing development)"}]},{"code":"B3","title":"Understanding Context: Regions in Canada","text":"identify Canada’s political and physical regions, and describe their main characteristics and some significant activities that take place in them (FOCUS ON: Significance; Patterns and Trends)","specific":[{"code":"B3.1","title":"","text":"identify various physical regions in Canada (e.g., landform, vegetation, and climatic regions), and describe their location and some of the major ways in which they are distinct from and similar to each other (e.g., the location of the Western Cordillera and the Appalachian regions and the characteristics of the mountains in each region; characteristics of boreal forest and tundra regions; similarities and differences between agricultural areas in the Niagara region, the Annapolis Valley, and the western plains; climatic differences between the rainforest of Vancouver Island and arid areas such as the Canadian badlands)"},{"code":"B3.2","title":"","text":"identify some of the main human activities, including industrial development and recreational activities, in various physical regions of Canada (e.g., large-scale farming in the plains and lowlands; mining and smelting in the Canadian Shield; cattle ranching in grasslands and plains; development of transportation routes along rivers and in valleys and mountain passes; fisheries in oceans, lakes, and rivers; skiing in mountain regions; boating on waterways; hiking on forest or coastal trails)"},{"code":"B3.3","title":"","text":"describe the four main economic sectors (i.e., the primary sector is resource based, the secondary sector is based on manufacturing and processing, the tertiary sector is service based, the quaternary sector is information based), and identify some industries that are commonly associated with each sector (e.g., primary: logging, fishing, mining; secondary: pulp and paper, car manufacturing; tertiary: banks, stores, transportation; quaternary: education, research and development)"},{"code":"B3.4","title":"","text":"identify various types of political regions in Canada (e.g., provinces, territories, municipalities, First Nations bands and reserves), and describe some of their basic similarities and differences (e.g., the powers of a province versus those of a territory)"},{"code":"B3.5","title":"","text":"identify Canada’s provinces and territories and their capital cities, and describe them with reference to their location and some of the peoples who live in them (e.g., New Brunswick, which is in Atlantic Canada, is the only bilingual province and has a large Acadian population; Toronto, which is the capital of Ontario, has a large immigrant population, which includes people from China, South Asia, Europe, and Latin America as well as Indigenous Canadians; the majority of people in Nunavut, in Arctic Canada, are Inuit)"},{"code":"B3.6","title":"","text":"describe significant opportunities and challenges related to quality of life in some of Canada’s political regions (e.g., job opportunities in Alberta’s booming resource sector; loss of jobs in the fishing industry in Newfoundland and Labrador; pollution generated in the Alberta oil sands; challenges related to employment and housing on First Nations reserves; urban sprawl in the Greater Toronto Area)"},{"code":"B3.7","title":"","text":"demonstrate an understanding of cardinal and intermediate directions (i.e., NW, SW, NE, and SE), and use these directions as well as number and letter grids to locate selected political and physical regions of Canada on a variety of print and digital/interactive maps"}]}]}]},"g5":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-sshg","sourceLang":"en","strands":[{"code":"A","title":"Heritage and Identity: Interactions of Indigenous Peoples and Europeans prior to 1713, in What Would Eventually Become Canada","why":"Students learn about the key characteristics of various Indigenous nations and European settler communities prior to 1713. They use different sources of information to investigate various perspectives, interactions and relationships between these communities. Students also increase their understanding of the impact of colonialism and how historical events continue to affect present-day Canada.","overall":[{"code":"A1","title":"Application: The Impact of Interactions","text":"analyse some key short- and long-term consequences of interactions among Indigenous peoples, among Europeans, and between Indigenous and European people prior to 1713 in what would eventually become Canada (FOCUS ON: Cause and Consequence; Continuity and Change)","specific":[{"code":"A1.1","title":"","text":"describe some of the positive and negative consequences of contact between Indigenous peoples and European explorers and settlers in what would eventually become Canada (e.g., with reference to the impact of European diseases on First Nations; the impact of Europeans’ belief that they had the right to claim First Nations territory for themselves; intermarriage between First Nations women and European men and the ethnogenesis of the Métis; competition between different First Nations peoples, Métis, and European settlers for land and resources; alliances among First Nations and between First Nations and European settlers; the introduction of alcohol and European weapons; the contribution of First Nation ideas about democratic community governance systems), and analyse their significance"},{"code":"A1.2","title":"","text":"analyse aspects of contact between Indigenous peoples and European explorers and settlers in what would eventually become Canada to determine ways in which different parties benefited from each other (e.g., early European settlers, slave owners, coureurs de bois, and European fur trade company employees benefited from First Nations and Métis ways of knowing, including their knowledge of land-based subsistence with respect to hunting, medicines, foods, geography, modes of transportation appropriate for local conditions, and established trade routes; the imperial government in France benefited economically from the fur trade and from alliances with First Nations, who aided them in their conflict with the British; First Nations benefited from some of the new materials and technologies introduced by Europeans; First Nations and European peoples benefited from the cultural knowledge, social ties, and language skills of the Métis)"},{"code":"A1.3","title":"","text":"explain some of the ways in which interactions among Indigenous peoples, among European explorers and settlers, and between Indigenous and European people in what would eventually become Canada are connected to issues in present-day Canada (e.g., with reference to land claims; treaty rights and responsibilities; treaty-making processes and people excluded from these processes; environmental stewardship and relationships with the land; resource ownership, extraction, and use)"}]},{"code":"A2","title":"Inquiry: Perspectives on Interactions","text":"use the social studies inquiry process to investigate aspects of the interactions among Indigenous peoples, among Europeans, and between Indigenous and European people prior to 1713 in what would eventually become Canada, from the perspectives of the various groups involved (FOCUS ON: Interrelationships; Perspective)","specific":[{"code":"A2.1","title":"","text":"formulate questions to guide investigations into aspects of the interactions among Indigenous peoples, among Europeans, and between Indigenous and European people in what would eventually become Canada, from the perspectives of various groups involved (e.g., questions about interactions from the perspectives of groups such as European settlers; First Nations, Métis, and/or Inuit men and women; different First Nations, Métis, and/or Inuit communities; coureurs de bois; missionaries; Filles du Roi; warriors; shamans; slaves and slave owners)"},{"code":"A2.2","title":"","text":"gather and organize information on interactions among Indigenous peoples, among Europeans, and between Indigenous and European people in what would eventually become Canada, using a variety of primary and secondary sources that present various perspectives (e.g., treaties; pictographs; petroglyphs; paintings; maps of trade routes; artefacts and their replicas; oral histories; traditional First Nations and European stories relating to similar themes/events; census records; journals written by Jesuits, early explorers, and/or Hudson’s Bay Company employees; accurate and authentic voices from Internet resources and/or books on Canadian history; interviews with Métis Senators, Elders, and/or knowledge keepers)"},{"code":"A2.3","title":"","text":"analyse and construct maps as part of their investigations into interactions among Indigenous peoples, among Europeans, and between Indigenous and European people in what would eventually become Canada (e.g., thematic maps that show how physical features influenced settlement patterns, seasonal migration, trade routes, Indigenous social networks, agricultural practices, or the habitat of animals that sustained the fur trade; historical maps that show First Nations territory prior to and after contact; historical maps that show the emergence of Métis communities)"},{"code":"A2.4","title":"","text":"interpret and analyse information and evidence relevant to their investigations, using a variety of tools (e.g., assess evidence to ensure that its voice is authentic and the information it provides is accurate; use a graphic organizer to help them compare the views of First Nations, Métis, and European settlers on nature and resource use; examine the content of journals or diaries to determine how European settlers and explorers reacted when meeting and working with First Nations peoples; use oral histories to develop their understanding of how one or more First Nations reacted to meeting and guiding settlers; use a comparison chart to help them analyse different perspectives on the fur trade or the establishment of Christian missions)"},{"code":"A2.5","title":"","text":"evaluate evidence and draw conclusions about aspects of the interactions among First Nations, Métis, and Inuit individuals and communities, among Europeans, and between Europeans and First Nations, Métis, and Inuit in what would eventually become Canada during this period, highlighting the perspectives of the different groups involved"},{"code":"A2.6","title":"","text":"communicate the results of their inquiries, using appropriate vocabulary (e.g., Elder, faith keeper, knowledge keeper, Métis Senator, shaman, oral history, wampum belt, pictograph, petroglyph, missionary, colonization, colonialism, settler, xenophobia, racism, prejudice, charter, treaty, coureur de bois, seigneur, Filles du Roi) and formats (e.g., a poem, song, or story that describes the founding of Quebec from two distinct perspectives; an annotated map that shows different perspectives on the growth of the fur trade and resulting settlements; a collection of images they have created themselves, downloaded from websites, and/or taken from printed sources, showing different perspectives on the work of missionaries)"}]},{"code":"A3","title":"Understanding Context: Significant Characteristics and Interactions","text":"describe significant features of and interactions among Indigenous peoples, among Europeans, and between Indigenous and European people prior to 1713 in what would eventually become Canada (FOCUS ON: Significance; Interrelationships)","specific":[{"code":"A3.1","title":"","text":"identify major Indigenous nations that came into contact with European settlers and/or explorers prior to 1713 in what would become Canada (e.g., Great Lakes–St. Lawrence region: some of the many nations were Abenaki, Algonkin, Haudenosaunee, Ojibwe, Ottawa, Potawatomie, Wendat, Weskarini; northern Ontario: some of the nations were Cree and Ojibwe; Atlantic Canada: some of the many nations were Beothuk, Innu, Mi’kmaq, Passamaquoddy, Wolastoqiyik; Arctic: some of the nations were Inuit and Dene), and describe key characteristics of selected nations (e.g., with respect to language; religious/spiritual beliefs and ceremonies; governance structures; food and clothing; roles of men, women, and children; the role and significance of arts and crafts)"},{"code":"A3.2","title":"","text":"describe some significant interactions among First Nations and between First Nations and Inuit before contact with Europeans (e.g., with reference to trade, alliances and treaties, and other instances of cooperation; competition between First Nations for control of waterways)"},{"code":"A3.3","title":"","text":"describe the main motives for Europeans’ exploration of Indigenous lands that were eventually claimed by Canada and for the establishment of permanent European settlements (e.g., with reference to Norse in Newfoundland and Labrador; the voyages of Cabot, Cartier, and/or Hudson; settlements by De Mons and/or Champlain in Quebec; exploration by Étienne Brûlé; motives such as colonization, the desire to gain control over Indigenous lands by imposing sovereignty and land ownership, missionary work to spread Christianity, the desire of European settlers to escape from oppressive European government structures, the exploitation of natural resources, including the establishment and expansion of the fur trade and the fishing industry)"},{"code":"A3.4","title":"","text":"identify significant offices and institutions in New France (e.g., the seigneurial system; the Roman Catholic Church; the king, governor, bishop, and intendant; nuns, priests, missionaries), and describe their importance to settlers in New France"},{"code":"A3.5","title":"","text":"describe significant aspects of the interactions between Indigenous peoples and European explorers and settlers in what would eventually become Canada (e.g., with reference to trade; sharing of beliefs, knowledge, skills, technology; disruption of Indigenous gender norms and roles; intermarriage; military alliances and conflict; the theft of Indigenous lands; spread of diseases; introduction of alcohol; the roles of First Nations, Métis, and Europeans in the fur trade; the impact of the fur trade on Indigenous peoples; loss of First Nations’ access to lands for sustenance and to support ways of life)"},{"code":"A3.6","title":"","text":"describe key factors that led to the ethnogenesis of the Métis people in what would eventually become Canada, with specific attention to the Great Lakes and Mattawa regions (e.g., contact between First Nations and European fur traders and explorers; the need among European traders/explorers in unfamiliar territories for help and guidance from First Nations; intermarriage between traders and First Nations women; gender imbalances in new settlements)"},{"code":"A3.7","title":"","text":"describe some significant differences among Indigenous peoples and between selected Indigenous and European communities in what would eventually become Canada (e.g., with reference to governance and economic organization; spiritual and/or cultural practices; land use/ownership; attitudes towards the environment; the roles of men, women, and children), and identify some of the reasons for these differences (e.g., climate; availability of resources and arable land; the culture, customs, and economic and political system in the mother country; individualistic versus communal world views; familiarity with the land and its resources)"},{"code":"A3.8","title":"","text":"describe some significant effects of European conflicts on Indigenous peoples and on what would eventually become Canada (e.g., conflict between First Nations who were allied to different imperial powers; changes in control of Acadia between the French and British; fur trade rivalries)"}]}]},{"code":"B","title":"People and Environments: The Role of Government and Responsible Citizenship","why":"Students learn about the levels of government and how they work together in Canada. They also learn about the rights and responsibilities of Canadian citizenship. Students investigate a variety of Canadian social and environmental issues from a variety of different perspectives.","overall":[{"code":"B1","title":"Application: Governments and Citizens Working Together","text":"assess responses of governments in Canada, including First Nations, Métis, and Inuit governments, to some significant issues, and develop plans of action for governments and citizens to address social and environmental issues (FOCUS ON: Interrelationships; Cause and Consequence)","specific":[{"code":"B1.1","title":"","text":"assess the effectiveness of actions taken by one or more levels of government, including Indigenous governments, to address an issue of national, provincial/territorial, and/or local significance (e.g., with reference to the Far North Act in addressing concerns of Inuit and First Nations about development in northern Ontario; municipal, provincial, and/or federal programs/policies aimed at reducing child poverty; policies related to the management of the Great Lakes; actions to support nation-to-nation relationships between federal/provincial governments and First Nations, Métis, and Inuit governments; youth advisory councils within the federal and provincial governments; policies/actions intended to address issues related to drinking water in First Nations communities; policies/actions on housing in Inuit communities; the actions taken as a result of the Métis Nation of Ontario Secretariat Act [2015] from the perspective of the Métis and the federal and provincial governments)"},{"code":"B1.2","title":"","text":"create a plan of action to address a social issue of local, provincial/territorial, and/or national significance (e.g., homelessness, child poverty, bullying in schools, availability of physicians in remote communities, lack of employment opportunities within some regions, overcrowded and poorly constructed housing and/or lack of mental health and social services in First Nations and/or Inuit communities, funding for education in First Nations communities, preservation of Indigenous languages, missing and murdered Indigenous women and girls), specifying the actions to be taken by the appropriate government or governments, including Indigenous governments, as well as by citizens"},{"code":"B1.3","title":"","text":"create a plan of action to address an environmental issue of local, provincial/territorial, and/or national significance (e.g., managing waste disposal, regulating industrial practices that damage the environment, ensuring safe drinking water, expanding availability of energy from renewable sources, reducing vehicle emissions, addressing land and water contamination on First Nations territory), specifying the actions to be taken by the appropriate government or governments, including Indigenous governments, as well as by citizens"}]},{"code":"B2","title":"Inquiry: Differing Perspectives on Social and Environmental Issues","text":"use the social studies inquiry process to investigate Canadian social and/or environmental issues from various perspectives, including those of Indigenous peoples as well as of the level (or levels) of government responsible for addressing the issues (FOCUS ON: Perspective)","specific":[{"code":"B2.1","title":"","text":"formulate questions to guide investigations into social and/or environmental issues in Canada from various perspectives, including the perspective of Indigenous peoples and of the level (or levels) of government responsible for addressing the issues (e.g., the perspectives of different levels of government, non-governmental organizations [NGOs], professionals in the field, and people directly affected by an issue such as child poverty on and off reserves, preservation of traditional languages, homelessness, bullying in schools, access to health care, climate change in the Arctic, waste disposal, or deforestation)"},{"code":"B2.2","title":"","text":"gather and organize a variety of information and data that present various perspectives about Canadian social and/or environmental issues, including the perspectives of Indigenous peoples and of the level (or levels) of government responsible for addressing the issues (e.g., with respect to the issue of climate change, gather data on sources of carbon dioxide emissions affecting Canada, photographic evidence of melting polar ice and its impact on Inuit and on Arctic wildlife, information on the positions and/or actions of various NGOs working on climate change, projections from corporations on the costs of addressing greenhouse gas emissions, information on the impact of climate change on the natural world from oral history and interviews with Elders, knowledge keepers, and Métis Senators, editorials and articles from Indigenous media outlets on the impact of climate change, and/or information on the positions of the federal, provincial, and/or territorial governments)"},{"code":"B2.3","title":"","text":"analyse and construct maps in various formats, including digital formats, as part of their investigations into social and/or environmental issues (e.g., a thematic map showing the extent of the areas affected by climate change or how air pollution generated in one jurisdiction affects another; a demographic map showing levels of poverty or homelessness in different provinces; a thematic map showing the location of potential resource-extraction sites in relation to treaty territories, historic Métis settlements, and sacred sites)"},{"code":"B2.4","title":"","text":"interpret and analyse information and data relevant to their investigations, using a variety of tools (e.g., use an idea web to help them determine connections between the way in which a group is affected by climate change and its perspective on the issue; extract information from a line or bar graph to determine variations in homelessness in several municipalities; use a double bar graph to help them determine the effectiveness of recycling and waste-diversion programs)"},{"code":"B2.5","title":"","text":"evaluate evidence and draw conclusions about social and/or environmental issues, outlining the strengths and weaknesses of different perspectives on the issues, including the perspectives of Indigenous peoples and of the level (or levels) of government responsible for addressing the issues"},{"code":"B2.6","title":"","text":"communicate the results of their inquiries, using appropriate vocabulary (e.g., government, local, municipal, provincial/territorial, federal, chief, band council, municipal council, Parliament, member of Parliament [MP], member of provincial parliament [MPP], non-governmental organization, stakeholder) and formats (e.g., a report to present to their local MP, MPP, or city/town councillor; a photo essay on the impact of the issue; a brochure or informational poster that presents the strongest points in the position of various stakeholders; a song, rap, or poem promoting the most convincing arguments on the issue; a map to accompany an oral presentation; a role play that other students can participate in to present differing perspectives)"}]},{"code":"B3","title":"Understanding Context: Roles and Responsibilities of Government and Citizens","text":"demonstrate an understanding of the roles and key responsibilities of citizens and of the different levels of government in Canada, including First Nations, Métis, and Inuit governments (FOCUS ON: Significance)","specific":[{"code":"B3.1","title":"","text":"describe the major rights and responsibilities associated with citizenship in Canada (e.g., rights: equal protection under the law, freedom of speech, freedom of religion, the right to vote; responsibilities: to respect the rights of others, to participate in the electoral process and political decision making, to improve their communities)"},{"code":"B3.2","title":"","text":"describe the jurisdiction of different levels of government in Canada, as well as of some other elected bodies (i.e., federal, provincial, territorial, and municipal governments; band councils; school boards), and some of the services provided by each (e.g., health services, education, policing, defence, social assistance, garbage collection, water services, public transit, libraries)"},{"code":"B3.3","title":"","text":"describe some First Nations, Métis, and Inuit governance structures that currently exist in Canada (e.g., with reference to the Métis Nation of Ontario, Inuit Tapiriit Kanatami, the Chiefs of Ontario, the Nishnawbe Aski Nation, the Union of Ontario Indians, the Haudenosaunee Confederacy)"},{"code":"B3.4","title":"","text":"describe the shared responsibility of various levels of government for providing some services and for dealing with selected social and environmental issues (e.g., services/issues related to transportation, health care, the environment, and/or crime and policing)"},{"code":"B3.5","title":"","text":"describe different processes that governments can use to solicit input from the public (e.g., elections, town hall meetings, public hearings, band council meetings, Métis general assemblies or community council meetings, commissions of inquiry, Supreme Court challenges, processes for granting easements, referendums, nation-to-nation discussions with First Nations and/or Inuit governments), and explain why it is important for all levels of government to provide opportunities for public consultation"},{"code":"B3.6","title":"","text":"demonstrate a basic understanding of what is meant by the federal and provincial governments’ having a duty to consult and accommodate First Nations, Métis, and Inuit communities, and describe some circumstances in which this constitutional right for Indigenous peoples might apply (e.g., when considering proposals to run pipelines through traditional territory or mining development projects that would affect First Nations communities; when developing agreements about the extraction of natural resources on treaty land)"},{"code":"B3.7","title":"","text":"describe key actions taken by governments, including Indigenous governments, to solve some significant national, provincial/territorial, and/or local issues (e.g., federal policies relating to the effects of climate change in the Arctic or the issue of sovereignty in Canadian waters; provincial policies around child mental health issues; municipal recycling and waste diversion programs; government action to relocate elk from the town of Banff, Alberta; existing laws that affect traditional Indigenous harvesting, hunting, and fishing rights; First Nations, Métis, and Inuit community projects and strategies to preserve Indigenous languages)"},{"code":"B3.8","title":"","text":"explain why different groups may have different perspectives on specific social and environmental issues (e.g., why oil industry representatives, farmers, environmentalists, and the Alberta government might differ on development of the oil sands; why the federal government and First Nations band councils might have different perspectives on housing problems on reserves"},{"code":"B3.9","title":"","text":"describe some different ways in which citizens can take action to address social and environmental issues (e.g., by determining the position of their local candidates on various issues and supporting/voting for the one whose position they agree with; through the court system; by organizing petitions or boycotts; by volunteering with organizations that work on specific issues; by writing to their elected representatives or to the media; by creating or participating in art projects that bring attention to an issue)"}]}]}]},"g6":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-sshg","sourceLang":"en","strands":[{"code":"A","title":"Heritage and Identity: Communities in Canada, Past and Present","why":"Students learn about and explore the experiences and perspectives of diverse communities in historical and contemporary Canada. In addition, students learn about significant developments and events that had a direct impact on those communities. Students examine how the diverse communities have contributed to the development of identities in Canada.","overall":[{"code":"A1","title":"Application: Diversity, Inclusiveness, and Canadian Identities","text":"assess contributions to Canadian identities made by various groups and communities, including First Nations, Métis, and Inuit communities, and by various features of Canadian communities and regions (FOCUS ON: Cause and Consequence; Patterns and Trends)","specific":[{"code":"A1.1","title":"","text":"explain how various features, including built, physical, and social features of communities, can contribute to identities in and images of a territory and/or country (e.g., built features such as memorials, different types of buildings, parks, canals, dams, railroads; physical features such as climate, landscape, vegetation, wildlife; social aspects such as cultural traditions, religious celebrations, economic bases; geographic, political, and/or socioeconomic boundaries between communities), and assess the contribution of some of these features to images of and identities in Canada (e.g., with reference to resource-based communities such as mining or logging towns or fishing outports; the Canadian winter; landscapes such as mountains, prairies, sea coasts, tundra; wildlife such as moose, elk, beaver, bison, cod; the variety of populations with heritages from around the world in neighbourhoods in some of Canada’s largest cities)"},{"code":"A1.2","title":"","text":"analyse some of the contributions that various First Nations, Métis, and Inuit communities and individuals have made to Canada (e.g., with reference to artists such as wood, bone, and soapstone carvers, painters and printmakers, bead workers, and/or the Indigenous Group of Seven; Inuit understanding of life and travel in the Arctic; the democratic ideas/practices of the Haudenosaunee; guidance/aid provided by First Nations, Métis, and Inuit people to European fur traders and explorers; modes of transportation such as canoes and kayaks; Indigenous knowledge of plants and medicines; technologies used for fishing, aquaculture, and agriculture)"},{"code":"A1.3","title":"","text":"analyse some of the contributions that various settler/newcomer groups have made to Canadian identities (e.g., the contributions of French and English communities to the development of Canada as a bilingual country, of the British to the Canadian parliamentary system, of Chinese labourers to the construction of the transcontinental railway, of Irish and Italian workers to the development of canal systems on the Great Lakes, of various communities to Canada’s multicultural identity)"},{"code":"A1.4","title":"","text":"explain how various groups and communities, including First Nations, Métis, and Inuit communities, have contributed to the goal of inclusiveness in Canada (e.g., with reference to the efforts of women’s rights, civil rights, Indigenous, or labour organizations, or of advocacy organizations for immigrants, disabled people, or various religious or ethnic groups; the Métis idea of and belief in respectful blending), and assess the extent to which Canada has achieved the goal of being an inclusive society (e.g., with reference to the policy of multiculturalism, the Canadian Charter of Rights and Freedoms, the Ontario Human Rights Code, the Ontarians with Disabilities Act, freedom of religion, the recognition of gay marriage, the ratification of the United Nations Declaration on the Rights of Indigenous People)"}]},{"code":"A2","title":"Inquiry: The Perspectives of Diverse Communities","text":"use the social studies inquiry process to investigate different perspectives on the historical and/or contemporary experiences of a few distinct communities, including First Nations, Métis, and/or Inuit communities, in Canada (FOCUS ON: Perspective)","specific":[{"code":"A2.1","title":"","text":"formulate questions to guide investigations into different perspectives on the historical and/or contemporary experiences of a few distinct communities, including First Nations, Métis, and/or Inuit communities, in Canada (e.g., the development of the reserve system from the perspective of First Nations, European settlers, and the federal government; the negotiation and interpretation of Indigenous treaties, from the perspective of Indigenous peoples and the federal government; the forced relocation of Japanese Canadians during World War II from the perspective of Japanese Canadians, the government at the time, and the government that issued an apology to Japanese Canadians; the formation of neighbourhoods of people who have different heritages, from the perspective of the newcomers, their children, the people already in the neighbourhood, the local school, and/or the agencies and governments that provide services to the neighbourhood)"},{"code":"A2.2","title":"","text":"gather and organize information from a variety of primary and secondary sources (e.g., photographs; letters and diaries; oral stories; maps; songs; paintings; newspaper reports; interviews with Elders, knowledge keepers, and/or community members at friendship centres or cultural centres; books written on the experiences of new settlers in a community; books written about a specific community; online databases and archival collections; treaties and wampum belts) that present different perspectives on the historical and/or contemporary experience of a few communities, including First Nations, Métis, and/or Inuit communities, in Canada"},{"code":"A2.3","title":"","text":"analyse and construct print and digital maps as part of their investigations into different perspectives on the historical and/or contemporary experience of communities, including First Nations, Métis, and/or Inuit communities, in Canada (e.g., analyse a flow map showing the relocation of First Nations, Métis, and/or Inuit communities; plot census data on a map to show the locations of different communities; construct a thematic map to show changes over time in the ethnic origin of the people in a community; construct a map that identifies places of significance within selected Indigenous communities; construct a map that shows the historic Métis communities in Ontario; construct an annotated map that explains the use of an Inuksuk [or several Inuksuit] as a navigational tool and the significance of its [or their] placement within Inuit territories)"},{"code":"A2.4","title":"","text":"interpret and analyse information and evidence relevant to their investigations, using a variety of tools (e.g., use a graphic organizer to help them determine differences in perspectives of participants in the Red River Resistance or North-West Resistance; plot census data on a line graph using a computer-based graphing program in order to help them determine changes over time in a specific community; analyse a collection of photographs for evidence about newcomers’ feelings towards their new community and about the feelings of people already living in that community towards the newcomers; examine the content of diaries to determine how people in the past felt about living in their community)"},{"code":"A2.5","title":"","text":"evaluate evidence and draw conclusions about perspectives on the historical and/or contemporary experience of a few distinct communities, including First Nations, Métis, and/or Inuit communities, in Canada"},{"code":"A2.6","title":"","text":"communicate the results of their inquiries, using appropriate vocabulary (e.g., perspective, ethnic group, emigrant, immigrant, entrepreneur, labourer, class, colonization, decolonization, colonialism, racism, classism, xenophobia, displacement, relocation, settler, newcomer) and formats (e.g., a dramatic piece in which different characters voice the perspectives of different groups; a presentation that expresses different perspectives with cultural sensitivity and uses authentic voices; a slideshow that includes photographs and/or paintings that illustrate different perspectives on the same event)"}]},{"code":"A3","title":"Understanding Context: The Development of Communities in Canada","text":"demonstrate an understanding of significant experiences of, and major changes and aspects of life in, various historical and contemporary communities, including First Nations, Métis, and Inuit communities, in Canada (FOCUS ON: Significance; Continuity and Change)","specific":[{"code":"A3.1","title":"","text":"identify the traditional Indigenous and treaty territory or territories on which their community is located (e.g., Orillia is located on the traditional territory of the Ojibwe/Chippewa and Anishinaabe and is within the boundaries set by the Williams Treaties; Sault Ste. Marie is located on the traditional territory of the Métis, Cree, Ojibwe/Chippewa, and Anishinaabe and is within the boundaries set by the Robinson-Huron Treaty; Red Lake is located on the traditional territory of the Métis and the Ojibwe/Chippewa and is within the boundaries set by Treaty 3)"},{"code":"A3.2","title":"","text":"identify the main reasons why different peoples migrated to Canada (e.g., political or religious freedom; political allegiances; perceptions about the availability of land; economic opportunity; family ties; poverty, famine, colonization of or political unrest in their country of origin; forced migration of slaves and “Home Children”)"},{"code":"A3.3","title":"","text":"describe some key economic, political, cultural, and social aspects of life in settler/newcomer communities in Canada (e.g., with reference to land ownership; agricultural practices; work; cultural practices; religious and/or spiritual beliefs/practices; dress and diet; family life and the roles of men, women, and children; social and service clubs), and identify significant ways in which the culture of settlers’ places of origin influenced their ways of life in Canada and, where applicable, had an impact on Indigenous communities"},{"code":"A3.4","title":"","text":"identify various types of communities in Canada and some ways in which they have contributed to the development of the country (e.g., First Nations, Inuit, Métis, French, and/or British; later immigrant groups such as Chinese, Germans, Scandinavians, South Asians, or Caribbean people; religious communities; economic communities such as resource towns; workers and labour organizations; rural and urban communities)"},{"code":"A3.5","title":"","text":"describe significant events or developments in the history of two or more First Nations, Métis, and/or Inuit communities in Canada (e.g., the arrival of European explorers and setters; the fur trade; the colonial/federal government’s banning of Indigenous ceremonies and gatherings; Indigenous treaties; the reserve system; the Indian Act; residential schools; the Gradual Civilization Act; court challenges for recognition of hunting and fishing rights; the creation of Nunavut, Nunavik, and Nunatsiavut; the struggle by Métis and Inuit for recognition in the constitution of their rights and status; loss of language and culture) and how these events affected the communities’ development and/or identities"},{"code":"A3.6","title":"","text":"describe significant events or developments in the history of two or more settler/newcomer communities in Canada (e.g., French Canadians: expulsion of the Acadians, loss of the Battle of the Plains of Abraham; Japanese: forced relocation during World War II, the apology for this action from the federal government in 1988; Black Canadians: the Act against Slavery, 1793; the Underground Railroad; Germans: religious freedom for Mennonite immigrants; the renaming of Berlin, Ontario, to Kitchener during World War I) and how these events affected the communities’ development and/or identities"},{"code":"A3.7","title":"","text":"describe significant events or developments in the history of Jewish communities in Canada, including some of the ways they have contributed to Canada (e.g., events and developments: official recording of the first Jewish settler in New France [1759]; establishment of Canada’s first synagogue, Shearith Israel, in Montreal [1768]; equal rights being given to Jewish people in Lower Canada [Quebec], including being able to hold public office [1832]; founding of Canada’s first national Jewish organization, the Federation of Zionist Societies in Canada [1899]; establishment of Montreal’s Young Men’s Hebrew Association and Young Women’s Hebrew Association [1910]; founding of the Canadian Jewish Congress [1919]; waves of Jewish immigration during the twentieth and twenty-first centuries from Europe, Asia, South America, and North and South Africa, increasing the diversity of Canada’s Jewish community; dedication of the National Holocaust Monument in Ottawa [2017]; Special Envoy on Preserving Holocaust Remembrance and Combatting Antisemitism role created [2020]; contributions: leaders in human rights laws since the 1940s; entrepreneurs in industry and manufacturing), and identify some of the impacts of antisemitism on these communities’ development and/or identities (e.g., restrictions: pre–World War II restrictions on participation in medicine and law; severe restrictions on Jewish immigration during World War II and up to 1947; prohibition of Jewish residences or property purchases in some Canadian neighbourhoods; reactions: building of Toronto’s Mount Sinai Hospital [1923] to serve the Jewish immigrant community and provide space for Jewish doctors who faced discrimination at other hospitals; resistance to antisemitism during the Christie Pits Riot in Toronto [1933]; building of the Jewish Community Centre in Toronto [1953] in response to not being allowed to join many of the existing clubs in the city; security at synagogues and cemeteries)"},{"code":"A3.8","title":"","text":"describe interactions between communities in Canada, including between newcomers and groups that were already in the country (e.g., trade among precontact First Nations; cooperation between First Nations and the French and British in the fur trade; Indigenous treaties; conflict between Catholic and Protestants in Ontario or white and Asian residents in British Columbia; racism directed at Black settlers in Nova Scotia and southern Ontario; responses of local businesses, ranging from the refusal to serve certain groups to providing new products and services to help meet the needs of new communities; interactions between newcomers and settlement agencies or advocacy organizations)"},{"code":"A3.9","title":"","text":"identify key differences, including social, cultural, and/or economic differences, between a few historical and/or contemporary communities, including at least one First Nations, Métis, or Inuit community, in Canada (e.g., differences in gender roles between First Nations and French settlers in early Canada; social and economic differences between upper-class and working-class people in industrializing cities; differences in lifestyle between people in rural areas and those in established towns and cities; differences in the religious background of residents in different communities or at different times; differences between Indigenous peoples and newcomers/settlers with respect to spiritual/cultural beliefs about the relationship with the land)"},{"code":"A3.10","title":"","text":"describe significant changes within their own community in Canada (e.g., within their ethnic or religious community, their local community, or their region)"},{"code":"A3.11","title":"","text":"identify and describe fundamental elements of Canadian identities (e.g., inclusiveness; respect for human rights; respect for diversity; multiculturalism; parliamentary democracy; constitutional monarchy; bilingualism; the recognition of three founding nations; universal health care; recognition of First Nations, Métis, and Inuit as Indigenous peoples and original inhabitants of what is now Canada; the importance of treaties and treaty rights)"}]}]},{"code":"B","title":"People and Environments: Canada's Interactions with the Global Community","why":"Students learn about the global community and Canada’s role in it. They will investigate current social, political, economic and environmental issues to develop their understanding of the importance of international action and cooperation. Students learn about the responses of the Canadian government to the Holocaust and the development of Canada’s responses to acts of hate and human rights violations. Students also will work on their graphing and mapping skills and develop their ability to extract and analyse information from a variety of sources.","overall":[{"code":"B1","title":"Application: Canada and International Cooperation","text":"explain the importance of international cooperation in addressing global issues, and evaluate the effectiveness of selected actions by Canada and Canadian citizens in the international arena (FOCUS ON: Interrelationships; Perspective)","specific":[{"code":"B1.1","title":"","text":"explain why Canada participates in specific international accords and organizations (e.g., the North American Free Trade Agreement [NAFTA]; Asia-Pacific Economic Cooperation [APEC]; the World Health Organization [WHO]; the North Atlantic Treaty Organization [NATO]; the United Nations [UN], including the Declaration on the Rights of Indigenous People and/or the Convention on the Rights of the Child), and assess the influence of some significant accords and/or organizations in which Canada participates"},{"code":"B1.2","title":"","text":"analyse responses of Canadian governments, non-governmental organizations (NGOs), and individual citizens to an economic, environmental, political, and/or social issue of international significance (e.g., how the federal government, different NGOs, business people, and individual consumers have responded to economic globalization; how different levels of government, health care workers, and individual citizens responded to the spread of H1N1 or SARS; how governments, development and human rights NGOs, and individuals, including students in their school, have responded to an issue such as a natural disaster in another region, child labour, child soldiers, climate change, or civil war and refugees)"},{"code":"B1.3","title":"","text":"explain why some environmental issues are of international importance and require the participation of other regions of the world, along with that of Canada, if they are to be effectively addressed (e.g., issues such as global warming, carbon dioxide and sulphur dioxide emissions, ownership and availability of fresh water, deforestation, overfishing, invasive species, habitat protection of migrating species, or disposal of electronic waste)"}]},{"code":"B2","title":"Inquiry: Responses to Global Issues","text":"use the social studies inquiry process to investigate some global issues of political, social, economic, and/or environmental importance, their impact on the global community, and responses to the issues (FOCUS ON: Cause and Consequence)","specific":[{"code":"B2.1","title":"","text":"formulate questions to guide investigations into global issues of political, social, economic, and/or environmental importance (e.g., child labour, dwindling oil supplies, ownership of and access to fresh water, climate change, food shortages, refugees, or natural disasters), their impact on the global community, and responses to the issues"},{"code":"B2.2","title":"","text":"gather and organize information on global issues of political, social, economic, and/or environmental importance, including their impact and responses to them, using a variety of resources and various technologies (e.g., use spatial technologies, satellite images, and/or online image banks as part of their investigation into the diminishing of ocean reef life; gather accounts by Inuit and northern First Nations witnesses to the effects of climate change; find annual precipitation rates for a region to study the relationship between drought and famine; locate data about products that Canadians import from countries that use child labour or other cheap labour; use interactive websites to find data and information about health issues facing specific countries or regions)"},{"code":"B2.3","title":"","text":"analyse and construct different types of maps, both print and digital, as part of their investigations into global issues, their impact, and responses to them (e.g., locate on a digital map or in a print atlas the region affected by a conflict that has given rise to refugee camps; use interactive atlases to track the spread of a disease; use issue-based or demographic maps to examine correlations between quality of life indicators; create a flow map that shows the starting point for some products that enter Canada)"},{"code":"B2.4","title":"","text":"interpret and analyse information and data relevant to their investigations, using a variety of tools (e.g., use an online mapping program to help them determine the relationship between Canadian aid and quality of life; analyse climate graphs to help them determine the effects of declining precipitation in a region or country; use a graphic organizer or a graph constructed on the computer to compare the number of Canadians who gave aid to Haiti after the 2010 earthquake with those who gave aid to Japan after the 2011 earthquake and tsunami)"},{"code":"B2.5","title":"","text":"evaluate evidence and draw conclusions about global issues of political, social, economic, and/or environmental importance, their impact on the global community, and responses to the issues"},{"code":"B2.6","title":"","text":"communicate the results of their inquiries, using appropriate vocabulary (e.g., non-governmental organization, intergovernmental organization, accord, international convention, aid, relief efforts) and formats (e.g., a plan of action for a fundraising project in their school; a report for their school newsletter about why people should buy fair trade products; a song, rap, or poem written from the perspective of a person in a refugee camp or a child labourer; an infographic that shows how much money Canadians contributed in the past year to various global causes; a map that shows the impact of climate change in an agricultural region)"}]},{"code":"B3","title":"Understanding Context: Canada's Global Interactions","text":"describe significant aspects of the involvement of Canada and Canadians in some regions around the world, including the impact of this involvement (FOCUS ON: Significance; Patterns and Trends)","specific":[{"code":"B3.1","title":"","text":"identify some of the major ways in which the Canadian government interacts with other nations of the world (e.g., through trade agreements, military alliances and action, intergovernmental organizations, environmental accords; by providing disaster relief or funds for social and/or economic development)"},{"code":"B3.2","title":"","text":"describe Canada’s participation in different international accords, organizations, and/or programs (e.g., the UN Declaration on the Rights of Indigenous Peoples, the WHO, NATO, the Blue Flag Program, UNICEF, NAFTA)"},{"code":"B3.3","title":"","text":"describe several groups or organizations through which Canada and Canadians are involved in global issues (e.g., NGOs such as Doctors Without Borders, Free the Children, Ryan’s Well, World Wide Fund for Nature; multinational corporations; intergovernmental organizations such as the UN, la Francophonie, the Commonwealth, APEC)"},{"code":"B3.4","title":"","text":"describe the responses of the Canadian government and some NGOs to different disasters and emergencies around the world (e.g., the 2010 earthquake in Haiti; the 2004 tsunami in the Indian Ocean; the AIDS pandemic in sub-Saharan Africa or another health crisis; poverty and drought in the Horn of Africa)"},{"code":"B3.5","title":"","text":"describe the responses of the Canadian government to human rights violations during the Holocaust (e.g., severe restrictions on immigration and the policy of “none is too many”; the turning away of the MS St. Louis; Canada’s policy to vastly restrict the number of Jewish refugees admitted from Europe, as shown by the response to the Evian Conference [1938]) and the impact that global changes in understanding and legislation around human rights since World War II have had on the development of Canada’s responses to acts of hate and human rights violations (e.g., Canada’s participation in the writing of the Universal Declaration of Human Rights [1948]; three sections related to genocide and hate crimes added to the Criminal Code of Canada; Canada’s response to the Vietnamese refugee crisis in the years following the war in Vietnam; the drafting of the Canadian Charter of Rights and Freedoms [1982]; the creation of the Canadian Multiculturalism Act [1988]; amendments to the Indian Act; boycotts of South Africa during apartheid; Canada’s Extradition Act [1999]; Canada’s adoption of the Justice for Victims of Corrupt Foreign Officials Act [2017], the Magnitsky legislation that allows sanctions to be placed on human rights abusers who are foreign nationals; government initiatives in response to the Truth and Reconciliation Commission’s Calls to Action [2015]; the criminalization of Holocaust denial in Bill C-19 [2022]; sending in observers and peacekeepers; responses to humanitarian crises internationally; the decriminalization of homosexuality)"},{"code":"B3.6","title":"","text":"identify some significant political, social, and economic interactions between Canada and other regions of the world, and describe some ways in which they affect these regions (e.g., the stabilization of regions resulting from Canada’s peacekeeping efforts; the development of maquiladoras as a result of trade agreements; change in the status of women as a result of education projects in a developing region)"},{"code":"B3.7","title":"","text":"identify and locate on a map countries and regions with which Canada has a significant interrelationship, and use longitude and latitude to locate cities in these countries/regions (e.g., Washington, D.C., London, Beijing, Tokyo, Mogadishu, Nairobi, Tripoli, Mumbai, Kabul, Port-au-Prince)"},{"code":"B3.8","title":"","text":"identify countries/regions with which Canada has a significant economic relationship (e.g., the relationship with the United States and Mexico through NAFTA; trade relations with China; sources of tourists to Canada and/or destinations of Canadians travelling internationally; Canadian investments overseas; recipients of Canadian aid) and some of the reasons why close relationships developed with these countries/regions and not others (e.g., geographic proximity, stable governments, production of products needed by Canada, markets for Canadian goods and services, types of labour/environmental regulations)"},{"code":"B3.9","title":"","text":"describe significant economic effects on Canada and Canadians of interactions between Canada and other regions of the world (e.g., loss of manufacturing jobs to countries with lower labour costs; the impact of trade agreements and/or disputes; the impact of changing immigration policies; the economic impact of the dominance of American cultural industries)"},{"code":"B3.10","title":"","text":"describe some ways in which Canada’s interactions with other regions of the world have affected the environment (e.g., the impact of Canada’s participation in the African tree-planting campaign of the United Nations Environment Programme; the proliferation of invasive species in the Great Lakes as a result of international trade/transportation; over-farming and loss of production for local markets as a result of Canadians’ desire for cheap cotton, sugar, cocoa, and tea)"}]}]}]}},"hpe":{"g1":{"url":"https://www.dcp.edu.gov.on.ca/fr/curriculum/elementaire-education-physique-sante","sourceLang":"fr","strands":[{"code":"A","title":"Apprentissage socioémotionnel","why":"Cette section du programme-cadre aide les élèves à favoriser: leur état général de santé et de bien-être; leur santé mentale; leur résilience et leur capacité d’apprendre et de s’épanouir. Les élèves acquièrent des habiletés socioémotionnelles qui les aideront à: reconnaître et à gérer leurs émotions; à gérer le stress; à éveiller une motivation et un état d’esprit positif; à bâtir des relations; à approfondir la conscience de soi; à penser de façon critique et créative.","overall":[{"code":"A1","title":"Habiletés socioémotionnelles","text":"mettre en pratique, au mieux de ses capacités, diverses habiletés socioémotionnelles dans l’acquisition de connaissances et d’habiletés liées aux attentes et aux contenus d’apprentissage dans les domaines Vie active, Compétence motrice et Vie saine pour son année d’études.","specific":[{"code":"A1.1","title":"Reconnaissance et gestion des émotions","text":"mettre en pratique des habiletés l’aidant à reconnaître et à gérer ses émotions, dans le cadre de situations d’apprentissage en éducation physique et santé, afin d’améliorer sa capacité à exprimer en français ses propres émotions ainsi qu’à comprendre celles des autres et à les considérer (p. ex., Vie active: expliquer les émotions ressenties quant à la participation à l’activité physique quotidienne [APQ] de groupe; Compétence motrice: reconnaître ses émotions dans l’apprentissage de nouvelles habiletés qui paraissent faciles et d’autres qui paraissent difficiles; Vie saine: reconnaître les émotions qu’on peut ressentir en réaction à des comportements bienveillants ou à des comportements qui pourraient se révéler malveillants)."},{"code":"A1.2","title":"Gestion du stress et adaptation","text":"mettre en pratique des habiletés permettant de reconnaître les sources de stress et de faire face aux difficultés, y compris être capable de demander de l’aide, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de favoriser le développement de la résilience personnelle (p. ex., Vie active: appliquer sa connaissance des mesures de sécurité afin de renforcer son sentiment de sécurité; connaître ses points forts, ses capacités et ses limites pour avoir confiance en soi sur le terrain de jeu; Compétence motrice: essayer de s’exprimer de façon positive en cas d’excitation ou de déception pendant un jeu; Vie saine: expliquer comment obtenir de l’aide au besoin en s’adressant à un adulte de confiance ou en composant le 9-1-1 en cas d’urgence)."},{"code":"A1.3","title":"Motivation positive et persévérance","text":"mettre en pratique des habiletés favorisant le développement d’habitudes de pensée propices à la motivation et à la persévérance, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de susciter l’optimisme et l’espoir (p. ex., Vie active: démontrer sa volonté d’essayer différentes façons de faire de l’activité physique; Compétence motrice: montrer de l’enthousiasme en essayant de nouvelles habiletés, tout en faisant preuve de persévérance; Vie saine: apaiser ses inquiétudes à l’égard de situations préoccupantes, comme la peur de se brûler sur la cuisinière, en mettant en place des mesures de sécurité)."},{"code":"A1.4","title":"Relations saines","text":"mettre en pratique des habiletés l’aidant à nouer des relations, à développer de l’empathie et à communiquer avec les autres en français, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de favoriser les relations saines, le sentiment d’appartenance et le respect de la diversité (p. ex., Vie active: s’adresser aux autres avec respect et leur accorder son attention lors du partage d’équipement; Compétence motrice: communiquer clairement, en ayant recours au contact visuel, au langage corporel et à la parole, s’il y a lieu, lors de l’envoi et de la réception d’objets ou du partage de l’espace de gymnase; Vie saine: écouter activement l’autre personne, porter attention à son langage verbal et non verbal, comme ses expressions faciales et le ton de sa voix, pour lui montrer qu’elle vous tient à cœur)."},{"code":"A1.5","title":"Conscience de soi et sentiment d’identité personnelle","text":"mettre en pratique des habiletés l’aidant à développer sa conscience de soi et sa confiance en soi, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de favoriser le développement d’un sentiment d’identité et d’appartenance au groupe, à l’école ou à la francophonie (p. ex., Vie active: établir des liens avec ses pairs, provenant du plaisir partagé de participer à diverses activités physiques quotidiennes (APQ); Compétence motrice: décrire son niveau de confort corporel en faisant différents mouvements; Vie saine: démontrer la connaissance de soi et de son corps et faire preuve de respect envers soi et son corps, en désignant les parties du corps par les bons termes)."},{"code":"A1.6","title":"Pensée critique et créative","text":"mettre en pratique des habiletés l’aidant à penser de manière critique et créative, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de favoriser l’établissement de liens, l’analyse, l’évaluation, la résolution de problèmes et la prise de décisions (p. ex., Vie active: établir des liens entre l’activité physique et la santé, tant physique que mentale; Compétence motrice: recourir aux habiletés de la pensée créative pour imaginer de nouvelles façons de bouger et de maintenir son équilibre, par exemple se tenir sur trois, quatre ou cinq parties du corps; Vie saine: expliquer les mesures à prendre pour se protéger du soleil, comme porter un chapeau et mettre de la crème solaire)."}]}]},{"code":"B","title":"Vie active","why":"Par la participation active, les élèves acquièrent les fondements pour mener une vie saine et active, tout en découvrant les facteurs qui contribuent au plaisir d’être actif.","overall":[{"code":"B1","title":"Participation active","text":"participer activement et régulièrement à une large gamme d’activités physiques, en cherchant des façons d’inclure ces activités dans son quotidien.","specific":[{"code":"B1.1","title":"Participation active","text":"participer activement à la vaste gamme d’activités physiques proposées (p. ex., jeu de poursuite, activités physiques au gymnase, jeu de parachute) selon sa capacité, tout en adoptant des comportements qui améliorent son état d’esprit et sa capacité à participer (p. ex., se joindre au jeu de plein gré; respecter ses pairs; suivre les directives; attendre son tour). [A1.3 Motivation, 1.5 Identité]"},{"code":"B1.2","title":"Participation active","text":"décrire des facteurs qui contribuent au plaisir d’être active et actif (p. ex., environnement sécuritaire et approprié aux activités, occasion de participer à des activités familiales et culturelles, y compris à des activités francophones ou liées à son héritage culturel, et de prendre part pleinement à tous les aspects d’une activité) au cours de sa participation à une vaste gamme d’activités, individuellement et en petits groupes. [A1.3 Motivation, 1.5 Identité]"},{"code":"B1.3","title":"Participation active","text":"déterminer diverses façons d’être active ou actif à l’école et à la maison tous les jours (p. ex., à l’école: jouer à des jeux actifs pendant la récréation; participer à diverses activités physiques en classe, y compris l’APQ; participer à des activités physiques après l’école; à la maison: participer à des activités à l’extérieur comme jardiner, ratisser ou pelleter de la neige; se promener à pied avec sa famille; jouer dans le parc; faire de la bicyclette sur les sentiers communautaires). [A1.6 Pensée]"}]},{"code":"B2","title":"Condition physique","text":"utiliser des concepts de la condition physique et des pratiques qui font valoir l’importance de l’activité physique pour une vie active et saine.","specific":[{"code":"B2.1","title":"Condition physique","text":"Activité physique quotidienne (APQ): participer à des activités physiques d’intensité modérée à vigoureuse (p. ex., animaux en mouvement, déplacement au rythme de la musique, saut à la corde) selon sa capacité au moins vingt minutes chaque jour, incluant le temps nécessaire à l’échauffement et au retour au calme. [A1.1 Émotions, 1.3 Motivation, 1.5 Identité]"},{"code":"B2.2","title":"Condition physique","text":"expliquer comment l’activité physique aide au maintien de la santé aussi bien physique que mentale. [A1.2 Adaptation]"},{"code":"B2.3","title":"Condition physique","text":"déterminer des signes physiologiques du niveau d’effort au cours de sa participation à des activités physiques (p. ex., essoufflement, rougissement du visage, augmentation de la chaleur corporelle, accélération du pouls, transpiration). [A1.3 Motivation]"}]},{"code":"B3","title":"Sécurité","text":"faire preuve d’un comportement responsable afin d’assurer sa sécurité et la sécurité des autres lors d’activités physiques.","specific":[{"code":"B3.1","title":"Sécurité","text":"mettre en pratique des procédures qui favorisent sa sécurité et celle des autres et qui réduisent le risque de blessures, y compris le risque de commotions cérébrales, pendant l’activité physique (p. ex., coopérer; porter des vêtements appropriés; écouter activement les consignes; maintenir une distance sécuritaire par rapport à ses pairs lors de l’échauffement; se déplacer avec prudence; porter des chaussures de sport bien attachées; respecter les limites du terrain; se servir de son fauteuil roulant comme étant une partie de son corps). [A1.4 Relations]"},{"code":"B3.2","title":"Sécurité","text":"expliquer les mesures à prendre pour se protéger des facteurs environnementaux qui présentent des risques, y compris des risques de commotions cérébrales, (p. ex., la chaleur extrême peut causer de la fatigue; l’exposition prolongée au soleil va provoquer des coups de soleil; le froid et le vent intenses peuvent causer des engelures; les objets au sol peuvent faire trébucher quelqu’un qui ne peut pas voir; la chaussée ou les planchers mouillés peuvent présenter un risque de chutes) pour profiter des activités de plein air en toute sécurité. [A1.5 Identité, 1.6 Pensée]"}]}]},{"code":"C","title":"Compétence motrice","why":"Grâce à l’exploration et à la participation à une variété d’activités, les élèves acquièrent des habiletés et des tactiques pour bouger, tout en augmentant leur confiance dans leurs capacités physiques.","overall":[{"code":"C1","title":"Habiletés motrices et concepts du mouvement","text":"mettre en pratique des habiletés motrices ainsi que des concepts du mouvement pour répondre aux exigences de base d’une variété d’activités physiques.","specific":[{"code":"C1.1","title":"Stabilité","text":"exécuter des exercices d’équilibre statique en utilisant différentes parties du corps à diverses hauteurs (p. ex., bas niveau: se courber vers l’avant en s’équilibrant à l’aide des mains et des pieds; niveau moyen: se tenir debout, se pencher en étendant les bras vers l’avant; niveau élevé: s’étirer en étendant les bras au-dessus de la tête et en écartant les jambes). [A1.3 Motivation, 1.5 Identité]"},{"code":"C1.2","title":"Locomotion","text":"se déplacer et s’arrêter avec contrôle en tenant compte des personnes et de l’équipement qui l’entoure. [A1.2 Adaptation, 1.4 Relations]"},{"code":"C1.3","title":"Locomotion","text":"se déplacer de différentes façons et dans plusieurs directions en utilisant différentes parties du corps (p. ex., marcher à reculons sur une ligne ou sauter par-dessus des lignes en toute sécurité; se déplacer en variant les parties du corps qui touchent le sol; bouger les bras de différentes façons en marchant, en dansant ou en sautillant; faire des pas de géants en se déplaçant de côté). [A1.5 Identité]"},{"code":"C1.4","title":"Manipulation","text":"envoyer des objets de diverses formes et tailles en variant sa position et sa technique et en utilisant différentes parties du corps (p. ex., assis, passer un ballon à un partenaire en le faisant rouler; lancer un sac de fèves dans un cerceau; frapper un ballon avec le pied en direction d’un mur; lancer un poulet en caoutchouc vers une cible; faire passer un ballon entre ses jambes). [A1.5 Identité]"},{"code":"C1.5","title":"Manipulation","text":"recevoir des objets de diverses formes et tailles en variant sa position et sa technique, tout en utilisant différentes parties du corps (p. ex., attraper un ballon à deux mains; arrêter avec le pied ou les mains un ballon qui roule; attraper un sac de fèves qui est lancé au-dessus de sa tête). [A1.1 Émotions, 1.5 Identité]"}]},{"code":"C2","title":"Habiletés tactiques","text":"mettre en pratique des habiletés tactiques dans le but d’améliorer sa participation et sa performance dans une variété d’activités physiques, tout en utilisant ses connaissances des composantes de ces activités.","specific":[{"code":"C2.1","title":"Habiletés tactiques","text":"utiliser ses connaissances des composantes de diverses activités physiques (p. ex., habiletés motrices, règles de base, limites du terrain, franc-jeu et savoir-vivre) dans le cadre de sa participation, individuellement ou en petits groupes, à une large gamme d’activités. [A1.3 Motivation, 1.4 Relations]"},{"code":"C2.2","title":"Habiletés tactiques","text":"mettre en pratique une variété de tactiques de base (p. ex., étendre les bras pour maintenir l’équilibre lorsqu’on est debout sur un pied; modifier sa vitesse, sa direction ou son niveau de hauteur pour éviter de se faire toucher par le chat dans un jeu de poursuite; se rapprocher d’une cible pour l’atteindre) qui permettent d’accroître ses possibilités de réussite lors de sa participation à diverses activités physiques. [A1.5 Identité, 1.6 Pensée]"}]}]},{"code":"D","title":"Vie saine","why":"Les élèves apprennent à résoudre des problèmes, à prendre des décisions et à se fixer des objectifs qui sont directement liés à leur propre état de santé et de bien-être. Les élèves développent ces habiletés en explorant les concepts suivants liés à la santé: l’alimentation saine; la sécurité personnelle et la prévention des blessures; la consommation de substances, la dépendance et les comportements associés; le développement de la personne et la santé sexuelle; la littératie en santé mentale. Ces sujets ont été choisis parce qu’ils sont fondamentalement liés à la vie quotidienne des élèves et leur offrent des occasions d’apprendre comment faire des choix sains et sécuritaires aujourd’hui et pour l’avenir. Développement de la personne et la santé sexuelle Lorsque les enfants savent comment prendre soin de leur corps et nommer les parties du corps, ils peuvent: mieux se comprendre et se respecter soi-même et leur corps; communiquer clairement ou demander de l’aide en cas de maladie, de blessure ou de mauvais traitements.","overall":[{"code":"D1","title":"Attitudes et comportements","text":"expliquer les facteurs qui favorisent le développement sain de la personne.","specific":[{"code":"D1.1","title":"Alimentation saine","text":"expliquer l’importance de manger pour avoir un corps et un esprit en santé (p. ex., la nourriture fournit de l’énergie et des nutriments pour la croissance saine des dents, de la peau, des os et des muscles, ainsi que pour le développement sain du cerveau). [A1.6 Pensée]"},{"code":"D1.2","title":"Sécurité personnelle et prévention des blessures","text":"décrire des pratiques et des connaissances essentielles qui contribuent à sa sécurité (p. ex., communiquer correctement son nom et son numéro de téléphone; connaître le nom et les coordonnées d’une personne à contacter en cas d’urgence; connaître et respecter la procédure de routine sécuritaire en quittant l’école; savoir comment obtenir de l’aide des personnes et des organismes dans sa communauté: enseignante ou enseignant, agente ou agent de police, intervenante ou intervenant des services à la jeunesse, ou adulte de confiance; savoir comment contacter le service d’urgence 9-1-1). [A1.2 Adaptation]"},{"code":"D1.3","title":"Développement de la personne et santé sexuelle","text":"reconnaître les parties du corps humain, y compris les parties génitales (p. ex., pénis, testicules, vagin, vulve), en utilisant la terminologie appropriée et un langage qui promeut une image positive du corps. [A1.5 Identité]"},{"code":"D1.4","title":"Développement de la personne et santé sexuelle","text":"décrire les fonctions des cinq sens (p. ex., vue: les yeux transmettent au cerveau de l’information sur le monde, en nous donnant la possibilité de voir des couleurs, des formes et des mouvements; toucher: les récepteurs situés dans la peau nous donnent des informations sur ce qu’on touche – chaud, froid, mouillé, sec, dur ou doux; ouïe: les oreilles sont sensibles aux vibrations de l’air et envoient des signaux au cerveau qui nous permettent d’entendre des sons qui sont forts et faibles, aigus ou graves; odorat et goût: la langue est couverte de papilles sur toute sa surface et le nez a des poils et des terminaisons nerveuses qui envoient des messages au cerveau sur les saveurs et les odeurs)."},{"code":"D1.5","title":"Littératie en santé mentale","text":"expliquer l’importance de la santé mentale en tant que partie intégrale de la santé globale, tout en réfléchissant aux moyens de prendre soin de son corps et de son esprit et de les apprécier. [A1.2 Adaptation, 1.4 Relations, 1.5 Identité]"}]},{"code":"D2","title":"Choix sains","text":"utiliser ses connaissances en matière de santé et ses habiletés socioémotionnelles afin de prendre des décisions éclairées et de poser des gestes qui contribuent à sa santé et à son bien-être.","specific":[{"code":"D2.1","title":"Alimentation saine","text":"décrire comment le Guide alimentaire canadien peut l’aider à développer des habitudes alimentaires saines. [A1.6 Pensée]"},{"code":"D2.2","title":"Alimentation saine","text":"expliquer l’importance de reconnaître les signes de la faim (p.ex., bruits dans l’estomac, fatigue, manque d’énergie, irritabilité), de la soif (p.ex., bouche sèche, mal de tête, fatigue) et du rassasiement (p. ex., ventre plein, regain d’énergie) pour adopter des habitudes alimentaires saines. [A1.5 Identité]"},{"code":"D2.3","title":"Sécurité personnelle et prévention des blessures","text":"déterminer des situations dans ses relations avec les autres qui font preuve de bienveillance (p.ex., écouter avec respect, offrir de l’aide, respecter les limites de chacune et de chacun) et des comportements qui peuvent nuire à la santé physique et mentale (p.ex., ignorer, exclure, intimider ou manipuler les autres; exploiter sexuellement ou maltraiter quelqu’un, y compris les attouchements inappropriés; exercer de la violence verbale, psychologique ou physique sur quelqu’un) ainsi que les sentiments associés à ces comportements et les façons de se comporter convenablement qui démontre sa compréhension de l’importance du consentement. [A1.1 Émotions, 1.2 Adaptation, 1.4 Relations]"},{"code":"D2.4","title":"Sécurité personnelle et prévention des blessures","text":"décrire des pratiques préventives afin d’assurer sa sécurité à l’école (p. ex., connaître ses allergies et en informer son enseignante ou enseignant; jouer dans les endroits surveillés; suivre les routines établies pour le transport aller-retour à l’école). [A1.3 Motivation, 1.5 Identité, 1.6 Pensée]"},{"code":"D2.5","title":"Développement de la personne et santé sexuelle","text":"expliquer comment de bonnes habitudes d’hygiène personnelle (p. ex., se laver les mains avec du savon; éternuer dans sa manche de chandail; se brosser les dents et passer la soie dentaire; utiliser des mouchoirs et les jeter de façon appropriée; ne pas partager sa brosse à cheveux) sont essentielles pour sa santé et pour éviter la transmission de maladies."}]},{"code":"D3","title":"Rapprochements entre santé et bien-être","text":"établir des rapprochements entre la santé et le bien-être pour expliquer l’incidence des choix faits, des comportements adoptés et des facteurs environnementaux sur sa santé, son bien-être et sur la santé et le bien-être des autres.","specific":[{"code":"D3.1","title":"Sécurité personnelle et prévention des blessures","text":"déterminer des sources de danger à domicile (p. ex., piscine, produits ménagers, jouets, chandelles, meubles dangereux, foyer, escaliers, fenêtres, prises électriques), dans sa communauté, en ligne et à l’extérieur (p. ex., milieu aquatique, route, terrain de jeu, centre communautaire, patinoire) ainsi que les risques qui y sont associés (p. ex., noyade, empoisonnement, étouffement, brûlure, chute, électrocution, accident de la route, fracture, sites Web qui ne conviennent pas à l’âge de l’utilisateur) et les précautions à prendre pour assurer sa sécurité, réduire les risques et éviter des blessures pour soi-même et les autres. [A1.5 Identité, 1.6 Pensée]"},{"code":"D3.2","title":"Consommation de substances, dépendance et comportements associés","text":"décrire des habitudes et des comportements qui peuvent nuire à la santé (p. ex., passer trop de temps devant un écran ou à jouer à des jeux vidéo, fumer, vapoter) ainsi que ceux qui encouragent les personnes de son entourage à adopter des options plus saines. [A1.2 Adaptation, 1.5 Identité, 1.6 Pensée]"},{"code":"D3.3","title":"Littératie en santé mentale","text":"expliquer de quelles façons les pensées, les émotions et les actions d’une personne peuvent avoir une incidence sur sa santé mentale. [A1.6 Pensée]"}]}]}]},"g2":{"url":"https://www.dcp.edu.gov.on.ca/fr/curriculum/elementaire-education-physique-sante","sourceLang":"fr","strands":[{"code":"A","title":"Apprentissage socioémotionnel","why":"Cette section du programme-cadre aide les élèves à favoriser: leur état général de santé et de bien-être; leur santé mentale; leur résilience et leur capacité d’apprendre et de s’épanouir. Les élèves acquièrent des habiletés socioémotionnelles qui les aideront à: reconnaître et à gérer leurs émotions; à gérer le stress; à éveiller une motivation et un état d’esprit positif; à bâtir des relations; à approfondir la conscience de soi; à penser de façon critique et créative.","overall":[{"code":"A1","title":"Habiletés socioémotionnelles","text":"mettre en pratique, au mieux de ses capacités, diverses habiletés socioémotionnelles dans l’acquisition de connaissances et d’habiletés liées aux attentes et aux contenus d’apprentissage dans les domaines Vie active, Compétence motrice et Vie saine pour son année d’études.","specific":[{"code":"A1.1","title":"Reconnaissance et gestion des émotions","text":"mettre en pratique des habiletés l’aidant à reconnaître et à gérer ses émotions, dans le cadre de situations d’apprentissage en éducation physique et santé, afin d’améliorer sa capacité à exprimer en français ses propres émotions ainsi qu’à comprendre celles des autres et à les considérer (p. ex., Vie active: si un sentiment de tristesse ou de colère est ressenti avant le début d’une activité physique, prendre le temps de respirer profondément et de se recentrer pour se préparer à participer pleinement à l’activité; Compétence motrice: reconnaître ses émotions et celles de son ou sa partenaire au moment de se lancer, en équipe, des objets de diverses tailles, et y réagir en adaptant sa façon de lancer; Vie saine: démontrer sa compréhension des sentiments d’une personne qui s’oppose à une activité qu’elle n’aime pas et refuse d’y participer)."},{"code":"A1.2","title":"Gestion du stress et adaptation","text":"mettre en pratique des habiletés permettant de reconnaître les sources de stress et de faire face aux difficultés, y compris être capable de demander de l’aide, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de favoriser le développement de la résilience personnelle (p. ex., Vie active: s’habiller convenablement pour les activités en plein air, reconnaissant qu’en faisant ainsi je me sens plus à l’aise; Compétence motrice: décrire l’importance du dialogue intérieur positif pour pouvoir gérer plusieurs variables lors de la participation à une activité, comme le lancer d’objets de diverses tailles, à différents niveaux et avec des parties du corps différentes; Vie saine: en réponse aux taquineries, essayer diverses solutions, comme quitter les lieux, dire à la personne d’arrêter, lui dire comment on se sent ou demander de l’aide)."},{"code":"A1.3","title":"Motivation positive et persévérance","text":"mettre en pratique des habiletés favorisant le développement d’habitudes de pensée propices à la motivation positive et à la persévérance, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de susciter l’optimisme et l’espoir (p. ex., Vie active: comprendre le lien entre un bon sommeil et le sentiment d’être prête ou prêt à participer à une activité; Compétence motrice: faire preuve de persévérance dans la recherche de façons d’utiliser différentes parties du corps et de maintenir son équilibre; Vie saine: se réjouir de tout ce que son corps peut faire)."},{"code":"A1.4","title":"Relations saines","text":"mettre en pratique des habiletés l’aidant à nouer des relations, à développer de l’empathie et à communiquer avec les autres en français, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de favoriser les relations saines, le sentiment d’appartenance et le respect de la diversité (p. ex., Vie active: montrer comment les élèves peuvent s’entraider lorsqu’ils utilisent l’équipement; Compétence motrice: dans un jeu de miroir, imiter les gestes de son ou sa partenaire en suivant les signes non verbaux ainsi que le langage corporel qui indiquent le prochain geste; Vie saine: employer un langage positif en s’adressant à ses camarades, afin de tisser des relations saines et d’inciter les autres à faire de même)."},{"code":"A1.5","title":"Conscience de soi et sentiment d’identité personnelle","text":"mettre en pratique des habiletés l’aidant à développer sa conscience de soi et sa confiance en soi, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de favoriser le développement d’un sentiment d’identité et d’appartenance au groupe, à l’école ou à la francophonie (p. ex., Vie active: observer les réponses physiques et mentales de son corps lors de la participation à une activité physique; Compétence motrice: après avoir fait un saut, penser aux gestes utiles posés pour retomber en position stable, et réfléchir à comment améliorer sa technique; Vie saine: dresser une liste de contrôle pour suivre son hygiène dentaire quotidienne et expliquer comment la liste peut aider à prendre conscience des bonnes habitudes d’hygiène qui contribuent à la santé en général)."},{"code":"A1.6","title":"Pensée critique et créative","text":"mettre en pratique des habiletés l’aidant à penser de manière critique et créative, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de favoriser l’établissement de liens, l’analyse, l’évaluation, la résolution de problèmes et la prise de décisions (p. ex., Vie active: expliquer comment la pratique d’une activité physique d’intensité modérée à vigoureuse est liée à une meilleure condition physique et à une meilleure santé; décrire ce dont on a besoin pour jouer confortablement et en toute sécurité à l’extérieur, quel que soit le temps; Compétence motrice: essayer diverses pièces d’équipement, expliquer les différences entre chacune et indiquer ses préférences; Vie saine: expliquer comment prévenir les incidents en énumérant les produits ménagers qui pourraient être dangereux)."}]}]},{"code":"B","title":"Vie active","why":"Par la participation active, les élèves acquièrent les fondements pour mener une vie saine et active, tout en découvrant les facteurs qui contribuent au plaisir d’être actif.","overall":[{"code":"B1","title":"Participation active","text":"participer activement et régulièrement à une large gamme d’activités physiques, en cherchant des façons d’inclure ces activités dans son quotidien.","specific":[{"code":"B1.1","title":"Participation active","text":"participer activement à la vaste gamme d’activités physiques proposées (p. ex., activités individuelles, activités de groupe, jeux coopératifs, mouvements rythmiques au son d’une musique) selon sa capacité, tout en adoptant des comportements qui améliorent son état d’esprit et sa capacité à participer (p. ex., s’impliquer dans le déroulement de l’activité; faire preuve d’habiletés interpersonnelles comme coopérer, communiquer de façon respectueuse, solliciter de l’aide ou offrir son aide). [A1.3 Motivation, 1.5 Identité]"},{"code":"B1.2","title":"Participation active","text":"décrire des facteurs qui contribuent au plaisir d’être active ou actif (p. ex., choix d’activités variées, environnement sécuritaire, occasion de participer à des activités en lien avec sa culture, y compris à des activités francophones; pleine participation à tous les aspects d’une activité, accès à un espace de jeu sécuritaire à l’extérieur) au cours de sa participation à une large gamme d’activités, individuellement ou en petits groupes. [A1.1 Émotions, 1.5 Identité]"},{"code":"B1.3","title":"Participation active","text":"déterminer des raisons qui motivent une personne à participer quotidiennement à des activités physiques (p. ex., divertissement, nouvelles amitiés, intérêt personnel, désir d’imiter une personne que l’on tient en haute estime, apprentissage par le jeu, maintien de la santé physique et mentale, plaisir d’être à l’extérieur et de découvrir la nature, suivre des enseignements culturels). [A1.1 Émotions, 1.2 Adaptation, 1.6 Pensée]"}]},{"code":"B2","title":"Condition physique","text":"utiliser des concepts de la condition physique et des pratiques qui font valoir l’importance de l’activité physique pour une vie active et saine.","specific":[{"code":"B2.1","title":"Condition physique","text":"Activité physique quotidienne (APQ): participer à des activités physiques d’intensité modérée à vigoureuse (p. ex., jeu de poursuite, jeu de cerceaux, course à relais, saut à la corde, utiliser son fauteuil roulant pour contourner des obstacles au gymnase) selon sa capacité au moins vingt minutes chaque jour, incluant le temps nécessaire à l’échauffement et au retour au calme. [A1.3 Motivation, 1.5 Identité]"},{"code":"B2.2","title":"Condition physique","text":"décrire des activités physiques qui améliorent l’état des poumons et du cœur (p. ex., courir; monter des escaliers; sauter à la corde; se déplacer rapidement en fauteuil roulant; faire un circuit d’entraînement pour le conditionnement physique; faire d’autres activités de motricité globale)."},{"code":"B2.3","title":"Condition physique","text":"évaluer son niveau d’effort au cours de sa participation à des activités physiques à l’aide de méthodes simples (p. ex., placer la main sur sa poitrine afin de prendre conscience d’un battement de cœur élevé, mesurer son rythme cardiaque, faire le test de la parole [vérifier si on peut parler lors de l’activité physique]) ainsi que des facteurs qui influent sur son niveau de performance (p. ex., qualité de l’air, degré d’humidité, température ambiante, état de santé, sommeil, émotions, intérêt, condition physique, stress). [A1.3 Motivation, 1.5 Identité]"},{"code":"B2.4","title":"Condition physique","text":"établir des objectifs personnels et collectifs réalistes d’activité physique (p. ex., faire une promenade avec des membres de sa famille au moins trois fois par semaine; accomplir en équipe un nombre déterminé de sauts en ciseaux; jouer à un jeu de poursuite pendant toute la durée de la récréation). [A1.3 Motivation, 1.6 Pensée]"}]},{"code":"B3","title":"Sécurité","text":"faire preuve d’un comportement responsable afin d’assurer sa sécurité et la sécurité des autres lors d’activités physiques.","specific":[{"code":"B3.1","title":"Sécurité","text":"mettre en pratique des procédures qui favorisent sa sécurité et celle des autres et qui réduisent le risque de blessures, y compris le risque de commotions cérébrales, pendant l’activité physique (p. ex., faire l’échauffement et le retour au calme de façon appropriée; éviter le contact physique; pousser un fauteuil roulant avec prudence, porter un casque protecteur bien ajusté pour faire de la bicyclette, du ski ou jouer au hockey; partager l’équipement à tour de rôle; éviter l’encombrement lors de l’utilisation de l’équipement dans la salle de classe et sur le terrain de jeu). [A1.4 Relations, 1.5 Identité]"},{"code":"B3.2","title":"Sécurité","text":"déterminer des façons de prévenir des risques d’accident pour soi et pour les autres au cours de sa participation à des activités physiques (p. ex., éviter de courir sur le gazon mouillé; aviser l’enseignante ou l’enseignant lorsqu’un équipement est défectueux), y compris pour celles et ceux qui ont une condition médicale (p. ex., réduire son niveau d’effort lorsqu’on souffre d’asthme; avoir à sa portée un auto-injecteur d’épinéphrine lorsqu’on a des allergies qui pourraient entraîner une réaction anaphylactique; apporter une collation lorsqu’on est sujet à l’hypoglycémie). [A1.4 Relations, 1.6 Pensée]"}]}]},{"code":"C","title":"Compétence motrice","why":"Grâce à l’exploration et à la participation à une variété d’activités, les élèves acquièrent des habiletés et des tactiques pour bouger, tout en augmentant leur confiance dans leurs capacités physiques.","overall":[{"code":"C1","title":"Habiletés motrices et concepts du mouvement","text":"mettre en pratique des habiletés motrices ainsi que des concepts du mouvement pour répondre aux exigences de base d’une variété d’activités physiques.","specific":[{"code":"C1.1","title":"Stabilité","text":"exécuter des exercices d’équilibre statique avec ou sans équipement (p. ex., maintenir une position d’équilibre au plancher, sur une ligne et sur un banc; maintenir des objets en équilibre sur différentes parties du corps) en utilisant différentes parties du corps à des hauteurs variées et en adoptant différentes positions (p. ex., bas niveau: redressement en V; niveau moyen: position de l’avion avec un point d’appui; niveau élevé: étirer les bras au-dessus de la tête en tenant un ballon et lever un pied). [A1.3 Motivation]"},{"code":"C1.2","title":"Stabilité","text":"sauter ou sautiller sur une ou deux jambes en maintenant l’équilibre quand on prend son élan et en faisant preuve de contrôle quand on termine le saut. [A1.3 Motivation]"},{"code":"C1.3","title":"Locomotion","text":"se déplacer de différentes façons en variant sa vitesse, son trajet et sa direction, avec ou sans équipement (p. ex., courir, sautiller ou rouler en fauteuil roulant en suivant une ligne courbe autour d’objets ou d’un arbre; sauter rapidement d’un côté d’une ligne à l’autre; se déplacer à vitesses variées au rythme d’un tambour; courir en contournant des cônes; communiquer des consignes à un élève ayant une déficience visuelle). [A1.3 Motivation, 1.4 Relations]"},{"code":"C1.4","title":"Manipulation","text":"envoyer des objets de diverses formes et tailles en variant sa position et sa technique tout en utilisant différentes parties du corps (p. ex., frapper un ballon avec le pied vers une cible; lancer un ballon à deux mains ou avec la main dominante en position assise; frapper un ballon de plage avec le genou, la main, la poitrine ou le pied en direction du mur; faire glisser un disque volant vers une cible). [A1.1 Émotions, 1.2 Adaptation, 1.5 Identité]"},{"code":"C1.5","title":"Manipulation","text":"recevoir des objets de diverses formes et tailles en variant sa position et sa technique tout en utilisant différentes parties du corps (p. ex., attraper un ballon à deux mains; arrêter avec le pied un ballon qui roule; attraper un sac de fèves qui a été lancé au-dessus de sa tête). [A1.1 Émotions, 1.5 Identité, 1.6 Pensée]"}]},{"code":"C2","title":"Habiletés tactiques","text":"mettre en pratique des habiletés tactiques dans le but d’améliorer sa participation et sa performance dans une variété d’activités physiques, tout en utilisant ses connaissances des composantes de ces activités.","specific":[{"code":"C2.1","title":"Habiletés tactiques","text":"utiliser ses connaissances des composantes (p. ex., habiletés motrices, règles de base, limites du terrain, franc-jeu et savoir-vivre) d’une activité physique, dans le cadre de sa participation, individuellement ou en petits groupes, à diverses activités. [A1.3 Motivation, 1.4 Relations]"},{"code":"C2.2","title":"Habiletés tactiques","text":"mettre en pratique une variété de tactiques de base (p. ex., courir ou faire rouler son fauteuil roulant dans un espace vide afin d’éviter de se faire toucher dans un jeu de poursuite; choisir un objet qu’on pense pouvoir lancer ou attraper facilement; choisir de l’équipement spécialisé, comme une balle avec une clochette à l’intérieur, afin de fournir un indice auditif aux élèves ayant une déficience visuelle) qui permettent d’accroître ses possibilités de réussite lors de sa participation à diverses activités physiques. [A1.6 Pensée]"}]}]},{"code":"D","title":"Vie saine","why":"Les élèves apprennent à résoudre des problèmes, à prendre des décisions et à se fixer des objectifs qui sont directement liés à leur propre état de santé et de bien-être. Les élèves développent ces habiletés en explorant les concepts suivants liés à la santé: l’alimentation saine; la sécurité personnelle et la prévention des blessures; la consommation de substances, la dépendance et les comportements associés; le développement de la personne et la santé sexuelle; la littératie en santé mentale. Ces sujets ont été choisis parce qu’ils sont fondamentalement liés à la vie quotidienne des élèves et leur offrent des occasions d’apprendre comment faire des choix sains et sécuritaires aujourd’hui et pour l’avenir. Développement de la personne et la santé sexuelle Lorsque les enfants comprennent que leur corps va changer (p. ex., perdre les dents de lait), ils peuvent: se préparer et s’adapter aux changements; apprécier le fonctionnement de leur corps, ce que leur corps peut faire et en avoir une perception positive","overall":[{"code":"D1","title":"Attitudes et comportements","text":"expliquer les facteurs qui favorisent le développement sain de la personne.","specific":[{"code":"D1.1","title":"Sécurité personnelle et prévention des blessures","text":"déterminer les pratiques sécuritaires à suivre à la maison (p. ex., prendre des précautions avant de répondre au téléphone et à la porte; utiliser des appareils électriques avec prudence; préparer un plan d’évacuation en cas d’incendie; prendre des précautions relatives à la préparation et à l’entreposage de la nourriture, se laver les mains), en plein air (p. ex., appliquer de la crème solaire, au besoin; respecter les règles de sécurité dans l’autobus scolaire et lors des déplacements à bicyclette ou à pied; porter la ceinture de sécurité en auto; avoir sur soi ses médicaments pour les allergies; faire attention aux plantes et aux animaux lors d’une sortie en plein air; reconnaître les voies et les symboles d’accessibilité; ne jamais jouer sur ou près des voies ferrées) et en ligne (p. ex., ne pas partager d’information personnelle; vérifier la validité de l’information trouvée en ligne auprès d’un adulte). [A1.5 Identité, 1.6 Pensée]"},{"code":"D1.2","title":"Sécurité personnelle et prévention des blessures","text":"déterminer des allergies ou des sensibilités alimentaires communes (p. ex., aux noix, aux fruits de mer, aux poissons, aux produits laitiers, aux œufs) et les réactions qu’elles peuvent provoquer (p. ex., toux, rougeurs, nausée, urticaire, enflure, asphyxie, douleurs abdominales, vomissements, coma, mort)."},{"code":"D1.3","title":"Consommation de substances, dépendance et comportements associés","text":"décrire les différences entre les médicaments sur ordonnance et les médicaments sans ordonnance en donnant des exemples et en y associant des pratiques qui permettent d’en faire un bon usage. [A1.6 Pensée]"},{"code":"D1.4","title":"Développement de la personne et santé sexuelle","text":"reconnaître des changements ainsi que des facteurs physiques, mentaux, sociaux et environnementaux qui contribuent à un développement sain pendant les divers stades de développement de la personne (p. ex., nourrisson, enfant, adolescent, adulte, aîné). [A1.5 Identité]"},{"code":"D1.5","title":"Développement de la personne et santé sexuelle","text":"démontrer sa compréhension du fonctionnement de son corps et son appréciation de ses divers aspects, ainsi que les façons de s’assurer de continuer à l’apprécier à mesure qu’il change et qu’il se développe. [A1.1 Émotions, 1.3 Motivation, 1.5 Identité]"},{"code":"D1.6","title":"Littératie en santé mentale","text":"décrire de quelles façons le corps et le cerveau réagissent à des situations difficiles ou inconfortables (p. ex., fatigue, sensation d’être facilement accablé, confusion, surstimulation; envie de pleurer ou émotions très intenses; mal de tête ou sensation de chaleur), et que faire pour atténuer ces sentiments. [A1.1 Émotions, 1.4 Relations, 1.5 Identité]"}]},{"code":"D2","title":"Choix sains","text":"utiliser ses connaissances en matière de santé et ses habiletés socioémotionnelles afin de prendre des décisions éclairées et de poser des gestes qui contribuent à sa santé et à son bien-être.","specific":[{"code":"D2.1","title":"Alimentation saine","text":"utiliser le Guide alimentaire canadien pour déterminer les aliments et les boissons qui favorisent les habitudes alimentaires saines."},{"code":"D2.2","title":"Alimentation saine","text":"décrire des choix alimentaires sains à inclure dans les collations et les repas en tenant compte de divers facteurs qui sont ou non sous son contrôle (p. ex., nourriture offerte à la maison; nourriture offerte au restaurant; besoin d’énergie à différentes périodes de la journée; allergies alimentaires; restrictions alimentaires à la suite d’un problème de santé tel que le diabète; facteurs culturels; facteurs concernant la préparation et l’entreposage des aliments). [A1.3 Motivation, 1.6 Pensée]"},{"code":"D2.3","title":"Sécurité personnelle et prévention des blessures","text":"décrire l’importance du consentement ainsi que les attitudes à adopter pour soutenir sa capacité de s’affirmer et de défendre les autres (p. ex., parler avec confiance; se tenir droit avec les épaules alignées; établir des limites que ce soit en personne ou en ligne; dire “non”; respecter les autres lorsqu’ils disent non et encourager ses pairs à en faire de même; dénoncer des comportements inappropriés, comme des attouchements sur son corps ou celui des autres) afin de favoriser la sécurité et le bien-être. [A1.1 Émotions, 1.2 Adaptation, 1.4 Relations]"},{"code":"D2.4","title":"Développement de la personne et santé sexuelle","text":"expliquer l’importance d’une bonne hygiène dentaire en cernant des façons de prendre soin de ses dents et de sa bouche (p. ex., se brosser les dents correctement et au moins deux fois par jour; passer la soie dentaire chaque jour; aller à la clinique dentaire régulièrement). [A1.3 Motivation, 1.5 Identité]"},{"code":"D2.5","title":"Littératie en santé mentale","text":"expliquer pourquoi il est important de comprendre ses sentiments et de pouvoir les nommer (p. ex., contente, décontracté, calme, mal à l’aise, triste, fâchée, frustré, apeuré, inquiet) afin d’être capable de savoir quand demander de l’aide. [A1.2 Adaptation, 1.3 Motivation, 1.5 Identité]"}]},{"code":"D3","title":"Rapprochements entre santé et bien-être","text":"établir des rapprochements entre la santé et le bien-être pour expliquer l’incidence des choix faits, des comportements adoptés et des facteurs environnementaux sur sa santé, son bien-être et sur la santé et le bien-être des autres.","specific":[{"code":"D3.1","title":"Sécurité personnelle et prévention des blessures","text":"décrire des façons d’interagir positivement avec les membres de sa famille, les aidantes et aidants et les autres (p. ex., coopérer; faire preuve de respect; communiquer ouvertement, gérer sa colère; tenir compte de ce que les autres disent, de leurs expressions faciales et de leur langage corporel) et des comportements qui peuvent blesser une personne (p. ex., violence physique: coup, croc-en-jambe, bousculade; abus verbal, y compris en ligne et en personne: insulte, moquerie, taquinerie; rejet social: ignorer délibérément quelqu’un ou les sentiments que cette personne exprime). [A1.1 Émotions, 1.2 Adaptation, 1.4 Relations]"},{"code":"D3.2","title":"Consommation de substances, dépendance et comportements associés","text":"décrire des options qui peuvent remplacer ou compléter la consommation de médicaments pour améliorer sa santé physique et mentale et prévenir ou traiter certains problèmes de santé (p. ex., un rhume peut se guérir avec du repos; l’air frais et l’exercice peuvent soulager un mal de tête; une bonne alimentation telle que recommandée par le Guide alimentaire canadien ou par le Guide alimentaire canadien Premières Nations, Inuit et Métis; des pratiques de guérison autochtones). [A1.2 Adaptation, 1.6 Pensée]"}]}]}]},"g3":{"url":"https://www.dcp.edu.gov.on.ca/fr/curriculum/elementaire-education-physique-sante","sourceLang":"fr","strands":[{"code":"A","title":"Apprentissage socioémotionnel","why":"Cette section du programme-cadre aide les élèves à favoriser: leur état général de santé et de bien-être; leur santé mentale; leur résilience et leur capacité d’apprendre et de s’épanouir. Les élèves acquièrent des habiletés socioémotionnelles qui les aideront à: reconnaître et à gérer leurs émotions; à gérer le stress; à éveiller une motivation et un état d’esprit positif; à bâtir des relations; à approfondir la conscience de soi; à penser de façon critique et créative.","overall":[{"code":"A1","title":"Habiletés socioémotionnelles","text":"mettre en pratique, au mieux de ses capacités, diverses habiletés socioémotionnelles dans l’acquisition de connaissances et d’habiletés liées aux attentes et aux contenus d’apprentissage dans les domaines Vie active, Compétence motrice et Vie saine pour son année d’études.","specific":[{"code":"A1.1","title":"Reconnaissance et gestion des émotions","text":"mettre en pratique des habiletés l’aidant à reconnaître et à gérer ses émotions, dans le cadre de situations d’apprentissage en éducation physique et santé, afin d’améliorer sa capacité à exprimer en français ses propres émotions ainsi qu’à comprendre celles des autres et à les considérer (p. ex., Vie active: en aidant une autre personne à suivre les règles de sécurité, prendre conscience de ses émotions et s’exprimer de façon positive; Compétence motrice: dans l’apprentissage de nouvelles activités, porter attention à soi-même et aux autres en faisant preuve d’esprit sportif; Vie saine: observer les émotions exprimées par les personnages dans des scènes de violence fictive et décrire les différences éventuelles avec les émotions qui pourraient être ressenties lorsque la violence est réelle)."},{"code":"A1.2","title":"Gestion du stress et adaptation","text":"mettre en pratique des habiletés permettant de reconnaître les sources de stress et de faire face aux difficultés, y compris être capable de demander de l’aide, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de favoriser le développement de la résilience personnelle (p. ex., Vie active: expliquer comment l’activité physique peut aider à calmer les émotions très vives; Compétence motrice: respirer profondément pour se recentrer lorsqu’une nouvelle activité est source de stress ou de nervosité; Vie saine: faire de son mieux pour bien dormir et bien manger, ce qui aide à mieux vivre chaque journée et à participer pleinement aux activités)."},{"code":"A1.3","title":"Motivation positive et persévérance","text":"mettre en pratique des habiletés favorisant le développement des habitudes de pensée propices à la motivation positive et à la persévérance, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de susciter l’optimisme et l’espoir (p. ex., Vie active: démontrer un état d’esprit axé sur la croissance lors de l’établissement d’objectifs personnels en matière d’activité physique; Compétence motrice: essayer d’adopter une attitude positive quand l’apprentissage d’une nouvelle habileté motrice ébranle sa confiance et décrire l’incidence de cette attitude positive sur son apprentissage; Vie saine: reconnaître et comprendre les facteurs de développement sain qu’on peut contrôler, et accepter les facteurs qu’on ne peut pas contrôler)."},{"code":"A1.4","title":"Relations saines","text":"mettre en pratique des habiletés l’aidant à nouer des relations, à développer de l’empathie et à communiquer avec les autres en français, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de favoriser les relations saines, le sentiment d’appartenance et le respect de la diversité (p. ex., Vie active: accepter de faire équipe avec tout un chacun et n’exclure personne lors du travail en petits groupes; Compétence motrice: au moment de s’exercer à lancer et à attraper des objets, parler avec son ou sa partenaire pour décider de l’équipement à utiliser et de la distance à laquelle se tenir l’un de l’autre; Vie saine: s’exprimer ou se comporter en soulignant les caractéristiques uniques de chacun de façon positive plutôt que de façon irrespectueuse ou offensante)."},{"code":"A1.5","title":"Conscience de soi et sentiment d’identité personnelle","text":"mettre en pratique des habiletés l’aidant à développer sa conscience de soi et sa confiance en soi, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de favoriser le développement d’un sentiment d’identité et d’appartenance au groupe, à l’école ou à la francophonie (p. ex., Vie active: connaître les activités familiales promouvant la santé physique et mentale, comme la marche, les repas et les moments de détente en famille, et expliquer comment un calendrier de saines habitudes de vie affiché sur le réfrigérateur à la maison permet de planifier et d’inscrire ces activités; Compétence motrice: vérifier sa stabilité dans une position d’équilibre statique et modifier sa position au besoin; observer si sa confiance augmente à mesure que l’équilibre statique est travaillé; Vie saine: cerner des caractéristiques qui en font une personne unique et comprendre que chaque personne possède des traits, visibles ou non, qui la rendent unique, comme des habiletés et des attributs physiques différents)."},{"code":"A1.6","title":"Pensée critique et créative","text":"mettre en pratique des habiletés l’aidant à penser de manière critique et créative, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de favoriser l’établissement de liens, l’analyse, l’évaluation, la résolution de problèmes et la prise de décisions (p. ex., Vie active: trouver des moyens d’augmenter son activité physique à la maison; Compétence motrice: après avoir effectué une séquence de mouvements, réfléchir à ce qui aurait pu être fait autrement pour rendre les transitions entre les mouvements plus fluides; Vie saine: penser aux choses à apporter à un pique-nique en famille ou à un repas communautaire en tenant compte des pratiques et aliments sains, et expliquer ses choix)."}]}]},{"code":"B","title":"Vie active","why":"Par la participation active, les élèves acquièrent les fondements pour mener une vie saine et active, tout en découvrant les facteurs qui contribuent au plaisir d’être actif.","overall":[{"code":"B1","title":"Participation active","text":"participer activement et régulièrement à une large gamme d’activités physiques, en cherchant des façons d’inclure ces activités dans son quotidien.","specific":[{"code":"B1.1","title":"Participation active","text":"participer activement à la vaste gamme d’activités physiques proposées (p. ex., jeu de poursuite, jeu coopératif, jeu à l’extérieur, activité rythmique) selon sa capacité, tout en adoptant des comportements qui améliorent son état d’esprit et sa capacité à participer (p. ex., être réceptive et réceptif à de nouvelles activités; encourager ses pairs à améliorer leurs habiletés; trouver des façons d’inclure tout le monde dans une activité physique; maintenir un niveau soutenu pendant toute la durée de l’activité; avoir l’équipement nécessaire afin de participer à l’activité; faire preuve de respect envers les autres et de franc-jeu; écouter activement; suivre les règles). [A1.3 Motivation, 1.5 Identité]"},{"code":"B1.2","title":"","text":"décrire des facteurs qui contribuent au plaisir d’être active et actif (p. ex., avoir la possibilité de participer pleinement à une activité, avoir le soutien de ses pairs, essayer diverses activités, y compris des activités francophones, être dans la nature) lors de sa participation à des jeux individuels et en petits groupes. [A1.1 Émotions, 1.5 Identité]"},{"code":"B1.3","title":"Participation active","text":"décrire les bienfaits physiques et mentaux liés à la pratique quotidienne d’activités physiques (p. ex., bienfaits physiques: augmenter son niveau d’énergie, améliorer la qualité de son sommeil, diminuer les risques de maladies; bienfaits sociaux: élargir son cercle social, développer son sens de l’empathie, vivre sa francophonie; bienfaits psychologiques et émotionnels: se sentir bien dans sa peau, renforcer ses habiletés interpersonnelles, acquérir plus de confiance en soi et d’autonomie, renforcer son appartenance à un groupe et à la francophonie, réduire le stress, améliorer sa concentration, contribuer au bien-être de sa communauté en prenant soin de sa santé et de son bien-être personnel). [A1.2 Adaptation, 1.6 Pensée]"}]},{"code":"B2","title":"Condition physique","text":"utiliser des concepts de la condition physique et des pratiques qui font valoir l’importance de l’activité physique pour une vie active et saine.","specific":[{"code":"B2.1","title":"Condition physique","text":"Activité physique quotidienne (APQ): participer à des activités physiques d’intensité modérée à vigoureuse (p. ex., circuit d’entraînement pour le conditionnement physique, mouvements de danse s’inspirant d’un conte, jeu avec un ballon) selon sa capacité au moins vingt minutes chaque jour, incluant le temps nécessaire à l’échauffement et au retour au calme. [A1.3 Motivation, 1.5 Identité]"},{"code":"B2.2","title":"Condition physique","text":"déterminer les capacités et les bienfaits physiques qui résultent d’une meilleure forme cardiorespiratoire (p. ex., muscle cardiaque plus fort; participation plus longue aux activités; distances franchies plus longues; temps de récupération réduit; sentiment de bien-être après une activité rigoureuse). [A1.6 Pensée]"},{"code":"B2.3","title":"Condition physique","text":"évaluer à l’aide de méthodes simples son niveau d’effort pendant des exercices cardiorespiratoires (p. ex., test de la parole [vérifier si on peut parler lors de l’activité physique], vérification du souffle, rythme cardiaque, rythme respiratoire, sensations ressenties pendant l’activité). [A1.5 Identité, 1.6 Pensée]"},{"code":"B2.4","title":"Condition physique","text":"mettre en pratique des objectifs personnels en matière d’activité physique (p. ex., sauter à la corde pendant une durée précise sans s’arrêter; marcher, parcourir en fauteuil roulant ou jogger un nombre déterminé de tours de piste au gymnase; faire une activité physique tous les jours). [A1.3 Motivation, 1.5 Identité, 1.6 Pensée]"}]},{"code":"B3","title":"Sécurité","text":"faire preuve d’un comportement responsable afin d’assurer sa sécurité et la sécurité des autres lors d’activités physiques.","specific":[{"code":"B3.1","title":"Sécurité","text":"mettre en pratique des procédures qui favorisent sa sécurité et celle des autres et qui réduisent le risque de blessures, y compris le risque de commotions cérébrales, pendant l’activité physique (p. ex., faire preuve de maîtrise de soi; prendre conscience de ce qui est autour de soi; coopérer avec les autres; respecter les règles et faire preuve de franc-jeu; communiquer de façon positive en aidant les autres à être en sécurité; faire un usage adéquat de l’équipement dans la salle de classe et sur le terrain de jeu). [A1.4 Relations, 1.5 Identité]"},{"code":"B3.2","title":"Sécurité","text":"décrire des comportements à adopter dans des cas de blessures ou d’accidents, y compris les commotions cérébrales, qui se produisent au cours de sa participation à des activités physiques (p. ex., rester calme; arrêter toute activité immédiatement sans enlever l’équipement; demander à la personne blessée si elle a besoin d’aide; avertir un adulte; respecter l’espace de la personne blessée). [A1.1 Émotions, 1.2 Adaptation, 1.6 Pensée]"}]}]},{"code":"C","title":"Compétence motrice","why":"Grâce à l’exploration et à la participation à une variété d’activités, les élèves acquièrent des habiletés et des tactiques pour bouger, tout en augmentant leur confiance dans leurs capacités physiques.","overall":[{"code":"C1","title":"Habiletés motrices et concepts du mouvement","text":"mettre en pratique des habiletés motrices ainsi que des concepts du mouvement pour répondre aux exigences de base d’une variété d’activités physiques.","specific":[{"code":"C1.1","title":"Stabilité","text":"exécuter, avec contrôle, un enchaînement de deux positions d’équilibre statique en utilisant différentes parties du corps et en adoptant différentes positions, à des hauteurs variées, avec ou sans équipement (p. ex., au yoga, passer de la position de la cigogne à l’arabesque, de la position assise en V à la position du crabe sur un banc). [A1.3 Motivation, 1.5 Identité]"},{"code":"C1.2","title":"Stabilité","text":"sauter en hauteur ou en longueur sur une ou deux jambes en maintenant l’équilibre pendant qu’on prend son élan et en terminant le saut (p. ex., sauter par-dessus des sacs de fèves; sauter pour atterrir dans des cerceaux maintenus à l’horizontale; sauter au-delà d’une ligne tracée). [A1.5 Identité]"},{"code":"C1.3","title":"Locomotion","text":"se déplacer de différentes façons, seul ou avec un partenaire, en variant sa vitesse, son trajet, sa direction et sa position tout en tenant compte des autres et de l’équipement (p. ex., se déplacer en imitant des animaux; suivre un parcours en sautant à la corde; se déplacer par-dessus, par-dessous et autour de l’équipement dans une course à obstacles; faire différentes formes avec un foulard tout en se déplaçant; créer un enchaînement de mouvements pour illustrer des verbes d’action ou les mots d’un poème). [A1.3 Motivation, 1.4 Relations]"},{"code":"C1.4","title":"Manipulation","text":"envoyer et recevoir différents objets à diverses hauteurs avec ou sans équipement, tout en utilisant différentes parties du corps et en tenant compte de cibles et d’obstacles mineurs (p. ex., lancer un sac de fèves à travers un cerceau; attraper un poulet en caoutchouc à deux mains sous la taille; frapper un ballon avec le pied vers son ou sa partenaire avec le pied droit puis avec le pied gauche et s’arrêter pour le recevoir; utiliser des objets fabriqués avec du matériel spécial pour que ce soit plus facile de les attraper; frapper une balle en éponge avec une raquette). [A1.3 Motivation, 1.5 Identité]"},{"code":"C1.5","title":"Manipulation","text":"contrôler de façons variées des objets de différentes formes et tailles en utilisant différentes parties du corps et de l’équipement varié (p. ex., contrôler un ballon en le faisant passer d’un pied à l’autre tout en se déplaçant autour de cônes; maintenir une balle en équilibre sur une raquette; modifier une activité pour permettre à des jeunes en fauteuil roulant d’attraper un ballon, puis s’arranger pour que des camarades courent à leur place). [A1.3 Motivation, 1.5 Identité]"}]},{"code":"C2","title":"Habiletés tactiques","text":"mettre en pratique des habiletés tactiques dans le but d’améliorer sa participation et sa performance dans une variété d’activités physiques, tout en utilisant ses connaissances des composantes de ces activités.","specific":[{"code":"C2.1","title":"Habiletés tactiques","text":"mettre en pratique ses connaissances relatives aux composantes des activités physiques (p. ex., habiletés motrices, règles de base, limites du terrain, franc-jeu et savoir-vivre) dans le cadre de sa participation à diverses activités individuelles et en petits groupes. [A1.1 Émotions, 1.4 Relations, 1.6 Pensée]"},{"code":"C2.2","title":"Habiletés tactiques","text":"mettre en pratique une variété de tactiques de base (p. ex., se placer pour recevoir le ballon lorsqu’on joue à un jeu de deux contre deux ou pour un départ rapide lors d’une course; s’entraîner pour maintenir son équilibre en marchant sur une ligne au gymnase pendant qu’on attend son tour pour utiliser une poutre ou un banc) qui permettent d’accroître ses possibilités de réussite lors de sa participation à diverses activités physiques. [A1.3 Motivation, 1.5 Identité, 1.6 Pensée]"}]}]},{"code":"D","title":"Vie saine","why":"Les élèves apprennent à résoudre des problèmes, à prendre des décisions et à se fixer des objectifs qui sont directement liés à leur propre état de santé et de bien-être. Les élèves développent ces habiletés en explorant les concepts suivants liés à la santé: l’alimentation saine; la sécurité personnelle et la prévention des blessures; la consommation de substances, la dépendance et les comportements associés; le développement de la personne et la santé sexuelle; la littératie en santé mentale. Ces sujets ont été choisis parce qu’ils sont fondamentalement liés à la vie quotidienne des élèves et leur offrent des occasions d’apprendre comment faire des choix sains et sécuritaires aujourd’hui et pour l’avenir. Développement de la personne et la santé sexuelle Afin d’amener les élèves à bâtir des relations saines dans leur vie, ils apprendront au sujet: du développement social et émotionnel; de l’intimidation; du consentement Les élèves apprendront aussi sur: ce qui les rend uniques, y compris une image corporelle saine; les différences visibles et invisibles afin de faire preuve de respect à l'égard de tous.","overall":[{"code":"D1","title":"Attitudes et comportements","text":"expliquer les facteurs qui favorisent le développement sain de la personne.","specific":[{"code":"D1.1","title":"Alimentation saine","text":"expliquer comment l’origine des aliments (p. ex., l’endroit où la nourriture est cultivée, récoltée, piégée, pêchée ou chassée, la transformation et la préparation des aliments ou les méthodes de transformation et de préparation) peut avoir une influence sur leur valeur nutritionnelle et sur l’environnement (p. ex., façon dont nous consommons les aliments et en disposons). [A1.6 Pensée]"},{"code":"D1.2","title":"Sécurité personnelle et prévention des blessures","text":"démontrer sa compréhension des commotions cérébrales et de la façon dont elles se produisent ainsi que du protocole sur les commotions cérébrales établi par le conseil scolaire. [A1.5 Identité, 1.6 Pensée]"},{"code":"D1.3","title":"Consommation de substances, dépendance et comportements associés","text":"décrire les effets que divers types de consommation de substances légales et illégales (p. ex., médicaments, tabac ou produits de vapotage, café, sucre et sodium dans des boissons énergisantes, alcool dans des boissons comme la bière, le vin et les spiritueux) peuvent avoir sur sa santé mentale et physique et sur celle des autres (p. ex., dépendance, relations difficiles, démêlés avec la justice, problèmes financiers, problèmes de santé, conséquences environnementales). [A1.4 Relations, 1.5 Identité]"},{"code":"D1.4","title":"Développement de la personne et santé sexuelle","text":"déterminer les caractéristiques de relations saines (p. ex., accepter et respecter les différences, éviter les préjugés, être inclusive ou inclusif, communiquer ouvertement, établir et respecter des limites personnelles, écouter, faire preuve de respect mutuel et de bienveillance, être honnête), les moyens pour répondre à l’intimidation et à d’autres défis (p. ex., exclusion, discrimination, pressions des pairs, abus) et la façon de communiquer le consentement dans ses interactions avec les autres. [A1.1 Émotions, 1.2 Adaptation, 1.4 Relations]"},{"code":"D1.5","title":"Développement de la personne et santé sexuelle","text":"déterminer des facteurs (p. ex., sommeil, alimentation, activité physique, hérédité, soutien d’un adulte bienveillant, sentiment d’appartenance, influence des pairs) qui influencent le développement physique (p. ex., cheveux, peau, taille et forme du corps, yeux), socioémotionnel (p. ex., conscience de soi, habiletés d’adaptation, habiletés relationnelles) ainsi que le développement d’une image corporelle saine (p. ex., capacité d’apprécier, de célébrer et de respecter son corps, de reconnaître ses sentiments à son sujet, d’accepter sa taille et sa forme et de mettre l’accent sur ce qu’il peut accomplir). [A1.1 Émotions, 1.2 Adaptation, 1.3 Motivation, 1.5 Identité]"},{"code":"D1.6","title":"Littératie en santé mentale","text":"expliquer comment le cerveau réagit (c.-à-d. la réponse au stress du cerveau – combat, fuite, inhibition) lorsqu’il perçoit une menace et comment cette réaction influe sur les pensées, les émotions et les actions. [A1.1 Émotions]"}]},{"code":"D2","title":"Choix sains","text":"utiliser ses connaissances en matière de santé et ses habiletés socioémotionnelles afin de prendre des décisions éclairées et de poser des gestes qui contribuent à sa santé et à son bien-être.","specific":[{"code":"D2.1","title":"Alimentation saine","text":"expliquer les liens entre des choix alimentaires et une bonne hygiène dentaire (p. ex., après avoir consommé des friandises, il faut se brosser les dents; certains aliments, comme le lait, fortifient les dents). [A1.3 Motivation, 1.5 Identité]"},{"code":"D2.2","title":"Sécurité personnelle et prévention des blessures","text":"élaborer des lignes directrices de pratiques sécuritaires à l’extérieur de la salle de classe, y compris en ligne, dans diverses situations (p. ex., plan d’évacuation en cas d’incendie à son domicile; guide pour la communication sécuritaire en ligne; sécurité en camping; directives et protocoles concernant la salubrité de l’eau potable; sécurité à l’Halloween, en allant à l’école à pied, près d’une piscine ou d’un cours d’eau; directives d’utilisation de désinfectants pour les mains; mesures pour éviter la transmission de maladies infectieuses; règles de comportement autour des chiens-guides et d’autres animaux d’assistance, ainsi que des animaux en général). [A1.6 Pensée]"},{"code":"D2.3","title":"Consommation de substances, dépendance et comportements associés","text":"cerner des stratégies et des facteurs permettant de faire des choix judicieux relatifs à son comportement et à sa consommation de diverses substances pouvant mener à une dépendance (p. ex., la consommation responsable à court terme de médicaments peut favoriser la guérison, mais la consommation nocive de certains médicaments peut conduire à des comportements de dépendance et peut nuire à la santé; l’utilisation modérée de la télévision et des ordinateurs peut être une bonne source de divertissement, d’apprentissage ou peut être nécessaire pour la préparation des devoirs, mais passer trop de temps devant un écran peut contribuer à un mode de vie sédentaire qui peut mener à l’isolement social et à une vulnérabilité accrue aux problèmes de santé physique et mentale; les enseignements culturels peuvent fournir des éclaircissements quant aux effets de la consommation de substances psychoactives). [A1.5 Identité, 1.6 Pensée]"}]},{"code":"D3","title":"Rapprochements entre santé et bien-être","text":"établir des rapprochements entre la santé et le bien-être pour expliquer l’incidence des choix faits, des comportements adoptés et des facteurs environnementaux sur sa santé, son bien-être et sur la santé et le bien-être des autres.","specific":[{"code":"D3.1","title":"Alimentation saine","text":"expliquer comment les aliments locaux et les aliments provenant de différentes cultures (p. ex., baies, caris, chapatis, litchis, choux frisés, lentilles, pain naan, maïs, gibier, poisson, tourtière) peuvent augmenter la gamme de choix alimentaires sains. [A1.6 Pensée]"},{"code":"D3.2","title":"Sécurité personnelle et prévention des blessures","text":"expliquer comment la violence fictive diffusée dans divers médias, incluant la violence en ligne (p. ex., dessins animés, jeux vidéo, Internet, films, clips vidéo), peut créer une perception peu réaliste des conséquences de la violence dans la vie réelle (p. ex., traumatisme physique, incapacité chronique, stress familial, mort). [A1.1 Émotions, 1.6 Pensée]"},{"code":"D3.3","title":"Développement de la personne et santé sexuelle","text":"expliquer comment respecter les différences visibles (p. ex., couleur de la peau, des cheveux et des yeux; traits faciaux, morphologie; aides à la mobilité, différentes aptitudes physiques; habillement, possessions) et invisibles (p. ex., capacité d’apprentissage, habiletés et talents, valeurs personnelles et culturelles et croyances, maladie mentale, antécédents familiaux, préférences personnelles, allergies et intolérances) pour apprécier le fait que chaque personne est unique. [A1.1 Émotions, 1.4 Relations, 1.5 Identité]"},{"code":"D3.4","title":"Littératie en santé mentale","text":"déterminer des facteurs externes, y compris des facteurs environnementaux, susceptibles de susciter des émotions, notamment des émotions inconfortables comme l’inquiétude (p. ex. transitions, comme le début d’une nouvelle année scolaire, déménagement, séparation familiale; excès de chaleur, de froid ou de bruit; changement imprévu dans la vie quotidienne; perte grave, telle que le décès d’un membre de la famille ou d’un animal domestique) et des façons de gérer ces émotions. [A1.1 Émotions]"}]}]}]},"g4":{"url":"https://www.dcp.edu.gov.on.ca/fr/curriculum/elementaire-education-physique-sante","sourceLang":"fr","strands":[{"code":"A","title":"Apprentissage socioémotionnel","why":"Cette section du programme-cadre aide les élèves à favoriser: leur état général de santé et de bien-être; leur santé mentale; leur résilience et leur capacité d’apprendre et de s’épanouir. Les élèves acquièrent des habiletés socioémotionnelles qui les aideront à: reconnaître et à gérer leurs émotions; à gérer le stress; à éveiller une motivation et un état d’esprit positif; à bâtir des relations; à approfondir la conscience de soi; à penser de façon critique et créative.","overall":[{"code":"A1","title":"Habiletés socioémotionnelles","text":"mettre en pratique, au mieux de ses capacités, diverses habiletés socioémotionnelles dans l’acquisition de connaissances et d’habiletés liées aux attentes et aux contenus d’apprentissage dans les domaines Vie active, Compétence motrice et Vie saine pour son année d’études.","specific":[{"code":"A1.1","title":"Reconnaissance et gestion des émotions","text":"mettre en pratique des habiletés l’aidant à reconnaître et à gérer ses émotions, dans le cadre de situations d’apprentissage en éducation physique et santé, afin d’améliorer sa capacité à exprimer en français ses propres émotions ainsi qu’à comprendre celles des autres et à les considérer (p. ex., Vie active: reconnaître les sentiments de joie ou de satisfaction durant la pratique d’activités physiques et garder ces sentiments à l’esprit au moment de se fixer des objectifs en matière d’entraînement et de santé; Compétence motrice: gérer les émotions comme la frustration ou l’excitation pendant les jeux en petits groupes, par exemple en reconnaissant sa frustration ou son excitation, puis en inspirant profondément ou en prenant une brève pause pour se calmer; Vie saine: reconnaître les nouvelles émotions liées au début de la puberté)."},{"code":"A1.2","title":"Gestion du stress et adaptation","text":"mettre en pratique des habiletés permettant de reconnaître les sources de stress et de faire face aux difficultés, y compris être capable de demander de l’aide, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de favoriser le développement de la résilience personnelle (p. ex., Vie active: expliquer en quoi participer à une activité à l’échelle de l’école, comme se joindre à un club ou à une équipe intra-muros, permet de gérer son stress et de faire face aux difficultés en tissant des liens sociaux; Compétence motrice: choisir de l’équipement offrant un niveau de difficulté et de soutien adapté pour pouvoir acquérir ou améliorer une habileté motrice; Vie saine: expliquer comment la connaissance des changements physiques et émotionnels liés à la puberté peut l’aider à s’adapter à ces changements lorsqu’ils se produiront)."},{"code":"A1.3","title":"Motivation positive et persévérance","text":"mettre en pratique des habiletés favorisant le développement des habitudes de pensée propices à la motivation positive et à la persévérance, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de susciter l’optimisme et l’espoir (p. ex., Vie active: expliquer pourquoi la santé mentale est une source intrinsèque de motivation à fournir un effort; Compétence motrice: continuer de trouver des façons créatives de protéger et de conserver un objet transporté; Vie saine: porter attention à ses choix et habitudes alimentaires et continuer de choisir des options saines)."},{"code":"A1.4","title":"Relations saines","text":"mettre en pratique des habiletés l’aidant à nouer des relations, à développer de l’empathie et à communiquer avec les autres en français, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de favoriser les relations saines, le sentiment d’appartenance et le respect de la diversité (p. ex., Vie active: offrir des mots d’encouragement aux membres de son équipe durant les jeux en petits groupes et expliquer les répercussions de ce comportement; Compétence motrice: coopérer avec les autres membres du groupe pour concevoir une séquence de mouvements créative; Vie saine: expliquer les façons d’éviter d’écrire dans un message texte ou sur les médias sociaux des propos qui ne seraient pas tenus en personne; trouver des enseignements des Premières Nations, des Métis ou des Inuit pouvant l’aider à consolider ses propres relations)."},{"code":"A1.5","title":"Conscience de soi et sentiment d’identité personnelle","text":"mettre en pratique des habiletés l’aidant à développer sa conscience de soi et sa confiance en soi, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de favoriser le développement d’un sentiment d’identité et d’appartenance au groupe, à l’école ou à la francophonie (p. ex., Vie active: expliquer ce qui lui plaît dans ses activités préférées et réfléchir à ce que cela révèle à son sujet; Compétence motrice: cerner les habiletés motrices maîtrisées avec confiance et celles qui lui causent le plus de difficultés; Vie saine: se fixer un objectif de saine alimentation en respectant les recommandations du Guide alimentaire canadien ainsi que ses préférences, ses besoins et sa situation et ceux de sa famille)."},{"code":"A1.6","title":"Pensée critique et créative","text":"mettre en pratique des habiletés l’aidant à penser de manière critique et créative, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de favoriser l’établissement de liens, l’analyse, l’évaluation, la résolution de problèmes et la prise de décisions (p. ex., Vie active: bien réfléchir aux mesures à prendre pour éviter de se blesser pendant une activité physique et les mettre en application; Compétence motrice: regrouper différents jeux et activités selon leurs caractéristiques communes; essayer différentes positions en roulant au sol, par exemple les bras allongés ou le long du corps ou le corps étiré ou relâché, pour déterminer la meilleure technique permettant de rouler en ligne droite; Vie saine: avec une ou un camarade de classe, chercher et énumérer des façons d’éviter les situations et comportements malsains qui les rendent mal à l’aise)."}]}]},{"code":"B","title":"Vie active","why":"Par la participation active, les élèves acquièrent les fondements pour mener une vie saine et active, tout en découvrant les facteurs qui contribuent au plaisir d’être actif.","overall":[{"code":"B1","title":"Participation active","text":"participer activement et régulièrement à une large gamme d’activités physiques, en cherchant des façons d’inclure ces activités dans son quotidien.","specific":[{"code":"B1.1","title":"Participation active","text":"participer activement à la vaste gamme d’activités physiques proposées (p. ex., jeu de poursuite, circuit d’entraînement pour le conditionnement physique, activité rythmique, mini-joute, activités de danse, jeu coopératif) selon sa capacité, tout en adoptant des comportements qui améliorent son état d’esprit et sa capacité à participer (p. ex., accepter de jouer à différents postes sur le terrain; respecter les idées et les opinions des autres; prendre l’initiative en s’impliquant dans une activité; encourager les autres; parler gentiment; faire preuve de maîtrise de soi en tout temps). [A1.3 Motivation, 1.5 Identité]"},{"code":"B1.2","title":"Participation active","text":"décrire des facteurs qui contribuent au plaisir d’être active ou actif (p. ex., savoir que les règles du franc-jeu et du savoir-vivre seront respectées; avoir l’occasion de penser de façon créative et d’adapter les activités à ses besoins ou ses préférences individuelles; être à l’aise du point de vue physique et émotionnel au cours des activités) lors de sa participation à des jeux individuels et en petits groupes ainsi qu’à des jeux d’introduction à différentes activités sportives. [A1.3 Motivation, 1.5 Identité]"},{"code":"B1.3","title":"Participation active","text":"déterminer des facteurs (p. ex., plaisir; disponibilité et coût des programmes; proximité et accessibilité des centres communautaires, des lacs ou des sentiers naturels; disponibilité des supports à vélo; soutien de la famille et de ses pairs; pertinence culturelle des activités) qui incitent à participer quotidiennement à des activités physiques à l’école, à la maison et dans sa communauté. [A1.2 Adaptation, 1.3 Motivation, 1.6 Pensée]"}]},{"code":"B2","title":"Condition physique","text":"utiliser des concepts de la condition physique et des pratiques qui font valoir l’importance de l’activité physique pour une vie active et saine.","specific":[{"code":"B2.1","title":"Condition physique","text":"Activité physique quotidienne (APQ): participer à des activités physiques d’intensité modérée à vigoureuse (p. ex., course, mini-soccer, chasse aux épingles à linge, mini-jeux olympiques, danse aérobique) selon sa capacité au moins vingt minutes chaque jour, incluant le temps nécessaire à l’échauffement et au retour au calme. [A1.3 Motivation, 1.5 Identité]"},{"code":"B2.2","title":"Condition physique","text":"déterminer des bienfaits de l’activité sur la condition physique et la santé physique et mentale (p. ex., santé mentale, santé physique et sentiment d’appartenance: activité en plein air avec une amie; endurance cardiorespiratoire: course, déplacement rapide en fauteuil roulant, randonnée pédestre en forêt, natation, danse; endurance musculaire et force: mini-redressement assis, circuit d’hébertisme; flexibilité: exercice d’étirement, danse, yoga, art martial). [A1.3 Motivation, 1.5 Identité]"},{"code":"B2.3","title":"Condition physique","text":"évaluer son niveau d’effort au cours de sa participation à des activités physiques à l’aide de méthodes simples (p. ex., test de la parole [vérifier si on peut parler lors de l’activité physique], prendre son pouls avant, pendant et après l’activité physique; rythme cardiaque, sensations) en tenant compte des facteurs internes et externes qui peuvent modifier son niveau d’effort (p. ex., facteurs internes: alimentation préalable, état de santé physique et mentale, motivation personnelle, encouragement des autres, niveau d’énergie, heure/période de la journée; facteurs externes: qualité de l’air, température ambiante, activité nouvelle). [A1.1 Émotions, 1.3 Motivation, 1.5 Identité, 1.6 Pensée]"},{"code":"B2.4","title":"Condition physique","text":"mettre en pratique des objectifs personnels en matière de condition physique basés sur ses champs d’intérêt et sur les résultats de son autoévaluation. [A1.1 Émotions, 1.3 Motivation, 1.5 Identité, 1.6 Pensée]"}]},{"code":"B3","title":"Sécurité","text":"faire preuve d’un comportement responsable afin d’assurer sa sécurité et la sécurité des autres lors d’activités physiques.","specific":[{"code":"B3.1","title":"Sécurité","text":"mettre en pratique des procédures qui favorisent sa sécurité et celle des autres et qui réduisent le risque de blessures, y compris le risque de commotions cérébrales, pendant l’activité physique (p. ex., coopérer; porter des chaussures appropriées à l’activité; se tenir à une distance sécuritaire des autres lors de ses déplacements; s’assurer que les chaises sont repoussées sous les pupitres avant l’activité physique quotidienne [APQ]; respecter les règles du jeu). [A1.4 Relations, 1.5 Identité]"},{"code":"B3.2","title":"Sécurité","text":"décrire des méthodes préventives communes visant à éviter les blessures et les accidents, y compris les commotions cérébrales, au cours de sa participation à diverses activités physiques (p. ex., porter un protège-dents pour se protéger les dents et la langue lors d’une partie de hockey communautaire; porter un casque protecteur pour réduire les risques de blessures à la tête; choisir une pente de ski judicieusement; porter des lunettes de sécurité pour se protéger les yeux lors d’une partie de badminton; consulter la météo et se vêtir convenablement lors d’activités à l’extérieur; bien attacher ses lacets de chaussures ou les cordons de ses vêtements pour éviter qu’ils se coincent dans l’équipement). [A1.6 Pensée]"}]}]},{"code":"C","title":"Compétence motrice","why":"Grâce à l’exploration et à la participation à une variété d’activités, les élèves acquièrent des habiletés et des tactiques pour bouger, tout en augmentant leur confiance dans leurs capacités physiques.","overall":[{"code":"C1","title":"Habiletés motrices et concepts du mouvement","text":"mettre en pratique des habiletés motrices ainsi que des concepts du mouvement pour répondre aux exigences de base d’une variété d’activités physiques.","specific":[{"code":"C1.1","title":"Stabilité","text":"exécuter des exercices d’équilibre statique, individuellement ou avec des partenaires, en se servant de différentes parties du corps à des hauteurs variées, en adoptant des positions différentes et en utilisant l’équipement approprié (p. ex., position de la planche, posture de l’arbre, posture du chien tête en bas, équilibre d’objets sur différentes parties du corps, position d’équilibre sur un banc ou un ballon d’exercice). [A1.4 Relations, 1.5 Identité]"},{"code":"C1.2","title":"Stabilité","text":"sauter d’un endroit peu élevé en maintenant l’équilibre et en prenant son élan, tout en faisant preuve de contrôle en terminant le saut (p. ex., sauter d’un banc en maintenant l’équilibre; sauter par-dessus une corde et s’arrêter net après le saut). [A1.5 Identité]"},{"code":"C1.3","title":"Locomotion","text":"combiner diverses habiletés motrices en variant sa vitesse, son trajet et sa direction, tout en tenant compte des autres et de l’équipement (p. ex., sauter à cloche-pied et sautiller à vitesses variées dans un parcours en zigzag; varier la hauteur du corps et les parties utilisées lors de danses créatives, culturelles et folkloriques; varier les mouvements de tai-chi ou de yoga ainsi que leur vitesse; suivre un parcours en fauteuil roulant, en avançant et en reculant). [A1.4 Relations, 1.5 Identité]"},{"code":"C1.4","title":"Manipulation","text":"envoyer et recevoir à diverses hauteurs et à vitesses variées des objets de différentes formes et tailles en utilisant différentes parties du corps et en respectant les principes fondamentaux du mouvement (p. ex., frapper un ballon avec le pied et le recevoir à différentes hauteurs en tenant compte de son environnement; lancer et attraper un ballon avec la main dominante, puis avec l’autre; reculer pour répartir son poids afin d’absorber l’impact d’un ballon lancé avec force; lancer et attraper des foulards en exécutant une suite simple lorsqu’on apprend à jongler; lancer et attraper un ballon qui contient un objet qui fait du bruit pour faire participer les élèves ayant une déficience visuelle). [A1.3 Motivation, 1.5 Identité]"},{"code":"C1.5","title":"Manipulation","text":"contrôler, en se déplaçant dans l’aire d’activité, des objets de différentes formes et tailles, avec ou sans équipement, tout en tenant compte des autres et de l’équipement (p. ex., frapper une balle avec un bâton de hockey; changer de direction rapidement en driblant avec un ballon de basket; dribler un ballon avec les mains ou les pieds en gardant la tête levée et en tenant compte des obstacles; faire rebondir un ballon en pivotant au cours d’une routine de gymnastique rythmique; avancer en fauteuil roulant avec un ballon de basket sur les jambes; marcher d’un bout du gymnase à l’autre en portant un volant ou une balle sur une raquette tout en évitant le contact avec les autres). [A1.3 Motivation, 1.5 Identité]"}]},{"code":"C2","title":"Habiletés tactiques","text":"mettre en pratique des habiletés tactiques dans le but d’améliorer sa participation et sa performance dans une variété d’activités physiques, tout en utilisant ses connaissances des composantes de ces activités.","specific":[{"code":"C2.1","title":"Habiletés tactiques","text":"utiliser ses connaissances des composantes d’une activité physique (p. ex., habiletés motrices, structures des jeux, règles de base et lignes directrices, franc-jeu et savoir-vivre) lors de sa participation à diverses activités physiques (p. ex., jeux préparatoires comme le soccer deux contre deux, le volley-ball de plage et le volley-ball en petits groupes; activités récréatives comme la planche à roulettes et les compétitions de hula-hoop et de lancer et d’attraper un disque; jeux coopératifs comme le jeu de jongle, la marche des monstres et le ballon singe; activités de conditionnement physique comme les circuits, la course et les exercices de souplesse; activités de danse comme le mouvement créatif, la danse folklorique et les danses des Premières Nations, des Métis et des Inuit). [A1.1 Émotions, 1.4 Relations, 1.6 Pensée]"},{"code":"C2.2","title":"Habiletés tactiques","text":"déterminer des similarités entre différentes catégories d’activités physiques (p. ex., jeu individuel, jeu de cible, jeu filet/mur, jeu frapper/saisir, jeu de territoire) ainsi que des tactiques qui semblent efficaces lors de sa participation à diverses activités physiques. [A1.6 Pensée]"},{"code":"C2.3","title":"Habiletés tactiques","text":"mettre en pratique une variété de tactiques (p. ex., activité individuelle: avoir un rythme de respiration approprié lors de la natation; activité de cible: choisir une cible plus grande afin d’augmenter ses chances de l’atteindre; activité filet/mur: adopter la position d’attente pour être prêt à recevoir le ballon; activité frapper/saisir: relancer le ballon dans un espace non couvert par l’adversaire; activité de territoire: garder la possession du ballon en faisant de courtes passes; bouger en étant consciente et conscient des autres afin de voir les espaces libérés par l’adversaire) qui permettent d’accroître ses possibilités de réussite lors de sa participation à diverses activités physiques. [A1.2 Adaptation, 1.4 Relations, 1.6 Pensée]"}]}]},{"code":"D","title":"Vie saine","why":"Les élèves apprennent à résoudre des problèmes, à prendre des décisions et à se fixer des objectifs qui sont directement liés à leur propre état de santé et de bien-être. Les élèves développent ces habiletés en explorant les concepts suivants liés à la santé: l’alimentation saine; la sécurité personnelle et la prévention des blessures; la consommation de substances, la dépendance et les comportements associés; le développement de la personne et la santé sexuelle; la littératie en santé mentale. Ces sujets ont été choisis parce qu’ils sont fondamentalement liés à la vie quotidienne des élèves et leur offrent des occasions d’apprendre comment faire des choix sains et sécuritaires aujourd’hui et pour l’avenir. Développement de la personne et la santé sexuelle C’est un fait que de nos jours, les enfants atteignent la puberté à un âge plus précoce. Pour les filles, l’âge de la puberté se situe entre 8 et 13 ans, et pour les garçons entre 9 et 14 ans. Lorsque le sujet de la puberté est abordé en classe avant que les élèves n’entrent dans l’âge de puberté, ils seront mieux préparés: à vivre les changements qui se produiront au niveau de leur corps et à adopter des pratiques d’hygiène; à comprendre leur impact au niveau émotionnel et social sur les relations avec d’autres.","overall":[{"code":"D1","title":"Attitudes et comportements","text":"expliquer les facteurs qui favorisent le développement sain de la personne.","specific":[{"code":"D1.1","title":"Alimentation saine","text":"expliquer comment les principaux nutriments (p. ex., lipides, glucides, protéines, vitamines, minéraux, eau) contenus dans les aliments contribuent à la croissance (p. ex., le calcium présent dans le lait fortifie les os et les dents), à la santé physique et mentale (p. ex., les fibres dans les céréales facilitent la digestion), à l’apprentissage (p. ex., un petit-déjeuner riche en protéines favorise la concentration et l’apprentissage) et à la performance physique (p. ex., les glucides dans les pâtes alimentaires sont une source importante d’énergie). [A1.6 Pensée]"},{"code":"D1.2","title":"Sécurité personnelle et prévention des blessures","text":"décrire des risques associés à l’utilisation des technologies de la communication, y compris l’utilisation d’Internet, de messageries textes et de jeux en réseau (p. ex., difficulté à développer des habiletés et des relations interpersonnelles saines dans le monde réel; trop peu de temps passé en personne avec la famille et les amis et trop de temps passé en ligne; risque d’entrer en contact avec des cyberprédateurs; isolement social, état dépressif, souci de se comparer aux autres et besoin de validation, perturbation du sommeil et autres troubles associés à la santé mentale), ainsi que des précautions à prendre et des stratégies permettant d’en faire une utilisation sécuritaire. [A1.4 Relations, 1.6 Pensée]"},{"code":"D1.3","title":"Sécurité personnelle et prévention des blessures","text":"décrire des types d’intimidation, d’abus et d’autres comportements non consensuels (p. ex., sociaux, émotionnels, physiques, verbaux), y compris la cyberintimidation (p. ex., au moyen de médias sociaux, d’applications, de courriels, de messages textes, de réseaux de clavardage, de sites Web), ainsi que leurs répercussions et les moyens appropriés de gérer ces situations. [A1.1 Émotions, 1.2 Adaptation]"},{"code":"D1.4","title":"Consommation de substances, dépendance et comportements associés","text":"décrire les effets sur la santé (p. ex., dépendance, cancer, troubles respiratoires, espérance de vie réduite) des substances (p. ex., nicotine, goudron, plomb, formaldéhyde, ammoniac, arsenic) contenues dans les produits de tabac et de vapotage (p. ex., cigarette, cigarette électronique, cigare, pipe, tabac à mâcher, tabac à priser) et dans la fumée."},{"code":"D1.5","title":"Développement de la personne et santé sexuelle","text":"décrire les changements physiques qui se produisent à la puberté (p. ex., développement de la pilosité, mue de la voix, odeurs corporelles, forme du corps, menstruation, développement des seins), ainsi que l’impact émotionnel et social que la puberté risque de provoquer chez les jeunes. [A1.1 Émotions, 1.2 Adaptation, 1.4 Relations]"}]},{"code":"D2","title":"Choix sains","text":"utiliser ses connaissances en matière de santé et ses habiletés socioémotionnelles afin de prendre des décisions éclairées et de poser des gestes qui contribuent à sa santé et à son bien-être.","specific":[{"code":"D2.1","title":"Alimentation saine","text":"déterminer vos habitudes alimentaires personnelles afin de prendre conscience de vos choix alimentaires et de développer des habitudes plus saines, en vous basant sur les recommandations et les directives des guides alimentaires canadiens (p. ex., faire de l’eau sa boisson de choix; manger des légumes et des fruits en abondance; prendre ses repas en bonne compagnie; aider à faire les courses et à préparer les repas à la maison; piéger, pêcher, chasser, récolter et cultiver des aliments). [A1.3 Motivation, 1.5 Identité, 1.6 Pensée]"},{"code":"D2.2","title":"Sécurité personnelle et prévention des blessures","text":"mettre en pratique un processus décisionnel (p. ex., déterminer les dangers et les risques potentiels, trouver des façons d’assurer sa sécurité, considérer les pour et les contre des différentes options, envisager l’appui d’un adulte de confiance, choisir l’option la plus sécuritaire, agir et réfléchir à sa décision, voir s’il y a lieu d’améliorer quelque chose pour la prochaine fois) afin d’évaluer les risques et de prendre des décisions éclairées dans diverses situations (p. ex., en chaise roulante, à vélo, en ligne, en préparant des aliments). [A1.2 Adaptation, 1.6 Pensée]"},{"code":"D2.3","title":"Consommation de substances, dépendance et comportements associés","text":"examiner des comportements et des stratégies, y compris des habiletés socioémotionnelles (p. ex., appliquer des stratégies conversationnelles comme dire “non” clairement et résolument, changer le sujet, donner des raisons, poser une question, faire une blague; réfléchir à ses valeurs, ses croyances culturelles et ses choix personnels; trouver des options pour remédier au stress; résister aux influences négatives; reconnaître les dangers de la consommation du tabac à long terme; éviter les endroits où on fume ou vapote, en particulier ceux où il y a des jeunes qui fument ou qui vapotent) qui permettent de prendre des décisions éclairées et de résister aux pressions relatives à la consommation du tabac et des produits de vapotage. [A1.2 Adaptation, 1.4 Relations, 1.6 Pensée]"},{"code":"D2.4","title":"Développement de la personne et santé sexuelle","text":"décrire l’importance des pratiques d’hygiène à la puberté (p. ex., prendre une douche régulièrement, avoir une bonne hygiène dentaire, utiliser des produits hygiéniques, changer de vêtements de façon régulière, prendre soin des membres artificiels et des dispositifs prothétiques). [A1.5 Identité]"},{"code":"D2.5","title":"Littératie en santé mentale","text":"décrire de quelles façons les choix faits tous les jours peuvent avoir une incidence positive sur sa santé mentale (p. ex., prendre du temps pour analyser ses sentiments; dormir suffisamment, interagir socialement et sincèrement en personne avec d’autres; être physiquement active et actif; utiliser des stratégies de pleine conscience; établir des liens avec des adultes responsables et bienveillants; participer à quelque chose de « plus grand » que soi-même qui demande de contribuer au bien public). [A1.2 Adaptation, 1.5 Identité, 1.6 Pensée]"}]},{"code":"D3","title":"Rapprochements entre santé et bien-être","text":"établir des rapprochements entre la santé et le bien-être pour expliquer l’incidence des choix faits, des comportements adoptés et des facteurs environnementaux sur sa santé, son bien-être et sur la santé et le bien-être des autres.","specific":[{"code":"D3.1","title":"Alimentation saine","text":"déterminer les mécanismes qui encouragent des habitudes alimentaires saines dans divers contextes (p. ex., école, patinoire, centre récréatif, centre d’achats; au camping, chez une amie ou un ami, lors des fins de semaine). [A1.6 Pensée]"},{"code":"D3.2","title":"Consommation de substances, dépendance et comportements associés","text":"décrire les effets à court terme et à long terme de la fumée primaire et secondaire et les effets du vapotage."},{"code":"D3.3","title":"Littératie en santé mentale","text":"décrire diverses stratégies à utiliser pour gérer le stress dans des situations où un certain contrôle est exercé (p. ex., relations entre pairs, maintien d’un équilibre de vie) et dans des situations qui sont plus difficiles à maîtriser (p. ex., déménagement dans une nouvelle maison, stress dans la famille, stress environnementaux). [A1.2 Adaptation, 1.6 Pensée]"}]}]}]},"g5":{"url":"https://www.dcp.edu.gov.on.ca/fr/curriculum/elementaire-education-physique-sante","sourceLang":"fr","strands":[{"code":"A","title":"Apprentissage socioémotionnel","why":"Cette section du programme-cadre aide les élèves à favoriser: leur état général de santé et de bien-être; leur santé mentale; leur résilience et leur capacité d’apprendre et de s’épanouir. Les élèves acquièrent des habiletés socioémotionnelles qui les aideront à: reconnaître et à gérer leurs émotions; à gérer le stress; à éveiller une motivation et un état d’esprit positif; à bâtir des relations; à approfondir la conscience de soi; à penser de façon critique et créative.","overall":[{"code":"A1","title":"Habiletés socioémotionnelles","text":"mettre en pratique, au mieux de ses capacités, diverses habiletés socioémotionnelles dans l’acquisition de connaissances et d’habiletés liées aux attentes et aux contenus d’apprentissage dans les domaines Vie active, Compétence motrice et Vie saine pour son année d’études.","specific":[{"code":"A1.1","title":"Reconnaissance et gestion des émotions","text":"mettre en pratique des habiletés l’aidant à reconnaître et à gérer ses émotions, dans le cadre de situations d’apprentissage en éducation physique et santé, afin d’améliorer sa capacité à exprimer en français ses propres émotions ainsi qu’à comprendre celles des autres et à les considérer (p. ex., Vie active: expliquer de quelle façon la motivation d’une personne à participer à des activités physiques est influencée par son sentiment de confiance et d’inclusion; Compétence motrice: décrire la façon dont différentes activités peuvent engendrer différents sentiments, y compris le calme, la satisfaction, l’énergie et l’excitation; Vie saine: décrire sa façon de déterminer qu’une personne se sent menacée par une autre et nommer les mesures à prendre pour aider cette personne en tant que témoin)."},{"code":"A1.2","title":"Gestion du stress et adaptation","text":"mettre en pratique des habiletés permettant de reconnaître les sources de stress et de faire face aux difficultés, y compris être capable de demander de l’aide, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de favoriser le développement de la résilience personnelle (p. ex., Vie active: utiliser des stratégies de résolution de problèmes pour rendre plus intéressantes et amusantes les activités physiques qui semblent difficiles; Compétence motrice: expliquer en quoi l’essai de différentes techniques, comme la modification de la position du corps ou de la vitesse, peut l’aider à contrôler un ballon avec ses pieds tout en courant sur un terrain; Vie saine: savoir comment obtenir de l’aide dans différentes situations, par exemple quand elle ou il ressent beaucoup de tristesse ou d’inquiétude, se trouve en situation d’urgence ou de violence, se fait intimider ou voit quelqu’un se faire intimider, ou de façon à prévenir les blessures)."},{"code":"A1.3","title":"Motivation positive et persévérance","text":"mettre en pratique des habiletés favorisant le développement des habitudes de pensée propices à la motivation positive et à la persévérance, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de susciter l’optimisme et l’espoir (p. ex., Vie active: changer son état d’esprit pour se concentrer sur ses points forts au moment d’établir des objectifs d’entraînement; Compétence motrice: durant la conception d’un programme comprenant des ballons et des activités locomotrices, s’efforcer d’inclure des éléments jamais essayés auparavant; Vie saine: réfléchir à un événement ayant causé de la déception et décrire une autre façon de voir cet événement)."},{"code":"A1.4","title":"Relations saines","text":"mettre en pratique des habiletés l’aidant à nouer des relations, à développer de l’empathie et à communiquer avec les autres en français, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de favoriser les relations saines, le sentiment d’appartenance et le respect de la diversité (p. ex., Vie active: collaborer avec ses pairs en dirigeant tour à tour les activités d’échauffement; Compétence motrice: écouter activement les idées de ses partenaires pendant le travail d’équipe pour créer une séquence de gymnastique développementale; Vie saine: respecter ses camarades de classe en les encourageant, en les félicitant et en évitant de les insulter ou de les exclure; respecter les différences culturelles et autres)."},{"code":"A1.5","title":"Conscience de soi et sentiment d’identité personnelle","text":"mettre en pratique des habiletés l’aidant à développer sa conscience de soi et sa confiance en soi, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de favoriser le développement d’un sentiment d’identité et d’appartenance au groupe, à l’école ou à la francophonie (p. ex., Vie active: suivre sa progression vers ses objectifs d’entraînement et relever les points à améliorer ou à travailler; Compétence motrice: expliquer comment la connaissance de ses points forts et de ses points à améliorer peut l’aider dans l’acquisition de nouvelles habiletés motrices; Vie saine: décrire les facteurs à considérer pour déterminer comment aider une amie ou un ami possiblement aux prises avec des problèmes de santé mentale, et établir les limites entre les actions qu’il est possible de faire soi-même et celles nécessitant l’aide d’un adulte de confiance)."},{"code":"A1.6","title":"Pensée critique et créative","text":"mettre en pratique des habiletés l’aidant à penser de manière critique et créative, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de favoriser l’établissement de liens, l’analyse, l’évaluation, la résolution de problèmes et la prise de décisions (p. ex., Vie active: établir des liens entre l’activité physique et l’atteinte d’objectifs personnels d’entraînement ainsi qu’une bonne santé mentale en général; Compétence motrice: expliquer le concept de saine compétition, les éléments qu’elle inclut et ceux qu’elle devrait exclure, et la façon dont la présence ou l’absence de ces éléments peut influencer la motivation à participer à des activités physiques; Vie saine: décrire la façon dont les médias peuvent influencer ses choix alimentaires)."}]}]},{"code":"B","title":"Vie active","why":"Par la participation active, les élèves acquièrent les fondements pour mener une vie saine et active, tout en découvrant les facteurs qui contribuent au plaisir d’être actif.","overall":[{"code":"B1","title":"Participation active","text":"participer activement et régulièrement à une large gamme d’activités physiques, en cherchant des façons d’inclure ces activités dans son quotidien.","specific":[{"code":"B1.1","title":"Participation active","text":"participer activement à la vaste gamme d’activités physiques proposées (p. ex., échauffement, activités récréatives, activités de conditionnement physique et d’endurance, danse) selon sa capacité, tout en adoptant des comportements qui améliorent son état d’esprit et sa capacité à participer (p. ex., encourager les autres par des commentaires positifs; respecter les décisions des autres; faire preuve de franc-jeu; accueillir de bon gré une critique constructive; respecter les opinions des autres). [A1.3 Motivation, 1.5 Identité]"},{"code":"B1.2","title":"Participation active","text":"décrire des facteurs qui contribuent au plaisir d’être active et actif (p. ex., avoir l’occasion de modifier des jeux afin qu’ils soient plus inclusifs et qu’ils encouragent une participation maximale; participer à de nouvelles activités, y compris à des activités francophones; se déplacer au son de la musique en exprimant sa créativité; prendre part à des activités pendant lesquelles on peut avoir une compétition saine avec soi-même et avec les autres; avoir accès à des aires de jeu qui sont propres et attrayantes; pratiquer des activités de plein air permettant de découvrir les merveilles de la nature) lors de sa participation à des jeux individuels et en petits groupes, ainsi qu’à des jeux d’introduction à différentes activités sportives. [A1.2 Adaptation, 1.3 Motivation, 1.5 Identité]"},{"code":"B1.3","title":"Participation active","text":"expliquer des facteurs qui peuvent motiver ou décourager la participation quotidienne aux activités physiques (p. ex., plaisir; confiance en soi; accès à des programmes en français; appui des pairs; sentiment d’appartenance; disponibilité du transport, de l’équipement, des ressources financières; défis ou attentes relatifs au genre; habiletés motrices personnelles; habiletés organisationnelles individuelles; responsabilités familiales; appui familial; manque de temps) ainsi que les moyens pour surmonter les obstacles à rester actives ou actifs. [A1.1 Émotions, 1.3 Motivation, 1.4 Relations]"}]},{"code":"B2","title":"Condition physique","text":"utiliser des concepts de la condition physique et des pratiques qui font valoir l’importance de l’activité physique pour une vie active et saine.","specific":[{"code":"B2.1","title":"Condition physique","text":"Activité physique quotidienne (APQ): participer à des activités physiques d’intensité modérée à vigoureuse (p. ex., sauterelle, corde à sauter, marche rapide, déplacement en fauteuil roulant, minimatch) selon sa capacité au moins vingt minutes chaque jour, incluant le temps nécessaire à l’échauffement et au retour au calme. [A1.3 Motivation, 1.5 Identité]"},{"code":"B2.2","title":"Condition physique","text":"déterminer les composantes de la condition physique (c.-à-d. endurance cardiorespiratoire, endurance musculaire, force, souplesse) ainsi que les avantages de les améliorer et de les maintenir à un certain niveau (p. ex., améliorer l’endurance cardiorespiratoire permet de prolonger l’effort physique; améliorer la souplesse permet une plus grande aisance de mouvement; améliorer la force et l’endurance musculaire permet de soulever une charge plus lourde plus longtemps). [A1.6 Pensée]"},{"code":"B2.3","title":"Condition physique","text":"évaluer une des composantes de sa condition physique (c.-à-d. endurance cardiorespiratoire, endurance musculaire, force, souplesse), en notant les changements qui se produisent lors de sa participation à des activités physiques, ceux qui se produisent ponctuellement ou sur une période prolongée. [A1.5 Identité, 1.6 Pensée]"},{"code":"B2.4","title":"Condition physique","text":"mettre en pratique un plan personnel d’entraînement basé sur une composante de sa condition physique en tenant compte des résultats de son autoévaluation et de ses champs d’intérêt. [A1.3 Motivation, 1.5 Identité]"}]},{"code":"B3","title":"Sécurité","text":"faire preuve d’un comportement responsable afin d’assurer sa sécurité et la sécurité des autres lors d’activités physiques.","specific":[{"code":"B3.1","title":"Sécurité","text":"mettre en pratique des procédures qui favorisent sa sécurité et celle des autres et qui réduisent le risque de blessures, y compris le risque de commotions cérébrales, pendant l’activité physique (p. ex., faire preuve d’autodiscipline et de responsabilisation en matière de sécurité; pratiquer les exercices d’échauffement de façon appropriée; s’assurer que ses actions favorisent une expérience émotionnelle positive pour soi-même et pour les autres; signaler tout équipement défectueux). [A1.4 Relations, 1.5 Identité]"},{"code":"B3.2","title":"Sécurité","text":"expliquer les précautions à prendre au cours de sa participation à des activités physiques en plein air (p. ex., s’hydrater; appliquer un écran solaire; s’habiller adéquatement selon les conditions météorologiques; interpréter les indices UV; s’assurer d’avoir son auto-injecteur d’épinéphrine en cas de réaction allergique violente; avoir son bronchodilatateur en cas de crise d’asthme; lire les panneaux d’avertissement affichés dans les aires de loisirs) afin d’en profiter pleinement tout en évitant les dangers des facteurs environnementaux pour la santé. [A1.6 Pensée]"}]}]},{"code":"C","title":"Compétence motrice","why":"Grâce à l’exploration et à la participation à une variété d’activités, les élèves acquièrent des habiletés et des tactiques pour bouger, tout en augmentant leur confiance dans leurs capacités physiques.","overall":[{"code":"C1","title":"Habiletés motrices et concepts du mouvement","text":"mettre en pratique des habiletés motrices ainsi que des concepts du mouvement pour répondre aux exigences de base d’une variété d’activités physiques.","specific":[{"code":"C1.1","title":"Stabilité","text":"contrôler le transfert de poids, avec ou sans équipement, lors d’exercices d’équilibre statique et dynamique, en en variant la vitesse et la hauteur (p. ex., effectuer une séquence de mouvements sur une ligne ou sur un banc; maintenir son équilibre en roulant, en pivotant, en sautant ou en sautillant rapidement puis lentement). [A1.5 Identité]"},{"code":"C1.2","title":"Stabilité","text":"sauter en hauteur et en longueur en faisant preuve d’équilibre et de contrôle et en utilisant diverses actions corporelles (p. ex., se propulser avec différentes parties du corps pour faire un saut en hauteur; contrôler la position de son corps en retombant sur ses pieds lors d’un saut en longueur; atterrir en douceur après un saut vertical et un demi-tour dans une routine de danse; maintenir le corps droit en tournant pendant un saut en hauteur). [A1.5 Identité]"},{"code":"C1.3","title":"Locomotion","text":"combiner diverses habiletés motrices en variant sa vitesse, sa hauteur, son trajet et sa direction tout en tenant compte des autres et de l’équipement (p. ex., varier sa vitesse et sa hauteur lors d’une course de relais avec obstacles; exécuter une danse avec un partenaire en utilisant différentes parties du corps pour exécuter des mouvements et en variant le rythme; exécuter une danse avec ruban et ballon en variant la hauteur des lancers). [A1.3 Motivation]"},{"code":"C1.4","title":"Manipulation","text":"lancer et recevoir des objets de différentes formes et tailles en utilisant différentes parties du corps, en s’adaptant à différentes vitesses et en respectant les principes fondamentaux du mouvement (p. ex., attraper un disque volant; frapper un ballon à une ou à un partenaire avec l’intérieur du pied et augmenter ou diminuer la force pour varier la vitesse; placer la balle sur un support stable pour la frapper plus facilement). [A1.3 Motivation, 1.4 Relations]"},{"code":"C1.5","title":"Manipulation","text":"contrôler des objets, avec ou sans équipement, en modifiant leur vitesse et leur trajet et en tenant compte des autres et de l’équipement (p. ex., dribler autour de cônes en ralentissant au besoin pour garder le contrôle du ballon; déplacer un anneau de feutre en contournant des obstacles; faire une course de relais en gardant le contrôle d’une balle sur une raquette; [pour les élèves ayant une déficience visuelle] manipuler une rondelle sonore afin de contourner des élèves qui servent de guide). [A1.5 Identité]"}]},{"code":"C2","title":"Habiletés tactiques","text":"mettre en pratique des habiletés tactiques dans le but d’améliorer sa participation et sa performance dans une variété d’activités physiques, tout en utilisant ses connaissances des composantes de ces activités.","specific":[{"code":"C2.1","title":"Habiletés tactiques","text":"utiliser ses connaissances des composantes d’activités physiques (p. ex., habiletés motrices, structures des jeux, règles de base et lignes directrices, franc-jeu et savoir-vivre) lors de sa participation à une variété d’activités physiques (p. ex., introduction à différents sports comme la crosse trois contre trois, le beep ball, le tchoukball et le mini-tennis; activités récréatives comme le disque golf, jeu de parachute, course d’orientation et jeux coopératifs; activités de conditionnement physique comme le yoga, les activités de musculation isométrique et d’endurance; activités de danse comme les mouvements de danses créatives et de hip-hop). [A1.1 Émotions, 1.4 Relations, 1.6 Pensée]"},{"code":"C2.2","title":"Habiletés tactiques","text":"décrire des similarités entre différentes catégories d’activités physiques (p. ex., jeu individuel, jeu de cible, jeu filet/mur, jeu frapper/saisir, jeu de territoire) ainsi que des tactiques communes efficaces qui permettent d’accroître ses possibilités de réussite lors de sa participation à diverses activités physiques. [A1.6 Pensée]"},{"code":"C2.3","title":"Habiletés tactiques","text":"mettre en pratique une variété de tactiques (p. ex., activité individuelle: ajuster sa position afin de maintenir l’équilibre en faisant du yoga; activité de cible: ajuster sa position et sa distance afin d’atteindre une cible; maintenir le contact visuel avec une cible afin d’améliorer sa précision; activité filet/mur: lancer le ballon loin de son adversaire; activité frapper/saisir: garder les yeux sur la balle avant de la frapper; activité de territoire: passer plus souvent le ballon à ses coéquipières et ses coéquipiers pour déjouer l’adversaire) qui permettent d’accroître ses possibilités de réussite lors de sa participation à diverses activités physiques. [A1.2 Adaptation, 1.4 Relations, 1.6 Pensée]"}]}]},{"code":"D","title":"Vie saine","why":"Les élèves apprennent à résoudre des problèmes, à prendre des décisions et à se fixer des objectifs qui sont directement liés à leur propre état de santé et de bien-être. Les élèves développent ces habiletés en explorant les concepts suivants liés à la santé: l’alimentation saine; la sécurité personnelle et la prévention des blessures; la consommation de substances, la dépendance et les comportements associés; le développement de la personne et la santé sexuelle; la littératie en santé mentale. Ces sujets ont été choisis parce qu’ils sont fondamentalement liés à la vie quotidienne des élèves et leur offrent des occasions d’apprendre comment faire des choix sains et sécuritaires aujourd’hui et pour l’avenir. Développement de la personne et la santé sexuelle En 5e année, les élèves ont déjà acquis un certain degré de conscience de soi et de capacité d’adaptation et ont appris des techniques de pensée critique et de réflexion. La période de puberté peut être stressante, mais lorsque les élèves comprennent les changements par lesquels passe leur corps, ils peuvent mieux y faire face. Par ailleurs, les élèves continueront d’apprendre l’importance: de faire preuve d’acceptation et de respect envers eux-mêmes et les autres, y compris des élèves qui atteignent la puberté avant ou après leurs pairs","overall":[{"code":"D1","title":"Attitudes et comportements","text":"expliquer les facteurs qui favorisent le développement sain de la personne.","specific":[{"code":"D1.1","title":"Sécurité personnelle et prévention des blessures","text":"déterminer des personnes de confiance (p. ex., parent, tutrice ou tuteur, membre de la famille, voisine ou voisin, enseignante ou enseignant, entraîneur ou entraîneuse, agente ou agent de police, brigadière ou brigadier scolaire, élève plus âgé) et des services de soutien (p. ex., les services de soutien professionnel en ligne comme Jeunesse, J’écoute, les centres jeunesse ou communautaires, le 9-1-1, le service Télésanté, les centres communautaires de santé, les services communautaires en santé mentale, les bureaux de santé, les services aux élèves) qui peuvent apporter un appui dans les cas de blessures, de détresse émotionnelle, d’intimidation, de partage non consensuel de photos et de tout autre comportement non consensuel, de harcèlement et de situations d’abus et de violence. [A1.1 Émotions, 1.2 Adaptation]"},{"code":"D1.2","title":"Consommation de substances, dépendance et comportements associés","text":"décrire des effets à court terme et à long terme de la consommation de l’alcool ainsi que des facteurs qui influent sur le degré d’intoxication (p. ex., quantité consommée, vitesse de consommation, type d’alcool, combinaison avec des médicaments, d’autres drogues comme le cannabis, des aliments ou des substances comme les boissons énergisantes)."},{"code":"D1.3","title":"Développement de la personne et santé sexuelle","text":"déterminer les diverses parties et fonctions de l’appareil reproducteur en y associant les changements qui s’opèrent durant la puberté. [A1.5 Identité]"},{"code":"D1.4","title":"Développement de la personne et santé sexuelle","text":"expliquer le rôle du cycle menstruel et de la spermatogenèse dans la reproduction et le développement global."}]},{"code":"D2","title":"Choix sains","text":"utiliser ses connaissances en matière de santé et ses habiletés socioémotionnelles afin de prendre des décisions éclairées et de poser des gestes qui contribuent à sa santé et à son bien-être.","specific":[{"code":"D2.1","title":"Alimentation saine","text":"évaluer la qualité de différents produits alimentaires en se servant de l’information fournie sur les étiquettes d’emballage afin de choisir judicieusement des aliments sains et salubres. [A1.6 Pensée]"},{"code":"D2.2","title":"Sécurité personnelle et prévention des blessures","text":"démontrer sa capacité à faire face à diverses situations menaçantes en utilisant des habiletés socioémotionnelles (p. ex., habiletés liées à la conscience de soi, incluant les habiletés d’autorégulation, d’adaptation et de maîtrise des émotions; habiletés relationnelles, y compris savoir s’affirmer et refuser) et en adoptant des stratégies pour assurer sa sécurité (p. ex., réfléchir avant d’agir; rechercher l’aide d’adultes de confiance; s’affirmer pour se protéger des influences négatives; dresser une liste d’organismes francophones réputés qui apportent leur appui aux jeunes en détresse; faire appel aux enseignements culturels). [A1.1 Émotions, 1.2 Adaptation, 1.3 Motivation, 1.4 Relations, 1.5 Identité]"},{"code":"D2.3","title":"Consommation de substances, dépendance et comportements associés","text":"décrire des habiletés relatives à la prise de décisions, à l’affirmation de soi et au refus pour résister à la pression des pairs quant à la consommation d’alcool ou à tout autre comportement (p. ex., tabagisme, vapotage, consommation de drogues, pratique compulsive de jeux de hasard et de jeux vidéo) pouvant mener à une dépendance. [A1.4 Relations, 1.6 Pensée]"},{"code":"D2.4","title":"Développement de la personne et santé sexuelle","text":"déterminer les facteurs communs qui influent sur le développement du concept de soi, y compris son orientation sexuelle (p. ex., la conscience de soi, la connaissance de soi, le milieu social, l’opinion des autres, les stéréotypes, la reconnaissance de ses points forts et de ses besoins, les compétences sociales, l’identité culturelle, le soutien offert, l’image corporelle, la santé mentale et le bien-être émotionnel, les habiletés physiques) et les façons dont ces facteurs peuvent favoriser sa santé et son bien-être. [A1.1 Émotions, 1.2 Adaptation, 1.5 Identité]"},{"code":"D2.5","title":"Développement de la personne et santé sexuelle","text":"décrire le stress, sur le plan émotionnel et interpersonnel, attribuable aux changements qui ont lieu à la puberté et les symptômes qui peuvent être indicatifs de problèmes de santé mentale (p. ex., questionnement sur ses changements physiques et émotifs; ajustement à l’évolution de ses relations; intensité des sentiments et émotions; questionnement sur son orientation sexuelle; conflit entre ses désirs personnels et les valeurs et pratiques culturelles de son milieu) ainsi que des stratégies (p. ex., être active et actif; exprimer ses sentiments dans un journal intime; faire une recherche et prendre des mesures au sujet d’une préoccupation; maintenir une communication ouverte avec les membres de sa famille; parler à un adulte digne de confiance; faire des exercices de respiration contrôlée; faire de la méditation; demander conseil à une Aînée ou un Aîné, à une sénatrice métisse ou un sénateur métis, ou à une détentrice ou un détenteur de savoir ou à une gardienne ou un gardien du savoir de son milieu culturel) pour gérer ce stress, améliorer sa résilience, maintenir un dialogue continu avec les membres de sa famille et des adultes bienveillants, et maintenir son bien-être émotionnel et sa santé mentale. [A1.1 Émotions, 1.2 Adaptation, 1.4 Relations, 1.5 Identité]"},{"code":"D2.6","title":"Littératie en santé mentale","text":"décrire son rôle, et les limites de ce rôle, pour venir en aide à une personne qui peut avoir besoin de soutien en santé mentale. [A1.2 Adaptation, 1.4 Relations, 1.5 Identité]"}]},{"code":"D3","title":"Rapprochements entre santé et bien-être","text":"établir des rapprochements entre la santé et le bien-être pour expliquer l’incidence des choix faits, des comportements adoptés et des facteurs environnementaux sur sa santé, son bien-être et sur la santé et le bien-être des autres.","specific":[{"code":"D3.1","title":"Alimentation saine","text":"décrire comment la publicité, le marketing alimentaire et les médias influent sur les choix alimentaires (p. ex., publicité télévisuelle, publicité intégrée à l’expérience du jeu vidéo, publicité avec appui d’une vedette et affichage dans les médias sociaux, emballage de produit, placement de produits et promotion des images corporelles idylliques et irréalistes dans des émissions de télévision et des films, promotion de régimes à la mode, programmes de fidélisation) afin d’aider les personnes à faire des choix éclairés en matière d’alimentation (p. ex., se renseigner sur les informations nutritionnelles des ingrédients et des nutriments; analyser les étiquettes des produits alimentaires; déterminer les renseignements d’une annonce publicitaire qui confirment sa validité; considérer d’un œil critique les messages publicitaires, le parrainage de produits par des vedettes et la réalité et la salubrité des images corporelles idéalisées dans les médias). [A1.6 Pensée]"},{"code":"D3.2","title":"Sécurité personnelle et prévention des blessures","text":"décrire des répercussions que des actions entreprises en personne ou en ligne, y compris des commentaires homophobes ou blessants (p. ex., comportements négatifs comme dénigrer les autres, faire des commentaires racistes ou sexistes, se moquer de l’apparence physique ou de la capacité de quelqu’un, exclure les autres, pratiquer l’intimidation et la cyberintimidation ou le harcèlement sexuel [incluant les activités en ligne comme faire des commentaires, partager des photos ou demander qu’on partage des photos à caractère sexuel]; comportements positifs comme faire l’éloge des autres, les encourager, les inclure et les défendre) peuvent avoir sur les sentiments, la santé mentale, y compris le bien-être émotionnel, la réputation et le concept de soi de l’auteur des actions et sur ceux de la personne qui en est la cible. [A1.1 Émotions, 1.4 Relations, 1.5 Identité]"},{"code":"D3.3","title":"Consommation de substances, dépendance et comportements associés","text":"décrire des facteurs personnels et sociaux (p. ex., facteur émotionnel, physique, psychologique, spirituel, culturel; démêlés avec la justice; influence des médias et des pairs) qui peuvent mener une personne à consommer de l’alcool ou du cannabis à différentes périodes de sa vie. [A1.2 Adaptation, 1.6 Pensée]"},{"code":"D3.4","title":"Littératie en santé mentale","text":"expliquer de quelles façons nos attitudes au sujet de la santé mentale ont une incidence sur celles et ceux qui nous sont proches et comment elles peuvent contribuer à créer ou prévenir une stigmatisation. [A1.6 Pensée]"}]}]}]},"g6":{"url":"https://www.dcp.edu.gov.on.ca/fr/curriculum/elementaire-education-physique-sante","sourceLang":"fr","strands":[{"code":"A","title":"Apprentissage socioémotionnel","why":"Cette section du programme-cadre aide les élèves à favoriser: leur état général de santé et de bien-être; leur santé mentale; leur résilience et leur capacité d’apprendre et de s’épanouir. Les élèves acquièrent des habiletés socioémotionnelles qui les aideront à: reconnaître et à gérer leurs émotions; à gérer le stress; à éveiller une motivation et un état d’esprit positif; à bâtir des relations; à approfondir la conscience de soi; à penser de façon critique et créative.","overall":[{"code":"A1","title":"Habiletés socioémotionnelles","text":"mettre en pratique, au mieux de ses capacités, diverses habiletés socioémotionnelles dans l’acquisition de connaissances et d’habiletés liées aux attentes et aux contenus d’apprentissage dans les domaines Vie active, Compétence motrice et Vie saine pour son année d’études.","specific":[{"code":"A1.1","title":"Reconnaissance et gestion des émotions","text":"mettre en pratique des habiletés l’aidant à reconnaître et à gérer ses émotions, dans le cadre de situations d’apprentissage en éducation physique et santé, afin d’améliorer sa capacité à exprimer en français ses propres émotions ainsi qu’à comprendre celles des autres et à les considérer (p. ex., Vie active: reconnaître ses émotions ainsi que son niveau d’énergie et de motivation durant différentes activités et la façon dont ces éléments influencent son appréciation des activités; Compétence motrice: expliquer la différence entre ses émotions durant une activité relativement facile, comme lancer et attraper un objet en position stationnaire, et une activité plus exigeante, comme lancer et attraper un objet plus petit en se déplaçant; Vie saine: décrire l’influence des émotions sur les habitudes et les choix alimentaires et comment la reconnaissance de cette influence peut l’aider à faire des choix plus sains)."},{"code":"A1.2","title":"Gestion du stress et adaptation","text":"mettre en pratique des habiletés permettant de reconnaître les sources de stress et de faire face aux difficultés, y compris être capable de demander de l’aide, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de favoriser le développement de la résilience personnelle (p. ex., Vie active: expliquer pourquoi un casque bien ajusté et des sangles bien arrimées sur un fauteuil roulant améliorent le sentiment de sécurité, la confiance en soi et le confort pendant l’activité physique; Compétence motrice: utiliser des tactiques pour améliorer le jeu ou atténuer l’inconfort, par exemple en modifiant sa cadence ou sa foulée pendant la course; Vie saine: décrire des stratégies permettant de faire face à d’éventuelles situations difficiles lors de la garde de jeunes enfants)."},{"code":"A1.3","title":"Motivation positive et persévérance","text":"mettre en pratique des habiletés favorisant le développement des habitudes de pensée propices à la motivation positive et à la persévérance, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de susciter l’optimisme et l’espoir (p. ex., Vie active: lorsque le transport est difficilement accessible, par exemple en milieu rural, recourir à des solutions de rechange telles que le covoiturage pour participer à des activités récréatives; Compétence motrice: connaître ses points forts et ses habiletés motrices à améliorer, par exemple tenir ou manipuler des objets avec sa main ou son pied non dominant, puis travailler à trouver des façons de tirer parti de ses points forts et de se dépasser; Vie saine: démontrer sa compréhension de la façon dont les saines habitudes alimentaires accroissent le niveau d’énergie et améliorent le concept de soi)."},{"code":"A1.4","title":"Relations saines","text":"mettre en pratique des habiletés l’aidant à nouer des relations, à développer de l’empathie et à communiquer avec les autres en français, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de favoriser les relations saines, le sentiment d’appartenance et le respect de la diversité (p. ex., Vie active: offrir des mots d’encouragement aux autres élèves pendant les activités physiques; respecter les décisions des membres de l’équipe qui agissent comme arbitres; Compétence motrice: proposer des idées au groupe lorsqu’un travail collaboratif doit être accompli; Vie saine: connaître la meilleure façon d’aider une personne en lui posant des questions et en lui offrant le type de soutien qu’elle préfère; décrire le langage verbal et non verbal pouvant servir à exprimer à une personne les sentiments qu’elle lui inspire)."},{"code":"A1.5","title":"Conscience de soi et sentiment d’identité personnelle","text":"mettre en pratique des habiletés l’aidant à développer sa conscience de soi et sa confiance en soi, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de favoriser le développement d’un sentiment d’identité et d’appartenance au groupe, à l’école ou à la francophonie (p. ex., Vie active: déterminer quels facteurs, parmi ceux qui motivent généralement les gens à faire de l’activité physique, ont le plus d’influence sur sa propre motivation; Compétence motrice: prendre conscience de la technique utilisée pour attraper un objet lancé à différentes vitesses, par exemple se rappeler de reculer pour attraper une balle lancée avec force; Vie saine: réfléchir à la façon dont les stéréotypes influencent le concept de soi et mettre en lumière d’autres facteurs qui agissent sur le sentiment d’identité, par exemple se faire accepter par les autres)."},{"code":"A1.6","title":"Pensée critique et créative","text":"mettre en pratique des habiletés l’aidant à penser de manière critique et créative, dans le cadre de situations d’apprentissage en éducation physique et santé, afin de favoriser l’établissement de liens, l’analyse, l’évaluation, la résolution de problèmes et la prise de décisions (p. ex., Vie active: décrire les mesures à prendre en cas de blessure superficielle; Compétence motrice: prévoir diverses tactiques offensives et défensives applicables à différentes situations dans les jeux de frappe et de réception; Vie saine: expliquer ce qui peut être fait pour combattre les stéréotypes et les préjugés et pour encourager les interactions respectueuses, l’acceptation de la différence et l’inclusion de tout le monde dans les activités sociales)."}]}]},{"code":"B","title":"Vie active","why":"Par la participation active, les élèves acquièrent les fondements pour mener une vie saine et active, tout en découvrant les facteurs qui contribuent au plaisir d’être actif.","overall":[{"code":"B1","title":"Participation active","text":"participer activement et régulièrement à une large gamme d’activités physiques, en cherchant des façons d’inclure ces activités dans son quotidien.","specific":[{"code":"B1.1","title":"Participation active","text":"participer activement à la vaste gamme d’activités physiques proposées (p. ex., jeux d’introduction à des activités sportives, activités récréatives, activités de conditionnement physique, danse) selon sa capacité, en fournissant un effort soutenu et en adoptant des comportements appropriés (p. ex., participer pleinement; écouter sans juger; féliciter ses partenaires pour leurs efforts; utiliser le temps alloué efficacement; partager l’équipement et l’espace; être réceptif à de nouvelles activités; exprimer clairement ses émotions telles que la joie ou le mécontentement). [A1.3 Motivation, 1.5 Identité]"},{"code":"B1.2","title":"Participation active","text":"décrire des facteurs qui contribuent au plaisir d’être active et actif (p. ex., variété de l’équipement utilisé et de la taille des groupes; choix des activités, y compris des activités francophones; possibilité de participer à des activités adaptées à ses besoins; participation active à un jeu ou à une activité au lieu de réchauffer le banc; encouragement des instructeurs ou des parents; nouveauté de l’activité; possibilité d’avoir de la musique; compétition saine; environnement sain et sécuritaire) lors de sa participation à des jeux individuels et en petits groupes ainsi qu’à des jeux d’introduction à différentes activités sportives. [A1.1 Émotions, 1.3 Motivation, 1.4 Relations]"},{"code":"B1.3","title":"Participation active","text":"expliquer ses choix d’activités physiques, à l’école et durant les loisirs, en exposant les facteurs qui motivent sa participation quotidienne (p. ex., influence des camarades ou des membres de sa famille, préférence pour des activités individuelles ou d’équipe, préférence pour des activités à l’intérieur ou à l’extérieur, disponibilité et coût de programmes communautaires, besoin de compétition saine, attrait des activités médiatisées). [A1.1 Émotions, 1.2 Adaptation, 1.3 Motivation, 1.5 Identité]"}]},{"code":"B2","title":"Condition physique","text":"utiliser des concepts de la condition physique et des pratiques qui font valoir l’importance de l’activité physique pour une vie active et saine.","specific":[{"code":"B2.1","title":"Condition physique","text":"Activité physique quotidienne (APQ): participer à des activités physiques d’intensité modérée à vigoureuse (p. ex., danse aérobique, jeu de poursuite, mini-soccer, circuit d’entraînement, randonnée pédestre, course d’orientation) selon sa capacité au moins vingt minutes chaque jour, incluant le temps nécessaire à l’échauffement et au retour au calme. [A1.3 Motivation, 1.5 Identité]"},{"code":"B2.2","title":"Condition physique","text":"expliquer comment la participation aux activités physiques améliore la condition physique (p. ex., les activités musculaires améliorent le tonus et la force des muscles; les activités cardiorespiratoires modérées améliorent le système immunitaire; les activités qui améliorent la souplesse des articulations aident à prévenir les blessures). [A1.6 Pensée]"},{"code":"B2.3","title":"Condition physique","text":"évaluer des composantes de sa condition physique (c.-à-d. endurance cardiorespiratoire, endurance musculaire, force, souplesse) durant diverses activités physiques en notant les changements qui se produisent en cours d’activité, ponctuellement et sur une période prolongée (p. ex., noter la fréquence de son pouls avant, pendant et après une activité; décrire les modifications de son état dans un journal de bord; consigner ses progrès quotidiens ou hebdomadaires sur une fiche informatisée). [A1.3 Motivation, 1.5 Identité, 1.6 Pensée]"},{"code":"B2.4","title":"Condition physique","text":"mettre en pratique des plans d’entraînement basés sur son évaluation des composantes de sa condition physique (c.-à-d. endurance cardiorespiratoire, endurance musculaire, force, souplesse) et sur ses champs d’intérêt pour atteindre ses objectifs personnels (p. ex., s’autoévaluer et tenir compte des résultats pour atteindre ses objectifs personnels; utiliser les principes d’entraînement appropriés; cerner les défis possibles et les sources de soutien; déterminer les indicateurs qui permettent de déterminer les objectifs atteints; suivre son progrès et comparer les résultats aux objectifs ciblés; reconnaître le succès; modifier les objectifs et les approches au besoin). [A1.3 Motivation, 1.6 Pensée]"}]},{"code":"B3","title":"Sécurité","text":"faire preuve d’un comportement responsable afin d’assurer sa sécurité et la sécurité des autres lors d’activités physiques.","specific":[{"code":"B3.1","title":"Sécurité","text":"mettre en pratique des procédures qui favorisent sa sécurité et celle des autres et qui réduisent le risque de blessures, y compris le risque de commotions cérébrales, pendant l’activité physique (p. ex., éviter de prendre des risques inutiles en jouant; utiliser en tout temps de l’équipement en bon état; dégager la surface de jeu de tout obstacle; porter l’équipement protecteur requis tel un casque protecteur pour faire de la planche à neige, des sports communautaires en équipe, du toboggan ou du vélo, entre autres; faire des activités de façon responsable et avec prudence, et respecter le protocole sur les commotions cérébrales établi par le conseil scolaire; prendre les précautions nécessaires suivant les conditions climatiques et les saisons telles qu’éviter de s’approcher de surfaces recouvertes d’une fine glace et se couvrir le visage et la tête dans les cas de froid extrême; aider quelqu’un à ajuster les sangles de son fauteuil roulant). [A1.4 Relations, 1.5 Identité]"},{"code":"B3.2","title":"Sécurité","text":"expliquer les mesures à prendre pour traiter des blessures mineures qui peuvent survenir au cours de sa participation à des activités physiques (p. ex., traiter l’enflure avec de la glace; nettoyer une coupure légère et y appliquer un pansement; appliquer de la pression sur une blessure qui saigne pour réduire ou arrêter le saignement; traiter une blessure immédiatement afin d’empêcher qu’elle ne s’aggrave). [A1.6 Pensée]"}]}]},{"code":"C","title":"Compétence motrice","why":"Grâce à l’exploration et à la participation à une variété d’activités, les élèves acquièrent des habiletés et des tactiques pour bouger, tout en augmentant leur confiance dans leurs capacités physiques.","overall":[{"code":"C1","title":"Habiletés motrices et concepts du mouvement","text":"mettre en pratique des habiletés motrices ainsi que des concepts du mouvement pour répondre aux exigences de base d’une variété d’activités physiques.","specific":[{"code":"C1.1","title":"Stabilité","text":"contrôler le transfert de poids, avec ou sans équipement, lors d’exercices d’équilibre statique et dynamique dans une variété de situations, tout en tenant compte des autres (p. ex., exercice avec ballon suisse; passer d’une position de yoga à une autre; passer d’un mouvement de danse hip-hop à un autre avec fluidité; exercice d’équilibre debout sur une toupie; maintenir l’équilibre sur une jambe; en fauteuil roulant, tenir un objet en équilibre sur une partie de son corps). [A1.4 Relations, 1.5 Identité]"},{"code":"C1.2","title":"Locomotion","text":"combiner diverses habiletés motrices en variant sa vitesse, son trajet et sa direction tout en tenant compte des autres et de l’équipement (p. ex., au basketball, modifier la vitesse ou la direction de sa course ou de son fauteuil roulant pour s’éloigner d’un adversaire; varier la vitesse d’exécution des mouvements en danse créative). [A1.4 Relations, 1.5 Identité]"},{"code":"C1.3","title":"Manipulation","text":"envoyer et attraper des objets variés (p. ex., anneau, sac de fèves, balle en éponge, balle de tennis, poulet en caoutchouc) en ajustant sa vitesse, son trajet et sa distance par rapport à la cible et en respectant les principes fondamentaux du mouvement (p. ex., varier sa force pour lancer un disque volant à une coéquipière ou à un coéquipier, en prenant compte du poids du disque et de la force d’impact de celui-ci sur sa coéquipière ou son coéquipier et en fonction de la position relative et du type d’objet lancé ou frappé; faire rebondir un ballon vers une coéquipière ou un coéquipier pour déjouer un adversaire; frapper un ballon avec le pied; plier les genoux, étendre les bras et lever la tête pour attraper un objet; faire le suivi de son mouvement dans la direction d’une cible afin d’améliorer son lancer et sa précision). [A1.1 Émotions, 1.4 Relations, 1.5 Identité]"},{"code":"C1.4","title":"Manipulation","text":"contrôler un objet à l’aide de différentes parties du corps en variant sa vitesse, son trajet et sa direction tout en tenant compte des autres et des obstacles (p. ex., se déplacer en tenant un ballon et en variant sa vitesse et sa direction afin de fuir un adversaire; effectuer un pas chassé avec feinte en tenant compte des obstacles; manipuler un disque de feutre lentement, puis rapidement, tout en gardant la tête levée). [A1.3 Motivation, 1.4 Relations, 1.5 Identité]"}]},{"code":"C2","title":"Habiletés tactiques","text":"mettre en pratique des habiletés tactiques dans le but d’améliorer sa participation et sa performance dans une variété d’activités physiques, tout en utilisant ses connaissances des composantes de ces activités.","specific":[{"code":"C2.1","title":"Habiletés tactiques","text":"utiliser ses connaissances des composantes (p. ex., habiletés motrices, structures des jeux, règles de base et lignes directrices, franc-jeu et savoir-vivre) de diverses activités physiques proposées (p. ex., jeux d’introduction à différentes activités sportives; jeux de tir au basketball et jeux de balle molle à deux buts; activités récréatives comme le mini-triathlon, la randonnée, le saut à la corde et autres jeux coopératifs; activités physiques comme le tai-chi; exercices avec ballon et bande élastique de résistance; défi personnel de conditionnement physique; danses folkloriques, créatives, jazz ou hip-hop). [A1.5 Identité, 1.6 Pensée]"},{"code":"C2.2","title":"Habiletés tactiques","text":"décrire des similarités entre différentes catégories d’activités physiques (p. ex., jeu individuel, jeu de cible, jeu filet/mur, jeu frapper/saisir, jeu de territoire) ainsi que des tactiques qui permettent d’accroître ses possibilités de réussite lors de sa participation à diverses activités physiques. [A1.6 Pensée]"},{"code":"C2.3","title":"Habiletés tactiques","text":"mettre en pratique une variété de tactiques (p. ex., activité individuelle: trouver une vitesse confortable lors d’une course, d’une marche ou en se déplaçant en fauteuil roulant; activité de cible: à la pétanque, frapper les boules de l’adversaire pour placer les siennes à un endroit stratégique; activité filet/mur: adopter une position d’attente et être prête ou prêt à recevoir le ballon; activité frapper/saisir: renvoyer la balle rapidement pour empêcher l’adversaire de marquer un but; activité de territoire: faire rebondir le ballon à diverses hauteurs afin de le protéger; varier la hauteur de lancement d’un disque volant afin d’éviter qu’un adversaire l’intercepte) qui permettent d’accroître ses possibilités de réussite lors de sa participation à diverses activités physiques. [A1.2 Adaptation, 1.4 Relations, 1.6 Pensée]"}]}]},{"code":"D","title":"Vie saine","why":"Les élèves apprennent à résoudre des problèmes, à prendre des décisions et à se fixer des objectifs qui sont directement liés à leur propre état de santé et de bien-être. Les élèves développent ces habiletés en explorant les concepts suivants liés à la santé: l’alimentation saine; la sécurité personnelle et la prévention des blessures; la consommation de substances, la dépendance et les comportements associés; le développement de la personne et la santé sexuelle; la littératie en santé mentale. Ces sujets ont été choisis parce qu’ils sont fondamentalement liés à la vie quotidienne des élèves et leur offrent des occasions d’apprendre comment faire des choix sains et sécuritaires aujourd’hui et pour l’avenir. Développement de la personne et la santé sexuelle Lorsque les enfants qui grandissent et entrent dans l’adolescence comprennent mieux les nombreux changements qui se produiront dans leur vie et celle de leurs pairs, ils pourront mieux arriver à une idée claire de qui ils sont. En 6e année, les élèves ont développé davantage la conscience de soi et des habiletés d’adaptation, ainsi que des habiletés de pensée critique et de réflexion, de résolution de problèmes, d’analyse et de prise de décision. Les élèves examineront et contesteront divers stéréotypes, notamment en fonction de: l’orientation sexuelle; la race; l’origine ethnique; la culture; la santé mentale et les capacités Ils continueront à développer le respect des autres et la confiance en soi l’aidant à nouer des relations saines.","overall":[{"code":"D1","title":"Attitudes et comportements","text":"expliquer les facteurs qui favorisent le développement sain de la personne.","specific":[{"code":"D1.1","title":"Sécurité personnelle et prévention des blessures","text":"décrire les bienfaits de l’inclusion, du respect et de la tolérance pour soi-même et les autres. [A1.1 Émotions, 1.4 Relations, 1.5 Identité]"},{"code":"D1.2","title":"Consommation de substances, dépendance et comportements associés","text":"décrire des effets de la consommation de cannabis et d’autres drogues (p. ex., médicaments sur ordonnance comme les opioïdes, les opioïdes illégaux comme l’héroïne, le crack, la cocaïne, l’ecstasy, la méthamphétamine, le GHB, le LSD, les stéroïdes) ainsi que de substances toxiques (p. ex., essence, colle, peinture). [A1.6 Pensée]"},{"code":"D1.3","title":"Développement de la personne et santé sexuelle","text":"décrire des répercussions du visionnement de médias à contenu sexuellement explicite, y compris de la pornographie (p. ex., conduit à une compréhension limitée ou fausse des relations intimes, renforce des attitudes sexistes préjudiciables, promeut une image corporelle irréaliste ou idéalisée)."},{"code":"D1.4","title":"Littératie en santé mentale","text":"déterminer des personnes, des ressources et des services à l’école ou dans la communauté (p. ex., membres de la famille, travailleuses et travailleurs en santé mentale et en toxicomanie, travailleuses et travailleurs sociaux, psychologues; lieux de culte, centres de santé, centres récréatifs, organismes communautaires, maisons des jeunes, bureaux de santé publique, lignes d’assistance téléphonique) dont l’accès peut offrir un soutien lorsqu’une personne éprouve des problèmes de santé mentale et est confrontée à des choix ou des situations associés à la consommation de drogues et d’alcool et à des comportements de dépendance. [A1.1 Émotions, 1.2 Adaptation, 1.6 Pensée]"},{"code":"D1.5","title":"Littératie en santé mentale","text":"démontrer sa compréhension des liens entre les pensées, les émotions et les actions d’une personne et l’impact potentiel de la pensée positive et négative sur la santé mentale. [A1.1 Émotions, 1.5 Identité, 1.6 Pensée]"}]},{"code":"D2","title":"Choix sains","text":"utiliser ses connaissances en matière de santé et ses habiletés socioémotionnelles afin de prendre des décisions éclairées et de poser des gestes qui contribuent à sa santé et à son bien-être.","specific":[{"code":"D2.1","title":"Alimentation saine","text":"démontrer ses connaissances des facteurs médicaux, émotionnels, sociaux et d’ordre pratique (p. ex., allergies et sensibilités alimentaires, goût et aversion, stress, santé dentaire, influence des médias, influence culturelle de la famille et des amis, politiques sur les aliments et les boissons de l’école, impact environnemental, coût) qui influencent les habitudes et les choix alimentaires afin de développer des objectifs personnels pour une alimentation plus saine. [A1.1 Émotions, 1.2 Adaptation, 1.4 Relations, 1.6 Pensée]"},{"code":"D2.2","title":"Alimentation saine","text":"expliquer l’influence des signes de la faim, de la soif et de la satiété sur son alimentation (p. ex., stade de développement, poussées de croissance, niveau d’activité physique, manger de grosses portions) afin de développer certaines habitudes propices à une alimentation saine. [A1.1 Émotions, 1.5 Identité, 1.6 Pensée]"},{"code":"D2.3","title":"Sécurité personnelle et prévention des blessures","text":"utiliser des habiletés socioémotionnelles (p. ex., la conscience de soi et la maîtrise de soi, y compris la gestion de la colère; les habiletés de communication, y compris l’écoute active et l’habileté de s’affirmer) pour promouvoir des interactions positives et gérer des conflits dans des situations sociales, en personne ou en ligne (p. ex., groupes de camarades de classe, groupes d’amis, équipes sportives, clubs scolaires, sites de médias sociaux, jeux en ligne). [A1.1 Émotions, 1.2 Adaptation, 1.4 Relations, 1.5 Identité]"},{"code":"D2.4","title":"Consommation de substances, dépendance et comportements associés","text":"décrire des facteurs (p. ex., valeurs personnelles, pression des pairs, influence des médias, curiosité, sanctions sociales et légales, enseignements culturels, religieux, spirituels) et des stratégies concernant la consommation de drogues comme l’alcool, le tabac et le cannabis ainsi que des activités telles que le vapotage, afin de faire des choix personnels judicieux, y compris choisir de s’abstenir. [A1.2 Adaptation, 1.4 Relations, 1.5 Identité, 1.6 Pensée]"},{"code":"D2.5","title":"Développement de la personne et santé sexuelle","text":"expliquer l’influence des changements physiques, sociaux et émotionnels au stade de l’adolescence sur la confiance en soi et le développement de relations saines (p. ex., changements physiques: mue de la voix, croissance, éruptions cutanées; changements sociaux: nouvelles amitiés, influence plus importante des amis; changements émotionnels: plus forte intensité des réactions et des émotions, développement de l’intérêt pour une relation, inquiétudes au sujet des changements qui se produisent pendant la puberté). [A1.1 Émotions, 1.4 Relations, 1.5 Identité]"},{"code":"D2.6","title":"Développement de la personne et santé sexuelle","text":"reconnaître l’importance de se respecter et de respecter les autres, y compris la notion de consentement, afin de faire des choix judicieux dans ses relations en appliquant diverses habiletés socioémotionnelles (p. ex., conscience de soi et identité personnelle; autogestion; habiletés de la pensée critique et créative; habiletés se rapportant aux savoirs traditionnels et aux enseignements culturels des Premières Nations, des Métis et des Inuit [enseignements de la roue de médecine liés au cycle de la vie, enseignements se rapportant aux sept Grands-pères ou autres enseignements culturels]). [A1.1 Émotions, 1.4 Relations, 1.5 Identité, 1.6 Pensée]"}]},{"code":"D3","title":"Rapprochements entre santé et bien-être","text":"établir des rapprochements entre la santé et le bien-être pour expliquer l’incidence des choix faits, des comportements adoptés et des facteurs environnementaux sur sa santé, son bien-être et sur la santé et le bien-être des autres.","specific":[{"code":"D3.1","title":"Alimentation saine","text":"expliquer comment une alimentation saine et une vie active influencent conjointement la santé physique et mentale globale ainsi que le bien-être (p. ex., niveau d’énergie élevé, prévention des maladies, meilleur concept de soi et de son image corporelle, poids santé), et de quelles façons en promouvoir les bienfaits dans son entourage. [A1.2 Adaptation, 1.3 Motivation, 1.5 Identité, 1.6 Pensée]"},{"code":"D3.2","title":"Sécurité personnelle et prévention des blessures","text":"décrire des responsabilités et des risques associés au fait de se prendre en main et de prendre soin des autres (p. ex., rester seule ou seul à la maison; faire des courses pour un parent ou un voisin plus âgé; garder des enfants; faire du bénévolat; aider une personne ayant un handicap; s’occuper d’un animal de compagnie; préparer des repas; aller à l’école à bicyclette ou en fauteuil roulant) ainsi que les pratiques et les procédures appropriées à mettre en pratique lors de situations potentiellement dangereuses (p. ex., pratiques sécuritaires de préparation des aliments; comportement en réponse à une réaction allergique, un incendie, une blessure sportive, une urgence dentaire ou à un cas d’hypothermie, d’intimidation, d’abus). [A1.4 Relations, 1.5 Identité, 1.6 Pensée]"},{"code":"D3.3","title":"Développement de la personne et santé sexuelle","text":"évaluer comment les stéréotypes et les idées préconçues à l’égard du rôle des genres, de l’orientation sexuelle, de la race, de la nationalité, de la culture, de la santé mentale et des déficiences physiques ou cognitives, peuvent avoir des répercussions sur le concept de soi d’une personne ainsi que sur son inclusion sociale et ses relations avec les autres, en vue de proposer des façons d’y réagir et de modifier les idées préconçues nuisibles qui peuvent mener à des attitudes sociales néfastes, y compris l’homophobie et le racisme. [A1.1 Émotions, 1.4 Relations, 1.5 Identité, 1.6 Pensée]"}]}]}]}},"arts":{"g1":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-arts","sourceLang":"en","strands":[{"code":"A","title":"Dance","why":"","overall":[{"code":"A1","title":"Creating and Presenting","text":"apply the creative process to the composition of simple dance phrases, using the elements of dance to communicate feelings and ideas","specific":[{"code":"A1.1","title":"","text":"use movements that are part of their daily experience in a variety of ways in dance phrases (e.g., alter and exaggerate movements based on even rhythms such as walking, galloping, and swimming, and on uneven rhythms such as skipping and jumping; amplify and modify percussive movements such as the movement of a clock ticking or the sustained hold of a cat stretching)"},{"code":"A1.2","title":"","text":"use dance as a language to express feelings and ideas suggested by songs, stories, and poems, with a focus on the element of body, particularly body shapes (e.g., use the entire body [crouch, slump] and body parts [folded arms, bowed head] to express an idea such as deep thought)"},{"code":"A1.3","title":"","text":"create dance phrases using a variety of ways to connect movements (e.g., connect a melt and a spin using a non-locomotor movement; connect a walk and a skip [locomotor movements] with a circle [pathway])"},{"code":"A1.4","title":"","text":"use varied and/or contrasting body shapes to communicate different types of messages (e.g., a high level and open, expansive shape to show dominance; a closed huddled shape to show that you are holding a treasured or secret object)"}]},{"code":"A2","title":"Reflecting, Responding, and Analysing","text":"apply the critical analysis process to communicate their feelings, ideas, and understandings in response to a variety of dance pieces and experiences","specific":[{"code":"A2.1","title":"","text":"describe differences they observe when various movements from daily life are used as the basis or stimulus for movements in a dance phrase (e.g., describe ways in which everyday actions and movements such as skipping on the playground, walking to school, brushing their teeth, or getting dressed are changed when they are used in a dance phrase)"},{"code":"A2.2","title":"","text":"identify and describe how the element of body is used in contrasting ways to communicate ideas in their own and others’ dance phrases, with teacher support (e.g., standing versus kneeling body bases can communicate differences in power; curved versus straight shapes can communicate contrasting emotions)"},{"code":"A2.3","title":"","text":"identify and give examples of their strengths and areas for growth as dance creators and audience members (e.g., using connecting movements; working collaboratively in groups to create dance phrases incorporating everyone’s ideas; watching peer performances attentively and asking relevant questions)"}]},{"code":"A3","title":"Exploring Forms and Cultural Contexts","text":"demonstrate an understanding of a variety of dance forms and styles from the past and present, and their social and/or community contexts","specific":[{"code":"A3.1","title":"","text":"describe, with teacher guidance, a variety of dances from different communities around the world that they have seen in the media, at live performances and social gatherings, or in the classroom (e.g., describe traditional dances they have seen to a partner [Chinese ribbon dance, Highland fling, powwow dance styles])"},{"code":"A3.2","title":"","text":"identify and describe dance experiences in their own lives and communities (e.g., At home: dancing or moving to a favourite song/story; seeing dance on television or in a movie DVD; At school: playing at recess; In the community: dancing or observing dances at weddings, parties, cultural celebrations)"}]}]},{"code":"B","title":"Drama","why":"","overall":[{"code":"B1","title":"Creating and Presenting","text":"apply the creative process to dramatic play and process drama, using the elements and conventions of drama to communicate feelings, ideas, and stories","specific":[{"code":"B1.1","title":"","text":"engage in dramatic play and role play, with a focus on exploring a variety of sources from diverse communities, times, and places (e.g., retell and enact nursery and other childhood rhymes, stories, or narratives from picture books; use movement and voice to explore the thoughts of a familiar folk tale character in a variety of situations; use guided imagery and descriptive language to explore what a character might feel and experience in a story setting or picture; use group role play to explore alternative endings to stories, fairy tales, and personal experiences; use role play or a tableau at key moments in a story to help the protagonist solve a problem; interview a teacher in the role of a character from a story)"},{"code":"B1.2","title":"","text":"demonstrate an understanding of the element of character by adopting thoughts, feelings, and gestures relevant to the role being played (e.g., use facial expressions, body movement, and words to respond in role to scenarios and questions; express different points of view after reading a picture book about issues of belonging and discrimination; work with a partner to create a short scene that shows the importance of acceptance, understanding, and inclusion)"},{"code":"B1.3","title":"","text":"plan and shape dramatic play by building on the ideas of others, both in and out of role (e.g., In role: add ideas to the dramatic play that reflect the knowledge and experience of the role that is being played [such as a scientist mentioning an experiment or a journalist mentioning an interview]; create and share scenes from their own experiences; Out of role: work in a group to plan and prepare a scene and ask follow-up questions such as “How could we make this clearer? What changes can we make to help our story be understood?”; describe the sort of person who might own a particular found object such as a bag or a coat)"},{"code":"B1.4","title":"","text":"communicate feelings and ideas to a familiar audience (e.g., classmates) using a few simple visual or technological aids to support and enhance their drama work (e.g., use a sheer cloth moved quickly to represent water; use a rainstick or shaker to create a sense of mystery or magic; use a variety of classroom objects to create a play area for specific dramatic play experiences)"}]},{"code":"B2","title":"Reflecting, Responding, and Analysing","text":"apply the critical analysis process to communicate feelings, ideas, and understandings in response to a variety of drama works and experiences","specific":[{"code":"B2.1","title":"","text":"express feelings and ideas about a drama experience or performance in a variety of ways, making personal connections to the characters and themes in the story (e.g., in oral discussion, relate themes about family relationships or friendships to their own lives; after viewing a play or clip of a movie dealing with family issues [such as Cinderella or Princess Mononoke], contribute to a class journal entry or draw a picture to show the feelings of one or more of the characters – a stepsister, Cinderella, the mice)"},{"code":"B2.2","title":"","text":"demonstrate an understanding of how the element of character/role is used in shared classroom drama experiences and theatre to communicate meaning (e.g., to provide important information in a situation; to represent a particular perspective/point of view; to change the direction of the plot; to symbolize an idea such as friendship)"},{"code":"B2.3","title":"","text":"identify and give examples of their strengths, interests, and areas for improvement as drama participants and audience members (e.g., using personal experience and imagination to extend ideas in the drama; building on their own or others’ ideas)"}]},{"code":"B3","title":"Exploring Forms and Cultural Contexts","text":"demonstrate an understanding of a variety of drama and theatre forms and styles from the past and present, and their social and/or community contexts","specific":[{"code":"B3.1","title":"","text":"identify and describe drama and theatre forms, events, and activities that they experience in their home, school, and community (e.g., favourite television or computer programs and characters, imaginative play with action figures, dramatic play, attending plays and celebrations, interacting with picture books, storytelling)"},{"code":"B3.2","title":"","text":"demonstrate an awareness of a variety of roles, themes, and subjects in dramas and stories from different communities around the world (e.g., contribute to a class scrapbook about characters such as trolls/fairies, trickster themes in Nanabush stories [from Native folklore] and Anansi stories [from West African folklore])"}]}]},{"code":"C","title":"Music","why":"","overall":[{"code":"C1","title":"Creating and Performing","text":"apply the creative process to create and perform music for a variety of purposes, using the elements and techniques of music","specific":[{"code":"C1.1","title":"","text":"sing songs in unison and play simple accompaniments for music from a wide variety of diverse cultures, styles, and historical periods (e.g., play a simple rhythmic ostinato on a drum or tambourine to accompany singing; match pitches in echo singing)"},{"code":"C1.2","title":"","text":"apply the elements of music when singing, playing, and moving (e.g., duration: while singing a familiar song, clap the rhythm while others pat the beat, and on a signal switch roles)"},{"code":"C1.3","title":"","text":"create compositions for a specific purpose and a familiar audience (e.g., use the notes “mi”, “so”, and “la” to create a melodic phrase that answers a sung question; use rhythm instruments, body percussion, or everyday objects to create an accompaniment to a story or song; use short rhythmic phrases in improvised answers to clapped questions)"},{"code":"C1.4","title":"","text":"use the tools and techniques of musicianship in musical performances (e.g., sing with relaxed but straight posture and controlled breathing; rehearse music to perform with others)"},{"code":"C1.5","title":"","text":"demonstrate understanding that sounds can be represented by symbols (e.g., show rhythm and beat with manipulatives such as math cubes or Popsicle sticks; use devised, or invented, forms of musical notation, or simple forms of standard musical notation)"}]},{"code":"C2","title":"Reflecting, Responding, and Analysing","text":"apply the critical analysis process to communicate their feelings, ideas, and understandings in response to a variety of music and musical experiences","specific":[{"code":"C2.1","title":"","text":"express initial reactions and personal responses to musical performances in a variety of ways (e.g., move like an animal of which the music reminds them)"},{"code":"C2.2","title":"","text":"describe ways in which the elements of music are used for different purposes in the music they perform, listen to, and create (e.g., the tempo and dynamics of a lullaby, the beat and rhythm of a march, the sound quality of a trumpet in a fanfare)"},{"code":"C2.3","title":"","text":"identify and give examples of their strengths and areas for growth as musical performers, creators, interpreters, and audience members (e.g., singing in unison, providing constructive feedback and suggestions for a classmate’s or guest performer’s performance)"}]},{"code":"C3","title":"Exploring Forms and Cultural Contexts","text":"demonstrate an understanding of a variety of musical genres and styles from the past and present, and their social and/or community contexts","specific":[{"code":"C3.1","title":"","text":"identify and describe musical experiences in their own lives (e.g., list the places and times within a day when they hear or perform music; describe various times when they sing, play, and move to music in school, at home, and in the community)"},{"code":"C3.2","title":"","text":"identify a variety of musical pieces from different cultures through performing and/or listening to them (e.g., folk songs, songs for celebrations, ceremonial music from Canadian and world sources)"}]}]},{"code":"D","title":"Visual Arts","why":"","overall":[{"code":"D1","title":"Creating and Presenting","text":"apply the creative process to produce a variety of two- and three-dimensional art works, using elements, principles, and techniques of visual arts to communicate feelings, ideas, and understandings","specific":[{"code":"D1.1","title":"","text":"create two- and three-dimensional works of art that express feelings and ideas inspired by personal experiences (e.g., a tempera painting that communicates their feelings about a special occasion or event such as a fair or a parade; a sculpture of a favourite musical instrument made with found objects; a watercolour painting of a favourite part of the schoolyard; an assemblage in which images and objects from home and school are used to represent special memories)"},{"code":"D1.2","title":"","text":"demonstrate an understanding of composition, using principles of design to create narrative art works or art works on a theme or topic (e.g., a drawing of an approaching storm that uses a variety of lines to create contrast [dashed, jagged, curved, spiral]; a cardboard or papier mâché sculpture of a mythical animal in a dynamic pose that uses surface materials to show a contrast in texture [fuzzy yarn; coarse, prickly sawdust])"},{"code":"D1.3","title":"","text":"use elements of design in art works to communicate ideas, messages, and personal understandings (e.g., a pattern of broken, wavy, and zigzag lines to make the bark of a tree look rough in a drawing; size and arrangement of organic shapes in a painting of flowers to create the impression that the various flowers are at different distances from the viewer)"},{"code":"D1.4","title":"","text":"use a variety of materials, tools, and techniques to respond to design challenges (e.g., drawing: use wax crayon or oil pastel lines on coloured paper to express their responses to different kinds of music or rhythm; mixed media: use torn paper and textured materials to create a landscape collage of a playground that includes a horizon line; painting: create paint resists that are made with wax crayon on paper, using rubbing plates that have a variety of textures [e.g., bumpy, wavy] to create imaginary creatures inspired by the artistic style of Eric Carle; printmaking: use cut sponge or cardboard and paint stamping to make a pattern of geometric and organic shapes; sculpture: use glued or taped scrap wood to build a wood block sculpture of an imaginary geometric machine)"}]},{"code":"D2","title":"Reflecting, Responding, and Analysing","text":"apply the critical analysis process to communicate feelings, ideas, and understandings in response to a variety of art works and art experiences","specific":[{"code":"D2.1","title":"","text":"express their feelings and ideas about art works and art experiences (e.g., describe feelings evoked by the use of colours in the painting Inside the Sugar Shack by Miyuki Tanobe or The Starry Night by Vincent van Gogh; use drama to respond to a community art work viewed during a neighbourhood walk; describe the ways in which an artist’s representation of an event relates to their own experiences)"},{"code":"D2.2","title":"","text":"explain how elements and principles of design are used to communicate meaning or understanding in their own and others’ art work (e.g., explain how repeated lines and shapes are used to depict the texture of snake, lizard, leopard, or dinosaur skin; classify images on a topic, and, focusing on a dominant element, use the images to explain that there are many different ways of approaching the same subject)"},{"code":"D2.3","title":"","text":"demonstrate an awareness of signs and symbols encountered in their daily lives and in works of art (e.g., green is associated with nature and sometimes with envy or illness in the West; red is associated with stopping [traffic lights] in the West, luck in China, success in Cherokee culture, mourning in South Africa)"},{"code":"D2.4","title":"","text":"identify and document their strengths, their interests, and areas for improvement as creators of art (e.g., discuss what they think is good about works in their art folder during conferences with their teacher; do a think-pair-share on their favourite part of one of their art works)"}]},{"code":"D3","title":"Exploring Forms and Cultural Contexts","text":"demonstrate an understanding of a variety of art forms, styles, and techniques from the past and present, and their social and/or community contexts","specific":[{"code":"D3.1","title":"","text":"identify and describe visual art forms that they see in their home, at school, in their community, and in visual arts experiences (e.g., illustrations in picture books, designs of various toys, patterns on clothing or other textiles, classroom visits by artists, student displays at their school, visits to galleries)"},{"code":"D3.2","title":"","text":"demonstrate an awareness of a variety of works of art from diverse communities, times, and places (e.g., iconic architecture they have seen either in pictures or in real life, such as the CN Tower, the Eiffel Tower, the Taj Mahal; comics from different countries; decorations or patterns on crafts or old artefacts; contemporary and ancient clay sculptures; paintings of family or community events from different cultures or from previous eras)"}]}]}]},"g2":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-arts","sourceLang":"en","strands":[{"code":"A","title":"Dance","why":"","overall":[{"code":"A1","title":"Creating and Presenting","text":"apply the creative process to the composition of simple dance phrases, using the elements of dance to communicate feelings and ideas","specific":[{"code":"A1.1","title":"","text":"develop short movement phrases inspired by a variety of activities in their community (e.g., riding a bike; movements from sports, yoga, or playground games/activities) and incorporating different pathways (e.g., straight, curvy), directions (e.g., forward, back, sideways, diagonal), and shapes (e.g., big/small shapes, shapes created individually and with partners)"},{"code":"A1.2","title":"","text":"use dance as a language to represent the main ideas in poems and stories, with a focus on body and space (e.g., use arm movements to suggest a cheering crowd; use a circle pathway to suggest the relationship among several characters; use a smooth and delicate sequence of expanding movements to suggest a butterfly emerging from a cocoon)"},{"code":"A1.3","title":"","text":"create distinct beginnings and endings for dance phrases in a variety of ways (e.g., having a moment of silence at the beginning and end of a dance phrase; freezing at the end of a dance phrase; starting and ending in similar or contrasting shapes; dimming the lights to signal the end of a dance phrase)"},{"code":"A1.4","title":"","text":"use a variety of locomotor and non-locomotor movements to depict creatures and objects in the world around them (e.g., depict a large animal with torso, arms, and legs that creeps along at a low level; change movements to interpret the motions of various animals represented by the different musical sections of Camille Saint-Saëns’s Carnival of the Animals)"}]},{"code":"A2","title":"Reflecting, Responding, and Analysing","text":"apply the critical analysis process to communicate their feelings, ideas, and understandings in response to a variety of dance pieces and experiences","specific":[{"code":"A2.1","title":"","text":"describe the similarities between their own dance phrases and those of others (e.g., similarities in the shapes, pathways, levels, and locomotor or non-locomotor movements used in one another’s dance phrases)"},{"code":"A2.2","title":"","text":"identify, using dance vocabulary, the elements of dance in their own dance phrases and those of others, and describe how each element is used to communicate meaning (e.g., describe how various aspects of body [shapes, body parts, locomotor and non-locomotor movements] and space [levels, direction] are used to depict crashing waves)"},{"code":"A2.3","title":"","text":"identify and give examples of their strengths and areas for growth as dance creators and audience members (e.g., describe to a partner what they do well; identify specific movements, stops, and turns that were effective in their dance)"}]},{"code":"A3","title":"Exploring Forms and Cultural Contexts","text":"demonstrate an understanding of a variety of dance forms and styles from the past and present, and their social and/or community contexts","specific":[{"code":"A3.1","title":"","text":"describe, with teacher guidance, a variety of dances from communities around the world that they have seen in the media, at live performances and social gatherings, or in the classroom (e.g., folk dances, ceremonial dances, dances of worship, theatrical dances, social dances)"},{"code":"A3.2","title":"","text":"identify various reasons why people dance in daily life and various contexts in which they do so (e.g., to socialize [Bangra], to dance for the earth [at powwows], to celebrate [Jewish wedding ritual], for exercise [hip hop], to tell stories [ballet], to relate history [West African dance])"}]}]},{"code":"B","title":"Drama","why":"","overall":[{"code":"B1","title":"Creating and Presenting","text":"apply the creative process to dramatic play and process drama, using the elements and conventions of drama to communicate feelings, ideas, and stories","specific":[{"code":"B1.1","title":"","text":"engage in dramatic play and role play, with a focus on exploring main ideas and central characters in stories from diverse communities, times, and places (e.g., retell and enact a story from different points of view; stop at a dramatic point in a story and adopt roles of the characters in the story; enact a scene between characters in a fairy-tale kingdom, animals in the tundra, or neighbours in a back alley)"},{"code":"B1.2","title":"","text":"demonstrate an understanding of the element of role by communicating thoughts, feelings, and perspectives appropriate to the role being played (e.g., devise and share a group mime showing how characters respond to the tension in a situation of conflict, departure, or anticipation; use voice expressively to convey an interpretation of a character’s attitude)"},{"code":"B1.3","title":"","text":"plan and shape the direction of a dramatic play or role play, building on their own and others’ ideas both in and out of role, with support (e.g., In role: respond to a scientist [roleplayed by the teacher] who says the class must give up their pet dinosaur because it poses a safety hazard; Out of role: use conventions such as discussion and/or guided imagery to establish the setting, context, and characters for a drama activity)"},{"code":"B1.4","title":"","text":"communicate feelings and ideas to a familiar audience (e.g., classmates), using several simple visual or technological aids to support and enhance their drama work (e.g., act out a familiar story using props instead of words; dim lights to create a spooky mood; use simple objects or props such as fur or feathers to indicate animal or bird characters in an Aboriginal story)"}]},{"code":"B2","title":"Reflecting, Responding, and Analysing","text":"apply the critical analysis process to communicate feelings, ideas, and understandings in response to a variety of drama works and experiences","specific":[{"code":"B2.1","title":"","text":"express thoughts, feelings, and ideas about drama experiences and performances in a variety of ways (e.g., use a journal response, a think-pair-share activity, visual art work, or a drama convention such as role on the wall to explore both the inner thoughts and feelings of the character and the perspectives of others who know the character)"},{"code":"B2.2","title":"","text":"identify, using drama terminology, the elements and conventions of drama used in shared drama experiences and theatre and describe how they help communicate ideas and feelings and create interest (e.g., as a class create a checklist of the elements in a drama and what each element contributes and helps communicate; use a tableau to share a moment of importance in the story)"},{"code":"B2.3","title":"","text":"identify and give examples of their strengths, interests, and areas for improvement as drama participants and audience members (e.g., identify the goals they had in presenting a drama work and communicate how they achieved those goals; generate multiple ideas for improvement in a mapping activity or experiential play experience)"}]},{"code":"B3","title":"Exploring Forms and Cultural Contexts","text":"demonstrate an understanding of a variety of drama and theatre forms and styles from the past and present, and their social and/or community contexts","specific":[{"code":"B3.1","title":"","text":"identify and describe a variety of drama and theatre forms they experience in their home, school, and community, and in the media (e.g., favourite television, film, computer programs; favourite play roles; playing with puppets to enact real-life scenarios; attending plays; listening to stories about family and community traditions)"},{"code":"B3.2","title":"","text":"demonstrate an awareness of some drama and theatre traditions of communities around the world (e.g., describe experiences with festivals, pageants, circuses; explain the use of special objects in ceremonies or celebrations; give examples of the use of a narrator in plays or street theatre)"}]}]},{"code":"C","title":"Music","why":"","overall":[{"code":"C1","title":"Creating and Performing","text":"apply the creative process to create and perform music for a variety of purposes, using the elements and techniques of music","specific":[{"code":"C1.1","title":"","text":"sing unison songs in tune and/or play simple melodies and accompaniments for music from a wide variety of cultures, styles, and historical periods (e.g., perform a simple three-note melodic ostinato to support a melody)"},{"code":"C1.2","title":"","text":"apply the elements of music when singing, playing an instrument, and moving (e.g., pitch: move the body to show how individual pitches go up, go down, or stay the same, and how they connect to form a melody)"},{"code":"C1.3","title":"","text":"create simple compositions for a specific purpose and a familiar audience (e.g., create accompaniments for songs, stories, or poems; create a simple song using the notes “mi”, “so”, and “la”, or the notes of a pentatonic scale)"},{"code":"C1.4","title":"","text":"use the tools and techniques of musicianship in musical performances (e.g., use controlled breathing and relaxed but straight posture when singing; show awareness of proper playing technique when playing instruments; match pitches within an accessible vocal range; clap back rhythms accurately while keeping a steady beat)"},{"code":"C1.5","title":"","text":"use symbols to represent sounds and sounds to represent musical symbols (e.g., match short melody maps with the corresponding phrases in a song; use rhythm syllables such as “ta ti-ti” to represent note values orally)"}]},{"code":"C2","title":"Reflecting, Responding, and Analysing","text":"apply the critical analysis process to communicate their feelings, ideas, and understandings in response to a variety of music and musical experiences","specific":[{"code":"C2.1","title":"","text":"express personal responses to musical performances in a variety of ways (e.g., use a teacher-directed listening log to record their thoughts, feelings, ideas; write or draw their response)"},{"code":"C2.2","title":"","text":"describe ways in which the elements of music are used for different purposes in the music they perform, listen to, and create (e.g., duration: an increase in tempo to indicate excitement; dynamics: a decrease in volume to create a feeling of relaxation in the music; timbre: the sound quality of a particular instrument to create a particular mood)"},{"code":"C2.3","title":"","text":"identify and give examples of their strengths and areas for growth as musical performers, creators, interpreters, and audience members (e.g., share with a partner what they did well during the last performance, using musical vocabulary)"}]},{"code":"C3","title":"Exploring Forms and Cultural Contexts","text":"demonstrate an understanding of a variety of musical genres and styles from the past and present, and their social and/or community contexts","specific":[{"code":"C3.1","title":"","text":"identify reasons why people make music in their daily lives (e.g., people sing songs that have special meaning in their family; children can use music to promote environmental awareness at school), and describe contexts in which they make music (e.g., family gatherings, seasonal celebrations)"},{"code":"C3.2","title":"","text":"identify, through performing and/or listening, a variety of musical forms or pieces from different communities, times, and places (e.g., “O Canada”, an Iroquoian lullaby, Indian classical music, Obwisana from Ghana)"}]}]},{"code":"D","title":"Visual Arts","why":"","overall":[{"code":"D1","title":"Creating and Presenting","text":"apply the creative process to produce a variety of two- and three-dimensional art works, using elements, principles, and techniques of visual arts to communicate feelings, ideas, and understandings","specific":[{"code":"D1.1","title":"","text":"create two- and three-dimensional works of art that express feelings and ideas inspired by activities in their community or observations of nature (e.g., a streetscape collage with children playing, made with paint, pastel, and various kinds of paper [newspaper, magazines]; small glue-line prints in which a variety of curvy and pointy lines show illusory texture or represent a pattern they have seen on insects in the schoolyard or garden)"},{"code":"D1.2","title":"","text":"demonstrate an understanding of composition, using principles of design to create narrative art works or art works on a theme or topic (e.g., use repetition of colour throughout an image that communicates a story; create a painting or series of stamp prints, showing depth, perspective, and contrast of pattern by overlapping fish and vegetation of different sizes and shapes)"},{"code":"D1.3","title":"","text":"use elements of design in art works to communicate ideas, messages, and understandings (e.g., use tints of a colour to create light areas for emphasis in a collaborative mural of favourite places in the neighbourhood; use a simple action pose to modify form in a sculpture of a pet or other animal made with modelling clay)"},{"code":"D1.4","title":"","text":"use a variety of materials, tools, and techniques to respond to design challenges (e.g., drawing: make marker or coloured-pencil drawings of trees that are close and far away, using contrasts in size and placement on the paper to show depth of space, and basing the drawings on observations of real trees and trees in a variety of art works [e.g., works by Emily Carr or Tom Thomson]; mixed media: use acrylic paint over textured materials [e.g., burlap, cardboard] to make expressive organic shapes, using a combination of traditional techniques [blending, glazing, sgraffito, scumbling, impasto] and experimental techniques [use of sponges, fingers, sticks, twigs, feathers, masking tape]; painting: make a tempera painting depicting friends playing playground games, using a limited palette of colours; printmaking: make a print of a motif for a storybook about dinosaurs, using polystyrene plate stamps or modelling-clay imprints of dinosaurs and plants; sculpture: make insect shapes and habitat features, using wood, twigs, raffia, corn husks, and other natural materials, to explore science concepts)"}]},{"code":"D2","title":"Reflecting, Responding, and Analysing","text":"apply the critical analysis process to communicate feelings, ideas, and understandings in response to a variety of art works and art experiences","specific":[{"code":"D2.1","title":"","text":"express their feelings and ideas about works of art (e.g., explain why they prefer a work by one artist over another; explain to a partner how well an art work reflects their personal knowledge and prior experience)"},{"code":"D2.2","title":"","text":"explain how elements and principles of design are used to communicate meaning or understanding in their own and others’ art work (e.g., use of different colours for achieving different effects, such as warm, sunny colours for a beach or cool colours for a wet forest; depiction of various textures, such as rough tree bark, smooth plastics, and ridged corduroy; elaboration and variation to create variety in otherwise symmetrical buildings)"},{"code":"D2.3","title":"","text":"demonstrate an awareness of signs and symbols encountered in their daily lives and in works of art (e.g., symbols and shapes related to school, travel, and the arts; sports or institutional logos; symbols from art works or heritage crafts of family or community significance)"},{"code":"D2.4","title":"","text":"identify and document their strengths, their interests, and areas for improvement as creators of art (e.g., identify what is interesting about a work they have produced; identify what they feel they have done well and what they would do differently next time to improve)"}]},{"code":"D3","title":"Exploring Forms and Cultural Contexts","text":"demonstrate an understanding of a variety of art forms, styles, and techniques from the past and present, and their social and/or community contexts","specific":[{"code":"D3.1","title":"","text":"identify and describe a variety of visual art forms they see in their home, at school, in their community, and in visual arts experiences (e.g., design of everyday items; picture books; artists-in-education; community art works, such as public sculpture, architecture, and murals; Aboriginal designs in dancing regalia; art works in student art exhibitions and community art festivals)"},{"code":"D3.2","title":"","text":"demonstrate an awareness of a variety of works of art and artistic traditions from diverse communities, times, and places (e.g., depictions of nature, of people doing things together, or of people at work; miniature paintings from India; Aboriginal textiles, ceramics, and petroglyphs; contemporary Inuit drawings of life in the North by Annie Pootoogook)"}]}]}]},"g3":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-arts","sourceLang":"en","strands":[{"code":"A","title":"Dance","why":"","overall":[{"code":"A1","title":"Creating and Presenting","text":"apply the creative process to the composition of dance phrases, using the elements of dance to communicate feelings and ideas","specific":[{"code":"A1.1","title":"","text":"imitate movements found in their natural environment in a variety of ways and incorporate them into a dance phrase (e.g., modify the movements of animals, snow falling to the ground, ice melting, plants growing; connect a series of insect-like movements together to make a phrase)"},{"code":"A1.2","title":"","text":"use dance as a language to represent ideas from diverse literature sources, with a focus on time and energy (e.g., interpret stories, poems, and texts from other subject areas through dance; respond to a story about insects by depicting the sustained lifting and pulling actions of ants versus the sustained floating actions of butterflies)"},{"code":"A1.3","title":"","text":"create dance phrases using a variety of pattern forms (e.g., create dances with distinct, self-contained sections that share movement qualities using AB form, ABA form, or ABBA form; demonstrate a pattern physically by making “A” a soft and fluid section and “B” a fast and percussive section)"},{"code":"A1.4","title":"","text":"demonstrate how dance elements can be used to create and expand the movement vocabulary within different sections of a larger pattern (e.g., A: varying the use of space while marching quickly; B: changing levels while waving arms slowly; A: varying locomotor and non-locomotor percussive movements while marching quickly)"}]},{"code":"A2","title":"Reflecting, Responding, and Analysing","text":"apply the critical analysis process to communicate their feelings, ideas, and understandings in response to a variety of dance pieces and experiences","specific":[{"code":"A2.1","title":"","text":"demonstrate an understanding of how the elements of dance can be used in their own and others’ dance phrases to illustrate or explore learning in other subject areas (e.g., show and explain how the elements of body and relationship can be used to depict the science concept of magnetic attraction)"},{"code":"A2.2","title":"","text":"identify, using dance vocabulary, the elements of dance used in their own and others’ dance phrases and explain their purpose (e.g., the use of body, space, time, and energy to create variety and interest; the use of levels, relationship, pathways, and shape to emphasize a mood; the use of canon, direction, grouping contrast, and repetition to explore pattern)"},{"code":"A2.3","title":"","text":"identify and give examples of their strengths and areas for growth as dance creators and audience members (e.g., share with a partner what they did well; write in a journal about what they need to improve)"}]},{"code":"A3","title":"Exploring Forms and Cultural Contexts","text":"demonstrate an understanding of a variety of dance forms and styles from the past and present, and their social and/or community contexts","specific":[{"code":"A3.1","title":"","text":"describe, with teacher guidance, a variety of dances from communities in Canada and around the world that they have seen in the media, at live performances and social gatherings, or in the classroom (e.g., dance numbers in animated movie musicals such as Happy Feet and Ice Age; First Nation dances at a powwow; folk dances of the early settlers; the farandole of France)"},{"code":"A3.2","title":"","text":"identify and describe the role of dance in the community (e.g., performances as entertainment; community dances as a way of socializing; traditional dances as a way of maintaining cultural connectedness; dance classes for learning and communicating)"}]}]},{"code":"B","title":"Drama","why":"","overall":[{"code":"B1","title":"Creating and Presenting","text":"apply the creative process to dramatic play and process drama, using the elements and conventions of drama to communicate feelings, ideas, and stories","specific":[{"code":"B1.1","title":"","text":"engage in dramatic play and role play, with a focus on exploring themes, ideas, characters, and issues from imagination or in stories from diverse communities, times, and places (e.g., act out moments from “a day in the life” of a main character from a story; improvise a short dialogue between two characters who are seeking a solution to a problem [as in Aboriginal teacher/trickster stories])"},{"code":"B1.2","title":"","text":"demonstrate an understanding of how the element of time and place can support the development of role (e.g., present tableaux, with transitions and thought tracking, that show differences between urban and rural settings and/or lifestyles to convey information about the characters)"},{"code":"B1.3","title":"","text":"plan and shape the direction of a dramatic play or role play by building on their own and others’ ideas, both in and out of role (e.g., In role: respond in role to extend the developing storyline in the drama [as townsfolk, plead with the mayor to save their town]; Out of role: in partners or small groups, combine their ideas to create a plan for how the characters will solve the problem in the drama)"},{"code":"B1.4","title":"","text":"communicate feelings and ideas to a familiar audience (e.g., classmates) using audio, visual, and/or technological aids to support or enhance their drama work (e.g., use items found in the classroom to create a feeling or a mood suggested by the teacher; use sound effects or music to create an element of surprise or tension)"}]},{"code":"B2","title":"Reflecting, Responding, and Analysing","text":"apply the critical analysis process to communicate feelings, ideas, and understandings in response to a variety of drama works and experiences","specific":[{"code":"B2.1","title":"","text":"express thoughts, feelings, and ideas about a variety of drama experiences and performances (e.g., in a journal response, in a think-pair-share activity, in class discussion, by writing in role, in a four corners activity, in a small group improvisation or drawing)"},{"code":"B2.2","title":"","text":"describe, using drama terminology, how elements and conventions of drama are used to shape their own and others’ work (e.g., describe how different characters’ actions help create suspense or tension; identify effective elements in a drama presentation; explain how setting highlights theme)"},{"code":"B2.3","title":"","text":"identify and give examples of their strengths, interests, and areas for growth as drama participants and audience members (e.g., describe how their understanding of role play is developing; identify a role they would like to play, and explain why)"}]},{"code":"B3","title":"Exploring Forms and Cultural Contexts","text":"demonstrate an understanding of a variety of drama and theatre forms and styles from the past and present, and their social and/or community contexts.","specific":[{"code":"B3.1","title":"","text":"identify some distinct stylistic features of a few drama and theatre forms they experience in their home, school, and community, and in the media (e.g., puppet shows and mask plays use easily recognizable character types to tell a story; actors in live theatre productions use exaggerated gestures and reactions designed to project beyond the footlights; street festivals use amplified live and/or recorded music, costumes, emcees, and amplified announcements to celebrate special events; clown acts use mime featuring clumsy gestures and comical accidents)"},{"code":"B3.2","title":"","text":"demonstrate an awareness of ideas and emotions expressed in drama works from communities around the world (e.g., ideas about friendship or loyalty or power or perseverance in dramas based on fairy tales or myths from different countries; ethics and values found in Aboriginal plays)"}]}]},{"code":"C","title":"Music","why":"","overall":[{"code":"C1","title":"Creating and Performing","text":"apply the creative process to create and perform music for a variety of purposes, using the elements and techniques of music","specific":[{"code":"C1.1","title":"","text":"sing, in tune, unison songs, partner songs, and rounds, and/or play accompaniments from a wide variety of cultures, styles, and historical periods (e.g., sing or play an instrument accompanied by body percussion or found sounds; sing or play a rhythmic or melodic ostinato)"},{"code":"C1.2","title":"","text":"apply the elements of music when singing, playing an instrument, and moving (e.g., timbre: sort sound sources by the way their sound is produced and make choices about which instruments will play in specific sections; form: change direction in a circle to show A and B sections of a song in ABA form; duration: sing a song first very quickly then very slowly, and explain how the different tempi change their experience of the music)"},{"code":"C1.3","title":"","text":"create compositions for a specific purpose and a familiar audience (e.g., create musical accompaniments for poems, stories, or dances they have created; create rhythmic ostinati based on significant words in a poem or words from a classroom topic or theme, then play them using instruments, body percussion, or found sounds; make changes to the rhythm and/or melody in a simple song that they know)"},{"code":"C1.4","title":"","text":"use the tools and techniques of musicianship in musical performances (e.g., determine where breaths should be taken in a song; given the shape of a melody, suggest where a change in dynamics would be effective; use available technology such as software, electronic instruments, or recording devices)"},{"code":"C1.5","title":"","text":"demonstrate an understanding of standard and non-traditional musical notation (e.g., design melody maps based on the direction of the melody; demonstrate various ways of representing sounds using devised symbols; perform melodic patterns based on the notes “do”, “re”, “mi”, “so”, and “la” by using solfège hand signs; create soundscapes illustrating dynamics and timbre)"}]},{"code":"C2","title":"Reflecting, Responding, and Analysing","text":"apply the critical analysis process to communicate their feelings, ideas, and understandings in response to a variety of music and musical experiences","specific":[{"code":"C2.1","title":"","text":"express personal responses to musical performances in a variety of ways (e.g., create a graphic or text response to a musical selection featuring a Latin American dance style)"},{"code":"C2.2","title":"","text":"describe ways in which the elements of music are used in the music they perform, listen to, and create (e.g., use a Venn diagram to compare how the elements of two contrasting pieces create mood)"},{"code":"C2.3","title":"","text":"identify and give examples of their strengths and areas for growth as musical performers, creators, interpreters, and audience members (e.g., singing in tune, breathing at the end of phrases, watching the conductor or teacher while rehearsing and performing)"}]},{"code":"C3","title":"Exploring Forms and Cultural Contexts","text":"demonstrate an understanding of a variety of musical genres and styles from the past and present, and their social and/or community contexts","specific":[{"code":"C3.1","title":"","text":"identify and describe ways in which music can be used in the community (e.g., to celebrate events, to bring people together, to dance to, to communicate, to entertain, to help people remember product names or telephone numbers in advertising, to help people remember concepts)"},{"code":"C3.2","title":"","text":"identify, through performing and/or listening, a variety of musical forms or pieces from different communities, times, and places (e.g., songs, instrumental pieces, and dances in social activities or celebrations of early settlers and First Nation communities in Upper Canada)"}]}]},{"code":"D","title":"Visual Arts","why":"","overall":[{"code":"D1","title":"Creating and Presenting","text":"apply the creative process to produce a variety of two- and three-dimensional art works, using elements, principles, and techniques of visual arts to communicate feelings, ideas, and understandings","specific":[{"code":"D1.1","title":"","text":"create two- and three-dimensional works of art that express personal feelings and ideas inspired by the environment or that have the community as their subject (e.g., make a symmetrical sculpture of an insect or a flower, using natural materials such as wood, pebbles, dry seed pods, feathers; draw a picture depicting a solution to the problem of litter in their community; make a painting of nature, focusing on a feature of personal interest or meaning to themselves)"},{"code":"D1.2","title":"","text":"demonstrate an understanding of composition, using principles of design to create narrative art works or art works on a theme or topic (e.g., use shapes of various sizes, in the foreground, middle ground, and background, to create an illusion of depth [perspective] in a painting about a make-believe world; create a mural to express a response to a community celebration, using a variety of lines and shapes; using a scratchboard that has a layer of various colours covered by india ink, make a high-contrast line drawing about a story by scratching the black surface to reveal the colours beneath the surface)"},{"code":"D1.3","title":"","text":"use elements of design in art works to communicate ideas, messages, and understandings (e.g., use asymmetrical cut-paper composite shapes to depict a Canadian landscape, with a clear foreground, middle ground, and background; use colour values and shapes in a “What’s inside me?” painting in the X-ray style of Norval Morrisseau to create contrast between the inside and the outside of the figure)"},{"code":"D1.4","title":"","text":"use a variety of materials, tools, and techniques to respond to design challenges (e.g., drawing: use a variety of lines and shapes, drawn with pencil and marker, to show movement in a flipbook about weather; mixed media: use wax crayons, oil pastels, paint resist, and materials of various textures [e.g. yarn, found objects] to depict a tree or plant above ground, and use the technique of elaboration to depict what is hidden below ground; painting: create a watercolour or tempera painting of animals, using colour in a non-representational and expressive way; printmaking: paint stencil prints in warm and cool colours, creating a simplified pattern inspired by a favourite fruit; sculpture: use modelling clay to create organic forms that are inspired by nature, such as shells, seed pods, and water-worn stones, and that show some kind of metamorphosis or transformation into another form or figure)"}]},{"code":"D2","title":"Reflecting, Responding, and Analysing","text":"apply the critical analysis process to communicate feelings, ideas, and understandings in response to a variety of art works and art experiences","specific":[{"code":"D2.1","title":"","text":"express personal feelings and ideas about art experiences and images (e.g., create a poster for an exhibition, using words of different sizes and colours to show their excitement about the event; express thoughts and ideas about an art work while in role as the artist in a peer artist interview)"},{"code":"D2.2","title":"","text":"explain how elements and principles of design are used to communicate meaning or understanding in their own and others’ art work (e.g., colour value in Emily Carr’s Indian Church; organic shapes to make the monsters look less frightening and more like stuffed animals in Where the Wild Things Are by Maurice Sendak)"},{"code":"D2.3","title":"","text":"demonstrate an awareness of the meaning of signs and symbols encountered in their daily lives and in works of art (e.g., fonts or logos that remind them of specific companies, messages, or moods; the meaning of animals such as the orca in Aboriginal clan symbols or the Inukshuk in Aboriginal art)"},{"code":"D2.4","title":"","text":"identify and document their strengths, their interests, and areas for improvement as creators of art (e.g., keep an art journal to record what they think they have done well in their art works, or learned about in their art works, as they complete them; use the strategy of matching word and image to share their feelings about an art work or its creation)"}]},{"code":"D3","title":"Exploring Forms and Cultural Contexts","text":"demonstrate an understanding of a variety of art forms, styles, and techniques from the past and present, and their social and/or community contexts","specific":[{"code":"D3.1","title":"","text":"identify and describe a variety of visual art forms they see in their home, at school, in the community, and in visual arts experiences (e.g., original paintings at a community gallery, sculptures in a local park, art reproductions in offices, murals or sculptural monuments in the community, mixed media art works at arts festivals)"},{"code":"D3.2","title":"","text":"demonstrate an awareness of a variety of works of art and artistic traditions from diverse communities, times, and places (e.g., a picture book that tells a story about people and the time and place in which they work, play, and build their community; George Littlechild’s book This Land Is My Land; Daphne Odjig’s historical mural The Indian in Transition; Jacob Lawrence’s paintings of African-Americans working, playing, and interacting; classical Greek sculptures of sports figures, and contemporary sports sculptures, such as the fans in Michael Snow’s The Audience)"}]}]}]},"g4":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-arts","sourceLang":"en","strands":[{"code":"A","title":"Dance","why":"","overall":[{"code":"A1","title":"Creating and Presenting","text":"apply the creative process to the composition of movement sequences and short dance pieces, using the elements of dance to communicate feelings and ideas;","specific":[{"code":"A1.1","title":"","text":"translate into dance a variety of movement sequences observed in nature (e.g., wind developing into a tornado; water freezing and melting on a landscape; rain transforming into a storm; a caterpillar evolving into a butterfly)"},{"code":"A1.2","title":"","text":"use dance as a language to explore and communicate ideas derived from a variety of literature sources (e.g., develop dance movements based on actions or emotions depicted in myths, short stories, legends from different cultures, picture books, or poetry)"},{"code":"A1.3","title":"","text":"use narrative form to create short dance pieces on a variety of themes (e.g., a dance based on the theme of a quest or other type of journey; movements arranged [choreographed] to create a relationship [linking, parting] between some of the dancers)"},{"code":"A1.4","title":"","text":"use the elements of energy (e.g., collapse, explode, float) and time (e.g., duration, suddenness) in a dance piece to communicate an idea (e.g., show the journey of a balloon as it floats, explodes suddenly, and then collapses back to the floor)"}]},{"code":"A2","title":"Reflecting, Responding, and Analysing","text":"apply the critical analysis process to communicate their feelings, ideas, and understandings in response to a variety of dance pieces and experiences","specific":[{"code":"A2.1","title":"","text":"demonstrate an understanding of how the language of dance can clarify and highlight ideas, images, and characters from familiar stories (e.g., explain how gestures and actions reveal and express the mood or personality or social position of a character)"},{"code":"A2.2","title":"","text":"identify, using dance vocabulary, the elements of dance used in their own and others’ dance pieces and explain how each helps communicate ideas and feelings (e.g., symmetry/asymmetry [body] can reflect themes of unity and separation; sudden and sustained movements used sequentially can communicate the idea of a thunderstorm)"},{"code":"A2.3","title":"","text":"identify and give examples of their strengths and areas for growth as dance creators and audience members (e.g., share with a small group what they did well, using dance terminology; explain what they need to practise to improve their ability to communicate through gesture and action)"}]},{"code":"A3","title":"Exploring Forms and Cultural Contexts","text":"demonstrate an understanding of a variety of dance forms, traditions, and styles from the past and present, and their sociocultural and historical contexts","specific":[{"code":"A3.1","title":"","text":"describe, with teacher guidance, how forms and styles of dance reflect people’s different social and political roles in various communities, times, and places (e.g., court dances in different countries in the 1500s and 1600s reflect the customs of the upper class [kings, queens, and people of the court] while country dances reflect the customs of the common people; carnival dances in Toronto, Brazil, New Orleans, and Cuba reflect various cultural traditions; martial arts disguised as capoeira dance reflects a response to oppression)"},{"code":"A3.2","title":"","text":"identify and describe the different roles of dance in their lives and in communities around the world (e.g., to socialize; for entertainment; to communicate and tell stories; to enrich the school experience [through a dance club]; to celebrate a good harvest year; as part of religious ceremonies)"}]}]},{"code":"B","title":"Drama","why":"","overall":[{"code":"B1","title":"Creating and Presenting","text":"apply the creative process to dramatic play and process drama, using the elements and conventions of drama to communicate feelings, ideas, and stories","specific":[{"code":"B1.1","title":"","text":"engage actively in drama exploration and role play, with a focus on exploring drama structures, key ideas, and pivotal moments in their own stories and stories from diverse communities, times, and places (e.g., use role play to explore the hierarchical structure of medieval society; use “inner and outer circle” to examine moments of conflict and power imbalance in group improvisations on a common theme)"},{"code":"B1.2","title":"","text":"demonstrate an understanding of the element of role by selectively using a few other elements of drama (e.g., time and place; relationship; focus and emphasis) to build belief in a role and establish its dramatic context"},{"code":"B1.3","title":"","text":"plan and shape the direction of the drama or role play by posing questions and working with others to find solutions, both in and out of role (e.g., In role: improvise possible solutions to a problem; Out of role: help select a drama form to represent the group’s idea)"},{"code":"B1.4","title":"","text":"communicate thoughts, feelings, and ideas to a specific audience, using audio, visual, and/or technological aids to enhance their drama work (e.g., use dimmed lights, black lights, and music to suggest a mood; project images with an overhead/data projector; use a microphone to enhance or create sound effects or amplify narration [such as a spirit communication in an Aboriginal story])"}]},{"code":"B2","title":"Reflecting, Responding, and Analysing","text":"apply the critical analysis process to communicate feelings, ideas, and understandings in response to a variety of drama works and experiences","specific":[{"code":"B2.1","title":"","text":"express personal responses and make connections to characters, themes, and issues presented in their own and others’ drama works (e.g., make a mural or map to explore the setting of the drama; interview a partner in and out of role to discover physical and personality traits of a character; write a diary entry describing the relationship between two fictitious characters)"},{"code":"B2.2","title":"","text":"explain, using drama terminology, how elements and drama conventions are used to produce specific effects and/or audience responses in their own and others’ drama works (e.g., characters’ differing points of view can be used to create tension; comic characters and scenes can help relieve tension; thought tracking can give insight into a character)"},{"code":"B2.3","title":"","text":"identify and give examples of their strengths, interests, and areas for growth as drama participants and audience members (e.g., strength: using expressive gestures to communicate; interest: creative use of props and costumes; area for growth: maintaining focus in role)"}]},{"code":"B3","title":"Exploring Forms and Cultural Contexts","text":"demonstrate an understanding of a variety of drama and theatre forms, traditions, and styles from the past and present, and their sociocultural and historical contexts","specific":[{"code":"B3.1","title":"","text":"identify and describe some similarities in the purposes of process drama and more formal, traditional theatre productions (e.g., both forms use the elements of drama to tell stories, to allow the audience to imagine the possible outcomes and implications of human actions, and to engage the emotions of actors and audience)"},{"code":"B3.2","title":"","text":"demonstrate an awareness of different kinds of drama and theatre from different times and places and of how they reflect their contexts (e.g., popular contemporary forms such as films or television shows and public processions and spectacles; historical forms such as medieval tournaments; oral storytelling by troubadours in earlier times and in contemporary contexts; travelling plays or pageants)"}]}]},{"code":"C","title":"Music","why":"","overall":[{"code":"C1","title":"Creating and Performing","text":"apply the creative process to create and perform music for a variety of purposes, using the elements and techniques of music","specific":[{"code":"C1.1","title":"","text":"sing and/or play, in tune, from musical notation, unison and two-part music with simple accompaniments from a wide variety of cultures, styles, and historical periods (e.g., perform folk songs with syncopation and traditional songs with a simple harmony part)"},{"code":"C1.2","title":"","text":"apply the elements of music when singing and/or playing, composing, and arranging music to create a specific effect (e.g., compose pieces using different expressive controls, such as staccato/legato or crescendo/decrescendo, to create contrasts and changes in mood; compose a pentatonic melody for recorder or voice with a bordun for an accompaniment)"},{"code":"C1.3","title":"","text":"create musical compositions for specific purposes and audiences (e.g., write a composition for recorder using musical notation on the five-line staff; compose a piece using non-traditional notation, such as a melody map or icons; compose a soundscape to represent the physical landscape of Canada; create a composition to accompany a dance piece)"},{"code":"C1.4","title":"","text":"use the tools and techniques of musicianship in musical performances (e.g., sing “O Canada” using controlled breathing technique and relaxed and straight posture while producing a clear and open head tone in their vocal range; play the xylophone using proper mallet technique)"},{"code":"C1.5","title":"","text":"demonstrate an understanding of musical signs and standard notation on the five-line staff, and use devised notation to record the sequence of sounds in a composition of their own (e.g., create a soundscape with other students or a melody map using their own symbols; include fermata and sudden changes in dynamics in their compositions; use a system of syllables, numbers, or letters to represent simple pitch notation in a composition)"}]},{"code":"C2","title":"Reflecting, Responding, and Analysing","text":"apply the critical analysis process to communicate their feelings, ideas, and understandings in response to a variety of music and musical experiences","specific":[{"code":"C2.1","title":"","text":"express detailed personal responses to musical performances in a variety of ways (e.g., respond by drawing, moving, using visual organizers, telling a story, making a collage; compare recordings of singers they think have a “good voice”, and defend their preference)"},{"code":"C2.2","title":"","text":"identify the elements used in the music they perform, listen to, and create, and describe how they are used (e.g., identify the mood of a piece and describe how the elements of music are used to create the mood)"},{"code":"C2.3","title":"","text":"identify and give examples of their strengths and areas for growth as musical performers, creators, interpreters, and audience members (e.g., identify two musical qualities that were effective in their group’s performance and one area for improvement)"}]},{"code":"C3","title":"Exploring Forms and Cultural Contexts","text":"demonstrate an understanding of a variety of musical genres and styles from the past and present, and their sociocultural and historical contexts","specific":[{"code":"C3.1","title":"","text":"identify the role of music in a community today and compare it to its role in a community of the past (e.g., music for gatherings now and in the Middle Ages; songs sung now and by the voyageurs)"},{"code":"C3.2","title":"","text":"demonstrate an awareness, through listening, of the characteristics of musical forms and traditions of diverse times, places, and communities (e.g., medieval musical genres performed by troubadours or minstrels, Indian classical music, music in Islamic cultures, music performed by female musical artists in North American culture, Aboriginal powwow music)"}]}]},{"code":"D","title":"Visual Arts","why":"","overall":[{"code":"D1","title":"Creating and Presenting","text":"apply the creative process to produce a variety of two- and three-dimensional art works, using elements, principles, and techniques of visual arts to communicate feelings, ideas, and understandings","specific":[{"code":"D1.1","title":"","text":"create two- and three-dimensional works of art that express feelings and ideas inspired by their interests and experiences (e.g., a comic strip or a storyboard featuring a space voyage; an oil pastel drawing of peers in sports or dance poses; a painted still life of objects related to a hobby)"},{"code":"D1.2","title":"","text":"demonstrate an understanding of composition, using selected principles of design to create narrative art works or art works on a theme or topic (e.g., a collaborative mural depicting a historical or an imaginary landscape in which objects and figures placed in the foreground create areas of emphasis, and objects placed in the background show diminishing size; a relief print of a seascape in which shapes that are similar, but are different in size or colour, give the work both unity and variety)"},{"code":"D1.3","title":"","text":"use elements of design in art works to communicate ideas, messages, and understandings (e.g., create a poster using colour and cropping of space to propose a solution to climate change; use contour lines of various weights in a charcoal gesture drawing of a person to capture the impression of movement; create a paper sculpture portrait of a favourite comic character that explores positive and negative space, using techniques of folding, scoring, fringing, and crimping)"},{"code":"D1.4","title":"","text":"use a variety of materials, tools, and techniques to determine solutions to design challenges (e.g., drawing: make contour drawings of overlapping objects that are easily recognizable [e.g., a piece of fruit, a shoe, a glove, a pitcher], using soft graphite drawing pencils [e.g., primary printers] and depicting the objects from different points of view [e.g., from the front, the back, the side]; mixed media: make a collage to depict a dream, using cut and torn paper, tissue paper, and found objects in contrasting shapes with a focus on positive and negative space; painting: use tempera paint and a range of monochromatic colour values to represent the emotional state of a character at a critical moment in a story that they have written or read; printmaking: use low-relief found objects [e.g., lace, textured leaves, and tin foil] to make a collograph in which texture and shape are used to create the composition, and embellish the final inked print with oil-pastel drawing; sculpture: make a clay or papier mâché mask featuring exaggeration for dramatic effect and textures made by embossing, piercing, pinching, pressing, and/or scraping)"}]},{"code":"D2","title":"Reflecting, Responding, and Analysing","text":"apply the critical analysis process to communicate feelings, ideas, and understandings in response to a variety of art works and art experiences","specific":[{"code":"D2.1","title":"","text":"interpret a variety of art works, and identify the feelings, issues, themes, and social concerns that they convey (e.g., express their response to student drawings on a classroom gallery walk; identify artistic techniques that are used to influence the viewer; in role as a famous artist, write a journal entry or letter identifying the artist’s compositional choices and intentions)"},{"code":"D2.2","title":"","text":"analyse the use of elements and principles of design in a variety of art works, and explain how they are used to communicate meaning or understanding (e.g., the use of texture and negative space in Henry Moore’s abstract forms to suggest natural objects or figures; the use of tints and shades to explore vivid colour in Alma Thomas’s aerial view paintings; the use of bright colours and rounded shapes in children’s advertising to get their attention and convey a friendly feeling)"},{"code":"D2.3","title":"","text":"demonstrate awareness of the meaning of signs, symbols, and styles in works of art (e.g., symbols representing luck; fonts typically used in marketing; heraldic symbols; aboriginal totems around the world; Egyptian hieroglyphics)"},{"code":"D2.4","title":"","text":"identify and document their strengths, their interests, and areas for improvement as creators and viewers of art (e.g., review notes and sketches they have made during a visit to a public gallery, and summarize what tends to interest them when they look at art; after a classroom gallery walk, identify what they think are the most useful of the comments and suggestions that their classmates had written on sticky notes and placed on their art work)"}]},{"code":"D3","title":"Exploring Forms and Cultural Contexts","text":"demonstrate an understanding of a variety of art forms, styles, and techniques from the past and present, and their sociocultural and historical contexts","specific":[{"code":"D3.1","title":"","text":"describe how visual art forms and styles represent various messages and contexts in the past and present (e.g., images that promote businesses, events, or festivals; paintings in art galleries that enrich, challenge, and engage viewers; picture books and graphic novels that inform and entertain; traditional and contemporary purposes of Aboriginal sculpture)"},{"code":"D3.2","title":"","text":"demonstrate an awareness of a variety of art forms, styles, and traditions, and describe how they reflect the diverse cultures, times, and places in which they were made (e.g., wax-resist batik as a national art form in Indonesia; masks used in the celebrations of various cultures; symbols, motifs, and designs on totem poles; radial symmetry in patterns in Islamic art; contemporary and historical oil paintings in an art gallery)"}]}]}]},"g5":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-arts","sourceLang":"en","strands":[{"code":"A","title":"Dance","why":"","overall":[{"code":"A1","title":"Creating and Presenting","text":"apply the creative process to the composition of movement sequences and short dance pieces, using the elements of dance to communicate feelings and ideas","specific":[{"code":"A1.1","title":"","text":"translate into movement sequences a variety of images and ideas from other classroom subjects, including the arts (e.g., portray the character of a young, boisterous child from a drama by using a variety of levels, quick movements, and indirect pathways in dance; develop movement phrases based on an image from a history textbook, a newspaper article, an Aboriginal story, or a painting in visual arts class)"},{"code":"A1.2","title":"","text":"use dance as a language to explore, interpret, and communicate ideas derived from a variety of literature sources (e.g., newspaper articles about sports, entertainment, or current events; stories, poems, picture books)"},{"code":"A1.3","title":"","text":"use movement in the choreographic form call and response in a variety of ways when creating dance pieces (e.g., the teacher performs or calls a movement and the whole class responds; one student calls and the rest of the group responds; in partners, one student leads the movement and the other mirrors it)"},{"code":"A1.4","title":"","text":"use the element of relationship in short dance pieces to communicate an idea (e.g., two dancers coming face to face to show either shared understanding or disagreement; a group of dancers holding hands to show unity)"}]},{"code":"A2","title":"Reflecting, Responding, and Analysing","text":"apply the critical analysis process to communicate their feelings, ideas, and understandings in response to a variety of dance pieces and experiences","specific":[{"code":"A2.1","title":"","text":"relate stories and characters in their own and others’ dance pieces to personal knowledge and experience (e.g., explain and demonstrate how dancers’ postures and mannerisms reflect things they have observed in everyday life; describe how the dance informed, moved, or changed their own perspective on an issue)"},{"code":"A2.2","title":"","text":"identify the elements of dance used in their own and others’ dance pieces and explain how they help communicate a message (e.g., describe their use of a high level, direct path, and strong movements to portray authority)"},{"code":"A2.3","title":"","text":"identify and give examples of their strengths and areas for growth as dance creators and audience members (e.g., identify two dance phrases that they believe were effective in their performance and explain their reasons for thinking so; assess whether they responded well to peer feedback about a performance and whether they implemented it)"}]},{"code":"A3","title":"Exploring Forms and Cultural Contexts","text":"demonstrate an understanding of a variety of dance forms, traditions, and styles from the past and present, and their sociocultural and historical contexts","specific":[{"code":"A3.1","title":"","text":"describe, with teacher guidance, dance forms and styles that reflect the beliefs and traditions of diverse communities, times, and places (e.g., choral dance was used to honour the god Dionysus, who was revered in ancient Greece; ballet developed to entertain the aristocracy in European courts; group and partner dances – such as the swing and the salsa – reflect various types of social interaction; dance has a symbolic celebratory role in African-American wedding rituals)"},{"code":"A3.2","title":"","text":"identify and describe some of the ways in which dance influences popular culture (e.g., the influence of hip hop dance on people’s mannerisms and behaviour, or on fashion, magazines, and music videos)"}]}]},{"code":"B","title":"Drama","why":"","overall":[{"code":"B1","title":"Creating and Presenting","text":"apply the creative process to process drama and the development of drama works, using the elements and conventions of drama to communicate feelings, ideas, and stories","specific":[{"code":"B1.1","title":"","text":"engage actively in drama exploration and role play, with a focus on examining issues and themes in fiction and non-fiction sources from diverse communities, times, and places (e.g., interview story characters who represent opposing views on an issue; use role play to explore social issues related to topics such as the environment, immigration, bullying, treaties, the rights and responsibilities of the child)"},{"code":"B1.2","title":"","text":"demonstrate an understanding of the element of role by selectively using some other elements of drama (e.g., time and place, relationship), to build belief in a role and establish its dramatic context (e.g., select and use supporting artefacts or simple props; arrange furniture to establish setting; work with others to select or create objects to build a convincing setting, such as a character’s room or the inside of a cave; use the drama convention of thought tracking to establish a relationship between two characters)"},{"code":"B1.3","title":"","text":"plan and shape the direction of the drama or role play by collaborating with others to develop ideas, both in and out of role (e.g., In role: improvise possible solutions to a dramatic conflict based on ideas from discussion and personal experience; Out of role: brainstorm in a group to generate ideas and make artistic choices)"},{"code":"B1.4","title":"","text":"communicate thoughts, feelings, and ideas to a specific audience, using audio, visual, and/or technological aids to achieve specific dramatic effects (e.g., shine a spotlight on a performer who is making a key point; use a clash of cymbals to highlight a pivotal moment)"}]},{"code":"B2","title":"Reflecting, Responding, and Analysing","text":"apply the critical analysis process to communicate feelings, ideas, and understandings in response to a variety of drama works and experiences","specific":[{"code":"B2.1","title":"","text":"express personal responses and make connections to characters, themes, and issues presented in their own and others’ drama works (e.g., draw a picture or write poetry to show how they see a character at the beginning and end of the drama; use journal writing to convey a feeling of connection to a character in a drama)"},{"code":"B2.2","title":"","text":"explain, using drama terminology, how different elements are used to communicate and reinforce the intended message in their own and others’ drama works (e.g., explain how specific scenes and/or relationships create tension and build up to the climax of the drama)"},{"code":"B2.3","title":"","text":"identify and give examples of their strengths, interests, and areas for improvement as drama creators, performers, and audience members (e.g., use journals, charts, rubrics, and peer- and self-assessment charts to keep track of successful contributions, unproductive ideas or efforts, and evolving preferences in drama; describe how they used established criteria to evaluate their own and others’ work; describe how they incorporated constructive feedback into their drama work; assess how well they differentiated between stereotypes and authentic characters when developing roles)"}]},{"code":"B3","title":"Exploring Forms and Cultural Contexts","text":"demonstrate an understanding of a variety of drama and theatre forms, traditions, and styles from the past and present, and their sociocultural and historical contexts","specific":[{"code":"B3.1","title":"","text":"describe forms of process drama, theatre, storytelling, and visual representation from diverse communities around the world, and explain how they may reflect some beliefs and traditions of their communities (e.g., identify contexts in which the spoken word is a form of drama; describe historical and/or contemporary examples of forms from African, Asian, and/or Central or South American societies; identify examples of forms that reflect alternative viewpoints within communities)"},{"code":"B3.2","title":"","text":"demonstrate an understanding of the broader world of drama and theatre by identifying and describing the roles and responsibilities of key theatre personnel (e.g., describe what a producer, director, actor, stage manager, set or costume designer, and/or lighting or sound technician does in a typical day and what each needs in order to complete his or her work)"}]}]},{"code":"C","title":"Music","why":"","overall":[{"code":"C1","title":" Creating and Performing","text":"apply the creative process to create and perform music for a variety of purposes, using the elements and techniques of music","specific":[{"code":"C1.1","title":"","text":"sing and/or play, in tune, from musical notation, unison and two-part music with accompaniments, from a wide variety of cultures, styles, and historical periods (e.g., perform a recorder duet that has a variety of rhythmic and melodic patterns)"},{"code":"C1.2","title":"","text":"apply the elements of music when singing and/or playing, composing, and arranging music to create a specific effect (e.g., form, timbre: create a rondo [ABACADA form] using a familiar song as the repeating A section, and compose short rhythmic or melodic materials for the B, C, and D sections using pitched or non-pitched percussion instruments, found sounds, recorders, or body percussion)"},{"code":"C1.3","title":"","text":"create musical compositions for specific purposes and audiences (e.g., compose an accompaniment for a story, poem, or drama presentation to address an environmental issue such as water conservation, recycling, or planting trees; create a piece that uses a rhythmic ostinato in $$\\frac{4}{4}$$time and that includes both eighth and sixteenth notes; use body percussion, found sounds, voice, and non-pitched percussion instruments to vary the timbres in their work)"},{"code":"C1.4","title":"","text":"use the tools and techniques of musicianship in musical performances (e.g., play recorder using proper hand position and posture; sing and/or play pitches and rhythms accurately; observe markings for dynamics and articulation; interpret accidentals and key signatures through playing and/or singing; sing and/or play songs in major and minor keys)"},{"code":"C1.5","title":"","text":"demonstrate an understanding of standard and other types of musical notation through performance and composition (e.g., notation of rhythms of skipping songs in $$\\frac{6}{8}$$ metre; dynamic markings, clefs, key signatures; notational software for scoring their own compositions; guitar tablature)"}]},{"code":"C2","title":"Reflecting, Responding, and Analysing","text":"apply the critical analysis process to communicate their feelings, ideas, and understandings in response to a variety of music and musical experiences","specific":[{"code":"C2.1","title":"","text":"express detailed personal responses to musical performances in a variety of ways (e.g., describe the sounds of a steel band, using musical terminology; analyse a movement from Vivaldi’s Four Seasons in a think-pair-share listening activity, and describe their feelings and personal impressions; compare the mood of a piece from today and a piece from the baroque period, using Venn diagrams)"},{"code":"C2.2","title":"","text":"identify the elements of music in the music they perform, listen to, and create, and describe how they are used (e.g., timbre: describe how brass instruments are used in a marching band; duration: clap dotted rhythm patterns in a fanfare, describe how a slow tempo contributes to the mood of a funeral march, describe the use of syncopation in rhythms in Latin American music; form and texture: graphically portray the layering of melodies in a round; dynamics: relate the soft or loud sounds in a ballad to the meaning of the text)"},{"code":"C2.3","title":"","text":"identify and give examples of their strengths and areas for growth as musical performers, creators, interpreters, and audience members (e.g., balancing the volume of their own singing part in relation to the volume of another singing part; using expressive controls while playing recorder; providing peer feedback in preparation for a musical performance; writing a reflection on a live or recorded musical performance)"}]},{"code":"C3","title":"Exploring Forms and Cultural Contexts","text":"demonstrate an understanding of a variety of musical genres and styles from the past and present, and their sociocultural and historical contexts","specific":[{"code":"C3.1","title":"","text":"identify and describe some of the key influences of music within contemporary culture (e.g., describe the use of music in film and advertising; identify effects of musical trends on young people’s musical tastes; describe examples of fusion in different musical styles and genres)"},{"code":"C3.2","title":"","text":"demonstrate an awareness of the use of music and musical instruments in various traditions, from early times to today (e.g., describe the use of the drum in various cultures, including Aboriginal cultures, and at various times around the world in ceremonial and celebratory music)"}]}]},{"code":"D","title":"Visual Arts","why":"","overall":[{"code":"D1","title":"Creating and Presenting","text":"apply the creative process to produce a variety of two- and three-dimensional art works, using elements, principles, and techniques of visual arts to communicate feelings, ideas, and understandings","specific":[{"code":"D1.1","title":"","text":"create two- and three-dimensional art works that express feelings and ideas inspired by their own and others’ points of view (e.g., a painting based on a photo montage about children’s rights and responsibilities; a coloured line drawing of an underwater setting or the view from an airplane that addresses environmental awareness by showing the interconnectedness of ecosystems; a painting of someone in a particular situation in which empathy for him or her is created through characterization)"},{"code":"D1.2","title":"","text":"demonstrate an understanding of composition, using selected principles of design to create narrative art works or art works on a theme or topic (e.g., create an abstract painting using different proportions of complementary colours; create a simple sculpture of a human form that depicts an emotional response and shows awareness of proportion and negative space [in the style of Barbara Hepworth]; create an impression of depth and space by neutralizing colour intensity and brightness in a landscape painting [atmospheric perspective])"},{"code":"D1.3","title":"","text":"use elements of design in art works to communicate ideas, messages, and understandings (e.g., a series of three relief prints that use a glueline relief print process to illustrate the beginning, middle, and end of a story; a poster that presents solutions to stereotyping, bias, or bullying, using angle of view; a graffiti-style mural that addresses a community issue, using convex shapes that lead the eye with implied lines)"},{"code":"D1.4","title":"","text":"use a variety of materials, tools, and techniques to determine solutions to design challenges (e.g., drawing: coloured pencils to create a caricature of a celebrity that exaggerates facial features and uses linear shading and cast shadows; mixed media: a composite image that uses photographs, photocopies, transfers, images, and selected opaque and transparent materials to reflect their self-identity; painting: tempera paint or watercolour pencils using unusual colours or perspectives to suggest a fantasy world; printmaking: a relief print transferred from a textured surface, made with glue lines, craft foam, cardboard, paper, or string glued to board, using shapes to create a graphic design that explores pattern in a non-objective op art style; sculpture: a human figure or an imaginary creature made from clay, using basic handbuilding methods such as making the piece with coils or slabs of clay or by pinching and pulling the clay)"}]},{"code":"D2","title":"Reflecting, Responding, and Analysing","text":"apply the critical analysis process to communicate feelings, ideas, and understandings in response to a variety of art works and art experiences","specific":[{"code":"D2.1","title":"","text":"interpret a variety of art works and identify the feelings, issues, themes, and social concerns that they convey (e.g., use an image round-table technique to compare interpretations of emotions suggested by abstract forms or figures in art work; sort and classify a variety of art images, such as Nigerian, Egyptian, Mayan, and Chinese sculptures, to determine common subjects or themes)"},{"code":"D2.2","title":"","text":"explain how the elements and principles of design are used in their own and others’ art work to communicate meaning or understanding (e.g., packaging designs [cereal boxes, drink packaging] that use complementary colours create an impression different from that created by packages that use other colour schemes; Alexander Calder’s mobiles and Piet Mondrian’s paintings use colour, line, and geometric shape to create an impression of movement; colour, line, and pattern are used to convey a story in the illuminated manuscript of the Ramayana)"},{"code":"D2.3","title":"","text":"demonstrate an understanding of how to read and interpret signs, symbols, and style in art works (e.g., Carl Ray’s paintings use symbols in the Woodland style of Aboriginal art to tell a story; Picasso’s cubist portraits use stylistic features from African masks; a tiger is used in Asian art to signify bravery)"},{"code":"D2.4","title":"","text":"identify and explain their strengths, their interests, and areas for improvement as creators, interpreters, and viewers of art (e.g., use of appropriate terminology in talking about their own art work; discussion of others’ ideas with sensitivity and respect; provision of reasons for their artistic choices in a diary entry in their art journal or sketchbook)"}]},{"code":"D3","title":"Exploring Forms and Cultural Contexts","text":"demonstrate an understanding of a variety of art forms, styles, and techniques from the past and present, and their sociocultural and historical contexts","specific":[{"code":"D3.1","title":"","text":"describe how forms and styles of visual and media arts represent various messages and contexts in the past and present (e.g., sculptural monuments to honour people in the past such as war veterans; promotion of ideas or products on film, television, and the Internet in everyday life)"},{"code":"D3.2","title":"","text":"demonstrate an awareness of ways in which visual arts reflect the beliefs and traditions of a variety of peoples and of people in different times and places (e.g., the use of contemporary Aboriginal art to support cultural revitalization; the use of images on ancient Greek vases to reflect narratives of daily life, legends, and war; the relationship between public art and its location; exhibitions of the art of local artists in local festivals; displays and exhibitions of art works in galleries and museums)"}]}]}]},"g6":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-arts","sourceLang":"en","strands":[{"code":"A","title":"Dance","why":"","overall":[{"code":"A1","title":"Creating and Presenting","text":"apply the creative process to the composition of short dance pieces, using the elements of dance to communicate feelings and ideas","specific":[{"code":"A1.1","title":"","text":"incorporate the use of props and materials (e.g., fabric, chairs, hats, hula hoops, balls, sticks) into dance pieces they create (e.g., use fabric as a shawl or an extension of an arm gesture or the movement of a ship’s sail; use a stretchy fabric body bag to create abstract shapes; use an artefact like a garbage can to explore rhythm and body movement)"},{"code":"A1.2","title":"","text":"use dance as a language to interpret and depict central themes in literature (e.g., develop a movement vocabulary that reinterprets themes such as good versus evil or humans versus nature; construct a dance that explores bravery in a legend or peace in a poem)"},{"code":"A1.3","title":"","text":"use guided improvisation in a variety of ways as a starting point for choreography (e.g., use exercises such as mirroring, flocking, and body storming to create movement material for choreography)"},{"code":"A1.4","title":"","text":"combine the elements of dance in different ways to communicate a variety of ideas (e.g., combine a low level and a wavy pathway to show evasion; use the sudden, quick, and indirect movements of a dynamic orchestra conductor and translate them into a whole body expression of the music)"}]},{"code":"A2","title":"Reflecting, Responding, and Analysing","text":"apply the critical analysis process to communicate their feelings, ideas, and understandings in response to a variety of dance pieces and experiences","specific":[{"code":"A2.1","title":"","text":"construct personal interpretations of dance pieces that depict stories, issues, and themes, and explain their interpretations, using dance terminology (e.g., write an opinion paragraph on a recorded or live community dance performance [Red Sky]; write a response journal entry on a dance piece performed by peers about a social issue [emotional or physical bullying, friendship, safety, fairness, family, inclusion, equity])"},{"code":"A2.2","title":"","text":"analyse, using dance vocabulary, how the elements of dance are used in their own and others’ dance pieces and explain how they help communicate messages and ideas (e.g., pairing free-flowing movements with slow music suggests a dreamy mood; using low levels and quick, short movements suggests busyness; using symmetry and asymmetry conveys the idea of change or transformation)"},{"code":"A2.3","title":"","text":"identify and give examples of their strengths and areas for growth as choreographers and audience members (e.g., determine how their preparations for a performance improved the performance and what they might do differently to strengthen future performances)"}]},{"code":"A3","title":"Exploring Forms and Cultural Contexts","text":"demonstrate an understanding of a variety of dance forms, traditions, and styles from the past and present, and their sociocultural and historical contexts","specific":[{"code":"A3.1","title":"","text":"describe, with teacher guidance, types of dances used among Aboriginal peoples in the past and the present that express aspects of their cultural identity (e.g., dances to express prayers and/or gratitude; initiation dances to mark rites of passage; shamans’ dances to assist in physical or spiritual healing; contemporary powwow dances for cultural affirmation and/or revitalization)"},{"code":"A3.2","title":"","text":"identify and describe ways in which pop culture and the media influence our awareness, understanding, and appreciation of dance (e.g., by making us aware of different kinds of dance and diverse uses of dance in society; by providing male role models in dance and helping us view dance as a way to have a healthy, active lifestyle)"}]}]},{"code":"B","title":"Drama","why":"","overall":[{"code":"B1","title":"Creating and Presenting","text":"apply the creative process to process drama and the development of drama works, using the elements and conventions of drama to communicate feelings, ideas, and multiple perspectives","specific":[{"code":"B1.1","title":"","text":"engage actively in drama exploration and role play, with a focus on identifying and examining a range of issues, themes, and ideas from a variety of fiction and non-fiction sources and diverse communities, times, and places (e.g., adapt roles and develop improvised scenes based on human rights issues and/or environmental issues such as species extinction; dramatize opinions about cultural appropriation; role-play historical characters; prepare a presentation about peace for Remembrance Day; use choral speaking and role playing to interpret poetry)"},{"code":"B1.2","title":"","text":"demonstrate an understanding of the element of role by selectively using other elements (e.g., time and place; relationship; tension) to build belief in a role and establish its dramatic context (e.g., develop a character in the context of a courtroom drama: judge, lawyer, witness, juror, the accused)"},{"code":"B1.3","title":"","text":"plan and shape the direction of the drama or role play by introducing new perspectives and ideas, both in and out of role (e.g., In role: conduct a “hot seat” interview with the protagonist or antagonist; Out of role: make suggestions and introduce new ideas when planning a drama presentation)"},{"code":"B1.4","title":"","text":"communicate feelings, thoughts, and ideas to a specific audience, using audio, visual, and/or technological aids to strengthen the impact on the viewer (e.g., use a data projector to project evocative imagery; use filters and gels to create unusual effects with lighting; use music to suggest a mood; use masks to highlight specific character traits)"}]},{"code":"B2","title":"Reflecting, Responding, and Analysing","text":"apply the critical analysis process to communicate feelings, ideas, and understandings in response to a variety of drama works and experiences","specific":[{"code":"B2.1","title":"","text":"express personal responses and preferences and make connections to themes and issues presented in their own and others’ drama works (e.g., describe their response to the attitudes and beliefs of specific characters in a drama)"},{"code":"B2.2","title":"","text":"identify a favourite scene and give reasons for their preference, using correct drama terminology to describe how the elements of drama contribute to its effectiveness (e.g., explain what elements made the final confrontation between the hero and the villain exciting to perform or watch)"},{"code":"B2.3","title":"","text":"identify and give examples of their strengths, interests, and areas for improvement as drama creators, performers, and audience members (e.g., write a journal entry about a new strategy they have learned; write a letter to a new student about how to cope with stage fright; respond to interview questions about their growth and development; explain to the teacher how they collaborated and contributed to the group work of developing, planning, and designing a drama)"}]},{"code":"B3","title":"Exploring Forms and Cultural Contexts","text":"demonstrate an understanding of a variety of drama and theatre forms, traditions, and styles from the past and present, and their sociocultural and historical contexts","specific":[{"code":"B3.1","title":"","text":"demonstrate an understanding of some drama and theatre themes and traditions from a variety of times, communities, and places (e.g., Aboriginal communities: storytelling forms – the Seven Grandfather teachings, Haida tales, Medicine Wheel stories; theatre forms – Red Sky Performance Theatre, De-ba-jeh-mu-jig Theatre)"},{"code":"B3.2","title":"","text":"identify and describe key contributions drama and theatre make to the community (e.g., provide opportunities for self-expression and creativity to both amateurs and professionals; provide employment for a wide variety of workers; encourage tourism; promote strengthening and healing in Aboriginal communities)"}]}]},{"code":"C","title":"Music","why":"","overall":[{"code":"C1","title":"Creating and Performing","text":"apply the creative process to create and perform music for a variety of purposes, using the elements and techniques of music","specific":[{"code":"C1.1","title":"","text":"sing and/or play, in tune, from musical notation, unison music and music in two or more parts from a wide variety of cultures, styles, and historical periods (e.g., perform three- and four-part rounds by Canadian choral composers; perform pieces for Orff ensemble using recorder and pitched and non-pitched percussion; perform pieces, using technology to provide the accompaniment)"},{"code":"C1.2","title":"","text":"apply the elements of music when singing and/or playing, composing, and arranging music to create a specific effect (e.g., compose a piece in the theme and variations form, using a well-known song for the theme to engage the listener; change the metre of a familiar eight-bar melody and describe the effect of the change; remove tone bars on a xylophone to create a pentatonic tonality, and then improvise a pentatonic response on the xylophone to a call played on a recorder)"},{"code":"C1.3","title":"","text":"create musical compositions for specific purposes and audiences (e.g., write a melodic composition reflecting a piece of art of their own or by another, such as Norval Morrisseau or Emily Carr; create a rhythmic composition using nonpitched percussion to accompany a First Nation legend, story, or poem; with a partner, compose a song to promote Canada to the rest of the world)"},{"code":"C1.4","title":"","text":"use the tools and techniques of musicianship in musical performances (e.g., conduct pieces in duple and triple metres, listen for balance and blend when singing and/or playing, interpret musical markings and Italian terms during performance)"},{"code":"C1.5","title":"","text":"demonstrate an understanding of standard and other types of musical notation through performance and composition (e.g., perform music that includes ledger lines, triplets, simple and compound metres; use original graphic or symbolic systems to represent vocal and instrumental sounds and musical ideas)"}]},{"code":"C2","title":"Reflecting, Responding, and Analysing","text":"apply the critical analysis process to communicate their feelings, ideas, and understandings in response to a variety of music and musical experiences","specific":[{"code":"C2.1","title":"","text":"express detailed personal responses to musical performances in a variety of ways (e.g., write a critical review of a live or recorded performance; write analyses of works they have listened to in a log or journal; create a drawing or graphic representation of their initial reaction to a song)"},{"code":"C2.2","title":"","text":"identify the elements of music in the repertoire they perform, listen to, and create, and describe how they are used (e.g., describe the way in which dotted rhythms, the sound quality of brass instruments, higher pitches, loud dynamics, and accented articulation combine to suggest music that introduces royalty)"},{"code":"C2.3","title":"","text":"identify and give examples of their strengths and areas for improvement as composers, musical performers, interpreters, and audience members (e.g., reflect on their first draft of an original composition and incorporate suggestions from their peers into their final piece)"}]},{"code":"C3","title":"Exploring Forms and Cultural Contexts","text":"demonstrate an understanding of a variety of musical genres and styles from the past and present, and their sociocultural and historical contexts","specific":[{"code":"C3.1","title":"","text":"identify and describe ways in which awareness or appreciation of music is affected by culture and the media (e.g., people attend concerts of music that they know and like or have found out about through the media; people can be influenced to buy products that are advertised with music that they relate to)"},{"code":"C3.2","title":"","text":"compare some aspects of the music of one culture and/or historical period with aspects of the music of another culture and/or historical period (e.g., compare selected characteristics of music from the baroque and classical periods, using a Venn diagram; write a review of music from another society, comparing the music of that society with the music with which they are familiar)"}]}]},{"code":"D","title":"Visual Arts","why":"","overall":[{"code":"D1","title":"Creating and Presenting","text":"apply the creative process to produce art works in a variety of traditional two- and three-dimensional forms, as well as multimedia art works, that communicate feelings, ideas, and understandings, using elements, principles, and techniques of visual arts as well as current media technologies","specific":[{"code":"D1.1","title":"","text":"create two-dimensional, three-dimensional, and multimedia art works that explore feelings, ideas, and issues from a variety of points of view (e.g., art work inspired by the motifs in other art forms [dance, music] or by hopes and dreams; a mixed-media piece or one-minute video “short” about adaptation and survival; a still-life painting that offers a social commentary on fast-food packaging)"},{"code":"D1.2","title":"","text":"demonstrate an understanding of composition, using selected principles of design to create narrative art works or art works on a theme or topic (e.g., use a larger area of a lighter tint and a smaller area of a darker tone of one colour in an asymmetrically balanced painting; use repetition, simplification, and exaggeration of proportion and shape to create a sense of rhythm in a graphite-and-pastel drawing of musical instruments and their shadows)"},{"code":"D1.3","title":"","text":"use elements of design in art works to communicate ideas, messages, and understandings (e.g., a design of a letter of the alphabet using shapes, symbols, colour, and font style to represent a selected animal and its habitat; a DVD cover design or movie poster that uses line, shape, space, colour, and value to communicate information about the content)"},{"code":"D1.4","title":"","text":"use a variety of materials, tools, techniques, and technologies to determine solutions to design challenges (e.g., drawing: use charcoal to create a shaded drawing of the exaggerated details of a face, a figure, or natural objects [e.g., shells, pods] on earthtoned papers [e.g., tan construction paper]; mixed media: create a collage that uses a limited colour palette by cutting, pasting, and layering to combine images, symbols, textured papers, and text about consumerism or cultural pride; painting: use a variety of paint techniques [e.g., blending, scumbling, glazing] in a mural of a landscape or cityscape incorporating stylistic elements from contemporary pop culture; printmaking: cut and gouge a variety of lines and marks to enhance the background and negative spaces in a softoleum, linoleum, or block print that depicts an endangered animal species; sculpture: create an assemblage on a topic or theme, using found objects that are painted or otherwise unified through colour, in the style of a sculpture by Louise Nevelson; technology: create a digital photo montage that represents aspects of environmentalism)"}]},{"code":"D2","title":"Reflecting, Responding, and Analysing","text":"apply the critical analysis process to communicate feelings, ideas, and understandings in response to a variety of art works and art experiences","specific":[{"code":"D2.1","title":"","text":"interpret a variety of art works and identify the feelings, issues, themes, and social concerns that they convey (e.g., describe Ted Harrison’s use of line, colour, brushstrokes, and rhythm to create a feeling of movement and excitement; compare the themes and the emotions conveyed in selected Western animations and in Japanese animations such as those by Hayao Miyazaki)"},{"code":"D2.2","title":"","text":"explain how the elements and principles of design are used in their own and others’ art work to communicate meaning or understanding (e.g., identify the point of view or gaze of the main subject, and explain how it is used to influence an intended audience of an art work or a media work; explain how Kenojuak Ashevak’s use of formal balance (symmetry) in The World Around Me conveys a sense of harmony in nature; explain how a rough texture can be used to represent strength, anger, or something unpleasant)"},{"code":"D2.3","title":"","text":"demonstrate an understanding of how to read and interpret signs, symbols, and style in art works (e.g., symbolism for sending messages and telling stories in Egyptian hieroglyphs, Agawa rock paintings, or graffiti art; symbols on currency or in advertisements that have specific national or other connotations; meanings associated with colour in different cultures [white dresses symbolize purity in Western culture but mourning and death in some Asian cultures])"},{"code":"D2.4","title":"","text":"identify and explain their strengths, their interests, and areas for improvement as creators, interpreters, and viewers of art (e.g., reflect on challenges and successes in the form of an artist’s statement; maintain a sketchbook or collection of ideas and images for art works; do peer reviews of each other’s art works, using a checklist of criteria created by the class to help them identify areas that need revision, and provide suggestions)"}]},{"code":"D3","title":"Exploring Forms and Cultural Contexts","text":"demonstrate an understanding of a variety of art forms, styles, and techniques from the past and present, and their sociocultural and historical contexts","specific":[{"code":"D3.1","title":"","text":"identify and describe some of the ways in which art forms and styles reflect the beliefs and traditions of a variety of communities, times, and places (e.g., art can represent ways in which people view their personal identity; contemporary Aboriginal artists use their artistic traditions to comment on identity, society, and the world; art can be a record of human experience; differences in style among different artists can be associated with a specific reason, intent, or motivation)"},{"code":"D3.2","title":"","text":"demonstrate an understanding of key contributions and functions of visual and media arts in various contexts at both the local and the national levels (e.g., community art schools or programs provide opportunities for creative expression and instruction by and for both amateurs and professionals; a wide variety of workers are employed by arts industries such as advertising, design, movie making, and broadcast media; artists contribute to Canada’s economy by providing both goods and services)"}]}]}]}},"fsl":{"g4":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-fsl","sourceLang":"en","strands":[{"code":"A","title":"Listening","why":"","overall":[{"code":"A1","title":"Listening to Understand","text":"determine meaning in a variety of oral French texts, using a range of listening strategies","specific":[{"code":"A1.1","title":"Using Listening Comprehension Strategies","text":"identify a range of listening comprehension strategies and use them appropriately before, during, and after listening to understand oral French texts (e.g., identify familiar words and phrases and frequently used expressions; use contextual and/or visual clues in oral texts, including the speaker’s body language and tone of voice, to confirm or clarify meaning; activate prior knowledge and make connections to personal experiences to confirm understanding; ask questions to obtain additional information; visualize, sketch, or draw to record information and ideas)"},{"code":"A1.2","title":"Demonstrating Understanding","text":"demonstrate an understanding of the purpose and meaning of oral French texts containing familiar words and expressions about everyday topics and situations, with contextual and visual support (e.g., follow classroom directions; follow a series of Total Physical Response [TPR] commands; sequence a group of pictures or images for a storyboard, based on a description; make drawings to illustrate objects in an oral description; find a specific classroom object by following directions from the teacher and class; identify refrains, rhyme schemes, and other word/sound patterns in songs, poems, read-alouds, chants, and rhymes; listen to a description and identify the object described)"}]},{"code":"A2","title":"Listening to Interact","text":"interpret messages accurately while interacting in French for a variety of purposes and with diverse audiences","specific":[{"code":"A2.1","title":"Using Interactive Listening Strategies","text":"identify and use interactive listening strategies to suit a variety of situations while participating in social and academic interactions (e.g., demonstrate an understanding of when to listen and when to speak; look at the speaker; listen without interrupting; make connections between personal experiences and what is being said; reconsider their point of view after hearing what others say; repeat a partner’s ideas in their own words as a way of confirming understanding; ask for repetition, confirmation, or clarification of what they hear using phrases such as “Un instant…Je ne comprends pas. Pourriez-vous répéter cela, s’il vous plaît? Qu’est-ce que cela veut dire…?”; use body language such as a nod to indicate understanding and/or agreement)"},{"code":"A2.2","title":"Interacting","text":"respond with understanding to what others say while participating in brief, structured interactions about themselves, family, friends, and their immediate environment, with contextual and visual support (e.g., respond appropriately to questions requiring a brief answer in paired and small-group interactions on familiar topics; respond constructively to a partner’s ideas in think-pair-share sessions, using gestures, visual aids, and/or familiar words and phrases; share reactions to a partner’s plans for a celebration or for the weekend)"},{"code":"A2.3","title":"Metacognition","text":"(a) describe, in conversation with the teacher and their peers, a few strategies they found helpful before, during, and after listening; (b) identify their areas of greater and lesser strength as listeners, and plan steps they can take to improve their listening skills (e.g., discuss with a partner some strategies and tools that have helped them improve their listening skills; self-monitor listening during a group discussion)"}]},{"code":"A3","title":"Intercultural Understanding","text":"demonstrate an understanding of information in oral French texts about aspects of culture in diverse French-speaking communities and other communities around the world, and of French sociolinguistic conventions used in a variety of situations and communities","specific":[{"code":"A3.1","title":"Intercultural Awareness","text":"using information from oral French texts, identify French-speaking communities in Ontario, find out about aspects of their cultures, and make connections to personal experiences and their own and other communities (e.g., listen to directions and locate on a map historic Franco-Ontarian or Métis communities such as Sault Ste. Marie or Mattawa; identify examples of the use of French in their immediate environment – such as the bilingual version of the national anthem sung at sports events; listen to a peer describe a family tradition and make connections to a similar tradition in their own family)"},{"code":"A3.2","title":"Awareness of Sociolinguistic Conventions","text":"using information from oral French texts, identify and demonstrate an understanding of sociolinguistic conventions used in a variety of situations in diverse French-speaking communities (e.g., formal and informal expressions of courtesy such as different types of salutations; verbal and non-verbal cues appropriate to different environments, such as social gatherings versus classroom contexts; brief expressions used to introduce themselves and others)"}]}]},{"code":"B","title":"Speaking","why":"","overall":[{"code":"B1","title":"Speaking to Communicate","text":"communicate information and ideas orally in French, using a variety of speaking strategies and age- and grade-appropriate language suited to the purpose and audience","specific":[{"code":"B1.1","title":"Using Oral Communication Strategies","text":"identify a range of speaking strategies and use them appropriately to express themselves clearly and coherently in French for various purposes and to a variety of audiences (e.g., use and reuse familiar language structures and patterns, such as repetition, and incorporate previously learned words and phrases to clarify the meaning of oral messages; use visual, nonverbal cues such as gestures, facial expression, body position, and eye contact – pointing, smiling, nodding, leaning forward – and vocal effects such as changes in pitch, tone, pace, and volume to support and clarify meaning; refer to classroom visuals such as anchor charts to help them clarify a message)"},{"code":"B1.2","title":"Producing Oral Communications","text":"using familiar words and expressions, produce brief, rehearsed messages in French containing information and ideas about themselves, family, friends, and their immediate environment, with contextual, auditory, and visual support (e.g., describe classroom routines; prepare and deliver a presentation introducing themselves, family members, and/or pets; recount a sequence of events from a fictional or news story; deliver brief, rehearsed oral presentations; give concise directions to a classmate describing how to perform an action or find an object)"},{"code":"B1.3","title":"Speaking with Fluency","text":"speak with a smooth pace, appropriate intonation, and accurate pronunciation in brief, rehearsed communications about personal and familiar topics (e.g., use accepted pronunciation for high-frequency words, regularly used phrases, and words with personal significance in brief oral exchanges, dialogues, and presentations; accurately pronounce familiar vocabulary when introducing themselves or their friends and family; speak at a comfortable pace in short, rehearsed question-and-answer routines about familiar topics; pronounce words smoothly and accurately as modelled by the teacher when reciting tongue twisters, chants, rhymes, and newly acquired vocabulary and when participating in choral speaking and/or shared reading activities; use intonation as modelled by the teacher to ask questions; deliver a rehearsed oral presentation at a smooth pace with appropriate phrasing and emphasis)"}]},{"code":"B2","title":"Speaking to Interact","text":"participate in spoken interactions in French for a variety of purposes and with diverse audiences","specific":[{"code":"B2.1","title":"Using Speaking Interaction Strategies","text":"demonstrate an understanding of appropriate speaking behaviour in a variety of situations (e.g., restate the contributions of other group members to confirm understanding and share preferences; use facial expressions, tone of voice, and gestures that are appropriate to the context and audience; ask questions to clarify the context and purpose for exchanging information)"},{"code":"B2.2","title":"Interacting","text":"engage in brief, structured spoken interactions, using familiar words and expressions, with teacher modelling and support (e.g., contribute brief oral instructions and responses in interactive games and role plays; ask and answer questions in surveys and interviews; participate in simulated telephone conversations; answer the teacher’s or their classmates’ questions about their oral presentations)"},{"code":"B2.3","title":"Metacognition","text":"(a) describe, in conversation with the teacher and their peers, a few strategies they found helpful before, during, and after speaking to communicate effectively; (b) identify their areas of greater and lesser strength as speakers, and plan steps they can take to improve their speaking skills (e.g., determine the elements of effective presentations; provide feedback on a peer’s oral presentation and listen to peers’ comments about their own presentations; evaluate their use of French in daily interactions with peers and the teacher)"}]},{"code":"B3","title":"Intercultural Understanding","text":"in their spoken communications, demonstrate an awareness of aspects of culture in diverse French-speaking communities and other communities around the world, and of the appropriate use of French sociolinguistic conventions in a variety of situations","specific":[{"code":"B3.1","title":"Intercultural Awareness","text":"communicate information orally about French-speaking communities in Ontario, including aspects of their cultures and their contributions to la francophonie and the world, and make connections to personal experiences and their own and other communities (e.g., share ideas about the importance of French as demonstrated by its status as an official language of Canada and a required subject in the Ontario elementary curriculum; repeat phrases from songs by Franco-Ontarian musicians that reveal aspects of French Canadian cultures; give brief oral presentations describing traditions and festivals such as le Bal de Neige in Ottawa; use a T-chart to organize information and guide discussions about aspects of Franco-Ontarian cultures, such as family, school life, traditions, and festivals, and make connections to their own culture)"},{"code":"B3.2","title":"Awareness of Sociolinguistic Conventions","text":"identify sociolinguistic conventions associated with a variety of social situations in diverse French-speaking communities and use them appropriately in spoken interactions (e.g., use greetings, leave-taking expressions, and expressions of courtesy – “bonjour”, “salut”, “au revoir”, “à demain”, “oui”, “non”, “merci”, “s’il vous plaît”, “excusez-moi” – as appropriate to the social context; use the verb “avoir” to state their age; use gestures and other forms of nonverbal communication as appropriate to the social context – bowing, shrugging, hand shaking; use standard introductory phrases to give personal information – “Je m’appelle… J’habite…”)"}]}]},{"code":"C","title":"Reading","why":"","overall":[{"code":"C1","title":"Reading Comprehension","text":"determine meaning in a variety of French texts, using a range of reading comprehension strategies","specific":[{"code":"C1.1","title":"Using Reading Comprehension Strategies","text":"identify a few reading comprehension strategies and use them before, during, and after reading to understand texts (e.g., activate prior knowledge by brainstorming about the cover, title page, and/or topic of a text; preview vocabulary to identify familiar words and cognates; create key questions as a class before reading; relate prior knowledge and personal experiences to topics in texts; discuss how they visualize a character or a scene in a text; discuss, draw, or write about evidence in the text that can be used to predict possible outcomes; use pictorial clues to predict meaning and confirm understanding of a text; use contextual clues to determine the meaning of new words; recognize relationships between words with common spelling patterns and use them to determine the meaning of new words, as in “an/année/anniversaire”; use visual clues such as illustrations, photos, and charts to help clarify meaning)"},{"code":"C1.2","title":"Reading for Meaning","text":"demonstrate an understanding of French texts containing visuals and familiar names, words, and phrases, with teacher support as required (e.g., draw pictures to retell a story; restate the main idea in a text using familiar vocabulary; create a tableau to dramatize a scene from a story they have read; use drama, music, or visual arts to respond to an issue raised in a text)"},{"code":"C1.3","title":"Reading with Fluency","text":"read texts containing familiar words and expressions at a sufficient rate and with sufficient ease to demonstrate that they understand the overall sense of the text (e.g., recognize high-frequency words, most regularly used words, and words of personal interest; recognize the same word in different graphic representations – such as on the word wall, in shared/guided/independent-reading texts, on shared- and interactive-writing charts in personal writing, and in a variety of fonts; make oral reading sound like spoken language, with appropriate pauses, stops, and starts as indicated by the punctuation)"},{"code":"C1.4","title":"Developing Vocabulary","text":"use a few vocabulary-acquisition strategies before, during, and after reading to determine or confirm the meaning of new and unfamiliar words (e.g., develop a bank of sight words using visual dictionaries; make word lists of personally relevant vocabulary; use memorization and visualization strategies and verbal and written repetition to consolidate learning of new words; develop lists of cognates to expand vocabulary; identify the tense of familiar verbs in the present, past, and future by their suffixes)"}]},{"code":"C2","title":"Purpose, Form, and Style","text":"identify the purpose(s) and characteristics of a variety of adapted and authentic text forms, including fictional, informational, graphic, and media forms","specific":[{"code":"C2.1","title":"Purposes of Text Forms","text":"identify the purpose(s) of some familiar text forms, including fictional, informational, graphic, and media forms (e.g., poem/song – to express ideas or convey a mood in figurative, evocative language; pattern book story – to entertain and/or explore problems, characters, and ideas; menu – to describe food offerings; calendar, list, or chart – to communicate information in an organized, easy-to-understand form; non-fiction book – to explain or describe something or explore an issue or topic; greeting card – to send good wishes or convey thanks; sign – to attract attention and/or give directions; advertisement – to attract attention and persuade)"},{"code":"C2.2","title":"Characteristics of Text Forms","text":"identify some characteristics and/or stylistic elements of familiar text forms, including fictional, informational, graphic, and media forms (e.g., poem/song – rhyming or non-rhyming patterns and use of imagery; pattern book story – title page, illustrations, repetitive use of familiar words and phrases, description of characters/setting/ conflict, possible resolution; menu – subsections listing offerings of salads/main courses/desserts/ beverages, prices, illustrations; calendar, list, or chart – table or column format; greeting card – brief text message in special fonts, illustrations/ graphics; non-fiction book – table of contents, illustrations, and captions; sign – distinctive fonts, colours, and symbols related to the content of the message; advertisement – eye-catching graphics, fonts, colours, and illustrations)"},{"code":"C2.3","title":"Metacognition","text":"(a) describe, in conversation with the teacher and their peers, a few strategies they found helpful before, during, and after reading to understand texts; (b) identify their areas of greater and lesser strength as readers, and plan steps they can take to improve their reading skills (e.g., use book reviews written by peers to expand choices for independent reading; discuss useful strategies for understanding a new expression in a text; share helpful strategies with peers; establish next steps after a guided reading lesson)"}]},{"code":"C3","title":"Intercultural Understanding","text":"demonstrate an understanding of information in French texts about aspects of culture in diverse French-speaking communities and other communities around the world, and of French sociolinguistic conventions used in a variety of situations and communities","specific":[{"code":"C3.1","title":"Intercultural Awareness","text":"using information from a variety of French texts, identify French-speaking communities in Ontario, find out about aspects of their cultures, and make connections to personal experiences and their own and other communities (e.g., information about traditions, powwows, and festivals such as le Bal de Neige or le Festival des tulipes – Ottawa, le Festival des voyageurs – Mattawa, Métis rendez-vous – Rivière des Français, sporting events such as les Jeux franco-ontariens, children’s games such as voyageur competitions and blanket throwing, family traditions, and favourite songs in various communities; read about Franco-Ontarian Métis, such as Marcel Labelle and Christian Pilon, and identify some of their accomplishments)"},{"code":"C3.2","title":"Awareness of Sociolinguistic Conventions","text":"identify, in age- and grade-appropriate French texts, examples of sociolinguistic conventions associated with a variety of social situations in diverse French-speaking communities (e.g., the use of “Salut” instead of “Bonjour”, “la fin de semaine” instead of “le week-end”, “mon mari/ma femme” instead of “mon époux/mon épouse”, “mon amie/mon ami” instead of “ma copine/mon copain”)"}]}]},{"code":"D","title":"Writing","why":"","overall":[{"code":"D1","title":"Purpose, Audience, and Form","text":"write French texts for different purposes and audiences, using a variety of forms","specific":[{"code":"D1.1","title":"Identifying Purpose and Audience","text":"determine, with support from the teacher, their purpose for writing and the audience for French texts they plan to create (e.g., to convey best wishes to a friend in a card/email/note; to complete a registration form or provide personal information in an application to a summer sports camp; to share a list of favourite activities with a friend in an email or text message; to communicate information in a report; to persuade people to protect the environment or to buy an environmentally responsible product in an advertisement)"},{"code":"D1.2","title":"Writing in a Variety of Forms","text":"write a variety of age- and grade-appropriate French texts, applying their knowledge of the basic structural and stylistic elements of each form (e.g., postcard/greeting card/email/announcement/ invitation – salutation and closing and a clear message; information sentence on a topic of interest – sentence starter followed by specific details; captions for a series of photographs of a class activity – classmates’ names and information about what they are doing; recipe for an easy-to-prepare meal, such as corn soup – lists of ingredients and instructions for combining them; survey/questionnaire – numbered questions in list format, with subsections for different subtopics, interrogative pronouns to introduce questions; shopping list – names of items, categories, prices)"}]},{"code":"D2","title":"The Writing Process","text":"use the stages of the writing process – including pre-writing, producing drafts, revising, editing, and publishing – to develop and organize content, clarify ideas and expression, correct errors, and present their written work effectively","specific":[{"code":"D2.1","title":"Generating, Developing, and Organizing Content","text":"generate, develop, and organize ideas for writing, using a variety of pre-writing strategies and resources, during modelled, shared, guided, and independent writing activities (e.g., brainstorm ideas for writing using visual prompts; gather ideas for writing from shared classroom experiences such as read-alouds and shared reading; activate prior knowledge about personal, family, and community experiences through brainstorming and think-alouds; do research to identify key ideas related to a topic; use graphic organizers to create a list of words related to a topic and/or to sort and classify ideas; discuss the topic with peers and the teacher to focus thinking; draw or sketch to formulate ideas and thoughts; jot down plans and draft an outline)"},{"code":"D2.2","title":"Drafting and Revising","text":"plan and produce drafts following a model (e.g., email, postcard, procedure, directions to determine location), and revise their writing using a variety of strategies, with teacher support (e.g., reread, change, add, subtract, and/or reorganize content; rewrite, edit, and revise drafts based on feedback from the teacher and peers)"},{"code":"D2.3","title":"Producing Finished Work","text":"make improvements to their written work, using knowledge of a few of the conventions of written French (e.g., spell familiar words correctly and with appropriate accents; use high-frequency adjectives of colour, quantity, location, and sentiment to enhance their messages; use the correct subject pronouns to refer to family members, friends, and community members; use high-frequency verbs in the present tense to describe things that are happening to and around them), and use a few elements of effective presentation to produce a polished product for publication (e.g., a larger font for headings; bold/italics/underlining for emphasis)"},{"code":"D2.4","title":"Metacognition","text":"(a) describe, in conversation with the teacher and their peers, a few strategies they found helpful before, during, and after writing; (b) identify their areas of greater and lesser strength as writers, and plan steps they can take to improve their writing skills (e.g., when conferencing with the teacher, evaluate their plan for writing; use comments on their written text from the teacher and their peers to plan next steps; reflect on their ability to represent familiar words in writing)"}]},{"code":"D3","title":"Intercultural Understanding","text":"in their written work, demonstrate an awareness of aspects of culture in diverse French-speaking communities and other communities around the world, and of the appropriate use of French sociolinguistic conventions in a variety of situations","specific":[{"code":"D3.1","title":"Intercultural Awareness","text":"in their written work, communicate information about French-speaking communities in Ontario, including aspects of their cultures and their contributions to la francophonie and the world, and make connections to personal experiences and their own and other communities (e.g., select pictures of a Franco-Ontarian, Aboriginal, or Métis community such as Sturgeon Falls, Verner, Noelville, or Mattawa and create descriptive captions for them; create a poster with illustrations and text to promote interest in speaking French in Ontario; research a famous Franco-Ontarian legend, myth, or story and write a poem about it)"},{"code":"D3.2","title":"Awareness of Sociolinguistic Conventions","text":"identify sociolinguistic conventions associated with a variety of social situations in diverse French-speaking communities and use them appropriately in their written work (e.g., greetings and expressions of courtesy such as “bonjour”, “au revoir”, “non”, “merci”, “s’il vous plaît”; standard formats for personal letters, postcards, emails; conventions for writing the date)"}]}]}]},"g5":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-fsl","sourceLang":"en","strands":[{"code":"A","title":"Listening","why":"","overall":[{"code":"A1","title":"Listening to Understand","text":"determine meaning in a variety of oral French texts, using a range of listening strategies","specific":[{"code":"A1.1","title":"Using Listening Comprehension Strategies ","text":"identify a range of listening comprehension strategies and use them appropriately before, during, and after listening to understand oral French texts (e.g., talk about ideas and personal experiences related to a topic before beginning a listening task to make predictions about it; take notes to confirm what they have heard; ask questions to determine next steps; use visual and auditory clues in multimedia texts to help determine meaning; sequence actions in descriptions of past, present, and future events)"},{"code":"A1.2","title":"Demonstrating Understanding","text":"demonstrate an understanding of the purpose and meaning of oral French texts containing familiar words and expressions about themselves, family, friends, and their immediate environment, with contextual and visual support (e.g., listen and re-listen to a read-aloud and note key ideas in a class-generated graphic organizer; identify a classmate from a physical description; listen to a classmate or teacher describe the weather and draw a picture to illustrate the description; use a checklist to indicate the important ideas in an oral text or presentation; construct or draw a model of an object based on a partner’s instructions; identify key concepts and vocabulary in recorded messages, songs, and audio webcasts, and use multiple intelligences to represent them; listen to a description of a classmate’s personal collection, favourite activity, or family celebration and write, draw, or choose images to compare it with their own)"}]},{"code":"A2","title":"Listening to Interact","text":"interpret messages accurately while interacting in French for a variety of purposes and with diverse audiences","specific":[{"code":"A2.1","title":"Using Interactive Listening Strategies ","text":"identify and use interactive listening strategies to suit a variety of situations while participating in social and academic interactions (e.g., build on what others are saying by offering relevant comments when participating in paired and small-group exchanges on familiar topics; observe a peer’s body language to help understand his or her intended message; ask questions in paired and small-group activities to clarify their understanding of what is said)"},{"code":"A2.2","title":"Interacting ","text":"respond with understanding to what others say while participating in brief, structured interactions about themselves, family, friends, and their immediate environment, with contextual and visual support (e.g., using familiar words/expressions and/or actions, respond appropriately to questions in paired and small-group exchanges on familiar topics or to a partner’s comments in a think-pair-share session; listen and respond to questions about familiar topics such as personal preferences, interests, and past or future events or experiences; offer a classmate comparable information in response to a description of his or her family; interview a classmate and use the information to introduce him or her to a group)"},{"code":"A2.3","title":"Metacognition","text":"(a) describe, in conversation with the teacher and their peers, a few strategies they found helpful before, during, and after listening; (b) identify their areas of greater and lesser strength as listeners, and plan steps they can take to improve their listening skills (e.g., plan to keep a journal of listening strategies they have found helpful, for future reference)"}]},{"code":"A3","title":"Intercultural Understanding","text":"demonstrate an understanding of information in oral French texts about aspects of culture in diverse French-speaking communities and other communities around the world, and of French sociolinguistic conventions used in a variety of situations and communities","specific":[{"code":"A3.1","title":"Intercultural Awareness","text":"using information from oral French texts, identify French-speaking communities in Quebec, find out about aspects of their cultures, and make connections to personal experiences and their own and other communities (e.g., listen to and identify topics of interest in songs, stories, and legends by Québécois artists and authors, such as Anthony Phelps – “Et moi, je suis une île”, Laïla Héloua – “Mandarine et Kiwi”; using a graphic organizer to guide listening, organize information from French texts about family, school life, traditions, powwows, and festivals in Québécois communities, such as Quebec City – Festival des journées d’Afrique, Danses et Rythmes du Monde, Trois-Rivières – Festival urbain, Montreal – Festival du monde arabe, and make connections to their own culture; listen to the recitation of a traditional French Canadian story used by Métis, such as La Chasse-galerie, and make connections to a familiar tale)"},{"code":"A3.2","title":"Awareness of Sociolinguistic Conventions","text":"using information from oral French texts, identify and demonstrate an understanding of sociolinguistic conventions used in a variety of situations in diverse French-speaking communities (e.g., compare French expressions to expressions used in English and/or their first language; compare different types of body language used in social interactions in various cultures; identify French phrases that are used to initiate, interrupt, and conclude conversations politely)"}]}]},{"code":"B","title":"Speaking","why":"","overall":[{"code":"B1","title":"Speaking to Communicate","text":"communicate information and ideas orally in French, using a variety of speaking strategies and age- and grade-appropriate language suited to the purpose and audience","specific":[{"code":"B1.1","title":"Using Oral Communication Strategies ","text":"identify a range of speaking strategies and use them appropriately to express themselves clearly and coherently in French for various purposes and to a variety of audiences (e.g., use a familiar model to structure messages; use think-aloud stems to structure descriptions and comments; use changes in pitch, tone, and volume to maintain the interest of listeners; vary the pace of speech to hold the audience’s attention when presenting)"},{"code":"B1.2","title":"Producing Oral Communications","text":"using familiar words and expressions, produce brief, rehearsed messages in French containing information and ideas about themselves, family, friends, and their immediate environment, with contextual, auditory, and visual support (e.g., make introductions; respond to questions and instructions using previously learned vocabulary; ask questions to obtain additional information about healthy food choices; describe themselves, other people, and places using familiar expressions; state their reactions to information in texts such as posters, food guides, environmental brochures, and Aboriginal songs and stories)"},{"code":"B1.3","title":"Speaking with Fluency ","text":"speak with a smooth pace, appropriate intonation, and accurate pronunciation in brief, rehearsed communications about personal and familiar topics (e.g., speak about familiar topics using planned pauses and few hesitations; pronounce new words from shared reading activities accurately, as modelled by the teacher)"}]},{"code":"B2","title":"Speaking to Interact","text":"participate in spoken interactions in French for a variety of purposes and with diverse audiences","specific":[{"code":"B2.1","title":"Using Speaking Interaction Strategies ","text":"demonstrate an understanding of appropriate speaking behaviour in a variety of situations (e.g., demonstrate an understanding of when to speak and when to listen, for instance using a talking stick/stone/feather to indicate the speaker; take turns; speak clearly; look at the listener/audience; use visual supports, facial expression, tone of voice, and gestures such as nodding, pointing, and shrugging to help clarify their meaning; when working in pairs or in a group, acknowledge the contributions of others before stating their own views; make personal connections to the experiences of others when responding; show awareness of and sensitivity towards the background and experiences of others when expressing their views)"},{"code":"B2.2","title":"Interacting","text":"engage in brief, structured spoken interactions with their peers and the teacher, using familiar words and expressions, with teacher modelling and support (e.g., ask and answer questions about name, age, and family; ask questions to clarify meaning before responding; share their ideas and respond to others’ opinions in a literature circle; make constructive comments when giving feedback to a classmate in a peer-assessment activity; contribute and respond to comments in interactive games and structured oral activities; participate in role-play conversations that simulate the authentic use of language; respond to questions from the teacher and their peers about their oral presentations; ask and answer questions about healthy food choices or environmental issues)"},{"code":"B2.3","title":"Metacognition","text":"(a) describe, in conversation with the teacher and their peers, a few strategies they found helpful before, during, and after speaking to communicate effectively; (b) identify their areas of greater and lesser strength as speakers, and plan steps they can take to improve their speaking skills (e.g., share and discuss a strategy used to participate in a discussion; compare speaking situations to reflect on their own ability to communicate; use classroom visuals and reference material to give feedback)"}]},{"code":"B3","title":"Intercultural Understanding","text":"in their spoken communications, demonstrate an awareness of aspects of culture in diverse French-speaking communities and other communities around the world, and of the appropriate use of French sociolinguistic conventions in a variety of situations","specific":[{"code":"B3.1","title":"Intercultural Awareness","text":"communicate information orally about French-speaking communities in Quebec, including aspects of their cultures and their contributions to la francophonie and the world, and make connections to personal experiences and their own and other communities (e.g., describe a specific region or community in Quebec, including Aboriginal communities, using a poster they have created or obtained from a travel agency to illustrate their remarks; describe the ingredients and procedure for making a familiar Québécois dish such as poutine; recite or paraphrase songs, stories, and/or legends by Québécois artists and authors; identify some famous Québécois[es], such as Michaëlle Jean, Maurice Richard, Mario Lemieux, Boucar Diouf, Nikki Yanofsky, Gilles Vigneault, William Shatner, Simple Plan, Pierre Trudeau, Samian, Emmanuelle Chriqui, Alexandre Bilodeau, Julie Payette, Marc Garneau, or Guy Laliberté, and describe some of their accomplishments; deliver a brief oral presentation comparing important issues or events in a Quebec community and their own community)"},{"code":"B3.2","title":"Awareness of Sociolinguistic Conventions","text":"identify sociolinguistic conventions associated with a variety of social situations in diverse French-speaking communities and use them appropriately in spoken interactions (e.g., identify and use appropriate forms of address to suit formal and informal situations – such as “tu” versus “vous” or the use of “Oui” by itself with their peers versus “Oui, Madame/Monsieur” with adults; use gestures and other forms of non-verbal communication – such as kissing and hand shaking – as appropriate to the social context; use greetings, leave-taking expressions, and expressions of courtesy – such as “bonjour”, “au revoir”, “s’il vous plaît”, “merci’’ – as appropriate to the social context; use accepted verbal formulas for interrupting, initiating, and concluding conversations politely – such as “Pardon, Madame/Monsieur”)"}]}]},{"code":"C","title":"Reading","why":"","overall":[{"code":"C1","title":"Reading Comprehension","text":"determine meaning in a variety of French texts, using a range of reading comprehension strategies","specific":[{"code":"C1.1","title":"Using Reading Comprehension Strategies ","text":"identify a few reading comprehension strategies and use them before, during, and after reading to understand texts (e.g., preview texts by looking at images, captions, headlines, and tables to gain a sense of the subject matter and structure; use brainstorming to activate prior knowledge about a topic; preview vocabulary to identify familiar words and cognates; predict possible outcomes to a story based on knowledge of similar text forms; create mental images of the setting or characters based on descriptive details; use contextual clues to infer meaning; reread a section of text to confirm or clarify understanding)"},{"code":"C1.2","title":"Reading for Meaning","text":"demonstrate an understanding of French texts containing visuals and familiar names, words, and expressions, with teacher support as required (e.g., retell the events of a narrative in pictures and simple phrases using a graphic organizer to identify the beginning, middle, and end; create skits or commercials based on a text; make graphs or T-charts to organize information from a text; dramatize a story they have read using puppets or oral accounts; use visual art, music, or dance to communicate their reactions to a text; identify a classmate’s favourite pastime from information on his or her web page)"},{"code":"C1.3","title":"Reading with Fluency","text":"read texts containing familiar words and expressions at a sufficient rate and with sufficient ease to demonstrate that they understand the overall sense of the text (e.g., make reading aloud sound like spoken language, with appropriate expression and emphasis, and pauses, stops, and starts as indicated by the punctuation; recognize familiar language structures in different contexts; identify the same word in different graphic representations – such as on the word wall, in shared/guided/independent-reading texts, on shared- and interactive-writing charts used in personal writing, in a variety of fonts)"},{"code":"C1.4","title":"Developing Vocabulary","text":"use a few vocabulary-acquisition strategies before, during, and after reading to determine or confirm the meaning of new and unfamiliar words (e.g., update a personal list of familiar words using resources such as dictionaries and the word wall; develop lists of cognates to expand vocabulary; use knowledge of word structure [prefixes, stems, suffixes] to determine the meaning of unfamiliar words)"}]},{"code":"C2","title":"Purpose, Form, and Style ","text":"identify the purpose(s) and characteristics of a variety of adapted and authentic text forms, including fictional, informational, graphic, and media forms","specific":[{"code":"C2.1","title":"Purposes of Text Forms","text":"identify the purpose(s) of some familiar text forms, including fictional, informational, graphic, and media forms (e.g., letter/email – to ask for information, share news with a friend, extend or reply to an invitation, express thanks; list – to record or communicate information or instructions; fictional story/legend, such as the Métis legend Ti-Jean – to entertain or enlighten through a description of imaginary events, places, and people; travelogue – to describe the experience of travelling to or in a country or region; newspaper/magazine article – to explore/describe a contemporary issue, event, person in the news, or trend)"},{"code":"C2.2","title":"Characteristics of Text Forms","text":"identify some characteristics and/or stylistic elements of familiar text forms, including fictional, informational, graphic, and media forms (e.g., travelogue – sequential/chronological order, descriptions of experiences and key sites/ landmarks, maps/illustrations/photographs, captions; newspaper/magazine article – statement of theme or topic, photographs/illustrations, captions, title, author name, subheadings, sidebars, pull quotes; fictional story/legend – description of characters and setting, plot line involving a problem or conflict, resolution; textbook/informational text – table of contents, title page, chapter or section divisions, subsections with headings, charts/diagrams, labels/captions)"},{"code":"C2.3","title":"Metacognition","text":"(a) describe, in conversation with the teacher and their peers, a few strategies they found helpful before, during, and after reading to understand texts; (b) identify their areas of greater and lesser strength as readers, and plan steps they can take to improve their reading skills (e.g., use an interest survey to identify reading preferences and opportunities to expand choices for independent reading; reflect on the texts listed in a personal reading log and set a goal to read other genres)"}]},{"code":"C3","title":"Intercultural Understanding","text":"demonstrate an understanding of information in French texts about aspects of culture in diverse French-speaking communities and other communities around the world, and of French sociolinguistic conventions used in a variety of situations and communities","specific":[{"code":"C3.1","title":"Intercultural Awareness","text":"using information from a variety of French texts, identify French-speaking communities in Quebec, find out about aspects of their cultures, and make connections to personal experiences and their own and other communities (e.g., determine the ingredients in a typical Québécois dish such as “le pouding chômeur”; describe ideas, themes, and characters depicted in music, stories, and legends by Québécois artists and authors such as Alain M. Bergeron, Sheldon Cohen, or Samian; read about Québécois personalities such as Régine Chassagne, Bruny Surin, Céline Dion, Gilles Pelletier, or Marc Favreau, or historical figures, and describe some of their accomplishments)"},{"code":"C3.2","title":"Awareness of Sociolinguistic Conventions","text":"identify, in age- and grade-appropriate French texts, examples of sociolinguistic conventions associated with a variety of social situations in diverse French-speaking communities (e.g., in the lyrics of a popular Québécois rap or song, recognize and explain variations in the spelling of a common word – such as “p’tit” versus “petit”; identify salutations and common words and expressions used in different types of letters, emails, and postcards)"}]}]},{"code":"D","title":"Writing","why":"","overall":[{"code":"D1","title":"Purpose, Audience, and Form","text":"write French texts for different purposes and audiences, using a variety of forms","specific":[{"code":"D1.1","title":"Identifying Purpose and Audience","text":"determine, with support from the teacher, their purpose in writing and the audience for French texts they plan to create (e.g., to send a greeting to a parent or classmate; to describe a real or imaginary place in a postcard to a friend, parent, or teacher; to provide a family tree to show to members of their family; to describe their personal preferences and interests to a pen pal; to communicate information about the school intramural sports program to classmates; to entertain with an amusing anecdote; to share their feelings with an Elder, grandparent, or veteran regarding the teachings and lessons learned from him or her)"},{"code":"D1.2","title":"Writing in a Variety of Forms","text":"write a variety of age- and grade-appropriate French texts, applying their knowledge of the basic structural and stylistic elements of each form (e.g., a family tree – names of family members and labels identifying their relationship to the writer – such as “ma mère/mon père”, “mon frère/ma sœur”, “mon grand-père/ma grand-mère”; a greeting card – salutation, closing, and message suited to the occasion; a memo giving information about a school event – a heading identifying the intended audience, the time and place of the event, and other relevant details)"}]},{"code":"D2","title":"The Writing Process","text":"use the stages of the writing process – including pre-writing, producing drafts, revising, editing, and publishing – to develop and organize content, clarify ideas and expression, correct errors, and present their written work effectively","specific":[{"code":"D2.1","title":"Generating, Developing, and Organizing Content","text":"generate, develop, and organize ideas for writing, using a variety of pre-writing strategies and resources during modelled, shared, guided, and independent writing activities (e.g., view films to generate ideas; formulate questions to use in gathering information for a report on the favourite activities of their family and friends; use word lists and the word wall to create a list of vocabulary related to a topic; identify big ideas/ topics for writing from read-alouds and shared reading activities; brainstorm ideas for writing using visual prompts; use print resources and assistive technology to do research on a topic; use a graphic organizer to record and sort information from a field trip to use in a description of the outing; write or draw to explore different facets of ideas; use peer and teacher feedback to clarify the focus of a topic)"},{"code":"D2.2","title":"Drafting and Revising","text":"plan and produce drafts following a model (e.g., a letter or postcard template, a series of sentence starters), and revise their writing using a variety of strategies, with teacher support (e.g., reread, rethink, and use teacher feedback to determine the best order in which to present information; use a dictionary to monitor word choice; add or subtract information, based on peer or teacher feedback, to highlight the most important points; rewrite, edit, and revise using an editing checklist provided by the teacher and/or teacher and peer feedback)"},{"code":"D2.3","title":"Producing Finished Work","text":"make improvements to their written work using knowledge of a few of the conventions of written French (e.g., use personal word lists to spell familiar words and expressions correctly; distinguish between a question and a statement using appropriate punctuation; describe and distinguish between male and female members of the family using adjectives of the appropriate gender; use appropriate verb tenses according to the context), and use a few elements of effective presentation to produce a polished product for publication (e.g., select pictures appropriate to the subject matter; use headings to identify main ideas)"},{"code":"D2.4","title":"Metacognition ","text":"(a) describe, in conversation with the teacher and their peers, a few strategies they found helpful before, during, and after writing; (b) identify their areas of greater and lesser strength as writers, and plan steps they can take to improve their writing skills (e.g., record feelings and opinions about their written work in a personal journal; share with peers writing resources that they find useful; provide feedback to peers, and use feedback from teacher and peers to identify gaps in information and plan next steps)"}]},{"code":"D3","title":"Intercultural Understanding","text":"in their written work, demonstrate an awareness of aspects of culture in diverse French-speaking communities and other communities around the world, and of the appropriate use of French sociolinguistic conventions in a variety of situations","specific":[{"code":"D3.1","title":"Intercultural Awareness","text":"in their written work, communicate information about French-speaking communities in Quebec, including aspects of their cultures and their contributions to la francophonie and the world, and make connections to personal experiences and their own and other communities (e.g., create labels for a poster advertising a sports or music event in Quebec, such as le Festival Couleurs du monde; write an email to a Québécois student describing information they have learned about the student’s community and asking for further details or clarification of unfamiliar practices or traditions; describe the sights and sounds they see and hear at a traditional celebration such as a powwow)"},{"code":"D3.2","title":"Awareness of Sociolinguistic Conventions","text":"identify sociolinguistic conventions associated with a variety of social situations in diverse French-speaking communities and use them appropriately in their written work (e.g., greetings, leave-taking expressions, and expressions of courtesy – such as “bonjour”, “au revoir”, “oui”, “non”, “merci”, “s’il vous plaît”, “excusez-moi”; the proper format for salutations and closings in a personal [informal] letter, on a postcard, or in an email; appropriate expressions for introducing themselves or asking for information; conventions for writing the date in French – such as the use of lower-case letters for days of the week and months of the year)"}]}]}]},"g6":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-fsl","sourceLang":"en","strands":[{"code":"A","title":"Listening","why":"","overall":[{"code":"A1","title":"Listening to Understand","text":"determine meaning in a variety of oral French texts, using a range of listening strategies","specific":[{"code":"A1.1","title":"Using Listening Comprehension Strategies","text":"identify a range of listening comprehension strategies and use them before, during, and after listening to understand oral French texts (e.g., activate prior knowledge to make connections between texts and their own experiences; take notes to record new vocabulary; visualize different elements in a description and speak, mime, or draw to depict what they have imagined; use self-questioning and make predictions to monitor understanding while listening; formulate and ask questions to clarify understanding)"},{"code":"A1.2","title":"Demonstrating Understanding","text":"demonstrate an understanding of the purpose and meaning of oral French texts containing familiar and new words and expressions about themselves, family, friends, and topics of personal interest, with contextual and visual support (e.g., listen to a classmate’s description of a procedure and mime the steps and/or actions described; listen to a description of a person in a story/movie and identify which character is being described; listen to the results of a survey and use numbers, words, and pictures to illustrate the findings; listen to a read-aloud of an authentic text about the environment, healthy eating, or First Nations people and use words, pictures, and/or actions to restate the main idea and related details; listen to a popular song in French and identify familiar words and expressions; listen to directions to a popular location or attraction and trace the route on a map)"}]},{"code":"A2","title":"Listening to Interact","text":"interpret messages accurately while interacting in French for a variety of purposes and with diverse audiences","specific":[{"code":"A2.1","title":"Using Interactive Listening Strategies","text":"identify and use interactive listening strategies to suit a variety of situations while participating in social and academic interactions (e.g., ask questions to deepen understanding and make connections to the ideas of others; affirm the ideas of others and build on them when offering their own views; use brief vocal prompts to signal agreement or interest during conversations; ask for repetition when necessary)"},{"code":"A2.2","title":"Interacting","text":"respond with understanding to what others say while participating in guided interactions about familiar topics, with contextual and visual support (e.g., conduct and/or respond to a survey of classmates and compile information about their favourite foods, sports, and/or family activities; in collaboration with a peer, plan a waste-free lunch; exchange opinions with a peer about a favourite video game, movie, or book; listen and respond to questions from a partner about personal interests; listen to a short paragraph read by the teacher and work with a group to reconstruct the text; participate in a conversation about school rules by listening to classmates’ ideas and contributing their own opinion)"},{"code":"A2.3","title":"Metacognition","text":"(a) describe, in conversation with the teacher and their peers, factors that prevent them from listening effectively (e.g., lack of familiarity with topics discussed, lack of familiarity with vocabulary, difficulty processing information quickly) and some strategies they found helpful before, during, and after listening; (b) identify their areas of greater and lesser strength as listeners, and plan steps they can take to improve their listening skills (e.g., compare postures that are conducive and not conducive to attentive listening; reflect on their ability to respond to specific cues that signal the need for attentive listening; evaluate their use of listening strategies and plan to incorporate new strategies to ensure comprehension; record useful strategies in a learning log)"}]},{"code":"A3","title":"Intercultural Understanding","text":"demonstrate an understanding of information in oral French texts about aspects of culture in diverse French-speaking communities and other communities around the world, and of French sociolinguistic conventions used in a variety of situations and communities","specific":[{"code":"A3.1","title":"Intercultural Awareness","text":"using information from oral French texts, identify French-speaking communities in eastern, western, and northern Canada; find out about aspects of their cultures; and make connections to personal experiences and their own and other communities (e.g., identify examples from audio and/or audio-visual media that illustrate the status of French as an official language of Canada; listen to the national anthem in French and work in groups to map some similarities and differences between the French and English versions; listen to French Canadian folktales and legends and speak, draw, write, graph, or select images to illustrate topics that interest them; listen to historical accounts about the voyageurs and coureurs de bois and discuss their significance in the development of Canada as a nation; listen to songs such as “À la claire fontaine”, “C’est l’aviron”, “V’la l’bon vent” and identify their significance to Métis and other French Canadian communities; listen to participate in traditional storytelling games)"},{"code":"A3.2","title":"Awareness of Sociolinguistic Conventions","text":"using information from oral French texts, identify and demonstrate an understanding of sociolinguistic conventions used in a variety of situations in diverse French-speaking communities (e.g., identify similarities and differences in language used by different age groups; listen to examples of polite/familiar and singular/plural forms of address and identify the correct form to suit specific situations; respond with understanding to familiar expressions used in greetings and leave-takings)"}]}]},{"code":"B","title":"Speaking","why":"","overall":[{"code":"B1","title":"Speaking to Communicate","text":"communicate information and ideas orally in French, using a variety of speaking strategies and age- and grade-appropriate language suited to the purpose and audience","specific":[{"code":"B1.1","title":"Using Oral Communication Strategies ","text":"identify a range of speaking strategies and use them appropriately to express themselves clearly and coherently in French for a variety of purposes and to a variety of audiences (e.g., use gestures, familiar words, and memorized expressions based on a model to present and refine a message; provide supporting details to clarify ideas and opinions)"},{"code":"B1.2","title":"Producing Oral Communications","text":"using familiar words and expressions, produce brief, rehearsed messages in French containing ideas and information about themselves, family, friends, and their environment, with contextual, auditory, and visual support (e.g., describe past and future personal experiences and events, and everyday routines, using familiar sentence patterns and vocabulary; use familiar expressions and words as sentence starters; describe the findings of a survey about trades and professions in Canada; describe popular leisure activities in a particular region; describe how they are caring for the planet by being environmentally friendly; describe the roles of an animal within its ecosystem)"},{"code":"B1.3","title":"Speaking with Fluency","text":"speak with a smooth pace, appropriate intonation, and accurate pronunciation in rehearsed communications about personal and familiar topics (e.g., make straightforward requests, express preferences, and describe interests with minimal hesitation; express themselves with some facility on everyday topics, using familiar vocabulary, language patterns, and learned sentence structures; use standard greetings and expressions of courtesy with minimal hesitation in classroom activities; pronounce words correctly in classroom activities to practise new vocabulary)"}]},{"code":"B2","title":"Speaking to Interact","text":"participate in spoken interactions in French for a variety of purposes and with diverse audiences","specific":[{"code":"B2.1","title":"Using Speaking Interaction Strategies ","text":"demonstrate an understanding of appropriate speaking behaviour in a variety of situations (e.g., paraphrase to clarify meaning; acknowledge and show respect for different points of view; ask for information to clarify understanding; acknowledge the contributions of others before stating their own views; look at the listener/audience; use visual supports, facial expression, tone of voice, and gestures such as nodding, pointing, and shrugging to help clarify their meaning)"},{"code":"B2.2","title":"Interacting","text":"engage in guided spoken interactions with their peers and the teacher, using familiar words and expressions, with teacher modelling and support (e.g., initiate and respond to greetings; participate in brief conversations; outline rules and negotiate actions when playing barrier games; ask questions, describe different perspectives, and outline possible solutions in discussions about environmental issues; contribute and respond to comments in interactive games and role plays; ask and answer questions in conducting or responding to surveys and interviews)"},{"code":"B2.3","title":"Metacognition","text":"(a) describe, in conversation with the teacher and their peers, a few strategies they found helpful before, during, and after speaking to communicate effectively; (b) identify their areas of greater and lesser strength as speakers, and plan steps they can take to improve their speaking skills (e.g., use feedback from the teacher and peers to make revisions to the form and content of oral language as they speak; determine which strategies were helpful when presenting their message; plan to use effective communication strategies to enhance interactions with others)"}]},{"code":"B3","title":"Intercultural Understanding","text":"in their spoken communications, demonstrate an awareness of aspects of culture in diverse French-speaking communities and other communities around the world, and of the appropriate use of French sociolinguistic conventions in a variety of situations","specific":[{"code":"B3.1","title":"","text":"communicate information orally about French-speaking communities in eastern, western, and northern Canada, including aspects of their cultures and their contributions to la francophonie and the world, and make connections to personal experiences and their own and other communities (e.g., describe French-speaking communities, including Aboriginal communities, in the Atlantic provinces, the prairie and western provinces, and the northern territories; share ideas and opinions regarding Canadian Heritage Moments video clips about topics in French Canadian history – such as the Métis and the Acadians – and make cross-curricular connections to topics in social studies; discuss personal reactions to and opinions of songs and artwork by French Canadian artists, including Aboriginal artists such as Leah Fontaine, Marcien Lemay, or Derek Letourneau; describe traditions, festivals, songs, and cuisine from French-speaking regions in western, eastern, and northern Canada, and make connections to customs in their own community)"},{"code":"B3.2","title":"Awareness of Sociolinguistic Conventions","text":"identify sociolinguistic conventions associated with a variety of social situations in diverse French-speaking communities and use them appropriately in spoken interactions (e.g., use the correct form to refer to the days of the week, the months of the year, and the date and time; use the appropriate form of address – polite/familiar, singular/plural – to suit specific situations; use idiomatic expressions with “avoir” – such as “j’ai besoin de”, “tu as chaud”, “il a faim”, “elle a soif”, “nous avons confiance”, “vous avez froid”, “elles n’ont jamais tort”; use an appropriate form of words to show understanding or lack of understanding – such as “Je comprends”, “Je ne comprends pas”, “Comment?”)"}]}]},{"code":"C","title":"Reading","why":"","overall":[{"code":"C1","title":"Reading Comprehension","text":"determine meaning in a variety of French texts, using a range of reading comprehension strategies","specific":[{"code":"C1.1","title":"Using Reading Comprehension Strategies ","text":"identify a few reading comprehension strategies and use them before, during, and after reading to understand texts (e.g., use titles, captions, illustrations, and knowledge of similar forms to make predictions about a story; use brainstorming to activate prior knowledge about a topic; use visual cues to confirm or clarify details; use semantic [meaning] cues such as prefixes, suffixes, and base words to activate existing knowledge of oral and written language; make connections to personal experience to understand characters’ feelings and behaviour; ask questions to clarify meaning)"},{"code":"C1.2","title":"Reading for Meaning","text":"demonstrate an understanding of French texts containing visuals and familiar names, words, and expressions, with teacher support as appropriate (e.g., identify and restate the main idea in a letter from a pen pal, orally or by drawing or writing; read and mime the steps outlined in a classmate’s instructions for carrying out a procedure such as making a sandwich or bannock; read and dramatize a story using props; read a restaurant, cafeteria, or powwow vendor’s menu and identify items they would like to order; use a graphic organizer to record important information from a text; list questions they have about an issue or character described in a text)"},{"code":"C1.3","title":"Reading with Fluency ","text":"read texts containing familiar words and expressions at a sufficient rate and with sufficient ease to demonstrate that they understand the overall sense of the text (e.g., make reading aloud sound like spoken language, with appropriate expression and emphasis, and pauses, stops, and starts as indicated by the punctuation; identify the same word in different graphic representations – such as on the word wall, in shared/guided/independent-reading texts, on shared- and interactive-writing charts used in personal writing, in a variety of fonts)"},{"code":"C1.4","title":"Developing Vocabulary","text":"use a few vocabulary-acquisition strategies before, during, and after reading to determine or confirm the meaning of new, unfamiliar, or recently learned words (e.g., develop a bank of sight words using visual dictionaries and personal word lists; develop lists of cognates to expand vocabulary; use memory aids and visualization techniques to consolidate learning of new words; develop lists of words from oral vocabulary and grade-level texts to expand vocabulary; analyse word parts/structures to help determine meaning; compile thematic lists of key concepts to consolidate learning of new words; use a dictionary to expand vocabulary; use new words appropriately in different contexts)"}]},{"code":"C2","title":"Purpose, Form, and Style","text":"identify the purpose(s) and characteristics of a variety of adapted and authentic text forms, including fictional, informational, graphic, and media forms","specific":[{"code":"C2.1","title":"Purposes of Text Forms","text":"identify the purpose(s) of some familiar text forms, including fictional, informational, graphic, and media forms (e.g., “how-to” book – to describe the equipment and actions for carrying out a procedure; logo – to aid in quick recognition or identification of a company or product; poster – to present specific information in a striking, memorable way; catalogue – to provide information in a systematic, easy-to-retrieve form; text message – to share personal experiences, thoughts, and actions; poem/song – to express ideas or feelings in vivid, evocative language; short story – to entertain and/ or to depict or highlight the significance of imagined events or experiences)"},{"code":"C2.2","title":"Characteristics of Text Forms","text":"identify some characteristics and/or stylistic elements of familiar text forms, including fictional, informational, graphic, and media forms (e.g., poem/song – rhyming or non-rhyming patterns and use of imagery; short story/legend – plot line about resolving a problem or gaining an insight, descriptions of characters and settings; manual – numbered steps, diagrams; recipe – list of ingredients and quantities, steps in cooking procedure, cooking time, number of servings; travel brochure – description of destination sites and activities/events, description of accommodation, maps, contact information; magazine article – repetition of key words or phrases, titles, subtitles, text boxes; flyer – images and descriptions of products)"},{"code":"C2.3","title":"Metacognition","text":"(a) describe, in conversation with the teacher and their peers, a few strategies they found helpful before, during, and after reading to understand texts; (b) identify their areas of greater and lesser strength as readers, and plan steps they can take to improve their reading skills (e.g., scan texts to identify the elements of the particular form or unfamiliar words to look up)"}]},{"code":"C3","title":"Intercultural Understanding","text":"demonstrate an understanding of information in French texts about aspects of culture in diverse French-speaking communities and other communities around the world, and of French sociolinguistic conventions used in a variety of situations and communities","specific":[{"code":"C3.1","title":"Intercultural Awareness","text":"using information from a variety of French texts, identify French-speaking communities in eastern, western, and northern Canada; find out about aspects of their cultures; and make connections to personal experiences and their own and other communities (e.g., consult an atlas or website and identify French-speaking communities, including Aboriginal communities, in Atlantic Canada, the prairie and western provinces, and the northern territories; write a sample exchange of letters between Louis and Sarah Riel; identify examples of texts – such as bilingual signs or government brochures – that reflect the status of French as an official language of Canada; read the lyrics and listen to songs by various French Canadian and Aboriginal artists and make comparisons with songs in their own first language; identify examples of French on product labels and street signs, and in newspapers, telephone directories, and websites; identify the traits of heroes in traditional legends such as Ti-Jean and Nanabijou)"},{"code":"C3.2","title":"Awareness of Sociolinguistic Conventions","text":"identify, in age- and grade-appropriate French texts, examples of sociolinguistic conventions associated with a variety of social situations in diverse French-speaking communities (e.g., the familiar and formal forms of words and expressions used in email messages from social network friends in French-speaking communities across Canada – such as “À la prochaine” versus “Bien à vous”; appropriate ways to invite someone to do something; conventions of a personal or official letter)"}]}]},{"code":"D","title":"Writing","why":"","overall":[{"code":"D1","title":"Purpose, Audience, and Form","text":"write French texts for different purposes and audiences, using a variety of forms","specific":[{"code":"D1.1","title":"","text":"determine, with support from the teacher, their purpose in writing and the audience for French texts they plan to create (e.g., to describe personal activities and interests to the class; to record a schedule of activities in a personal diary; to outline the menu for a class celebration; to describe a fire evacuation route on a poster about school safety for the classroom; to provide a “to-do” list for a small-group project; to create a word web describing a character in a story for a class discussion; to add healthy or locally grown foods to the family’s weekly shopping list; to teach a friend how to cook a favourite dish; to complete a registration form for summer camp; to describe, for an advertising brochure, a company’s socially and environmentally responsible practices; to describe celebrations such as powwows; to describe garments historically worn by Métis and voyageurs in the fur trade)"},{"code":"D1.2","title":"Writing in a Variety of Forms","text":"write a variety of age- and grade-appropriate French texts, applying their knowledge of the basic structural and stylistic elements of each form (e.g., a menu outlining the courses for a traditional Métis family meal or a school event – subsections for different courses, brief descriptions of dishes with ingredients, illustrations, information about beverage choices; sequential chart – columns and rows for entering date/time and type of activity; brochure – headings, subheadings, illustrations/graphics, captions, descriptive or explanatory text; “how-to” manual, such as how to build a traditional canoe – lists of needed tools and materials, numbered steps, descriptions of techniques, diagrams/illustrations, captions; email message – subject line, salutation, closing/signature line)"}]},{"code":"D2","title":"The Writing Process","text":"use the stages of the writing process – including pre-writing, producing drafts, revising, editing, and publishing – to develop and organize content, clarify ideas and expression, correct errors, and present their work effectively","specific":[{"code":"D2.1","title":"Generating, Developing, and Organizing Content","text":"generate, develop, and organize ideas for writing, using a variety of pre-writing strategies and resources during modelled, shared, guided, and independent writing activities (e.g., refer to the word wall to identify vocabulary related to a topic; use brainstorming to activate prior knowledge about a topic; identify big ideas/topics for writing from read-alouds and shared reading activities; use print resources, Internet search engines, and assistive technology to research a topic; use peer and teacher feedback to clarify the focus of an idea for writing; use graphic organizers such as timelines and charts to record, sort, and classify information about a topic)"},{"code":"D2.2","title":"Drafting and Revising","text":"plan and produce drafts following a model (e.g., a model of a “how-to” manual or book; examples of pamphlets, brochures, advertisements, and/or logos provided by students; templates for letters, emails, or text messages), and revise their writing using a variety of strategies, with teacher support (e.g., review drafts to determine whether information is presented in the best order and to identify gaps; rewrite, edit, and revise based on teacher and peer feedback and/or an editing checklist provided by the teacher; use a dictionary to monitor word choice)"},{"code":"D2.3","title":"Producing Finished Work","text":"make improvements to their written work, using knowledge of some of the conventions of written French (e.g., spell familiar words correctly; verify that they have used the appropriate prepositions to indicate direction and location; verify that they have used appropriate endings to indicate the masculine or feminine form; verify that they have used the correct preposition with the verb to suit the context – as in “jouer à” for playing a sport versus “jouer de” for playing a musical instrument), and use a few elements of effective presentation to produce a polished product for publication (e.g., graphics, borders and shading, different text sizes and colours)"},{"code":"D2.4","title":"Metacognition","text":"(a) describe, in conversation with the teacher and their peers, some strategies they found helpful before, during, and after writing; (b) identify their areas of greater and lesser strength as writers, and plan steps they can take to improve their writing skills (e.g., act on teacher and peer feedback to identify information gaps; record writing successes and challenges in a personal journal; use a class-developed anchor chart to provide feedback to a partner; share and discuss with peers revision strategies that they find useful)"}]},{"code":"D3","title":"Intercultural Understanding","text":"in their written work, demonstrate an awareness of aspects of culture in diverse French-speaking communities and other communities around the world, and of the appropriate use of French sociolinguistic conventions in a variety of situations","specific":[{"code":"D3.1","title":"Intercultural Awareness","text":"in their written work, communicate information about French-speaking communities in eastern, western, and northern Canada, including aspects of their cultures and their contributions to la francophonie and the world, and make connections to personal experiences and their own and other communities (e.g., using a T-chart, organize and compare information about French-speaking communities in Manitoba and New Brunswick, such as St. Laurent and Memramcook; using a graphic organizer, classify the popular pastimes of French-speaking students in Atlantic Canada, the prairie and western provinces, and the northern territories; build a personal dictionary of French expressions from different regions and communities in Canada)"},{"code":"D3.2","title":"Awareness of Sociolinguistic Conventions","text":"identify examples of sociolinguistic conventions associated with a variety of social situations in diverse French-speaking communities and use them appropriately in their written work (e.g., greetings, leave-taking expressions, and expressions of courtesy; the proper format for salutations and closings in a personal [informal] letter, on a postcard, or in an email; conventions for writing the date in French; conventions for writing numbers and money amounts – such as the use of spaces in numbers with four or more digits [1 000] and the use of a comma rather than a decimal point in currency amounts [1,75 $])"}]}]}]}},"fsli":{"g1":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-fsl","sourceLang":"en","strands":[{"code":"A","title":"Listening","why":"","overall":[{"code":"A1","title":"Listening to Understand","text":"determine meaning in a variety of oral French texts, using appropriate listening strategies","specific":[{"code":"A1.1","title":"Using Listening Comprehension Strategies","text":"identify a few listening comprehension strategies and use them appropriately before, during, and after listening to understand a variety of oral French texts (e.g., ask questions to clarify meaning; review key vocabulary related to the topic before listening to an oral text; use background and prior knowledge to enhance understanding; restate important information to confirm or monitor understanding; pay attention to non-verbal cues such as facial expression, gestures, and tone of voice to aid comprehension)"},{"code":"A1.2","title":"Understanding Purposes for Listening","text":"demonstrate an understanding of the purpose for listening in a few specific situations (e.g., for enjoyment; to hear and identify the sounds of the French language in songs, chants, and poems; to increase vocabulary; to perform a task; to follow instructions; to learn about others; to understand information heard during a presentation in class; to participate in a class discussion)"},{"code":"A1.3","title":"Listening for Meaning","text":"demonstrate an understanding of the intent and meaning of oral French texts containing familiar words and expressions and dealing with everyday topics, with contextual and visual support (e.g., follow directions for daily routines; record information heard using pictures, words, and short sentences; demonstrate comprehension of “comptines” or songs from a variety of French-speaking communities through dramatization; ask and answer questions during a group discussion; identify the purpose and intended audience of an advertising jingle; use key words to explain the author’s message)"},{"code":"A1.4","title":"Responding to and Evaluating Media Texts","text":"express in verbal and non-verbal ways their personal thoughts, feelings, and opinions about the messages and the ways they are presented in brief oral media texts about familiar, everyday topics, with teacher support and guidance as appropriate (e.g., draw pictures or use mime to show how they feel after viewing/listening to a video report or song; give “oui” or “non” answers to questions about what they did or did not like about a video clip/film; describe the impact of sound effects on their own feelings; compare media texts to describe their effectiveness)"}]},{"code":"A2","title":"Listening to Interact","text":"interpret messages accurately while interacting in French for a variety of purposes and with diverse audiences","specific":[{"code":"A2.1","title":"Using Interactive Listening Strategies","text":"identify and use a few interactive listening strategies to suit a variety of situations while participating in structured and guided social and academic interactions (e.g., watch for non-verbal cues; look at and pay attention to the speaker; wait until the speaker has finished speaking before responding; identify appropriate moments to share relevant thoughts or ideas in a class discussion)"},{"code":"A2.2","title":"Interacting","text":"respond with understanding to what others say while participating in interactions about familiar, everyday topics (e.g., respond to a peer’s request in the classroom, using words, gestures, and/or visual aids; ask relevant questions during a conversation; listen to understand a peer’s point of view when resolving a conflict)"},{"code":"A2.3","title":"Metacognition","text":"(a) describe strategies they found helpful before, during, and after listening; (b) identify their areas of greater and lesser strength as listeners, and plan steps they can take to improve their listening skills (e.g., refer to an anchor chart or other classroom resources to compare postures that are conducive and not conducive to attentive listening; reflect on their ability to respond to specific cues that signal the need for attentive listening)"}]},{"code":"A3","title":"Intercultural Understanding","text":"demonstrate an understanding of information in oral French texts about aspects of culture in diverse French-speaking communities and other communities around the world, and of French sociolinguistic conventions used in a variety of situations and communities","specific":[{"code":"A3.1","title":"Intercultural Awareness","text":"using information from oral French texts, find out about aspects of the cultures of local French-speaking communities, and make connections to personal experiences and their own and other communities (e.g., listen to French songs or “comptines” from a variety of communities and compare them to similar texts from their own community; listen to information on family life in diverse French-speaking communities and describe what they heard)"},{"code":"A3.2","title":"Awareness of Sociolinguistic Conventions","text":"using information from oral French texts, identify and demonstrate an understanding of French sociolinguistic conventions used in a variety of situations (e.g., appropriate forms of salutation in different situations; formal/plural versus informal/singular forms of address; non-verbal cues such as body language and tone of voice)"}]}]},{"code":"B","title":"Speaking","why":"","overall":[{"code":"B1","title":"Speaking to Communicate","text":"communicate information and ideas orally in French, using a variety of speaking strategies and age- and grade-appropriate language suited to the purpose and audience","specific":[{"code":"B1.1","title":"Using Oral Communication Strategies","text":"identify a few speaking strategies and use them appropriately to express themselves clearly and coherently in French for various purposes and to a variety of audiences (e.g., use body language, including gestures and facial expressions, as well as changes in tone to support and clarify their message; practise with a partner; use vocabulary that is familiar to their audience; record a message and review it to improve their delivery)"},{"code":"B1.2","title":"Producing Oral Communications","text":"using familiar words and expressions, produce planned and rehearsed messages in French containing information and ideas about themselves and their family, friends, and immediate environment, with contextual, auditory, and visual support (e.g., recount events and key information; express wishes and needs to the teacher and their peers; record brief messages using technology; describe a character from a video clip and explain what makes the character appealing or not appealing; identify the message in an advertisement and describe how the colours used influence their response)"},{"code":"B1.3","title":"Speaking with Fluency","text":"speak with a smooth pace, appropriate intonation, and accurate pronunciation in planned and rehearsed communications about personal and familiar topics, using familiar words and expressions (e.g., use intonation when asking a question; incorporate familiar vocabulary in presentations; retell a story using a familiar structure such as beginning, middle, and end; perform a favourite family song or “comptine” for the class)"},{"code":"B1.4","title":"Creating Media Texts","text":"create oral media texts using forms, conventions, and techniques appropriate to the purpose and audience (e.g., present a slideshow accompanied by verbal descriptions of the members of their family; create an audio advertisement for an event; record a mock interview of a favourite performer or athlete with a classmate)"}]},{"code":"B2","title":"Speaking to Interact","text":"participate in spoken interactions in French for a variety of purposes with diverse audiences","specific":[{"code":"B2.1","title":"Using Speaking Interaction Strategies","text":"demonstrate an understanding of appropriate speaking behaviour in a variety of situations (e.g., take turns; stay on topic; adjust tone and volume to the situation; use a combination of words and non-verbal cues)"},{"code":"B2.2","title":"Interacting","text":"engage in rehearsed and spontaneous spoken interactions, in structured and guided social and academic contexts, on familiar topics related to matters of personal interest or daily routines (e.g., ask and answer questions about themselves, their families, and their neighbourhoods; rehearse a conversation with a partner in which they take on particular roles; plan a group project with classmates)"},{"code":"B2.3","title":"Metacognition","text":"(a) describe strategies they found helpful before, during, and after speaking to communicate effectively; (b) identify their areas of greater and lesser strength as speakers, and plan steps they can take to improve their speaking skills (e.g., determine the elements of effective presentations; provide feedback on a peer’s oral presentation and listen to peers’ comments about their own presentations; evaluate their use of French in daily interactions with peers and teachers)"}]},{"code":"B3","title":"Intercultural Understanding","text":"in their spoken communications, demonstrate an awareness of aspects of culture in diverse French-speaking communities and other communities around the world, and of the appropriate use of French sociolinguistic conventions in a variety of situations","specific":[{"code":"B3.1","title":"Intercultural Awareness","text":"communicate information orally about local French-speaking communities, including aspects of their cultures and their contributions to la francophonie and the world, and make connections to personal experiences and their own and other communities (e.g., communicate information about Franco-Ontarian foods, songs, children’s games, or sports that they have collected from various sources, including French-speaking members of the school community; make personal connections between aspects of life in French-speaking communities and their own lives)"},{"code":"B3.2","title":"Awareness of Sociolinguistic Conventions","text":"identify sociolinguistic conventions associated with a variety of social situations in French-speaking communities, and use them appropriately in spoken interactions (e.g., standard greetings and leave-taking expressions; polite versus informal forms of address; ways of politely joining a conversation)"}]}]},{"code":"C","title":"Reading","why":"","overall":[{"code":"C1","title":"Reading Comprehension ","text":"determine meaning in a variety of French texts, using a few reading comprehension strategies","specific":[{"code":"C1.1","title":"Using Reading Comprehension Strategies","text":"identify a few reading comprehension strategies and use them appropriately before, during, and after reading to understand a variety of French texts, with teacher support (e.g., use visualization to help clarify descriptions of scenes in a story; preview vocabulary to identify familiar words and cognates; use pictures and contextual clues to predict meaning and confirm understanding of a text; use knowledge of form to understand the author’s purpose)"},{"code":"C1.2","title":"Reading for Meaning","text":"demonstrate an understanding of the intent and meaning of French texts containing familiar words and expressions and dealing with everyday topics, with contextual and visual support (e.g., mime actions from a descriptive poem or “comptine”; retell a story they have read; describe some symbols and words used on signs in their community and explain what they mean; make connections between a story they have read and a personal experience; identify who is missing from an advertisement for a toy, and explain how that child might feel; explain why some information on a product is given in large, bold type and other information is given in smaller type)"},{"code":"C1.3","title":"Reading with Fluency","text":"read French texts containing familiar words, names, expressions, and language structures, and dealing with everyday topics, at a sufficient rate and with sufficient ease to convey the sense of the text, using a variety of cues (e.g., connect letter combinations to specific sounds in high-frequency words; recognize common spelling patterns; recognize familiar words, phrases, sentences, and visuals that connect to existing knowledge of oral and written language; recognize marks of punctuation and use them to understand the relationship between words, phrases, and sentences; read confidently and accurately when participating in shared reading of pattern books, “comptines”, and poems; recognize and read numbers to thirty, written in numerals and in words)"},{"code":"C1.4","title":"Developing Vocabulary","text":"identify and use a few strategies to expand vocabulary through reading (e.g., identify cognates [mots apparentés] and familiar words; recognize smaller words within larger words; refer to an interactive word wall to determine the meaning of a word; use a concept map to list related vocabulary; use context and knowledge of familiar words to infer the meaning of unfamiliar words)"},{"code":"C1.5","title":"Responding to and Evaluating Media Texts","text":"express personal thoughts, feelings, and opinions about the messages and the ways they are presented in media texts about familiar, everyday topics, with teacher support as appropriate (e.g., give reasons why they think an advertisement is effective; explain why they do or do not believe the message in an advertisement; describe or draw a picture to show how a poster, an advertisement, or the packaging for a video makes them feel; explain why the words, expressions, and colours on a cereal box might make it appealing to a young person; create a collage promoting healthy eating habits after visiting a website)"}]},{"code":"C2","title":"Purpose, Form, and Style","text":"identify the purpose(s) and characteristics of a variety of adapted and authentic text forms, including fictional, informational, graphic, and media forms","specific":[{"code":"C2.1","title":"Purposes of Text Forms","text":"identify the purpose(s) of some familiar text forms, including fictional, informational, graphic, and media forms, with support and guidance from the teacher (e.g., poem/song – to express ideas or convey a mood; picture book – for entertainment and reflection; pattern book story – to entertain and/or explore characters, ideas, and problems; “comptine” – for enjoyment of the rhythmic and musical qualities of language and for practice in recognizing letter-sound relationships and basic sentence structures; labels – for information; restaurant menu – to describe food offerings; greeting card – to send good wishes or to say thank you; advertisement – to attract attention and persuade; account or report – to describe an experience or event)"},{"code":"C2.2","title":"Characteristics and Stylistic Elements of Text Forms","text":"identify some characteristics and/or stylistic elements of a variety of text forms, including fictional, informational, graphic, and media forms, with support and guidance from the teacher (e.g., poem/song – rhyming or non-rhyming patterns and use of imagery; pattern book story – title page, illustrations, repetitive use of familiar words, phrases, and sentence structures; science book – titles and subtitles as key organizational features; greeting card – special fonts, illustrations, colours; restaurant menu – subsections grouping offerings of main courses/beverages/desserts, prices, illustrations)"},{"code":"C2.3","title":"Metacognition","text":"(a) identify, in conversation with the teacher and their peers, a few strategies they found helpful before, during, and after reading to understand texts; (b) identify their areas of greater and lesser strength as readers, and plan steps they can take to improve their reading skills (e.g., ask a peer to comment on their reading of a text; listen to peers’ comments about their expressiveness when reading; consider book recommendations from the teacher and peers to expand their choices for independent reading)"}]},{"code":"C3","title":"Intercultural Understanding","text":"demonstrate an understanding of information in French texts about aspects of culture in diverse French-speaking communities and other communities around the world, and of French sociolinguistic conventions used in a variety of situations and communities","specific":[{"code":"C3.1","title":"Intercultural Awareness","text":"using information from a variety of French texts, identify local French-speaking communities, find out about aspects of their cultures, and make connections to personal experiences and their own and other communities (e.g., identify some features of a French-speaking community, using information from stories; identify places in their community where they might read French signs or texts; describe social and cultural customs depicted in a pattern book; compare regional traditions and festivals, children’s games, popular songs, and family traditions)"},{"code":"C3.2","title":"Awareness of Sociolinguistic Conventions","text":"identify, in age- and grade-appropriate French texts, examples of sociolinguistic conventions associated with a variety of social situations (e.g., different forms of greetings used with peers and adults; expressions of courtesy; expressions for indicating agreement or disagreement; words used for the same item in different communities; variations in pronunciation of the same word in different communities)"}]}]},{"code":"D","title":"Writing","why":"","overall":[{"code":"D1","title":"Purpose, Audience, and Form","text":"write in French in a variety of forms and for a variety of purposes and audiences, using knowledge of vocabulary and stylistic elements to communicate clearly and effectively","specific":[{"code":"D1.1","title":"Identifying Purpose and Audience","text":"determine, with support from the teacher, their purpose for writing and the audience for French texts they plan to create (e.g., to compile a menu of healthy foods for a class celebration; to share information about their family in an entry in the class book; to thank a community visitor in a letter for making a presentation to the class; to invite the principal to attend a classroom celebration; to describe an animal’s appearance and behaviour for a science project; to label a picture in a reading response, using familiar and new vocabulary; to describe family members using a family tree)"},{"code":"D1.2","title":"Writing in a Variety of Forms","text":"write a variety of texts in French, conveying information, ideas, and opinions about themselves, friends, family, and their immediate environment, following models appropriate to the purpose and incorporating some of the basic elements of each form (e.g., compose a personal account of a class event or outing; create a “how-to” book; compile a list of signs of fall/winter/spring/summer following an exploration of the neighbourhood; share preferences in a report; participate in shared writing of a class book, list, poem, poster, or speech bubbles for a graphic story; incorporate some elements of familiar texts in their own writing)"},{"code":"D1.3","title":"Developing Vocabulary","text":"confirm word meanings and review, refine, and vary word choices, using a variety of resources (e.g., use a personal word list with familiar names, places, people, and objects; use classroom anchor charts, word lists, and dictionaries with pictures; consult with peers; discuss and use previous knowledge to expand vocabulary; analyse written texts to find new vocabulary related to familiar topics; ask and answer questions before writing a text; break words into phonemes and identify cognates; integrate new words into their writing after studying a written story)"},{"code":"D1.4","title":"Using Stylistic Elements","text":"begin to establish a personal voice and a clear point of view, with teacher support (e.g., use the narrative pattern in a familiar story to write a story of their own; use pictures and words that convey their intended mood or message; adopt a point of view when writing about a familiar topic)"},{"code":"D1.5","title":"Creating Media Texts","text":"using familiar words and expressions, create a variety of media texts in French for specific purposes and audiences, using a few simple media forms and the conventions and techniques appropriate to the chosen form (e.g., analyse a media text to explore basic elements and the author’s techniques, and incorporate some of these elements into their own writing; use technology to advertise or write about an event in their community; use images, symbols, and words to express personal likes and dislikes on a poster)"}]},{"code":"D2","title":"The Writing Process","text":"use the stages of the writing process – including pre-writing, producing drafts, revising, editing, and publishing – to develop and organize content, clarify ideas and expression, correct errors, and present their written work effectively","specific":[{"code":"D2.1","title":"Generating, Developing, and Organizing Ideas","text":"generate, develop, focus, and organize ideas for writing, using a variety of strategies and print, electronic, and other resources, as appropriate (e.g., brainstorm to generate ideas for writing; use word walls to identify vocabulary related to their topic; create a sketch to help them focus ideas and clarify thoughts; use graphic or visual organizers to help them to classify and sort ideas)"},{"code":"D2.2","title":"Drafting and Revising","text":"plan and produce drafts, following a model, and revise their writing to improve its content, clarity, and interest, using a few simple strategies (e.g., use words and pictures to write texts related to familiar topics; consider feedback from the teacher and their peers when making revisions; use punctuation for specific effects, such as an exclamation mark to show enthusiasm; refer to classroom resources such as anchor charts and checklists when making revisions; share writing with a peer to help them revise their text)"},{"code":"D2.3","title":"Producing Finished Work","text":"edit, proofread, and publish a variety of written pieces, following a model or a set of guidelines to meet established criteria, with support as appropriate (e.g., proofread and correct their writing using guiding questions provided by the teacher; consult a checklist co-constructed with the teacher; use some appropriate elements such as proper spacing between words, graphics, pictures, different fonts, headings, and captions in the finished product to add to the effectiveness of their presentation)"},{"code":"D2.4","title":"Metacognition","text":"(a) identify, in conversation with the teacher and their peers, a few strategies they found helpful before, during, and after writing; (b) determine their areas of greater and lesser strength as writers, and plan steps they can take to improve their writing skills (e.g., in a conference with the teacher, evaluate their plan for writing; use comments on their written text from the teacher and their peers to plan next steps; reflect on their ability to represent familiar words in writing)"}]},{"code":"D3","title":"Intercultural Understanding","text":"in their written work, demonstrate an awareness of aspects of culture in diverse French-speaking communities and other communities around the world, and of the appropriate use of French sociolinguistic conventions in a variety of situations","specific":[{"code":"D3.1","title":"Intercultural Awareness","text":"communicate information in writing about local French-speaking communities, including aspects of their cultures and their contributions to la francophonie and the world, and make connections to personal experiences and their own and other communities (e.g., use words and pictures to communicate information about a French-speaking community; write a dialogue taking place in a French shop, using a question-and-answer format; list places in their community where they can read and/or listen to French; incorporate French names from diverse French-speaking communities in their story writing)"},{"code":"D3.2","title":"Awareness of Sociolinguistic Conventions","text":"identify sociolinguistic conventions associated with a variety of social situations in French-speaking communities, and use them appropriately in their written work (e.g., the appropriate uses of different salutations and leave-taking expressions, such as “bonjour”, “salut”, “bonsoir”, “à bientôt”, “au revoir”, “adieu”, “amitiés”, “ton ami(e)”; informal and polite forms of address; use of terms of endearment in a letter or note)"}]}]}]},"g2":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-fsl","sourceLang":"en","strands":[{"code":"A","title":"Listening","why":"","overall":[{"code":"A1","title":"Listening to Understand","text":"determine meaning in a variety of oral French texts, using appropriate listening strategies","specific":[{"code":"A1.1","title":"Using Listening Comprehension Strategies","text":"identify a few listening comprehension strategies and use them appropriately before, during, and after listening to understand a variety of oral French texts (e.g., adopt an attitude conducive to listening during a presentation; restate information to confirm understanding; use context and background knowledge to make predictions while listening to a read-aloud; create a mental picture while listening to a song)"},{"code":"A1.2","title":"Understanding Purposes for Listening","text":"demonstrate an understanding of the purpose for listening in a few specific situations (e.g., to receive instructions for a task; to be able to respond to questions; to understand a presentation; to identify rhymes, words, and language patterns)"},{"code":"A1.3","title":"Listening for Meaning","text":"demonstrate an understanding of the intent and meaning of oral French texts containing familiar words and expressions and dealing with everyday topics, with contextual and visual support (e.g., share information heard using pictures, words, and sentences; create visual art in response to an oral text; ask questions after listening to a presentation; follow oral directions to participate in a game during daily physical activity/activité physique quotidienne; list key words and expressions that were used to describe important ideas in an oral presentation; identify key messages heard in a poem; reconstruct a story from a read-aloud using pictures)"},{"code":"A1.4","title":"Responding to and Evaluating Media Texts","text":"express in verbal and non-verbal ways their personal thoughts, feelings, and opinions about the messages and the ways they are presented in brief oral media texts about familiar, everyday topics, with teacher support and guidance as appropriate (e.g., compare and analyse how sound effects support the spoken messages in an advertisement or film; evaluate the effectiveness of the choice of words in a variety of oral media texts; name the product in an advertisement and list the reasons given for why they should buy it)"}]},{"code":"A2","title":"Listening to Interact","text":"interpret messages accurately while interacting in French for a variety of purposes and with diverse audiences","specific":[{"code":"A2.1","title":"Using Interactive Listening Strategies","text":"identify and use a few interactive listening strategies to suit a variety of situations while participating in structured and guided social and academic interactions (e.g., watch for nonverbal cues; paraphrase to confirm understanding; ask questions for clarification; nod or use facial expressions to signal interest and understanding)"},{"code":"A2.2","title":"Interacting","text":"respond with understanding to what others say while participating in interactions about familiar, everyday topics (e.g., participate in a group discussion; ask questions to gather information at a francophone or Aboriginal celebration; listen to various points of view to resolve conflicts in classroom community circles; ask and answer questions about local animals and plant life in an inside/outside circle)"},{"code":"A2.3","title":"Metacognition","text":"(a) describe strategies they found helpful before, during, and after listening; (b) identify their areas of greater and lesser strength as listeners, and plan steps they can take to improve their listening skills (e.g., role-play examples of attentive and inattentive listening; record in a journal situations in which they were successful and challenged when listening; identify strategies to address distractions in listening situations)"}]},{"code":"A3","title":"Intercultural Understanding","text":"demonstrate an understanding of information in oral French texts about aspects of culture in diverse French-speaking communities and other communities around the world, and of French sociolinguistic conventions used in a variety of situations and communities","specific":[{"code":"A3.1","title":"Intercultural Awareness","text":"using information from oral French texts, find out about aspects of the cultures of local French-speaking communities, and make connections to personal experiences and their own and other communities (e.g., compare music from a French-speaking community to their own; listen to stories, songs, or “comptines” to learn interesting facts and historical information about a particular French-speaking community, including First Nations, Métis, and Inuit communities; recognize the use of French words, expressions, and names of people and places in their community)"},{"code":"A3.2","title":"Awareness of Sociolinguistic Conventions","text":"using information from oral French texts, identify and demonstrate an understanding of French sociolinguistic conventions used in a variety of situations (e.g., formal and informal forms of address required for different audiences; standard ways to introduce someone; non-verbal cues when listening in interactive situations)"}]}]},{"code":"B","title":"Speaking","why":"","overall":[{"code":"B1","title":"Speaking to Communicate","text":"communicate information and ideas orally in French, using a variety of speaking strategies and age- and grade-appropriate language suited to the purpose and audience","specific":[{"code":"B1.1","title":"Using Oral Communication Strategies","text":"identify a few speaking strategies and use them appropriately to express themselves clearly and coherently in French for various purposes and to a variety of audiences (e.g., use body language such as position and eye contact to support their message; refer to anchor charts and classroom visuals to find appropriate words and sentence structures; rehearse with a peer before presenting a brief message)"},{"code":"B1.2","title":"Producing Oral Communications","text":"using familiar words and expressions, produce planned and rehearsed messages in French containing information and ideas about themselves and their family, friends, and immediate environment, with contextual, auditory, and visual support (e.g., express opinions and responses in complete sentences; give directions for a procedure; share information about a favourite toy; describe familiar events and personal experiences; discuss personal feelings about the main character in a story; share different points of view about the same media text; ask questions in a role play between characters in a film; share a grandparent’s or Elder’s story)"},{"code":"B1.3","title":"Speaking with Fluency","text":"speak with a smooth pace, appropriate intonation, and accurate pronunciation in planned and rehearsed communications about personal and familiar topics, using familiar words and expressions (e.g., recite a poem with appropriate expression, phrasing, and intonation; use accepted pronunciation for high-frequency words, regularly used phrases, and words with personal significance in brief oral exchanges, dialogues, and presentations; accurately pronounce familiar vocabulary when introducing themselves or their friends and family; use intonation as modelled by the teacher to ask questions; deliver a rehearsed oral presentation at a smooth pace with appropriate phrasing and emphasis)"},{"code":"B1.4","title":"Creating Media Texts","text":"create oral media texts using forms, conventions, and techniques appropriate to the purpose and audience (e.g., create a video describing their morning routine; create and present an announcement about the importance of a healthy snack; create a video about items that can and cannot be recycled; record an explanation of their artwork for a multimedia art presentation; use sound effects to support the message in an advertisement)"}]},{"code":"B2","title":"Speaking to Interact","text":"participate in spoken interactions in French for a variety of purposes with diverse audiences","specific":[{"code":"B2.1","title":"Using Speaking Interaction Strategies","text":"demonstrate an understanding of appropriate speaking behaviour in a variety of situations (e.g., paraphrase to confirm understanding; use appropriate tone of voice for an interaction; consult classroom references to select appropriate words and sentence structures for their conversations)"},{"code":"B2.2","title":"Interacting","text":"engage in rehearsed and spontaneous spoken interactions, in structured and guided social and academic contexts, on familiar topics related to matters of personal interest or daily routines (e.g., ask and answer questions to understand someone’s point of view and share their own; role-play different interactive situations in everyday life; introduce a classmate to another classmate)"},{"code":"B2.3","title":"Metacognition","text":"(a) describe strategies they found helpful before, during, and after speaking to communicate effectively; (b) identify their areas of greater and lesser strength as speakers, and plan steps they can take to improve their speaking skills (e.g., share and discuss a strategy used to enhance their participation in a discussion; compare speaking situations to reflect on their own ability to communicate; consult classroom visuals and reference material to support the development of their speaking skills)"}]},{"code":"B3","title":"Intercultural Understanding","text":"in their spoken communications, demonstrate an awareness of aspects of culture in diverse French-speaking communities and other communities around the world, and of the appropriate use of French sociolinguistic conventions in a variety of situations","specific":[{"code":"B3.1","title":"Intercultural Awareness","text":"communicate information orally about local French-speaking communities, including aspects of their cultures and their contributions to la francophonie and the world, and make connections to personal experiences and their own and other communities (e.g., role-play and ask questions about the traditions in a particular French-speaking community; share information about a French-speaking community during a group presentation; describe an artefact from a particular French-speaking region and share its significance)"},{"code":"B3.2","title":"Awareness of Sociolinguistic Conventions","text":"identify sociolinguistic conventions associated with a variety of social situations in French-speaking communities, and use them appropriately in spoken interactions (e.g., greetings, leave-taking expressions, and expressions of courtesy – “bonjour”,” salut”, “au revoir”, “à demain”, “oui”, “non”, “merci”, “s’il vous plait”, “excusez-moi” – appropriate to the social context; gestures and other forms of non-verbal communication appropriate to the social context – bowing, shrugging, hand shaking; standard introductory phrases to give personal information – “Je m’appelle… J’habite…”)"}]}]},{"code":"C","title":"Reading","why":"","overall":[{"code":"C1","title":"Reading Comprehension","text":"determine meaning in a variety of French texts, using a few reading comprehension strategies","specific":[{"code":"C1.1","title":"Using Reading Comprehension Strategies","text":"identify a few reading comprehension strategies and use them appropriately before, during, and after reading to understand a variety of French texts, with teacher support (e.g., use questions to select information when reading; use personal experiences to make inferences during reading; make text-to-text connections between fiction and non-fiction texts on the same topic; divide words into syllables; use details and information from text to confirm predictions)"},{"code":"C1.2","title":"Reading for Meaning","text":"demonstrate an understanding of the intent and meaning of French texts containing familiar words and expressions and dealing with everyday topics, with contextual and visual support (e.g., use drama to explore the personality traits of a character in a story they are reading; share personal experiences to support their understanding of the implicit message in a text; draw a picture to illustrate a text’s main idea or key message)"},{"code":"C1.3","title":"Reading with Fluency","text":"read French texts containing familiar words, names, expressions, and language structures, and dealing with everyday topics, at a sufficient rate and with sufficient ease to convey the sense of the text, using a variety of cues (e.g., read text aloud with intonation based on punctuation; use knowledge of consonant blends and phonemes to read new words; participate in a reader’s theatre; find words with a specific phoneme in independent reading selections)"},{"code":"C1.4","title":"Developing Vocabulary","text":"identify and use a few strategies to expand vocabulary through reading (e.g., refer to personal dictionaries and vocabulary lists; find synonyms, cognates, and familiar words in a text; record the use and context of new and interesting words; use visual elements from the text to help them determine the meaning of new vocabulary; use context to help them understand new words; use new vocabulary when sharing information from a text)"},{"code":"C1.5","title":"Responding to and Evaluating Media Texts","text":"express personal thoughts, feelings, and opinions about the messages and the ways they are presented in media texts about familiar, everyday topics, with teacher support as appropriate (e.g., evaluate the effectiveness of a newspaper advertisement, and state why they agree or disagree with its message; determine the intent of a poster; explain how a movie advertisement influences their decision about whether or not to watch the film; discuss the effectiveness of word choice and the amount of text on the packaging of products for children)"}]},{"code":"C2","title":"Purpose, Form, and Style","text":"identify the purpose(s) and characteristics of a variety of adapted and authentic text forms, including fictional, informational, graphic, and media forms","specific":[{"code":"C2.1","title":"Purposes of Text Forms","text":"identify the purpose(s) of some familiar text forms, including fictional, informational, graphic, and media forms, with support and guidance from the teacher (e.g., procedural text – to provide instructions on how to accomplish a task; non-fiction – to convey information; personal account/narrative – to prompt discussions around thought-provoking questions; strategy/anchor chart – to note information from oral discussions)"},{"code":"C2.2","title":"Characteristics and Stylistic Elements of Text Forms","text":"identify some characteristics and/or stylistic elements of a variety of text forms, including fictional, informational, graphic, and media forms, with support and guidance from the teacher (e.g., textbook – table of contents, headings, and index to help locate information; personal account – personal experiences, past tense, first person; fairy tale/folktale – usually begins with “Il était une fois…”, moral, hero(in)es; website – sidebars with subtitles to indicate information on linked pages; sports/trading card – biographical information, statistics, team name; recipe – list of ingredients, numbered steps, description of procedure; reader’s theatre script – character names followed by a colon to indicate who reads each line)"},{"code":"C2.3","title":"Metacognition","text":"(a) identify, in conversation with the teacher and their peers, a few strategies they found helpful before, during, and after reading to understand texts; (b) determine their areas of greater and lesser strength as readers, and plan steps they can take to improve their reading skills (e.g., use book reviews written by peers to expand choices for independent reading; discuss useful strategies for understanding a new expression in a text; share helpful strategies with peers; establish next steps after a guided reading lesson)"}]},{"code":"C3","title":"Intercultural Understanding","text":"demonstrate an understanding of information in French texts about aspects of culture in diverse French-speaking communities and other communities around the world, and of French sociolinguistic conventions used in a variety of situations and communities","specific":[{"code":"C3.1","title":"Intercultural Awareness","text":"using information from a variety of French texts, identify local French-speaking communities, find out about aspects of their cultures, and make connections to personal experiences and their own and other communities (e.g., read articles online and in magazines to collect information about social and cultural customs in a French-speaking community; identify and correctly read city and country names in French on a map and compare those to their names in English; read about a local French-speaking community; identify examples of bilingual signs and texts in their community)"},{"code":"C3.2","title":"Awareness of Sociolinguistic Conventions","text":"identify, in age- and grade-appropriate French texts, examples of sociolinguistic conventions associated with a variety of social situations (e.g., forms of address; regional words and expressions from different communities; conventions for an invitation or greeting card; conventions for a registration form)"}]}]},{"code":"D","title":"Writing","why":"","overall":[{"code":"D1","title":"Purpose, Audience, and Form","text":"write in French in a variety of forms and for a variety of purposes and audiences, using knowledge of vocabulary and stylistic elements to communicate clearly and effectively","specific":[{"code":"D1.1","title":"Identifying Purpose and Audience","text":"determine, with support from the teacher, their purpose for writing and the audience for French texts they plan to create (e.g., to label a diagram or illustration; to fill in a registration form; to describe a friend using familiar adjectives and adverbs on a poster; to recommend a book to classmates; to collaborate with classmates on a friendly letter to an author; to respond to a read-aloud in a double-entry journal, following a model; to write personal opinions about images on the home page of a website; to create an advertisement about a favourite toy or an eco-friendly product; to produce an informative brochure on a local tourist attraction)"},{"code":"D1.2","title":"Writing in a Variety of Forms","text":"write a variety of texts in French, conveying information, ideas, and opinions about themselves, friends, family, and their immediate environment, following models appropriate to the purpose and incorporating some of the basic elements of each form (e.g., recount a family celebration; compose a poem for a greeting card; develop a class report on a social or environmental topic of interest; compose a persuasive slogan for a toy label; write a recipe; ask questions in a letter or note to a friend)"},{"code":"D1.3","title":"Developing Vocabulary","text":"confirm word meanings and review, refine, and vary word choices, using a variety of resources (e.g., incorporate interesting words and expressions from their reading or from the word wall in their written texts; brainstorm vocabulary related to familiar and relevant topics; record and organize new vocabulary for a project in a mind map or word web; share new words and expressions with a peer; sort new words into categories to use in a piece of writing)"},{"code":"D1.4","title":"Using Stylistic Elements","text":"begin to establish a personal voice and a clear point of view, with teacher support (e.g., use rhyme or repetition to emphasize an idea; use words to convey meaning, an attitude, or a feeling; use pictures or charts to add context to writing)"},{"code":"D1.5","title":"Creating Media Texts","text":"using familiar words and expressions, create a variety of media texts in French for specific purposes and audiences, using a few simple media forms and the conventions and techniques appropriate to the chosen form (e.g., explore information on a cereal box to identify key elements necessary to create a product box of their own; write a weather report containing symbols and a legend; create a web page or a captioned slideshow describing a typical day in Grade 2; create a personal or family emblem; create a poster or write a blog post sharing instructions for caring for a plant or pet)"}]},{"code":"D2","title":"The Writing Process","text":"use the stages of the writing process – including pre-writing, producing drafts, revising, editing, and publishing – to develop and organize content, clarify ideas and expression, correct errors, and present their written work effectively","specific":[{"code":"D2.1","title":"Generating, Developing, and Organizing Ideas","text":"generate, develop, focus, and organize ideas for writing, using a variety of strategies and print, electronic, and other resources, as appropriate (e.g., use background knowledge and personal experiences to generate ideas about familiar topics; use pictures and graphic organizers to help them select and organize ideas; in pairs or groups, list ideas for shared or independent writing)"},{"code":"D2.2","title":"Drafting and Revising","text":"plan and produce drafts, following a model, and revise their writing to improve its content, clarity, and interest, using a few simple strategies (e.g., use a teacher- or class-generated graphic organizer or model when planning their writing; reread, change, add, remove, and reorganize content; rewrite, edit, and revise drafts based on feedback from the teacher and their peers; use criteria co-constructed with the teacher and their peers to improve their writing)"},{"code":"D2.3","title":"Producing Finished Work","text":"edit, proofread, and publish a variety of written pieces, following a model or a set of guidelines to meet established criteria, with support as appropriate (e.g., proofread and correct their writing using a checklist or guiding questions provided by the teacher; spell familiar words correctly and with appropriate accents; use high-frequency adjectives of colour, quantity, location, and sentiment to enhance their messages; use the correct subject pronouns to refer to family members, friends, community members, animals, and living things in nature; use high- frequency verbs in the present tense to describe things that are happening to and around them)"},{"code":"D2.4","title":"Metacognition","text":"(1) identify, in conversation with the teacher and their peers, a few strategies they found helpful before, during, and after writing; (b) determine their areas of greater and lesser strength as writers, and plan steps they can take to improve their writing skills (e.g., record feelings and opinions about their written work in a personal journal; share with peers writing resources that they find useful; provide feedback to peers, and refer to feedback from their teacher and peers when planning next steps)"}]},{"code":"D3","title":"Intercultural Understanding","text":"in their written work, demonstrate an awareness of aspects of culture in diverse French-speaking communities and other communities around the world, and of the appropriate use of French sociolinguistic conventions in a variety of situations","specific":[{"code":"D3.1","title":"Intercultural Awareness","text":"communicate information in writing about local French-speaking communities, including aspects of their cultures and their contributions to la francophonie and the world, and make connections to personal experiences and their own and other communities (e.g., write about customs and traditions of French-speaking communities; compare a festival in a French-speaking community with one from another cultural community, using information they recorded on a Venn diagram; describe the pastimes of children in a French-speaking community)"},{"code":"D3.2","title":"Awareness of Sociolinguistic Conventions","text":"identify sociolinguistic conventions associated with a variety of social situations in French-speaking communities, and use them appropriately in their written work (e.g., regional expressions and words from a French-speaking community; varying levels of politeness in letter writing to different recipients; use of “tu” and “vous” in giving directions)"}]}]}]},"g3":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-fsl","sourceLang":"en","strands":[{"code":"A","title":"Listening","why":"","overall":[{"code":"A1","title":"Listening to Understand","text":"determine meaning in a variety of oral French texts, using appropriate listening strategies","specific":[{"code":"A1.1","title":"Using Listening Comprehension Strategies","text":"identify a few listening comprehension strategies and use them appropriately before, during, and after listening to understand a variety of oral French texts (e.g., activate prior knowledge; restate information to confirm understanding; identify key words related to the subject/message/theme of a song; ask for repetition and clarification during and after listening)"},{"code":"A1.2","title":"Understanding Purposes for Listening","text":"demonstrate an understanding of the purpose for listening in a few specific situations (e.g., to participate in group work; to follow detailed or multi-step instructions for a task; to identify language patterns or expressions; to formulate questions about a presentation)"},{"code":"A1.3","title":"Listening for Meaning","text":"demonstrate an understanding of the intent and meaning of oral French texts containing familiar words and expressions and dealing with everyday topics, with contextual and visual support (e.g., record information during an oral presentation or a literature circle; ask questions about the topic after listening to a media text; note important ideas using key words and sentences from the text; restate the author’s feelings and opinions; select appropriate clothing for an upcoming event based on a weather report; identify the importance of a special event mentioned in an announcement or radio commercial)"},{"code":"A1.4","title":"Responding to and Evaluating Media Texts","text":"express in verbal and non-verbal ways their personal thoughts, feelings, and opinions about the messages and the ways they are presented in brief oral media texts about familiar, everyday topics, with teacher support and guidance as appropriate (e.g., analyse the elements in a movie trailer or advertisement and discuss how they convey the intended messages; list the words and expressions in a song that evoke mental pictures; articulate personal connections to the messages presented in a commercial; comment on the speaker’s/author’s point of view in a public service announcement or radio commercial)"}]},{"code":"A2","title":"Listening to Interact","text":"interpret messages accurately while interacting in French for a variety of purposes and with diverse audiences","specific":[{"code":"A2.1","title":"Using Interactive Listening Strategies","text":"identify and use a few interactive listening strategies to suit a variety of situations while participating in structured and guided social and academic interactions (e.g., adopt a respectful posture during conversations; ask questions for clarification; identify appropriate moments to encourage peers; maintain engagement; make connections to respond to and validate what someone says; acknowledge another point of view in conversation)"},{"code":"A2.2","title":"Interacting","text":"respond with understanding to what others say while participating in interactions about familiar, everyday topics (e.g., discuss plans for future events; participate in collaborative inquiry; respond to oral feedback during a writer’s workshop; ask and answer questions in a conversation)"},{"code":"A2.3","title":"Metacognition","text":"(a) describe strategies they found helpful before, during, and after listening; (b) identify their areas of greater and lesser strength as listeners, and plan steps they can take to improve their listening skills (e.g., use co-constructed criteria to self-monitor listening during a conversation; determine next steps based on comments and feedback from peers and the teacher; share with a partner a listening strategy they find helpful; record in a journal situations in which they are successful and challenged when listening)"}]},{"code":"A3","title":"Intercultural Understanding","text":"demonstrate an understanding of information in oral French texts about aspects of culture in diverse French-speaking communities and other communities around the world, and of French sociolinguistic conventions used in a variety of situations and communities","specific":[{"code":"A3.1","title":"Intercultural Awareness","text":"using information from oral French texts, identify French-speaking communities locally and across Ontario, find out about aspects of their cultures, and make connections to personal experiences and their own and other communities (e.g., listen to stories and songs from a range of Franco-Ontarian communities and make connections to their own community; re-create cultural artefacts based on oral instructions; record information heard in a presentation or a report to identify Franco-Ontarian symbols, traditions, and/or celebrations, such as le drapeau franco-ontarien, le Festival franco-ontarien, and la Fête de la Sainte-Catherine; identify some contributions of French-speaking and Aboriginal communities to Canadian culture, such as street/place names, historic sites, festivals, and items such as the canoe or maple syrup)"},{"code":"A3.2","title":"Awareness of Sociolinguistic Conventions","text":"using information from oral French texts, identify and demonstrate an understanding of sociolinguistic conventions used in a variety of situations in diverse French-speaking communities (e.g., language registers used in different French-speaking communities; formal and informal expressions of courtesy, such as different types of salutations; verbal and non-verbal cues appropriate to different environments, such as social gatherings or classroom discussions; brief expressions used to introduce themselves and others)"}]}]},{"code":"B","title":"Speaking","why":"","overall":[{"code":"B1","title":"Speaking to Communicate","text":"communicate information and ideas orally in French, using a variety of speaking strategies and age- and grade-appropriate language suited to the purpose and audience","specific":[{"code":"B1.1","title":"Using Oral Communication Strategies","text":"identify a few speaking strategies and use them appropriately to express themselves clearly and coherently in French for various purposes and to a variety of audiences (e.g., share background knowledge and personal experiences to make connections to a topic; use body language and facial expressions to keep the audience’s attention; rehearse with a partner before an oral presentation; incorporate key words and expressions heard in oral communications; identify and practise structures and expressions that are challenging)"},{"code":"B1.2","title":"Producing Oral Communications","text":"using familiar words and expressions, produce planned and rehearsed messages in French containing information and ideas about themselves and their family, friends, and immediate environment, with contextual, auditory, and visual support (e.g., use appropriate vocabulary and a variety of sentence types and structures to express personal preferences and ideas; ask questions to inquire about a variety of everyday situations; incorporate new and familiar vocabulary in their discourse; describe a past or future event; discuss the effectiveness of various features in a children’s magazine; describe their favourite animal; explain their use of graphics on a poster)"},{"code":"B1.3","title":"Speaking with Fluency","text":"speak with a smooth pace, appropriate intonation, and accurate pronunciation in planned and rehearsed communications about personal and familiar topics, using familiar words and expressions (e.g., pronounce words smoothly and accurately as modelled by the teacher when reciting tongue twisters, chants, and/or rhymes, when using newly acquired vocabulary, and when participating in choral speaking and/or shared reading activities; deliver a rehearsed oral presentation at a smooth pace with appropriate phrasing and emphasis)"},{"code":"B1.4","title":"Creating Media Texts","text":"create oral media texts using forms, conventions, and techniques appropriate to the purpose and audience (e.g., use vocabulary and expressions from mentor texts that they have viewed, heard, or read in their own media text; create and share a multimedia text using technology; justify the use of sound effects and music to enhance a slideshow presentation)"}]},{"code":"B2","title":"Speaking to Interact","text":"participate in spoken interactions in French for a variety of purposes with diverse audiences","specific":[{"code":"B2.1","title":"Using Speaking Interaction Strategies","text":"demonstrate an understanding of appropriate speaking behaviour in a variety of situations (e.g., intervene politely in a conversation; use an object such as a talking stick to determine whose turn it is to talk; paraphrase a peer’s comment to confirm understanding of his or her idea before adding their own; use language specific to their role in a cooperative group task)"},{"code":"B2.2","title":"Interacting","text":"engage in rehearsed and spontaneous spoken interactions, in structured and guided social and academic contexts, on familiar topics related to matters of personal interest or daily routines (e.g., use a variety of familiar words and expressions when engaged in conversations; ask and answer questions about other communities; share ideas, opinions, and feelings and encourage others to share their points of view during a literature circle)"},{"code":"B2.3","title":"Metacognition","text":"(a) describe strategies they found helpful before, during, and after speaking to communicate effectively; (b) identify their areas of greater and lesser strength as speakers, and plan steps they can take to improve their speaking skills (e.g., refer to feedback from the teacher and peers when revising oral presentations; determine which strategies were helpful when presenting their message; plan to incorporate effective communication strategies to enhance interactions with others)"}]},{"code":"B3","title":"Intercultural Understanding","text":"in their spoken communications, demonstrate an awareness of aspects of culture in diverse French-speaking communities and other communities around the world, and of the appropriate use of French sociolinguistic conventions in a variety of situations","specific":[{"code":"B3.1","title":"Intercultural Awareness","text":"communicate information orally about French-speaking communities locally and across Ontario, including aspects of their cultures and their contributions to la francophonie and the world, and make connections to personal experiences and their own and other communities (e.g., share ideas about the importance of French as demonstrated by its status as an official language of Canada and a required subject in the Ontario elementary curriculum; sing or repeat phrases from songs by Franco-Ontarian musicians that reveal aspects of French Canadian cultures; explain how symbols on a flag help to represent a community; give brief oral presentations describing family, school life, traditions, and festivals in Franco-Ontarian communities and comparing them to their own)"},{"code":"B3.2","title":"Awareness of Sociolinguistic Conventions","text":"identify sociolinguistic conventions associated with a variety of social situations in diverse French-speaking communities, and use them appropriately in spoken interactions (e.g., language registers used by community members in various situations; body language and gestures appropriate to different audiences; appropriate expressions to signify agreement)"}]}]},{"code":"C","title":"Reading","why":"","overall":[{"code":"C1","title":"Reading Comprehension","text":"determine meaning in a variety of French texts, using a few reading comprehension strategies","specific":[{"code":"C1.1","title":"Using Reading Comprehension Strategies","text":"identify a few reading comprehension strategies and use them appropriately before, during, and after reading to understand a variety of French texts, with teacher support (e.g., use background knowledge and personal experiences to infer implicit messages; ask questions when analysing a character’s actions; identify and highlight key words, phrases, and information in a non-fiction text; explain the message in a descriptive poem, citing specific words, phrases, or images from the text to support their interpretation; use visualization to clarify details of a scene)"},{"code":"C1.2","title":"Reading for Meaning","text":"demonstrate an understanding of the intent and meaning of French texts containing familiar words and expressions and dealing with everyday topics, with contextual and visual support (e.g., in a double-entry journal, compare personal opinions to an author’s viewpoint; use words and pictures to express feelings and opinions about a written text; dramatize the main event in a narrative text; determine the included and excluded points of view)"},{"code":"C1.3","title":"Reading with Fluency","text":"read French texts containing familiar words, names, expressions, and language structures, and dealing with everyday topics, at a sufficient rate and with sufficient ease to convey the sense of the text, using a variety of cues (e.g., group words into meaningful phrases; read aloud with some intonation and expression; recognize various spellings of the same sound in independent reading selections; participate in shared or echo reading)"},{"code":"C1.4","title":"Developing Vocabulary","text":"identify and use a few strategies to expand vocabulary through reading (e.g., use cognates to understand the meaning of new words; use context clues to infer meaning of new words; refer to classroom visual supports and resources such as subject-specific word banks)"},{"code":"C1.5","title":"Responding to and Evaluating Media Texts","text":"express personal thoughts, feelings, and opinions about the messages and the ways they are presented in media texts about familiar, everyday topics, with teacher support as appropriate (e.g., analyse the text, illustrations, and techniques used in an advertisement and discuss their effectiveness in representing a product or a group of people; explain how the elements on the cover of a magazine might persuade someone to read or buy it; discuss how a media text on a subject of public interest could lead to action; analyse how specific features communicate the message in a tourism brochure; make informed decisions and healthy choices after reading food labels; identify the intended audience for an advertisement for a toy, and explain whether the advertisement is effective; describe how animals or environmental images are used to evoke emotions in print advertisements)"}]},{"code":"C2","title":"Purpose, Form, and Style","text":"identify the purpose(s) and characteristics of a variety of adapted and authentic text forms, including fictional, informational, graphic, and media forms","specific":[{"code":"C2.1","title":"Purposes of Text Forms","text":"identify the purpose(s) of some familiar text forms, including fictional, informational, graphic, and media forms, with support and guidance from the teacher (e.g., book review – to help others decide whether to read a book; poem – to express ideas or convey a mood or image; graph of survey results – to show patterns in information)"},{"code":"C2.2","title":"Characteristics and Stylistic Elements of Text Forms","text":"identify some characteristics and/ or stylistic elements of a variety of text forms, including fictional, informational, graphic, and media forms, with support and guidance from the teacher (e.g., procedural text – temporal and sequential words; persuasive text – a stated point or opinion followed by supporting ideas; map – pictures, symbols, legends, and use of different colours; fairy tale/folktale – a moral or lesson, a hero or heroine, descriptive language, personification of animals or objects)"},{"code":"C2.3","title":"Metacognition","text":"(a) identify, in conversation with the teacher and their peers, a few strategies they found helpful before, during, and after reading to understand texts; (b) determine their areas of greater and lesser strength as readers, and plan steps they can take to improve their reading skills (e.g., use an interest survey to identify reading preferences and opportunities to expand choices for independent reading; reflect on the texts listed in a personal reading log and set a goal to read other genres)"}]},{"code":"C3","title":"Intercultural Understanding","text":"demonstrate an understanding of information in French texts about aspects of culture in diverse French-speaking communities and other communities around the world, and of French sociolinguistic conventions used in a variety of situations and communities","specific":[{"code":"C3.1","title":"Intercultural Awareness","text":"using information from a variety of French texts, identify French-speaking communities locally and across Ontario, find out about aspects of their cultures, and make connections to personal experiences and their own and other communities (e.g., recognize and correctly read the names of cities with French origins on a map of Ontario; describe ideas, themes, and characters depicted in Franco-Ontarian music, stories, and legends; research and share findings about a cultural tradition or celebration in a Franco-Ontarian community; read about Franco-Ontarian personalities and/or historical figures and describe some of their accomplishments; identify cultural elements in a brochure about a French-speaking community in Ontario)"},{"code":"C3.2","title":"Awareness of Sociolinguistic Conventions","text":"using information from French texts, identify and demonstrate an understanding of sociolinguistic conventions used in a variety of situations in diverse French-speaking communities (e.g., abbreviations such as M., Mme, Dr., Boul.; appropriate use of “tu” and “vous”; salutations and leave-taking expressions used in letters, emails, and postcards)"}]}]},{"code":"D","title":"Writing","why":"","overall":[{"code":"D1","title":"Purpose, Audience, and Form","text":"write in French in a variety of forms and for a variety of purposes and audiences, using knowledge of vocabulary and stylistic elements to communicate clearly and effectively","specific":[{"code":"D1.1","title":"Identifying Purpose and Audience","text":"determine, with support from the teacher, their purpose for writing and the audience for French texts they plan to create (e.g., to label and add legends with precise vocabulary to maps of communities; to collaborate with classmates on a persuasive letter to a school newspaper; to critique a piece of artwork; to write a sequel to or continuation of a story read in a favourite class read-aloud, following a model; to recount a grand-parent’s childhood story)"},{"code":"D1.2","title":"Writing in a Variety of Forms","text":"write a variety of texts in French, conveying information, ideas, and opinions about themselves, friends, family, and their immediate environment, following models appropriate to the purpose and incorporating some of the basic elements of each form (e.g., recount their participation in a school-wide activity; write a personal adventure based on a familiar story; write a letter or email to an author to share their opinions about a book; compose a reader’s theatre script about conflict resolution; retell a story from various points of view; write a sketch of a character from a popular movie; create the invitations, menu, and program for a party for their favourite fictional character; compose a list of actions to conserve and protect water, such as shutting off the tap while brushing teeth)"},{"code":"D1.3","title":"Developing Vocabulary","text":"confirm word meanings and review, refine, and vary word choices, using a variety of resources (e.g., vary word choice with synonyms of frequently used words such as “dit”, “grand”, or “personne”; incorporate words and expressions heard or read; use word webs to help them develop and organize ideas)"},{"code":"D1.4","title":"Using Stylistic Elements","text":"begin to establish a personal voice and a clear point of view, with teacher support (e.g., incorporate elements from mentor texts into their own writing; use words, visual aids, and a variety of sentence structures to convey their message; use verbs of conviction such as “devoir”, “croire”, “être nécessaire” to express their point of view on a familiar topic of public interest)"},{"code":"D1.5","title":"Creating Media Texts","text":"using familiar words and expressions, create a variety of media texts in French for specific purposes and audiences, using a few simple media forms and the conventions and techniques appropriate to the chosen form (e.g., create a comic strip about a school event for a class newsletter; compose an electronic greeting card for someone special; design a poster to recommend a favourite movie; create a pamphlet recommending actions for Earth Day or Earth Hour; draft and distribute an email petition about an environmental issue)"}]},{"code":"D2","title":"The Writing Process","text":"use the stages of the writing process – including pre-writing, producing drafts, revising, editing, and publishing – to develop and organize content, clarify ideas and expression, correct errors, and present their written work effectively","specific":[{"code":"D2.1","title":"Generating, Developing, and Organizing Ideas","text":"generate, develop, focus, and organize ideas for writing, using a variety of strategies and print, electronic, and other resources, as appropriate (e.g., brainstorm ideas for writing about a familiar topic; describe illustrations or objects to generate ideas for writing; share and discuss prior knowledge and experiences related to a topic; gather information on a topic from texts used in independent or class reading; sort and organize ideas using labels, titles, pictures, graphic organizers, and/or software; record and develop ideas on various topics and for various purposes in a personal journal)"},{"code":"D2.2","title":"Drafting and Revising","text":"plan and produce drafts, following a model, and revise their writing to improve its content, clarity, and interest, using a few simple strategies (e.g., choose or create and use a graphic organizer to help them plan a short story; reread and change, add, remove, or reorganize content; read their text aloud to a peer to ensure fluency; refer to feedback from a writing conference with a teacher or peer when revising and editing a text)"},{"code":"D2.3","title":"","text":"edit, proofread, and publish a variety of written pieces, following a model or a set of guidelines to meet established criteria, with support as appropriate (e.g., use dashes in a dialogue to indicate a change in speaker; verify agreement in number and gender of nouns, verbs, and adjectives; use specific action verbs in a description of an activity; use a checklist, co-constructed with the teacher and peers, when editing their text; read their text aloud to their peers or teacher and use their feedback when checking that they have met all the specified criteria)"},{"code":"D2.4","title":"Metacognition","text":"(a) identify, in conversation with the teacher and their peers, a few strategies they found helpful before, during, and after writing; (b) determine their areas of greater and lesser strength as writers, and plan steps they can take to improve their writing skills (e.g., record writing successes and challenges in a personal journal; refer to a class-developed anchor chart to guide them when providing feedback to a partner; share and discuss with peers revision strategies that they find useful)"}]},{"code":" D3","title":"Intercultural Understanding","text":"in their written work, demonstrate an awareness of aspects of culture in diverse French-speaking communities and other communities around the world, and of the appropriate use of French sociolinguistic conventions in a variety of situations","specific":[{"code":"D3.1","title":"Intercultural Awareness","text":"communicate information in writing about French-speaking communities locally and across Ontario, including aspects of their cultures and their contributions to la francophonie and the world, and make connections to personal experiences and their own and other communities (e.g., select pictures from a Franco-Ontarian community and create descriptive captions for them; create a poster with illustrations and text to promote interest in speaking French in Ontario; incorporate references to Franco-Ontarian cultural elements or artefacts in personal writing; write a postcard to a French-speaking pen pal, asking questions about his or her cultural traditions; write about historic voyageur routes and related modern Métis communities, such as Mattawa)"},{"code":"D3.2","title":"Awareness of Sociolinguistic Conventions","text":"identify sociolinguistic conventions associated with a variety of social situations in diverse French-speaking communities and use them appropriately in their written work (e.g., standard formats for personal letters, postcards, emails; conventions for writing the date; language registers for formal and informal communication in familiar contexts)"}]}]}]},"g4":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-fsl","sourceLang":"en","strands":[{"code":"A","title":"Listening","why":"","overall":[{"code":"A1","title":"Listening to Understand","text":"determine meaning in a variety of oral French texts, using appropriate listening strategies","specific":[{"code":"A1.1","title":"Using Listening Comprehension Strategies","text":"identify a range of listening comprehension strategies and use them appropriately before, during, and after listening to understand a variety of oral French texts (e.g., ask questions about facts to clarify meaning; take notes using a graphic organizer during an oral presentation; make personal connections during and after listening to an audio text; use visualization during the description of a past or future event)"},{"code":"A1.2","title":"Understanding Purposes for Listening","text":"demonstrate an understanding of the purpose for listening in a variety of situations (e.g., to enable them to respond appropriately to peers during literature circles; to formulate an opinion about a social or environmental issue based on information provided in a broadcast; to learn from others during oral presentations; to learn new vocabulary from songs, chants, and rhymes; to participate in a game or activity)"},{"code":"A1.3","title":"Listening for Meaning","text":"demonstrate an understanding of the intent and meaning of various oral French texts containing familiar and unfamiliar words and expressions and dealing with familiar, academic, and personally relevant topics, with support as appropriate (e.g., summarize main ideas using graphic organizers; paraphrase ideas heard after a think-pair-share activity; discuss the purpose and main points of an oral presentation by a peer or guest speaker; create a tableau depicting the solution to a problem from a read-aloud; use a pictogram to demonstrate sequencing after listening to the description of a historical event; express opinions on the platforms presented by candidates in a class election; explain their feelings and personal reactions to a recorded Aboriginal folktale)"},{"code":"A1.4","title":"Responding to and Evaluating Media Texts","text":"express their personal opinions about the treatment and presentation of the messages in a variety of oral media texts about familiar, academic, and personally relevant topics, and give evidence from the texts for their opinions, with teacher support as appropriate (e.g., listen to a video clip on a health or environmental issue and explain its impact on their life; identify expressions heard in advertisements that signal an attempt to persuade the listener to do or buy something; listen to an advertisement aimed at youth and identify how the product is promoted)"}]},{"code":"A2","title":"Listening to Interact","text":"interpret messages accurately while interacting in French for a variety of purposes and with diverse audiences","specific":[{"code":"A2.1","title":"Using Interactive Listening Strategies","text":"identify and use interactive listening strategies to suit a variety of situations while participating in social and academic interactions about familiar and personally relevant topics (e.g., demonstrate an understanding of when to listen and when to speak; listen without interrupting; reconsider their opinion after hearing what others say; ask the speaker to repeat or explain at appropriate moments)"},{"code":"A2.2","title":"Interacting","text":"respond with understanding to what others say while participating in a variety of interactions about familiar, academic, and personally relevant topics (e.g., acknowledge another point of view in conversation; ask and answer questions to understand a peer’s statements and opinions; respond effectively to a peer’s ideas in a think-pair-share situation)"},{"code":"A2.3","title":"Metacognition","text":"(a) describe factors that prevent them from listening effectively and strategies they found helpful before, during, and after listening; (b) identify their areas of greater and lesser strength as listeners, and plan steps they can take to improve their listening skills (e.g., refer to feedback from teachers and peers to identify areas of strength and set listening goals; reflect in a personal journal on areas in need of improvement and ways to listen more effectively)"}]},{"code":"A3","title":"Intercultural Understanding","text":"demonstrate an understanding of information in oral French texts about aspects of culture in diverse French-speaking communities and other communities around the world, and of French sociolinguistic conventions used in a variety of situations and communities","specific":[{"code":"A3.1","title":"Intercultural Awareness","text":"using information from oral French texts, identify French-speaking communities in Ontario, find out about aspects of their cultures, and make connections to personal experiences and their own and other communities (e.g., listen to directions to locate on a map historic Franco-Ontarian or Métis communities such as Sault Ste. Marie or Mattawa; identify examples of the use of French in daily life in their immediate environment, such as the bilingual version of the national anthem sung at school or sports events; listen to a peer describe a Franco-Ontarian tradition, and make connections to a similar tradition in their own family)"},{"code":"A3.2","title":"Awareness of Sociolinguistic Conventions","text":"using information from oral French texts, identify and demonstrate an understanding of sociolinguistic conventions used in a variety of situations in diverse French-speaking communities (e.g., differences in language used in conversations with a teacher versus with a peer; conventions used in informal exchanges such as telephone calls with a family member)"}]}]},{"code":"B","title":"Speaking","why":"","overall":[{"code":"B1","title":"Speaking to Communicate","text":"communicate information and ideas orally in French, using a variety of speaking strategies and age- and grade-appropriate language suited to the purpose and audience","specific":[{"code":"B1.1","title":"Using Oral Communication Strategies","text":"identify a range of speaking strategies and use them appropriately to express themselves clearly and coherently in French for various purposes and to a variety of audiences (e.g., plan and rehearse their message; use gestures and visuals to support their point of view; use vocal techniques to engage the audience)"},{"code":"B1.2","title":"Producing Oral Communications","text":"using familiar words and expressions, produce planned, rehearsed, and increasingly spontaneous messages in French containing information and ideas about academic topics and matters of immediate personal relevance, with contextual, auditory, and visual support (e.g., summarize or retell a First Nations, Métis, or Inuit story such as the creation story of L’île de la tortue; describe the findings of a survey about trades and professions in Canada; describe popular leisure activities in a particular region; deliver a speech communicating personal thoughts and opinions on an environmental or financial issue; share, in small or large groups, personal reactions to the music in advertisements; discuss the impact of product placement – food, beverages, toys, clothing, or games – in films and television shows; debate the suitability of video games for different age groups)"},{"code":"B1.3","title":"Speaking with Fluency","text":"speak with a smooth pace, appropriate intonation, and accurate pronunciation in planned, rehearsed, and increasingly spontaneous communications about familiar, academic, and personally relevant topics, using familiar words and expressions (e.g., make straightforward requests, express preferences, and describe interests with minimal hesitation; use standard greetings and expressions of courtesy with minimal hesitation in classroom activities; pronounce new vocabulary correctly in classroom activities; use classroom reference materials and teacher prompts to self-correct errors in spoken French)"},{"code":"B1.4","title":"Creating Media Texts","text":"create a variety of oral media texts using forms, conventions, and techniques appropriate to the purpose and audience (e.g., record an interview with someone in the school community about his or her role in protecting the environment; use technology to record their point of view on social media and how it affects their interactions; provide the voice-over for an advertisement advocating the purchase of fair-trade goods; create a video recounting a traditional story from a First Nation or Métis Elder)"}]},{"code":"B2","title":"Speaking to Interact","text":"participate in spoken interactions in French for a variety of purposes with diverse audiences","specific":[{"code":"B2.1","title":"Using Speaking Interaction Strategies","text":"demonstrate an understanding of appropriate speaking behaviour in a variety of situations (e.g., take turns when speaking in a group; make relevant and constructive comments in discussions with peers; ask relevant questions in conversations)"},{"code":"B2.2","title":"Interacting","text":"engage in rehearsed and spontaneous spoken interactions, in guided and increasingly spontaneous social and academic contexts, about personally relevant and academic topics (e.g., discuss the importance of recycling practices in their community; discuss healthy and unhealthy eating habits; ask for and give directions to specific places, such as a restaurant, friend’s home, park, or town; role-play an interaction that involves a financial transaction)"},{"code":"B2.3","title":"Metacognition","text":"(a) describe strategies they found helpful before, during, and after speaking to communicate effectively; (b) identify their areas of greater and lesser strength as speakers, and plan steps they can take to improve their speaking skills (e.g., refer to and use established criteria for effective communication; plan to incorporate effective communication strategies in their daily interactions; discuss areas of strength with teachers and peers, and set goals to improve oral communication)"}]},{"code":"B3","title":"Intercultural Understanding","text":"in their spoken communications, demonstrate an awareness of aspects of culture in diverse French-speaking communities and other communities around the world, and of the appropriate use of French sociolinguistic conventions in a variety of situations","specific":[{"code":"B3.1","title":"Intercultural Awareness","text":"communicate information orally about French-speaking communities in Ontario, including aspects of their cultures and their contributions to la francophonie and the world, and make connections to personal experiences and their own and other communities (e.g., give brief oral presentations describing Franco-Ontarian traditions and festivals such as le Bal de Neige in Ottawa; describe the significance of la FESFO – la Fédération de la jeunesse franco-ontarienne; research and discuss French-speaking historical and current figures and their influence on Ontario; discuss the rich cultural diversity that constitutes the Franco-Ontarian community; discuss ways in which French-speaking Aboriginal people can celebrate both their Franco-Ontarian and Aboriginal cultures)"},{"code":"B3.2","title":"Awareness of Sociolinguistic Conventions","text":"identify sociolinguistic conventions associated with a variety of social situations in diverse French-speaking communities, and use them appropriately in spoken interactions (e.g., appropriate form of address – polite/familiar, singular/plural – to suit specific situations; greetings, leave-taking expressions, and expressions of courtesy appropriate to the social context; ways to accept or decline invitations; expressions of understanding or lack of understanding such as “Je comprends”,“Je ne comprends pas”,“Comment?”)"}]}]},{"code":"C","title":"Reading","why":"","overall":[{"code":"C1","title":"Reading Comprehension","text":"determine meaning in a variety of French texts, using a range of reading comprehension strategies","specific":[{"code":"C1.1","title":"Using Reading Comprehension Strategies","text":"identify a range of reading comprehension strategies and use them appropriately before, during, and after reading to understand a variety of French texts, with support as appropriate (e.g., activate prior knowledge through brainstorming; use visualization to clarify details; make and confirm predictions based on evidence from the text)"},{"code":"C1.2","title":"Reading for Meaning","text":"demonstrate an understanding of the intent and meaning of a variety of French texts about familiar, academic, and personally relevant topics, with contextual and visual support (e.g., create a visual representation of a narrative in storyboard form; write a journal entry to respond to an independent reading text; dramatize important events in a story read in a literature circle)"},{"code":"C1.3","title":"Reading with Fluency","text":"read French texts containing familiar vocabulary and language structures, and dealing with familiar, academic, and personally relevant topics, at a sufficient rate and with sufficient expression to convey the sense of the text, using a variety of cues (e.g., use appropriate phrasing and expression when participating in a reader’s theatre; make oral reading sound like spoken language with appropriate pauses, stops, and starts indicated by punctuation)"},{"code":"C1.4","title":"Developing Vocabulary","text":"identify and use several different strategies to expand vocabulary through reading (e.g., categorize vocabulary based on word patterns; create a personal dictionary of interesting words and familiar expressions; look for familiar prefixes, suffixes, or word stems in unfamiliar words; use visuals to help them infer the meaning of unfamiliar words or expressions; read words within words)"},{"code":"C1.5","title":"Responding to and Evaluating Media Texts","text":"express their personal opinions about the treatment and presentation of the messages in a variety of media texts about familiar, academic, and personally relevant topics, and give evidence from the text for their opinions, with teacher support as appropriate (e.g., express opinions on a magazine article; compare newspaper and online articles on the same event or subject; identify and evaluate the persuasive techniques used in advertisements; discuss how photography and headlines or slogans work together on magazine covers or billboards; identify effective elements in comics, graphic novels, or product packaging)"}]},{"code":"C2","title":"Purpose, Form, and Style","text":"identify the purpose(s) and characteristics of a variety of adapted and authentic text forms, including fictional, informational, graphic, and media forms","specific":[{"code":"C2.1","title":"Purposes of Text Forms","text":"identify the purpose(s) of a variety of text forms, including fictional, informational, graphic, and media forms (e.g., diary/journal – to articulate a personal perspective; brochure – to present information briefly; instructions – to describe how to perform a task or use a device; receipt – to show the item bought and the price paid for it)"},{"code":"C2.2","title":"Characteristics and Stylistic Elements of Text Forms","text":"identify some characteristics and/or stylistic elements of a variety of text forms, including fictional, informational, graphic, and media forms, and explain how they help to convey the meaning, with support and guidance from the teacher (e.g., magazine – headlines, subheadings, text boxes, and photographs; movie review – opinions and supporting evidence; letter – date, salutation, information, feelings, and opinions intended for a specific reader; travel guide – maps, images, and information divided by many headings)"},{"code":"C2.3","title":"Metacognition","text":"(a) identify, in conversation with the teacher and their peers, a few strategies they found helpful before, during, and after reading to understand texts; (b) determine their areas of greater and lesser strength as readers, and plan steps they can take to improve their reading skills (e.g., recognize when understanding has broken down; identify which reading strategies are being used effectively; discuss how the text form affects their choice of reading strategies)"}]},{"code":"C3","title":"Intercultural Understanding","text":"demonstrate an understanding of information in French texts about aspects of culture in diverse French-speaking communities and other communities around the world, and of French sociolinguistic conventions used in a variety of situations and communities","specific":[{"code":"C3.1","title":"Intercultural Awareness","text":"using information from a variety of French texts, identify French-speaking communities in Ontario, find out about aspects of their cultures, and make connections to personal experiences and their own and other communities (e.g., compare cultural experiences and perspectives in texts to those in their own community; research the achievements and contributions of French speakers in Ontario; make connections to stories or legends from French-speaking communities in Ontario, such as Sleeping Giant in Thunder Bay; research information about traditions and festivals such as le Festival des tulipes and le Festival Haïti en Fête – Ottawa, le Festival des voyageurs – Mattawa, Métis rendez-vous – Rivière des Français, le Festival Bana y’Afrique – Toronto, and powwows, sporting events such as les Jeux Franco-ontariens, children’s games such as voyageur competitions and blanket throwing, family traditions, and favourite songs in various communities; read about Franco-Ontarian Métis such as Marcel Labelle and Christian Pilon and identify some of their accomplishments)"},{"code":"C3.2","title":"Awareness of Sociolinguistic Conventions","text":"using information from French texts, identify and demonstrate an understanding of sociolinguistic conventions used in a variety of situations in diverse French-speaking communities (e.g., the familiar and formal forms of expressions used in letters, emails, and text messages, such as “À la prochaine” versus “Bien à vous”; appropriate ways to invite someone to do something; conventions of personal and business letters)"}]}]},{"code":"D","title":"Writing","why":"","overall":[{"code":"D1","title":"Purpose, Audience, and Form","text":"write in French in a variety of forms and for a variety of purposes and audiences, using knowledge of vocabulary, language conventions, and stylistic elements to communicate clearly and effectively","specific":[{"code":"D1.1","title":"Identifying Purpose and Audience","text":"determine, with support from the teacher, their purpose for writing and the audience for French texts they plan to create (e.g., to give a friend directions to their home; to create a timeline of significant events to accompany a biography; to express in a letter to the parents’ committee of the school their feelings about the importance of recreational equipment in the school yard; to write about the use of plants in traditional remedies)"},{"code":"D1.2","title":"Writing in a Variety of Forms","text":"write a variety of French texts to convey information, ideas, and opinions about familiar, personally relevant, and academic topics, following models appropriate to the purpose and incorporating some elements of each form (e.g., write an alternative ending to a popular folktale, fairy tale, legend, or tall tale; develop and write directions for a board game linked to bullying prevention or healthy living; write a poem, letter, or email to a veteran recognizing the sacrifices made by Canadian soldiers and peacekeepers; write a report or journal entry to convey thoughts and feelings about an environmental or social issue in their community)"},{"code":"D1.3","title":"Developing Vocabulary","text":"confirm word meanings and review, refine, and vary word choices, using a variety of resources (e.g., select new words from a list of synonyms to avoid repetition and vary word choice; use fiction and non-fiction texts to confirm spelling and meaning; use a visual dictionary to associate pictures and written words)"},{"code":"D1.4","title":"Using Stylistic Elements","text":"use word choice and stylistic elements to establish a personal voice and a clear point of view (e.g., provide a main idea and supporting details in a letter; use present tense and sequencing words in an explanation; use adjectives and adverbs to describe the characters, setting, and events in a narrative)"},{"code":"D1.5","title":"Creating Media Texts","text":"using familiar words and expressions, create a variety of media texts in French for specific purposes and audiences, using several media forms and the conventions and techniques appropriate to the chosen form (e.g., create a poster to illustrate a procedure or to promote healthy living; create a brochure for a provincial park; design a bumper sticker about a social or environmental issue; create a map with labels and a legend showing where plants with medicinal properties such as blueberries, apples, and wild ginger can be harvested)"},{"code":"D1.6","title":"Applying Language Conventions","text":"communicate their meaning clearly, using parts of speech appropriately and following conventions for correct spelling, word order, and punctuation (e.g., masculine and feminine forms of adjectives; irregular plural nouns such as “travail/travaux”, “cheval/chevaux”; present, past, and future tenses of familiar -er, -ir, and -re verbs; expressions with “avoir” and “faire” such as “avoir besoin”, “avoir faim”, “avoir soif”, “faire chaud”, “faire du ski”; passé récent using “venir de”, such as “Je viens d’arriver”; impératif to give directions and instructions; demonstrative adjectives such as “ce”, “cet”, “cette”, “ces”; position and agreement in gender and number of irregular adjectives with nouns, such as “bel arbre”, “neige blanche”; possessive adjectives such as “notre/nos”, “votre/vos”, “leur/leurs”; position of frequently used adverbs such as “peu”, “beaucoup”, “assez”, “trop”; the prepositions “voici” and “voilà”; subject-verb inversion to ask questions; compound sentences using connecting words such as “d’abord”, “et”, “puis”, “ensuite”)"}]},{"code":"D2","title":"The Writing Process","text":"use the stages of the writing process – including pre-writing, producing drafts, revising, editing, and publishing – to develop and organize content, clarify ideas and expression, correct errors, and present their written work effectively","specific":[{"code":"D2.1","title":"Generating, Developing, and Organizing Ideas","text":"generate, develop, focus, and organize ideas for writing, using a variety of strategies and print, electronic, and other resources, as appropriate (e.g., order the events in a story on a storyboard; select an idea from their writer’s notebook and develop questions to guide research; sort and classify ideas by highlighting key words, using graphic organizers, or making jot notes)"},{"code":"D2.2","title":"Drafting and Revising","text":"plan and produce drafts, following established criteria, and revise their writing to improve its content, clarity, and interest, using a variety of strategies (e.g., outline the elements of their report on a graphic organizer; consult classroom resources when editing their writing; refer to teacher models and exemplars when revising their writing)"},{"code":"D2.3","title":"Producing Finished Work","text":"edit, proofread, and publish a variety of written pieces, following a model or a set of guidelines to meet established criteria, with support as appropriate (e.g., refer to feedback from their teacher or peers when refining or proofreading their writing; consult a checklist to ensure that they have included all the appropriate elements in their narrative; enhance the presentation of information in a report with diagrams, pictures, and illustrations; add personal touches that support the message, such as titles, subtitles, word art, or text boxes, using presentation software)"},{"code":"D2.4","title":"Metacognition:","text":"(a) identify, in conversation with the teacher and their peers, several strategies they found helpful before, during, and after writing; (b) determine their areas of greater and lesser strength as writers, and plan steps they can take to improve their writing skills (e.g., discuss the importance of co-constructing success criteria before writing; describe how using exemplars helps improve writing skills; evaluate the effectiveness of using a checklist to improve the final draft)"}]},{"code":"D3","title":"Intercultural Understanding","text":"in their written work, demonstrate an awareness of aspects of culture in diverse French-speaking communities and other communities around the world, and of the appropriate use of French sociolinguistic conventions in a variety of situations","specific":[{"code":"D3.1","title":"Intercultural Awareness","text":"in their written work, communicate information about French-speaking communities in Ontario, including aspects of their culture and their contributions to la francophonie and the world, and make connections to personal experiences and their own and other communities (e.g., write a report about a Franco-Ontarian tradition and compare and contrast it with a personal tradition; write a journal entry about the contributions of local Franco-Ontarians; research a Franco-Ontarian legend/myth/story and develop a song or poem about it; compare modern and traditional methods used in French-speaking Aboriginal communities to produce maple syrup)"},{"code":"D3.2","title":"Awareness of Sociolinguistic Conventions","text":"identify sociolinguistic conventions associated with a variety of social situations in diverse French-speaking communities and use them appropriately in their written work (e.g., conventions of an invitation; conventions for writing numbers, such as the use of spaces in numbers with four or more digits [1 000], the position of currency signs after the amount, and the use of a comma rather than a decimal point in currency amounts [1,75$])"}]}]}]},"g5":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-fsl","sourceLang":"en","strands":[{"code":"A","title":"Listening","why":"","overall":[{"code":"A1","title":"Listening to Understand","text":"determine meaning in a variety of oral French texts, using appropriate listening strategies","specific":[{"code":"A1.1","title":"Using Listening Comprehension Strategies","text":"identify a range of listening comprehension strategies and use them appropriately before, during, and after listening to understand a variety of oral French texts (e.g., ask questions to clarify meaning; use non-verbal cues to facilitate understanding; use a graphic organizer to help them synthesize ideas; activate prior knowledge before listening)"},{"code":"A1.2","title":"Understanding Purposes for Listening","text":"demonstrate an understanding of the purpose for listening in a variety of situations (e.g., to gather information by taking notes during a teacher or peer conference; to identify the main point of view in a video clip; to compare their ideas with those of their peers during and after an oral presentation; to gather information from an interview)"},{"code":"A1.3","title":"Listening for Meaning","text":"demonstrate an understanding of the intent and meaning of various oral French texts containing familiar and unfamiliar words and expressions and dealing with familiar, academic, and personally relevant topics, with support as appropriate (e.g., list main ideas and some supporting details from an oral presentation; draw something based on a partner’s oral instructions; participate in a dramatization following a read-aloud; share personal opinions related to the messages in a report; create a timeline of events after listening to a biography; identify the main message and key lessons heard in a story from a French-speaking First Nation, Métis, or Inuit community)"},{"code":"A1.4","title":"Responding to and Evaluating Media Texts","text":"express their personal opinions about the treatment and presentation of the messages in a variety of oral media texts about familiar, academic, and personally relevant topics, and give evidence from the texts for their opinions, with teacher support as appropriate (e.g., describe how different audiences might react to a television commercial; role-play to convey their agreement or disagreement with the message presented in a popular song; create a poster to share personal reactions to the information heard in an interview; listen “between the lines” to detect bias in a media text; identify missing points of view; evaluate the effectiveness of an advertisement about an eco-friendly product)"}]},{"code":"A2","title":"Listening to Interact","text":"interpret messages accurately while interacting in French for a variety of purposes and with diverse audiences","specific":[{"code":"A2.1","title":"Using Interactive Listening Strategies","text":"identify and use interactive listening strategies to suit a variety of situations while participating in social and academic interactions about familiar and personally relevant topics (e.g., make connections between personal experiences and what is being said; reconsider their opinion after hearing what others say; ask for repetition, confirmation, or clarification of what they hear using phrases such as “Un instant”, “Je ne comprends pas”, “Pourriez-vous répéter cela, s’il vous plaît?”, “Qu’est-ce que cela veut dire?”; use body language such as nodding to indicate understanding or agreement)"},{"code":"A2.2","title":"Interacting","text":"respond with understanding to what others say while participating in a variety of interactions about familiar, academic, and personally relevant topics (e.g., paraphrase a group member’s opinion before responding to it; acknowledge another point of view in a telephone, video, or face-to-face exchange; ask and answer questions in small groups, during a role play, or in reader’s theatre; use a talking stick to share information and ideas in a community circle)"},{"code":"A2.3","title":"Metacognition","text":"(a) describe factors that prevent them from listening effectively and strategies they found helpful before, during, and after listening; (b) identify their areas of greater and lesser strength as listeners, and plan steps they can take to improve their listening skills (e.g., record listening strategies they have found helpful in a journal for future reference; engage in dialogue with teachers and peers to determine criteria for effective listening; use feedback from peers and self-evaluation when identifying and planning next steps to improve listening comprehension)"}]},{"code":"A3","title":"Intercultural Understanding","text":"demonstrate an understanding of information in oral French texts about aspects of culture in diverse French-speaking communities and other communities around the world, and of French sociolinguistic conventions used in a variety of situations and communities","specific":[{"code":"A3.1","title":"Intercultural Awareness","text":"using information from oral French texts, identify French-speaking communities in Quebec, find out about aspects of their cultures, and make connections to personal experiences and their own and other communities (e.g., listen to and identify topics of interest in songs, stories, and legends by Québécois artists and authors, such as Anthony Phelps – “Et moi, je suis une île” or Laïla Héloua – “Mandarine et Kiwi”; using a graphic organizer to guide listening, organize information from oral texts about family, school life, traditions, powwows, and festivals in Québécois communities (Quebec City – Festival des journées d’Afrique, Danse et rythmes du monde; Trois-Rivières – Festival Urbain; Montreal – Festival du monde arabe), and make connections to their own culture; listen to the recitation of a traditional French story, such as “La Chasse-galerie” used by Métis)"},{"code":"A3.2","title":"Awareness of Sociolinguistic Conventions","text":"using information from oral French texts, identify and demonstrate an understanding of sociolinguistic conventions used in a variety of situations in diverse French-speaking communities (e.g., dialects and regional vocabulary; formal and informal language; language styles among various age groups)"}]}]},{"code":"B","title":"Speaking","why":"","overall":[{"code":"B1","title":"Speaking to Communicate","text":"communicate information and ideas orally in French, using a variety of speaking strategies and age- and grade-appropriate language suited to the purpose and audience","specific":[{"code":"B1.1","title":"Using Oral Communication Strategies","text":"identify a range of speaking strategies and use them appropriately to express themselves clearly and coherently in French for various purposes and to a variety of audiences (e.g., rehearse what they want to say; concentrate on the message; rephrase ideas using familiar vocabulary to clarify their message; ask questions to engage their audience)"},{"code":"B1.2","title":"Producing Oral Communications","text":"using familiar words and expressions, produce planned, rehearsed, and increasingly spontaneous messages in French containing information and ideas about academic topics and matters of personal interest, with contextual, auditory, and visual support (e.g., respectfully present a personal opinion in a soapbox forum; deliver a speech regarding the importance of a balanced diet and regular exercise; recount a personal experience; identify obvious and subliminal key messages in a television commercial)"},{"code":"B1.3","title":"Speaking with Fluency","text":"speak with a smooth pace, appropriate intonation, and accurate pronunciation in planned, rehearsed, and increasingly spontaneous communications about familiar, academic, and personally relevant topics, using familiar words and expressions (e.g., use intonation to show surprise; give clear directions with minimal hesitation; recite a poem using appropriate pauses as indicated by the punctuation and/or layout of the lines to communicate the poet’s intended meaning accurately)"},{"code":"B1.4","title":"Creating Media Texts","text":"create a variety of oral media texts using forms, conventions, and techniques appropriate to the purpose and audience (e.g., create a short announcement identifying the benefits of knowing another language; create a public service announcement detailing the evacuation procedure during a fire; record an advertisement for a local farmers’ market; create a podcast promoting Earth Day or Earth Hour)"}]},{"code":"B2","title":"Speaking to Interact","text":"participate in spoken interactions in French for a variety of purposes with diverse audiences","specific":[{"code":"B2.1","title":"Using Speaking Interaction Strategies","text":"demonstrate an understanding of appropriate speaking behaviour in a variety of situations (e.g., take turns when speaking; use appropriate tone; remain on topic in a conversation; use formal and informal language appropriately)"},{"code":"B2.2","title":"Interacting","text":"engage in rehearsed and spontaneous spoken interactions, in guided and increasingly spontaneous social and academic contexts, about personally relevant and academic topics (e.g., engage in a discussion following a read-aloud; discuss rules and laws in various contexts such as sports, school, and government; express understanding of the perspectives and opinions of others by making connections and drawing comparisons to their own experiences)"},{"code":"B2.3","title":"Metacognition","text":"(a) describe strategies they found helpful before, during, and after speaking to communicate effectively; (b) identify their areas of greater and lesser strength as speakers, and plan steps they can take to improve their speaking skills (e.g., explain during a student-teacher conference how they monitor their speaking skills; make and record revisions to the form and content of speech using feedback from peers and the teacher; identify and describe the key elements used by peers and others during oral presentations; set small, attainable goals to improve oral communication, increase confidence, and sustain motivation)"}]},{"code":"B3","title":"Intercultural Understanding","text":"in their spoken communications, demonstrate an awareness of aspects of culture in diverse French-speaking communities and other communities around the world, and of the appropriate use of French sociolinguistic conventions in a variety of situations.","specific":[{"code":"B3.1","title":"Intercultural Awareness","text":"communicate information orally about French-speaking communities in Quebec, including aspects of their cultures and their contributions to la francophonie and the world, and make connections to personal experiences and their own and other communities (e.g., describe a specific region or community in Quebec, including Aboriginal communities, using a poster they have created or obtained from a travel agency to illustrate their remarks; describe the ingredients and procedure for making a familiar Québécois dish such as poutine; recite or paraphrase songs, stories, and/or legends by Québécois artists and authors; identify some famous Québécois[es], such as Maurice Richard, Mario Lemieux, Boucar Diouf, Marie-Mai, Gilles Vigneault, William Shatner, Pierre Trudeau, Oscar Peterson, Alexandre Bilodeau, Julie Payette, Marc Garneau, or Guy Laliberté, and describe some of their accomplishments; deliver a brief oral presentation comparing important issues or events in a Quebec community and their own community)"},{"code":"B3.2","title":"Awareness of Sociolinguistic Conventions","text":"identify sociolinguistic conventions associated with a variety of social situations in diverse French-speaking communities, and use them appropriately in spoken interactions (e.g., regional terminology for food; greetings and salutations used by youth in various French-speaking communities; polite directions or instructions in different language registers)"}]}]},{"code":"C","title":"Reading","why":"","overall":[{"code":"C1","title":"Reading Comprehension","text":"determine meaning in a variety of French texts, using a range of reading comprehension strategies","specific":[{"code":"C1.1","title":"Using Reading Comprehension Strategies","text":"identify a range of reading comprehension strategies and use them appropriately before, during, and after reading to understand a variety of French texts, with support as appropriate (e.g., ask questions to focus reading; visualize content to clarify details; reread to confirm and clarify meaning; make connections to understand a character’s motivation; identify the main idea and supporting details)"},{"code":" C1.2","title":"Reading for Meaning","text":"demonstrate an understanding of the intent and meaning of a variety of French texts about familiar, academic, and personally relevant topics, with contextual and visual support (e.g., explain the point of view of various characters in traditional French, Aboriginal, or other tales; participate in an informal class discussion about the arguments presented in a persuasive text; illustrate the main points of a newspaper article on an environmental issue; role-play an interview with a character from a story; identify the key messages in and intended audience for a travel brochure about Quebec)"},{"code":"C1.3","title":"Reading with Fluency","text":"read French texts containing familiar vocabulary and language structures, and dealing with familiar, academic, and personally relevant topics, at a sufficient rate and with sufficient expression to convey the sense of the text, using a variety of cues (e.g., read a poem aloud with appropriate emphasis and phrasing; read words and expressions from other subject areas; understand and read words in context with appropriate tone of voice and intonation; chunk text into logical sections/phrases)"},{"code":"C1.4","title":"Developing Vocabulary","text":"identify and use several different strategies to expand vocabulary through reading (e.g., create a word web on a specific topic and its sub-topics; use technology/media to help them classify vocabulary based on word patterns; refer to classroom anchors and word walls; identify subject-specific terminology and incorporate it in their daily communications)"},{"code":"C1.5","title":"Responding to and Evaluating Media Texts","text":"express their personal opinions about the treatment and presentation of the messages in a variety of media texts about familiar, academic, and personally relevant topics, and give evidence from the text for their opinions, with teacher support as appropriate (e.g., explain the effect of humour in cartoon advertisements; share personal reactions to a blog post; comment on the graphic design of a video game package or book jacket; identify promises made in junk mail or flyers; discuss the impact of subtitles in movies; describe the main message of an environmental website and explain how the message connects to the organization that created it)"}]},{"code":"C2","title":"Purpose, Form, and Style","text":"identify the purpose(s) and characteristics of a variety of adapted and authentic text forms, including fictional, informational, graphic, and media forms","specific":[{"code":"C2.1","title":"Purposes of Text Forms","text":"identify the purpose(s) of a variety of text forms, including fictional, informational, graphic, and media forms (e.g., short story – to entertain and/or to depict imagined events or experiences; email and text messages – to communicate with friends; website – to provide information about a specific topic; bill or invoice – to show the cost of goods or services bought or sold)"},{"code":"C2.2","title":"Characteristics and Stylistic Elements of Text Forms","text":"identify some characteristics and/or stylistic elements of a variety of text forms, including fictional, informational, graphic, and media forms, and explain how they help to convey the meaning, with support and guidance from the teacher (e.g., song/poem – analogy, rhyme, parallel structure, comparison, contrast, simile, metaphor, personification; short story/legend – plot line about resolving a problem or gaining an insight, descriptions of characters and settings; manual – numbered steps, diagrams)"},{"code":"C2.3","title":"Metacognition","text":"(a) identify, in conversation with the teacher and their peers, a few strategies they found helpful before, during, and after reading to understand texts; (b) determine their areas of greater and lesser strength as readers, and plan steps they can take to improve their reading skills (e.g., keep a reading log to track their reading trends; analyse their reading log to determine preferred text forms and set goals to expand the variety of texts read; plan to use newly acquired vocabulary in spoken and written contexts)"}]},{"code":"C3","title":"Intercultural Understanding","text":"demonstrate an understanding of information in French texts about aspects of culture in diverse French-speaking communities and other communities around the world, and of French sociolinguistic conventions used in a variety of situations and communities","specific":[{"code":"C3.1","title":"Intercultural Awareness","text":"using information from a variety of French texts, identify French-speaking communities in Quebec, find out about aspects of their cultures, and make connections to personal experiences and their own and other communities (e.g., role-play stories and legends from diverse French-speaking communities; research national and Québécois symbols and how they represent the values and accomplishments of Canada and Quebec; discuss various Québécois and/or Aboriginal stories or legends, such as “Le Cap diamant” or “Le Rocher de Grand-mère”, and make connections to current environmental or social issues; determine the ingredients in a typical Québécois dish such as “le pouding chômeur”; describe ideas, themes, and characters depicted in music, stories, and legends by Québécois artists and authors such as Alain M. Bergeron or Sheldon Cohen; read about Québécois personalities such as Oliver Jones, Senaya, Céline Dion, or Gilles Pelletier, or historical figures, and describe some of their accomplishments)"},{"code":"C3.2","title":"Awareness of Sociolinguistic Conventions","text":"using information from French texts, identify and demonstrate an understanding of sociolinguistic conventions used in a variety of situations in diverse French-speaking communities (e.g., standard salutations and expressions in invitations; language in personal letters; layout of and vocabulary in newspaper articles; abbreviations and use of the infinitif in recipes or procedural texts)"}]}]},{"code":"D","title":"Writing","why":"","overall":[{"code":"D1","title":"Purpose, Audience, and Form","text":"write in French in a variety of forms and for a variety of purposes and audiences, using knowledge of vocabulary, language conventions, and stylistic elements to communicate clearly and effectively","specific":[{"code":"D1.1","title":"Identifying Purpose and Audience","text":"determine, with support from the teacher, their purpose for writing and the audience for French texts they plan to create (e.g., to outline their opinion on a social issue in a formal letter to the local government; to write horoscopes or review a sporting event for the class newspaper; to draft notes for a speech on an environmental issue)"},{"code":"D1.2","title":"Writing in a Variety of Forms","text":"write a variety of French texts to convey information, ideas, and opinions about familiar, personally relevant, and academic topics, following models appropriate to the purpose and incorporating some elements of each form (e.g., research and write a report about an aspect of healthy living; develop a narrative based on a topic from social studies or science and technology; draft a script for a short play based on a novel, illustration, song, event, or short story)"},{"code":"D1.3","title":"Developing Vocabulary","text":"confirm word meanings and review, refine, and vary word choices, using a variety of resources (e.g., use dictionaries, thesauri, and subject-specific texts to help them make accurate word choices; create a word web to prepare vocabulary before writing)"},{"code":"D1.4","title":"Using Stylistic Elements","text":"use word choice and stylistic elements to establish a personal voice and a clear point of view (e.g., use comparative adjectives and adverbs, similes, and metaphors to describe a character from a novel or movie in a review; using a serious tone, write a newspaper article telling the story of a local hero or heroine)"},{"code":"D1.5","title":"Creating Media Texts","text":"using familiar words and expressions, create a variety of media texts in French for specific purposes and audiences, using several media forms and the conventions and techniques appropriate to the chosen form (e.g., create a photo essay with captions about an outing with family, friends, or peers; create a poster to advertise an event or inform their peers about a social studies or science topic; create a multimedia presentation to persuade consumers to buy local produce; compose song lyrics about an environmental issue)"},{"code":"D1.6","title":"Applying Language Conventions","text":"communicate their meaning clearly, using parts of speech appropriately and following conventions for correct spelling, word order, and punctuation (e.g., use of hyphens in subject-verb inversions; present, past, and future tenses of familiar -er, -ir, and -re verbs; various interrogative constructions such as subject-verb inversion, “est-ce que”, and the interrogative adjectives “quel”, “quelle”, “quels”, “quelles”; the superlative and comparative forms of adjectives and adverbs, such as “plus”, “le plus”, “moins”, “le moins”, “mieux”, “le mieux”; formation of regular adverbs through the addition of “-ment”; standard ways of expressing past events and personal experiences)"}]},{"code":"D2","title":"The Writing Process","text":"use the stages of the writing process – including pre-writing, producing drafts, revising, editing, and publishing – to develop and organize content, clarify ideas and expression, correct errors, and present their written work effectively","specific":[{"code":"D2.1","title":"Generating, Developing, and Organizing Ideas","text":"generate, develop, focus, and organize ideas for writing, using a variety of strategies and print, electronic, and other resources, as appropriate (e.g., think-pair-share to determine the topic and content of a script; use a timeline when planning a biography; brainstorm ideas and questions before beginning research; use a KWL chart to help them plan their research)"},{"code":"D2.2","title":"Drafting and Revising","text":"plan and produce drafts, following established criteria, and revise their writing to improve its content, clarity, and interest, using a variety of strategies (e.g., select appropriate graphic organizers to assist with planning and revisions; refer to teacher models and exemplars when editing work; work in pairs to identify errors and repetition)"},{"code":"D2.3","title":"Producing Finished Work","text":"edit, proofread, and publish a variety of written pieces, follow- ing a model or a set of guidelines to meet established criteria, with support as appropriate (e.g., refer to success criteria to help them self-assess their work; use technology to publish finished work; select fonts, images, or photographs that enhance their message or support their opinion)"},{"code":"D2.4","title":"Metacognition","text":"(a) identify, in conversation with the teacher and their peers, several strategies they found helpful before, during, and after writing; (b) determine their areas of greater and lesser strength as writers, and plan steps they can take to improve their writing skills (e.g., discuss how brainstorming and thought webs help them generate ideas for writing; determine which graphic organizers were most useful in helping them develop and organize thoughts and ideas during writing; assess the effectiveness of peer feedback and peer editing in revising their work; determine which writing strategies were most helpful)"}]},{"code":"D3","title":"Intercultural Understanding","text":"in their written work, demonstrate an awareness of aspects of culture in diverse French-speaking communities and other communities around the world, and of the appropriate use of French sociolinguistic conventions in a variety of situations","specific":[{"code":"D3.1","title":"Intercultural Awareness","text":"in their written work, communicate information about French-speaking communities in Quebec, including aspects of their culture and their contributions to la francophonie and the world, and make connections to personal experiences and their own and other communities (e.g., draft a “Bienvenue au Québec” brochure for children immigrating to Canada; write a newspaper article comparing some school settings from around the world; describe a Québécois cultural celebration from the point of view of a visitor to Canada; create the home page for a website of a prominent Québécois(e) such as Michaëlle Jean, Régine Chassagne, Bruny Surin, Marc Favreau)"},{"code":"D3.2","title":"Awareness of Sociolinguistic Conventions","text":"identify sociolinguistic conventions associated with a variety of social situations in diverse French-speaking communities and use them appropriately in their written work (e.g., expressions from different French-speaking regions; conventions related to personal and formal letters; elements in a note accepting or declining an invitation)"}]}]}]},"g6":{"url":"https://www.dcp.edu.gov.on.ca/en/curriculum/elementary-fsl","sourceLang":"en","strands":[{"code":"A","title":"Listening","why":"","overall":[{"code":"A1","title":"Listening to Understand","text":"determine meaning in a variety of oral French texts, using appropriate listening strategies","specific":[{"code":"A1.1","title":"Using Listening Comprehension Strategies","text":"identify a range of listening comprehension strategies and use them appropriately before, during, and after listening to understand a variety of oral French texts (e.g., make predictions before listening to a text; ask questions to clarify things they do not understandin a peer’s presentation; recognize and interpret gestures, facial expressions, and tone of voice to facilitate understanding; visualize elements of an oral text)"},{"code":"A1.2","title":"Understanding Purposes for Listening","text":"demonstrate an understanding of the purpose for listening in a variety of situations (e.g., to gather feedback during student-teacher and peer conferences that can be used to help them plan next steps; to formulate questions on a topic based on peer presentations; to express an opinion in a class debate; to identify the perspective in the dramatization or retelling of a myth or legend)"},{"code":"A1.3","title":"Listening for Meaning","text":"demonstrate an understanding of the intent and meaning of various oral French texts containing familiar and unfamiliar words and expressions and dealing with familiar, academic, and personally relevant topics, with support as appropriate (e.g., create a poster for a product using the main ideas heard in a commercial; summarize main ideas and supporting details heard in a webcast, using a graphic organizer; create a storyboard based on a read-aloud; compare experiences heard in a song with their own experiences; identify whose points of view are present or missing in an oral text)"},{"code":"A1.4","title":"Responding to and Evaluating Media Texts","text":"express their personal opinions about the treatment and presentation of the messages in a variety of oral media texts about familiar, academic, and personally relevant topics, and give evidence from the texts for their opinions, with teacher support as appropriate (e.g., evaluate different news broadcasts for bias; analyse the effectiveness of an advertisement aimed at a specific age group; evaluate how the visuals support the spoken messages in a documentary on Aboriginal peoples; explain how a television or radio advertisement might have a different effect on boys and on girls; identify the target audience for a documentary on an environmental issue; compile images from newspapers, magazines, and the Internet to illustrate the mood of a song or poem)"}]},{"code":"A2","title":"Listening to Interact","text":"interpret messages accurately while interacting in French for a variety of purposes and with diverse audiences","specific":[{"code":"A2.1","title":"Using Interactive Listening Strategies","text":"identify and use interactive listening strategies to suit a variety of situations while participating in social and academic interactions about familiar and personally relevant topics (e.g., ask questions to clarify meaning and understanding; paraphrase ideas from peers during a debate; ask for repetition when participating in discussions)"},{"code":"A2.2","title":"Interacting","text":"respond with understanding to what others say while participating in a variety of interactions about familiar, academic, and personally relevant topics (e.g., offer feedback on a peer’s presentation; respond to a speaker’s opinion while showing respect for his or her ideas; offer suggestions in a group discussion on preserving biodiversity; listen and respond during improvised role play; exchange opinions with a peer about a story read in class)"},{"code":"A2.3","title":"Metacognition","text":"(a) describe factors that prevent them from listening effectively and strategies they found helpful before, during, and after listening; (b) identify their areas of greater and lesser strength as listeners, and plan steps they can take to improve their listening skills (e.g., discuss what helped them to understand and allowed them to interact more effectively during a discussion; determine next steps after assessing the effectiveness of the listening strategies they use most often; set learning goals during a teacher conference to improve their listening skills)"}]},{"code":"A3","title":"Intercultural Understanding","text":"demonstrate an understanding of information in oral French texts about aspects of culture in diverse French-speaking communities and other communities around the world, and of French sociolinguistic conventions used in a variety of situations and communities","specific":[{"code":"A3.1","title":"Intercultural Awareness","text":"using information from oral French texts, identify French-speaking communities in eastern, western, and northern Canada; find out about aspects of their cultures; and make connections to personal experiences and their own and other communities (e.g., identify examples from audio or audio-visual media that illustrate the status of French as an official language of Canada; listen to the national anthem in French and determine some similarities and differences between the French and English versions; listen to French Canadian folktales and legends and discuss, write about, or create artworks to depict aspects that interest them; listen to historical accounts about the voyageurs and coureurs de bois and discuss their significance to the development of Canada as a nation; listen to songs such as “À la claire fontaine”,“C’est l’aviron”,“V’là l’bon vent” and identify their significance to Métis and other French Canadian communities; listen to participate in traditional storytelling games)"},{"code":"A3.2","title":"Awareness of Sociolinguistic Conventions","text":"using information from oral French texts, identify and demonstrate an understanding of sociolinguistic conventions used in a variety of situations in diverse French-speaking communities (e.g., language used in different French-speaking regions; formal and informal language used in a variety of social situations)"}]}]},{"code":"B","title":"Speaking","why":"","overall":[{"code":"B1","title":"Speaking to Communicate","text":"communicate information and ideas orally in French, using a variety of speaking strategies and age- and grade-appropriate language suited to the purpose and audience","specific":[{"code":"B1.1","title":"Using Oral Communication Strategies","text":"identify a range of speaking strategies and use them appropriately to express themselves clearly and coherently in French for various purposes and to a variety of audiences (e.g., allocate time to planning, mapping out, and practising a presentation; practise in front of a mirror to gain confidence before a presentation; rehearse with a partner or while recording themselves before sharing a presentation in a large group; use visuals to supplement and enhance a presentation; use editing tools to help make a presentation flow; use tone of voice, pace, and volume to help communicate meaning; use appropriate facial expressions, gestures, and eye contact to engage their audience)"},{"code":"B1.2","title":"Producing Oral Communications","text":"produce planned, rehearsed, and increasingly spontaneous messages in French containing information and ideas about academic topics and matters of personal interest, with contextual, auditory, and visual support (e.g., explore various points of view through dramatization and role play; prepare an oral presentation to persuade peers to react to a social or environmental issue; share their opinion of a book or movie; deliver a speech to motivate students to participate in an environmental initiative; analyse the works of various Aboriginal artists through group discussion; talk about the purpose, message, and effectiveness of editorial cartoons; express personal reactions to a documentary on economic globalization; discuss the effectiveness of persuasive language in television ads)"},{"code":"B1.3","title":"Speaking with Fluency","text":"speak with a smooth pace, appropriate intonation, and accurate pronunciation in planned, rehearsed, and increasingly spontaneous communications about familiar, academic, and personally relevant topics, using familiar words and expressions (e.g., use pauses appropriately when presenting information; use tone of voice to articulate feeling or expression during a role play)"},{"code":"B1.4","title":"Creating Media Texts","text":"create a variety of oral media texts using forms, conventions, and techniques appropriate to the purpose and audience (e.g., create a podcast presenting opposing opinions about a current event; create a television commercial for a healthy food product; create an anti-drug advertising campaign for radio; create a historical travelogue describing the journey of a First Nation guide and a European explorer; create a multimedia report on renewable sources of energy)"}]},{"code":"B2","title":"Speaking to Interact","text":"participate in spoken interactions in French for a variety of purposes with diverse audiences","specific":[{"code":"B2.1","title":"Using Speaking Interaction Strategies","text":"demonstrate an understanding of appropriate speaking behaviour in a variety of situations (e.g., take turns when speaking; paraphrase to clarify meaning; make connections to their own experience when responding to a peer’s comment; use facial expressions and gestures to indicate agreement or confusion)"},{"code":"B2.2","title":"Interacting","text":"engage in rehearsed and spontaneous spoken interactions, in guided and increasingly spontaneous social and academic contexts, about personally relevant and academic topics (e.g., participate in small- and large-group discussions on international issues; interview a partner about his or her healthy living practices; role-play a meeting between an individual from a First Nation community and an early European settler; debate a local social issue such as bullying; participate in a group discussion about what they and their peers do with their allowance)"},{"code":"B2.3","title":"Metacognition","text":"(a) describe strategies they found helpful before, during, and after speaking to communicate effectively; (b) identify their areas of greater and lesser strength as speakers, and plan steps they can take to improve their speaking skills (e.g., determine which strategies were helpful when interacting with classmates; discuss the effective elements of their presentation and identify elements that could be incorporated in future; use a checklist to monitor their contributions to and participation in discussions)"}]},{"code":"B3","title":"Intercultural Understanding","text":"in their spoken communications, demonstrate an awareness of aspects of culture in diverse French-speaking communities and other communities around the world, and of the appropriate use of French sociolinguistic conventions in a variety of situations","specific":[{"code":"B3.1","title":"Intercultural Awareness","text":"communicate information orally about French-speaking communities in eastern, western, and northern Canada, including aspects of their cultures and their contributions to la francophonie and the world, and make connections to personal experiences and their own and other communities (e.g., describe French-speaking communities, including First Nations, Métis, and Inuit communities, in the Atlantic provinces, the prairie and western provinces, and the northern territories; share ideas and opinions regarding Canadian Heritage Moments video clips about topics in French Canadian history – such as the Métis or the Acadians – and make cross-curricular connections to topics in social studies; discuss personal reactions to songs and artwork by French Canadian artists, including Aboriginal artists, such as Leah Fontaine, Marcien Lemay, Derek Letourneau; describe traditions, festivals, songs, and cuisine from French-speaking regions in western, eastern, and northern Canada, and make connections to customs in their own community; make a presentation about a cultural artefact or a cultural event such as a wampum belt, Journée Louis Riel, or National Aboriginal Day)"},{"code":"B3.2","title":"Awareness of Sociolinguistic Conventions","text":"identify sociolinguistic conventions associated with a variety of social situations in diverse French-speaking communities, and use them appropriately in spoken interactions (e.g., levels of formality appropriate to the audience or purpose of communication; politeness/formality in customer service etiquette in restaurants or stores; expressions of gratitude; regional variations in vocabulary)"}]}]},{"code":"C","title":"Reading","why":"","overall":[{"code":"C1","title":"Reading Comprehension","text":"determine meaning in a variety of French texts, using a range of reading comprehension strategies","specific":[{"code":"C1.1","title":"Using Reading Comprehension Strategies","text":"identify a range of reading comprehension strategies and use them appropriately before, during, and after reading to understand a variety of French texts, with support as appropriate (e.g., activate prior knowledge about a subject by brainstorming; make predictions about a text based on knowledge of similar texts; use visualization and mental images to clarify the message; read on to confirm or clarify understanding; summarize key points on a graphic organizer)"},{"code":"C1.2","title":"Reading for Meaning","text":"demonstrate an understanding of the intent and meaning of a variety of French texts about familiar, academic, and personally relevant topics, with contextual and visual support (e.g., create a Venn diagram to compare and contrast characters in two texts; create promotional materials to encourage others to read a text from the class library; in a guided reading group, read an article on an environmental issue and design the cover page for a magazine featuring the article; identify the point of view in a narrative text; summarize an informational text in their own words)"},{"code":"C1.3","title":"Reading with Fluency","text":"read French texts containing familiar vocabulary and language structures, and dealing with familiar, academic, and personally relevant topics, at a sufficient rate and with sufficient expression to convey the sense of the text, using a variety of cues (e.g., read a radio drama or editorial in role with suitable emphasis and phrasing; use tone of voice, pace, and expression during reader’s theatre; reread a familiar text; use knowledge of prefixes and suffixes)"},{"code":"C1.4","title":"Developing Vocabulary","text":"identify and use several different strategies to expand vocabulary through reading (e.g., use prefixes and suffixes to create new words; create a personal lexicon; develop a list of word patterns to determine meaning of new words; use a thesaurus to generate synonyms and antonyms for frequently used words)"},{"code":"C1.5","title":"Responding to and Evaluating Media Texts","text":"express their personal opinions about the treatment and presentation of the messages in a variety of media texts about familiar, academic, and personally relevant topics, and give evidence from the text for their opinions, with teacher support as appropriate (e.g., compare the effectiveness of written and audio advertisements for the same product; discuss how the point of view expressed in an editorial influenced their opinion; determine the implied audience of an advertisement and describe how the message might change if the advertisement were directed at a different audience; identify differences between language used in packaging for healthy food and fast food; identify features of an eco-tourism brochure that are intended to attract travellers)"}]},{"code":"C2","title":"Purpose, Form, and Style","text":"identify the purpose(s) and characteristics of a variety of adapted and authentic text forms, including fictional, informational, graphic, and media forms","specific":[{"code":"C2.1","title":"Purposes of Text Forms","text":"identify the purpose(s) of a variety of text forms, including fictional, informational, graphic, and media forms (e.g., myth – to explain the world through imaginary and supernatural characters; advertisement – to sell a product or promote awareness of an issue; biography – to tell the story of someone’s life and accomplishments; map – to convey geographical relationships; directions for a science experiment – to explain steps to students)"},{"code":"C2.2","title":"Characteristics and Stylistic Elements of Text Forms","text":"identify some characteristics and/or stylistic elements of a variety of text forms, including fictional, informational, graphic, and media forms, and explain how they help to convey the meaning, with support and guidance from the teacher (e.g., traditional First Nation, Métis, or Inuit story – characters, personification of objects or animals, moral or lesson; newspaper article – captions, headline, and subheadings; map – legend, coordinates, grid; persuasive letter – argument and supporting information; poetry – alliteration and rhyme; narrative – comparison, personification, simile, contrast, metaphor, sarcasm/irony, comparison, symbolism)"},{"code":"C2.3","title":"Metacognition","text":"(a) identify, in conversation with the teacher and their peers, some strategies they found helpful before, during, and after reading to understand texts; (b) determine their areas of greater and lesser strength as readers, and plan steps they can take to improve their reading skills (e.g., recognize that rereading will help them to repair meaning when understanding has broken down; evaluate how deleting unimportant information when summarizing helped them arrive at the essence of meaning; recognize how synthesizing new knowledge with prior knowledge deepens understanding of ideas or concepts)"}]},{"code":"C3","title":"Intercultural Understanding","text":"demonstrate an understanding of information in French texts about aspects of culture in diverse French-speaking communities and other communities around the world, and of French sociolinguistic conventions used in a variety of situations and communities","specific":[{"code":"C3.1","title":"Intercultural Awareness","text":"using information from a variety of French texts, identify French- speaking communities in eastern, western, and northern Canada; find out about aspects of their cultures; and make connections to personal experiences and their own and other communities (e.g., identify how family is represented in different text forms from various French-speaking regions of Canada; read a daily food log or a menu from an individual in a French-speaking community, such as Iqaluit, Saint Boniface, or Moncton, and compare its contents to their own daily diet; read maps to identify differences and similarities with respect to economic and agricultural activity in various French-speaking communities; consult an atlas or website to identify French-speaking communities, including Aboriginal communities, in Atlantic Canada, the prairie and western provinces, and the northern territories; read about important French Canadian/Métis historical figures such as Louis Riel; discuss various Aboriginal stories or legends, such as Légende de la Prairie-du-Cheval-Blanc, and make connections to current environmental and social issues; identify examples of texts – such as bilingual signs or government brochures – that reflect the status of French as an official language of Canada; read the lyrics and listen to songs by various French Canadian and Aboriginal artists such as Elisapie Isaac, Florent Vollant, and Samian, and make comparisons with songs in their own first languages; identify the traits of heroes in traditional legends such as Ti-Jean and Nanabijou)"},{"code":"C3.2","title":"Awareness of Sociolinguistic Conventions","text":"using information from French texts, identify and demonstrate an understanding of socio-linguistic conventions used in a variety of situations in diverse French-speaking communities (e.g., formal and informal language and style in letters and advertisements; regional dialects such as l’acadien, le chiac, le Michif, le créole)"}]}]},{"code":"D","title":"Writing","why":"","overall":[{"code":"D1","title":"Purpose, Audience, and Form","text":"write in French in a variety of forms and for a variety of purposes and audiences, using knowledge of vocabulary, language conventions, and stylistic elements to communicate clearly and effectively","specific":[{"code":"D1.1","title":"Identifying Purpose and Audience","text":"determine, with support from the teacher, their purpose for writing and the audience for French texts they plan to create (e.g., to create steps for the respectful resolution of conflict; to share a personal experience; to inform their peers about a global economic issue; to recount a legend; to express an opinion in an editorial; to inform classmates of the dangers of using drugs in a report; to write instructions for a sport or cooperative game; to describe the importance of forest conservation for the protection of animal and plant species)"},{"code":"D1.2","title":"Writing in a Variety of Forms","text":"write a variety of French texts to convey information, ideas, and opinions about familiar, personally relevant, and academic topics, following models appropriate to the purpose and incorporating some elements of each form (e.g., compose an article on a current or historical event; create a graphic text to promote the benefits of daily physical activity; write a diary entry from the point of view of an Aboriginal Canadian or early Canadian settler; write a script promoting anti-bullying awareness; review a movie or book; write a letter to their city councillor about steps to improve the local environment)"},{"code":"D1.3","title":"Developing Vocabulary","text":"confirm word meanings and review, refine, and vary word choices, using a variety of resources (e.g., use regular and irregular adjectives and adverbs to enhance interest in text; use a thesaurus to find synonyms for commonly used words; use online and print dictionaries to determine word meaning)"},{"code":"D1.4","title":"Using Stylistic Elements","text":"use word choice and stylistic elements to establish a personal voice and a clear point of view (e.g., use similes when comparing themselves to a character; vary sentence length and type; use persuasive language and supporting details to request a change in school rules; use personification to give life to an object or idea; use first- or third-person narration)"},{"code":"D1.5","title":"Creating Media Texts","text":"using familiar words and expressions, create a variety of media texts in French for specific purposes and audiences, using several media forms and the conventions and techniques appropriate to the chosen form (e.g., write a script for a vignette/short video depicting trade between Aboriginal and European peoples in colonial Canada; create a DVD jacket or poster for a movie; create a multimedia campaign to raise awareness about substance abuse; design a web page for an amusement park; create a blog to encourage young people to take action on or find solutions to a social issue in their community; write a script for a public service announcement to encourage healthy eating or litterless lunches)"},{"code":"D1.6","title":"Applying Language Conventions","text":"communicate their meaning clearly, using parts of speech appropriately and following conventions for correct spelling, word order, and punctuation (e.g., appropriate conjunctions and punctuation in compound and complex sentence structures; indirect object pronouns such as “lui”, “leur”; relative pronouns such as “qui”,“que”, “dont”, “lequel”; possessive pronouns such as “le mien”, “la tienne”, “les siens”,“le leur”; passé composé, imparfait, présent, and futur of familiar verbs according to the context)"}]},{"code":"D2","title":"The Writing Process","text":"use the stages of the writing process – including pre-writing, producing drafts, revising, editing, and publishing – to develop and organize content, clarify ideas and expression, correct errors, and present their written work effectively","specific":[{"code":"D2.1","title":"Generating, Developing, and Organizing Ideas","text":"generate, develop, focus, and organize ideas for writing, using a variety of strategies and print, electronic, and other resources, as appropriate (e.g., before writing a procedural text, record the steps in a flow chart; brainstorm prior knowledge of a topic to generate ideas for writing; list arguments on a graphic organizer before drafting a persuasive letter; create a storyboard to outline a narrative)"},{"code":"D2.2","title":"Drafting and Revising","text":"plan and produce drafts, following established criteria, and revise their writing to improve its content, clarity, and interest, using a variety of strategies (e.g., make an outline before writing a report; use a graphic organizer to help them organize main points and supporting details; refer to teacher models and exemplars when editing work; highlight ideas or information that should be omitted or changed; cut and paste to present their arguments more logically; use an asterisk to identify sentences that require further clarification; identify repetitive words and substitute alternatives; consider feedback from their teacher or peers)"},{"code":"D2.3","title":"Producing Finished Work","text":"edit, proofread, and publish a variety of written pieces, following a model or a set of guidelines to meet established criteria, with support as appropriate (e.g., refer to checklists and anchor charts to determine whether all criteria have been met; consider comments from peers when editing their writing; choose relevant graphics and images to enhance the message; read their written draft aloud to verify logical organization; use proofreading tools such as a spellcheck program to identify mistakes)"},{"code":"D2.4","title":"Metacognition","text":"(a) identify, in conversation with the teacher and their peers, several strategies they found helpful before, during, and after writing; (b) determine their areas of greater and lesser strength as writers, and plan steps they can take to improve their writing skills (e.g., determine which strategies helped them organize information and ideas effectively; evaluate the effectiveness of peer editing and peer feedback; record areas needing improvement and next steps in a writer’s notebook)"}]},{"code":"D3","title":"Intercultural Understanding","text":"in their written work, demonstrate an awareness of aspects of culture in diverse French-speaking communities and other communities around the world, and of the appropriate use of French sociolinguistic conventions in a variety of situations","specific":[{"code":"D3.1","title":"Intercultural Awareness","text":"in their written work, communicate information about French-speaking communities in eastern, western, and northern Canada, including aspects of their culture and their contributions to la francophonie and the world, and make connections to personal experiences and their own and other communities (e.g., use presentation software to share a cultural experience; write a report on a French Canadian cultural event, making connections to an event from their own cultures; write a biography of a French-speaking person who has contributed to Canadian society; following an example of a French Canadian myth or legend, write a legend explaining a cultural event or geographic phenomenon from their own community; write a report on a French Canadian tradition adapted from First Nations traditions, such as making maple syrup)"},{"code":"D3.2","title":"Awareness of Sociolinguistic Conventions","text":"identify sociolinguistic conventions associated with a variety of social situations in diverse French-speaking communities and use them appropriately in their written work (e.g., idiomatic expressions; appropriate level of formality for dialogue between strangers; appropriate language for the questions in a survey)"}]}]}]}}}};
